window.__D("text/zohar-hebrew-translation/c030",{"p":[[9522012288,"<p>כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם. כֹּה תְבָרֲכוּ - בִּלְשׁוֹן הַקֹּדֶשׁ. כֹּה תְבָרֲכוּ - בְּיִרְאָה. כֹּה תְבָרֲכוּ - בַּעֲנָוָה. אָמַר רַבִּי אַבָּא, כֹּה תְבָרֲכוּ - לָמַדְנוּ, הַצֶּדֶק הַזֶּה נִקְרָא כֹּ\"ה, שֶׁכָּל הַדִּינִים מִתְעוֹרְרִים מִכֹּ\"ה (ממנו), וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר, מַה זֶּה מַכָּה (שכה) רַבָּה? כְּלוֹמַר, מַכָּה מִכֹּה. וְכָתוּב (שמות ז) וְהִנֵּה לֹא שָׁמַעְתָּ עַד כֹּ\"ה, כְּמוֹ שֶׁהִפְחִיד מֹשֶׁה. וְכָתוּב בְּזֹּאת תֵּדַע כִּי אֲנִי ה', וְהַכֹּל אֶחָד. וְכָתוּב וְלֹא שָׁת לִבּוֹ גַּם לָזֹּאת, שֶׁהִזְמִינָהּ לְהַחֲרִיב אֶת אַרְצוֹ.</p>\n<p>מֵהַכֹּ\"ה הַזֹּאת מִתְעוֹרְרִים הַדִּינִים, וּמִשֶּׁהִתְחַבֵּר עִמָּהּ חֶסֶד, מִתְבַּשֶּׂמֶת. וּמִשּׁוּם כָּךְ נִמְסָר זֶה לַכֹּהֵן שֶׁבָּא מֵחֶסֶד, כְּדֵי שֶׁתִּתְבָּרֵךְ וְתִתְבַּשֵּׂם כֹּ\"ה. זֶהוּ שֶׁכָּתוּב כֹּה תְבָרֲכוּ. כְּלוֹמַר, אַף עַל גַּב שֶׁהַכֹּה הַזֹּאת נִמְצֵאת בְּדִינִים, תְּבַשְּׂמוּ אוֹתָהּ וּתְבָרְכוּ אוֹתָהּ, שֶׁכָּתוּב כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. תְּבָרְכוּ בְחֶסֶד זֶה אֶת כֹּ\"ה, וּתְבַשְּׂמוּ אוֹתָהּ מוּל יִשְׂרָאֵל, כְּדֵי שֶׁלֹּא יִמָּצְאוּ בָהּ דִּינִים.</p>\n<p>זְהִוּ שֶׁכָּתוּב כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם. לֹא כָתוּב אִמְרוּ, אֶלָּא אָמוֹר, לְהוֹצִיא מִשֶּׁרַבּוּ הַפָּרִיצִים שֶׁלֹּא מְפַרְסְמִים דָּבָר, שֶׁהֲרֵי לֹא הִצְטַוּוּ לְפַרְסֵם הַשֵּׁם, מַשְׁמָע שֶׁכָּתוּב אָמוֹר לָהֶם. אָמוֹר סְתָם. דָּבָר אַחֵר אָמוֹר - כֵּיוָן שֶׁכָּתוּב כֹּה תְבָרֲכוּ, לָמָּה לֹא כָתוּב תֹּאמְרוּ? אֶלָּא שָׁנָה רַבִּי יְהוּדָה, אָמוֹר לָהֶם, זָכוּ - לָהֶם. לֹא זָכוּ - אָמוֹר סְתָם.</p>\n<p>רַבִּי יִצְחָק פָּתַח, (דניאל י) וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי אֶת הַמַּרְאָה וְהָאֲנָשִׁים אֲשֶׁר הָיוּ עִמִּי לֹא רָאוּ אֶת הַמַּרְאָה וְגוֹ'. וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי?! וַהֲרֵי שָׁנִינוּ, הֵם נְבִיאִים, וְהוּא לֹא נָבִיא, וּמִי הֵם? חַגַּי זְכַרְיָה וּמַלְאָכִי. אִם כָּךְ, נַעֲשָׂה קֹדֶשׁ חֹל, וַהֲרֵי כָּתוּב לֹא רָאוּ, לָמָּה פָּחֲדוּ? וּבְדָנִיֵּאל כָּתוּב וְרָאִיתִי אֲנִי, וְלֹא פָחַד, וְהוּא לֹא נָבִיא, הֲרֵי חֹל קֹדֶשׁ?</p>\n<p>אֶלָּא כָּךְ לָמַדְנוּ, כָּתוּב (תהלים כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי אִם תָּקוּם עָלַי מִלְחָמָה בְּזֹּאת אֲנִי בוֹטֵחַ. בְּזֹּאת, זֶה שֶׁאָמַרְנוּ. זֹּאת חֶבֶל חֶלְקוֹ לִירַשׁ וְלַעֲשׂוֹת לוֹ נְקָמוֹת. וְשָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת דָּוִד מֶרְכָּבָה קְדוֹשָׁה עִם הָאָבוֹת, כְּתָרִים עֶלְיוֹנִים קְדוֹשִׁים שֶׁל הַכֹּל, שֶׁיָּרְשׁוּ הָאָבוֹת. וְלָמַדְנוּ שֶׁדָּוִד הוֹרִישׁ מַלְכוּת לְבָנָיו, וּבִמְקוֹם מַלְכוּת הָעֶלְיוֹנָה הִתְחַזֵּק וְיָרַשׁ הוּא וּבָנָיו מַלְכוּת זוֹ שֶׁלֹּא תַעֲבֹר מִשִּׁלְטוֹנָם לְדוֹרֵי דוֹרוֹת.</p>\n<p>וְלָמַדְנוּ, בְּשָׁעָה שֶׁכֶּתֶר הַמַּלְכוּת הַזֶּה הִתְעוֹרֵר לִבְנֵי דָוִד, אֵין מִי שֶׁיַּעֲמֹד לְפָנָיו. וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי אֶת הַמַּרְאָה, מִשּׁוּם שֶׁמִּבְּנֵי דָוִד הָיָה, שֶׁכָּתוּב (דניאל א) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיֵּאל חֲנַנְיָה וְגוֹ'. וְהוּא רָאָה וְשָׂמַח בָּזֶה שֶׁהוּא מִצַּד יְרֻשַּׁת חֵלֶק חֶבֶל אָבִיו, וּמִשּׁוּם שֶׁהָיָה שֶׁלּוֹ הוּא סָבַל, וַאֲחֵרִים לֹא סָבְלוּ. שֶׁאָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהַכֹּ\"ה הַזֹּאת מִתְעוֹרֶרֶת בְּדִינֶיהָ, לֹא יְכוֹלִים בְּנֵי הָעוֹלָם לַעֲמֹד לְפָנֶיהָ.</p>\n<p>וּבְשָׁעָה שֶׁהַכֹּהֲנִים פּוֹרְשִׂים יְדֵיהֶם, שֶׁבָּאִים מֵחֶסֶד, מִתְעוֹרֵר חֶסֶד שֶׁלְּמַעְלָה וּמִתְחַבֵּר בַּכֹּ\"ה הַזֹּאת, וּמִתְבַּשֶּׂמֶת וּמִתְבָּרֶכֶת בְּפָנִים מְאִירוֹת לִבְנֵי יִשְׂרָאֵל, וּמַעֲבִירִים מֵהֶם דִּינִים. זֶהוּ שֶׁכָּתוּב כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל, וְלֹא אֶת שְׁאָר הָעַמִּים.</p>\n<p>בִּגְלַל כָּךְ כֹּהֵן וְלֹא אַחֵר. כֹּהֵן, כְּדֵי שֶׁיִּתְעוֹרֵר הַכֶּתֶר הַזֶּה שֶׁלּוֹ, חֶסֶד, עַל יָדוֹ, שֶׁנִּקְרָא חָסִיד, שֶׁכָּתוּב (דברים לג) לְאִישׁ חֲסִידֶךְ. וְהוּא בָּא מִצַּד הַחֶסֶד. וְכָתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה. אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹ\"ה. כֹּה תְבָרֲכוּ - בַּשֵּׁם הַמְפֹרָשׁ. כֹּה תְבָרֲכוּ - בִּלְשׁוֹן הַקֹּדֶשׁ.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, בְּשָׁעָה שֶׁהַכֹּהֵן שֶׁלְּמַטָּה קָם וּפוֹרֵשׂ יָדָיו, כָּל הַכְּתָרִים (ספירות) הַקְּדוֹשִׁים שֶׁלְּמַעְלָה מִתְעוֹרְרִים וּמְתֻקָּנִים לְהִתְבָּרֵךְ, וּמְאִירִים מֵעֹמֶק הַבְּאֵר שֶׁנִּמְשָׁךְ לָהֶם מֵאוֹתוֹ עֹמֶק שֶׁיּוֹצֵא תָמִיד, וְלֹא פוֹסְקִים הַבְּרָכוֹת הַנּוֹבְעוֹת מַבּוּעִים לְכָל הָעוֹלָמוֹת, וּמִתְבָּרְכִים וּמֻשְׁקִים מִכֻּלָּם.</p>\n<p>וְלָמַדְנוּ, בְּאוֹתוֹ זְמַן לַחַשׁ וּשְׁתִיקָה יֵשׁ בְּכָל הָעוֹלָמוֹת. לְמֶלֶךְ שֶׁרוֹצֶה לְהִזְדַּוֵּג בַּמַּלְכָּה וְרוֹצֶה לְהִכָּנֵס אֵלֶיהָ בְּלַחַשׁ, וְכָל הַשַּׁמָּשִׁים מִתְעוֹרְרִים בְּאוֹתוֹ זְמַן וּמִתְלַחֲשִׁים: הֲרֵי הַמֶּלֶךְ בָּא לְהִזְדַּוֵּג בַּמַּלְכָּה. מִי הַמַּלְכָּה? זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִי כְּנֶסֶת יִשְׂרָאֵל? כְּנֶסֶת יִשְׂרָאֵל סְתָם.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, כֹּהֵן צָרִיךְ לִזְקֹף יָמִין עַל שְׂמֹאל, שֶׁכָּתוּב (ויקרא ט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרַכֵם. יָדוֹ כָּתוּב, וְלֹא יָדָיו, מִשּׁוּם שֶׁשֶּׁבַח הַיָּמִין עַל הַשְּׂמֹאל. אָמַר רַבִּי אֶלְעָזָר, סוֹד הוּא, מִשּׁוּם שֶׁכָּתוּב (בראשית ג) וְהוּא יִמְשָׁל בָּךְ.</p>\n<p>לָמַדְנוּ, כֹּהֵן שֶׁרוֹצֶה לִפְרֹשׂ יָדָיו, צָרִיךְ שֶׁיִּתּוֹסֵף קְדֻשָּׁה עַל קְדֻשָּׁתוֹ, שֶׁצָּרִיךְ לְקַדֵּשׁ יָדָיו עַל יַד הַקָּדוֹשׁ. מִי יָד שֶׁל הַקָּדוֹשׁ? זֶה לֵוִי, שֶׁצָּרִיךְ כֹּהֵן לִטֹּל קְדֻשָּׁה שֶׁל מַיִם מִיָּדָיו, שֶׁכָּתוּב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. הֲרֵי הֵם קְדוֹשִׁים. וְכָתוּב בַּלְוִיִּם, (במדבר יח) וְגַם אֶת אַחֶיךְ מַטֵּה לֵוִי וְגוֹ'. שֵׁבֶט אָבִיךְ - כְּלָל. מִכָּאן שֶׁכָּל כֹּהֵן שֶׁפּוֹרֵשׂ יָדָיו, צָרִיךְ לְהִתְקַדֵּשׁ עַל יְדֵי קָדוֹשׁ, לְהוֹסִיף קְדֻשָּׁה עַל קְדֻשָּׁתוֹ. וְלָכֵן לֹא יִטֹּל קְדֻשָּׁה שֶׁל מַיִם מִבֶּן אָדָם אַחֵר שֶׁאֵינֶנּוּ קָדוֹשׁ.</p>\n<p>וּבְסִפְרָא דִצְנִיעוּתָא לָמַדְנוּ, לֵוִי שֶׁהִתְקַדֵּשׁ כֹּהֵן עַל יָדוֹ, צָרִיךְ הוּא לְהִתְקַדֵּשׁ בַּתְּחִלָּה. וְלָמָּה לֵוִי? שֶׁיִּתְקַדֵּשׁ עַל יְדֵי כֹהֵן אַחֵר. לָמַדְנוּ, כֹּהֵן אַחֵר לֹא צָרִיךְ, שֶׁהֲרֵי כֹּהֵן שֶׁאֵינוֹ שָׁלֵם, לֹא צָרִיךְ זֶה הַכֹּהֵן הַשָּׁלֵם לְהִפָּגֵם עַל יְדֵי פָגוּם שֶׁלֹּא שָׁלֵם. אֲבָל לֵוִי שֶׁהוּא שָׁלֵם וְרָאוּי לַעֲלוֹת לַדּוּכָן וְלַעֲבֹד בְּאֹהֶל מוֹעֵד, הֲרֵי הוּא שָׁלֵם, וַהֲרֵי נִקְרָא קָדוֹשׁ, שֶׁכָּתוּב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. אָמַר רַבִּי תַנְחוּם, אַף נִקְרָא טָהוֹר, שֶׁכָּתוּב וְטִהַרְתָּ אֹתָם. וּמִשּׁוּם כָּךְ צָרִיךְ לְהוֹסִיף כֹּהֵן קְדֻשָּׁה עַל קְדֻשָּׁתוֹ.</p>\n<p>לָמַדְנוּ, כֹּהֵן שֶׁפּוֹרֵשׂ יָדָיו, צָרִיךְ שֶׁהָאֶצְבָּעוֹת לֹא יִתְחַבְּרוּ זוֹ בָּזוֹ, כְּדֵי שֶׁיִּתְבָּרְכוּ כְתָרִים קְדוֹשִׁים כָּל אֶחָד וְאֶחָד לְבַדּוֹ כְּמוֹ שֶׁרָאוּי לוֹ, מִשּׁוּם שֶׁשֵּׁם הַקָּדוֹשׁ צָרִיךְ לְהִתְפָּרֵשׁ בְּאוֹתִיּוֹת רְשׁוּמוֹת שֶׁלֹּא לְעָרֵב זֶה בָּזֶה, וְלֹא יִתְכַּוֵּן (ולהתכון) בְּאוֹתָם דְּבָרִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְבָּרְכוּ עֶלְיוֹנִים כְּדֵי שֶׁיִּתְבָּרְכוּ תַחְתּוֹנִים, וְיִתְבָּרְכוּ עֶלְיוֹנִים שֶׁהֵם קְדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה עַל יְדֵי הַתַּחְתּוֹנִים, שֶׁהֵם קְדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, שֶׁהֵם קְדוֹשִׁים מִכָּל קְדוֹשִׁים שֶׁלְּמַטָּה, שֶׁכָּתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּל כֹּהֵן שֶׁלֹּא יוֹדֵעַ סוֹד זֶה, וּלְמִי מְבָרֵךְ, וּמַהִי הַבְּרָכָה שֶׁמְּבָרֵךְ - אֵין בִּרְכָתוֹ בְּרָכָה, וְהַיְנוּ מַה שֶּׁכָּתוּב (מלאכי ב) כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ. מַה זֶּה דַּעַת? דַּעַת סְתָם. וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ, עֶלְיוֹנִים יְבַקְשׁוּ מִפִּיהוּ. וּמַה יְבַקְשׁוּ מִפִּיהוּ? תּוֹרָה. תּוֹרָה סְתָם. אֵיךְ אֲחוּזָה תוֹרָה שֶׁלְּמַעְלָה שֶׁנִּקְרֵאת תּוֹרָה סְתָם? שֶׁלָּמַדְנוּ, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה בְּאוֹתָם כְּתָרִים עֶלְיוֹנִים שֶׁנִּקְרְאוּ כָּךְ. מָה הַטַּעַם? כִּי מַלְאַךְ ה' צְבָאוֹת הוּא. וְלָמַדְנוּ שֶׁצָּרִיךְ הַכֹּהֵן לְכַוֵּן בְּאוֹתָם דְּבָרִים שֶׁלְּמַעְלָה לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כְּפִי שֶׁצָּרִיךְ.</p>"],[9522012289,"<p>אָמַר רַבִּי שִׁמְעוֹן, לָמַדְנוּ בְּסִפְרָא דִּצְנִיעוּתָא, שֵׁם הַקָּדוֹשׁ גָּלוּי וּמְכֻסֶּה, שֶׁגָּלוּי הֲרֵי כָּתוּב בְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. שֶׁמְּכֻסֶּה כָּתוּב בְּאוֹתִיּוֹת אֲחֵרוֹת, וְאוֹתוֹ שֶׁמְּכֻסֶּה הוּא הַנִּסְתָּר (אחרים, ואותו שמכסה הוא נסתר) שֶׁל הַכֹּל. אָמַר רַבִּי יְהוּדָה, וַאֲפִלּוּ אוֹתוֹ שֶׁמְּגֻלֶּה מְכֻסֶּה בְּאוֹתִיּוֹת אֲחֵרוֹת, בִּגְלַל אוֹתוֹ טְמִיר הַטְּמִירִים בִּפְנִים.</p>\n<p>שֶׁהֲרֵי כָּאן צָרִיךְ הַכֹּהֵן לְצָרֵף שֵׁם הַקָּדוֹשׁ וּלְהוֹרִיד רַחֲמִים, (כלם) שֶׁכֻּלָּם כְּלוּלִים בְּדִבּוּר שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת (שכלן מדות) (בשני כתרים) כִּתְרֵי הָרַחֲמִים. וּבְאוֹתִיּוֹת אֵלּוּ שֵׁל הַשֵּׁם הַזֶּה סְתוּמִים עֶשְׂרִים וּשְׁתַּיִם מִדּוֹת הָרַחֲמִים, וּשְׁלֹשׁ עֶשְׂרֵה שֶׁל הָעַתִּיק נִסְתָּר וְגָנוּז מֵהַכֹּל. וְתֵשַׁע שֶׁהִתְגַּלּוּ מִזְּעֵיר אַנְפִּין (בזעיר אנפין), וּמִתְחַבְּרִים כֻּלָּם בְּצֵרוּף שֵׁם אֶחָד שֶׁהָיָה הַכֹּהֵן מְכַוֵּן כְּשֶׁפָּרַס יָדָיו בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת.</p>\n<p>וְלָמַדְנוּ, כְּשֶׁהָיְתָה צְנִיעוּת בָּעוֹלָם, הָיָה מִתְגַּלֶּה שֵׁם זֶה לַכֹּל. מִשֶּׁרָבְתָה הַחֻצְפָּה בָּעוֹלָם, נִסְתַּר בְּאוֹתִיּוֹתָיו. שֶׁכְּשֶׁהָיָה מִתְגַּלֶּה, הַכֹּהֵן הָיָה מְכַוֵּן, וְהַשֵּׁם מִתְפָּרֵשׁ. בַּמֶּה מְכַוֵּן? מְכַוֵּן בַּנִּסְתָּר שֶׁטָּמִיר וְגָנוּז, וּמִתְגַּלֶּה וּמִתְפָּרֵשׁ. מִשֶּׁהִתְרַבְּתָה הַחֻצְפָּה בָּעוֹלָם, נִסְתַּר הַכֹּל בְּאוֹתִיּוֹת רְשׁוּמוֹת.</p>\n<p>וּבֹא רְאֵה שֶׁכָּל אֵלּוּ עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת (רחמים) (שכל אלו עשרים ושתים מדות הרחמים), מֹשֶׁה אָמַר אוֹתָן בִּשְׁתֵּי פְעָמִים. פַּעַם רִאשׁוֹנָה אָמַר שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל עַתִּיק הָעַתִּיקִים, נִסְתַּר הַכֹּל, לְהוֹרִיד אֵלֶּה לְמָקוֹם שֶׁנִּמְצָא הַדִּין, לִכְפּוֹתָם. פַּעַם שְׁנִיָּה אָמַר תֵּשַׁע מִדּוֹת רַחֲמִים שֶׁכְּלוּלִים בַּזְּעֵיר אַנְפִּין, וּמְאִירִים מֵהָעַתִּיק נִסְתַּר הַכֹּל. וְכֻלָּם כּוֹלֵל הַכֹּהֵן כְּשֶׁפּוֹרֵשׂ יָדָיו לְבָרֵךְ אֶת הָעָם, וְנִמְצָאִים שֶׁמִּתְבָּרְכִים כָּל (העליונים) הָעוֹלָמוֹת בְּצַד הָרַחֲמִים שֶׁנִּמְשָׁכִים מֵהָעַתִּיק הַטָּמִיר, נִסְתַּר הַכֹּל. וְכָל הָעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַלָּלוּ מִדּוֹת נִסְתָּרוֹת.</p>\n<p>יְבָרֶכְךָ ה' וְיִשְׁמְרֶךְ, אֵלּוּ שְׁלֹשָׁה פְסוּקִים וּשְׁלֹשָׁה שֵׁמוֹת שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת הַכְּלוּלוֹת כְּנֶגְדָּם, וּבַכֹּל הִתְכַּוֵּן הַכֹּהֵן. וְכָל עֶלְיוֹנִים וְתַחְתּוֹנִים מִתְבַּשְּׂמִים בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁנִּסְתָּרוֹת בִּשְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ, כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם (אותיות) מִדּוֹת רַחֲמִים שֶׁכּוֹלְלוֹת הַכֹּל. וְלָכֵן כָּתוּב אָמוֹר, וְלֹא אִמְרוּ, כְּמוֹ שֶׁבֵּאַרְנוּ. אָמוֹר - שֶׁצָּרִיךְ לְכַוֵּן בְּכָל הַנִּסְתָּרִים הַלָּלוּ בְּכָל הַמַּעֲלוֹת הַלָּלוּ. אָמוֹר - בִּדְבָרִים נִסְתָּרִים שֶׁל מַעְלָה. אָמוֹר - חֶשְׁבּוֹן רמ\"ח אֵיבָרִים שֶׁבָּאָדָם חָסֵר אֶחָד. מָה הַטַּעַם? שֶׁבְּאֶחָד כֻּלָּם תְּלוּיִים. וְכֻלָּם מִתְבָּרְכִים בִּבְרָכָה זוֹ בִּשְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ כְּמוֹ שֶׁבֵּאַרְנוּ. לָהֶם - לִכְלֹל בִּבְרָכָה זוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, יוֹם אֶחָד יָשַׁבְתִּי לִפְנֵי רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן וְשָׁאַלְתִּי אוֹתוֹ, אָמַרְתִּי, רַבִּי, מָה רָאָה דָוִד שֶׁאָמַר (תהלים לו) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'? אָדָם מֵילָא, בְּהֵמָה לָמָּה? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ, הַכֹּל הוּא בְּמִנְיָן. זָכוּ - אָדָם. לֹא זָכוּ - בְּהֵמָה.</p>\n<p>אָמַרְתִּי, רַבִּי, סוֹד הַדָּבָר אֲנִי רוֹצֶה. אָמַר לוֹ, הַכֹּל נֶאֱמַר, וּבֹא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיִשְׂרָאֵל אָדָם, כְּדֻגְמָה שֶׁלְּמַעְלָה, וְקָרָא לָהֶם בְּהֵמָה, וְהַכֹּל בְּפָסוּק אֶחָד, שֶׁכָּתוּב וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי וְגוֹ'. (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי - הֲרֵי בְּהֵמָה. אָדָם אַתֶּם - הֲרֵי אָדָם. וְיִשְׂרָאֵל נִקְרְאוּ אָדָם וּבְהֵמָה, וּמִשּׁוּם זֶה אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. וְעוֹד סוֹד הַדָּבָר, זָכוּ - אָדָם כְּדֻגְמָה שֶׁלְּמַעְלָה, לֹא זָכוּ - נִקְרְאוּ בְהֵמָה, וְכֻלָּם מִתְבָּרְכִים בִּזְמַן אֶחָד - אָדָם שֶׁלְּמַעְלָה וּבְהֵמָה שֶׁלְּמַטָּה. וְכָל שֶׁכֵּן שֶׁהַכֹּל יֵשׁ בָּהֶם בְּיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'.</p>\n<p>וּבֹא רְאֵה, הַבְּרָכָה לֹא נִמְצֵאת לְמַטָּה עַד שֶׁתִּמָּצֵא לְמַעְלָה, וּמִשֶּׁנִּמְצְאָה לְמַעְלָה - גַּם לְמַטָּה נִמְצֵאת, וְהַכֹּל תָּלוּי כָּךְ לְטוֹב וּלְרַע. לְטוֹב, שֶׁכָּתוּב (הושע ב) אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. לְרַע, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, בִּגְלַל זֶה (התפארת הזו פתח בו) כָּתוּב אָמוֹר לָהֶם, סְתָם, לְהִתְבָּרֵךְ עֶלְיוֹנִים וְתַחְתּוֹנִים כֻּלָּם כְּאֶחָד, שֶׁכָּתוּב כֹּה תְבָרֲכוּ בַּתְּחִלָּה, וְאַחַר כָּךְ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם סְתָם, לְהִתְבָּרֵךְ כֻּלָּם כְּאֶחָד. יְבָרֶכְךְ ה' - לְמַעְלָה. וְיִשְׁמְרֶךְ - לְמַטָּה. יָאֵר ה' פָּנָיו - לְמַעְלָה. וִיחֻנֶּךָּ - לְמַטָּה. יִשָּׂא ה' פָּנָיו - לְמַעְלָה. וְיָשֵׂם לְךְ שָׁלוֹם - לְמַטָּה.</p>\n<p>רַבִּי אַבָּא אָמַר, כֻּלָּם מִתְבָּרְכִים כְּאֶחָד בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּכְלָל וְנִסְתָּר כָּאן, בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת כֻּלָּם מִתְבָּרְכִים. וְהֵם רַחֲמִים תּוֹךְ רַחֲמִים, שֶׁלֹּא נִמְצָא בָהֶם דִּין. וָלֹא? וַהֲרֵי כָּתוּב יִשָּׂא ה' פָּנָיו אֵלֶיךְ! אָמַר רַבִּי אַבָּא, יִשָּׂא - יְסַלֵּק וְיַעֲבִיר כְּדֵי שֶׁלֹּא יִמָּצֵא דִין כְּלָל.</p>"],[9522012290,"<p>לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו, אָסוּר לָעָם לְהִסְתַּכֵּל בּוֹ, מִשּׁוּם שֶׁשְּׁכִינָה שׁוֹרָה בְיָדָיו. אָמַר רַבִּי יִצְחָק, אִם כָּךְ, כֵּיוָן שֶׁלֹּא רוֹאִים, אָז מָה אִכְפַּת לָהֶם, שֶׁהֲרֵי כָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחַי, בְּחַיֵּיהֶם לֹא רוֹאִים, אֲבָל בְּמִיתָתָם רוֹאִים? אָמַר לוֹ, מִשּׁוּם שֶׁהַשֵּׁם הַקָּדוֹשׁ רָמוּז בְּאֶצְבְּעוֹת יָדָיו, וְצָרִיךְ הָאָדָם לִפְחֹד. אַף עַל גַּב שֶׁלֹּא רוֹאֶה שְׁכִינָה, לֹא צָרִיךְ לְהִסְתַּכֵּל עַל הַיָּדַיִם שֶׁל הַכֹּהֲנִים, כְּדֵי שֶׁהָעָם לֹא יִמָּצֵא בְחֻצְפָּה אֶל הַשְּׁכִינָה.</p>\n<p>לָמַדְנוּ, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו, צָרִיךְ הָעָם לָשׁוּב בְּיִרְאָה, בְּאֵימָה, וְלָדַעַת שֶׁאוֹתָהּ שָׁעָה עֵת רָצוֹן נִמְצָא בְּכָל הָעוֹלָמוֹת, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְאֵין דִּין בְּכֻלָּם, וְהִיא הַשָּׁעָה שֶׁמִּתְגַּלֶּה הַנִּסְתָּר עַתִּיק הָעַתִּיקִים בִּזְעֵיר אַנְפִּין, וְנִמְצָא שָׁלוֹם בַּכֹּל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּרָאשֵׁי שְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ יוֹ\"ד יוֹ\"ד יוֹ\"ד: יְ\"בָרֶכְךְ יָ\"אֵר יִ\"שָּׂא. כֻּלָּם לְהַרְאוֹת אֱמוּנָה הַשְּׁלֵמָה, וּלְהִתְבָּרֵךְ מֵהָעַתִּיק מִי שֶׁצָּרִיךְ. יוֹ\"ד יוֹ\"ד יוֹ\"ד, לְהִתְבָּרֵךְ זְעֵיר אַנְפִּין מֵעַתִּיק הַכֹּל. וּמִשּׁוּם כָּךְ, יְבָרֶכְךְ ה' לְמַעְלָה, וְיִשְׁמְרֶךְ הוּא לְמַטָּה, וְכֵן כֻּלָּם. וְשָׁנָה הַתַּנָּא לִפְנֵי רַבִּי שִׁמְעוֹן, מִי שֶׁמִּצְטַעֵר בַּחֲלוֹמוֹ, שֶׁיָּבא בְשָׁעָה שֶׁהַכֹּהֲנִים פּוֹרְשִׂים יְדֵיהֶם, וְיֹאמַר: רִבּוֹנוֹ שֶׁל עוֹלָם, אֲנִי שֶׁלְּךְ וַחֲלוֹמוֹתַי שֶׁלְּךְ וְכוּ'. לָמָּה? מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה נִמְצָאִים רַחֲמִים בְּכָל הָעוֹלָמוֹת, וּמִי שֶׁיְּבַקֵּשׁ תְּפִלָּתוֹ בְצַעֲרוֹ, מִתְהַפֵּךְ לוֹ דִּין לְרַחֲמִים.</p>"],[9522012291,"<p>מִצְוָה (כ\"ב) זוֹ לְבָרֵךְ הַכֹּהֵן אֶת הָעָם בְּכָל יוֹם בִּזְקִיפוּת הָאֶצְבָּעוֹת, וּלְבָרֵךְ בְּרָכָה בְּכָל יוֹם, לְהִמָּצֵא בְרָכוֹת מַעְלָה וּמַטָּה. שֶׁהֲרֵי הָאֶצְבָּעוֹת עוֹמְדוֹת בְּסוֹד עֶלְיוֹן, חָמֵשׁ תּוֹךְ חָמֵשׁ. חָמֵשׁ שֶׁל הַיָּמִין וְחָמֵשׁ שֶׁל שְׂמֹאל. חָמֵשׁ שֶׁל הַיָּמִין הֵן שֶׁבַח יוֹתֵר עַל אוֹתָן שֶׁל שְׂמֹאל, מִשּׁוּם שֶׁיָּמִין זוֹ יֵשׁ לָהּ שֶׁבַח יָתֵר עַל שְׂמֹאל. וְעַל זֶה בַּבְּרָכָה שֶׁמְּבָרֵךְ הַכֹּהֵן אֶת הָעָם, צָרִיךְ לִזְקֹף יָמִין עַל שְׂמֹאל וּלְעַיֵּן בְּעַיִן טוֹבָה.</p>\n<p>וּכְשֶׁפּוֹרֵשׂ הַכֹּהֵן אֶת יָדָיו, הַשְּׁכִינָה שׁוֹרָה עַל אוֹתָן הָאֶצְבָּעוֹת, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עִם הַכֹּהֵן בְּאוֹתָן בְּרָכוֹת. וְיִשְׂרָאֵל מִתְבָּרְכִים מִשְּׁנֵי צְדָדִים - מִלְמַעְלָה וּמִלְּמַטָּה. מִלְמַעְלָה - הַשְּׁכִינָה שֶׁשּׁוֹרָה עַל אוֹתָן אֶצְבָּעוֹת, וְהַכֹּהֵן שֶׁמְּבָרֵךְ.</p>\n<p>בֹּא רְאֵה, דְּבָרִים שֶׁעוֹשִׂים, מְעוֹרְרִים דְּבָרִים לְמַעְלָה. כְּמוֹ זֶה בִּפְרִישַׂת אֶצְבְּעוֹת הַכֹּהֵן לְמַטָּה, מִתְעוֹרֶרֶת הַשְּׁכִינָה לָבֹא וְלִשְׁרוֹת עָלֵינוּ. וְכֵן כַּמָּה דְבָרִים הֵם בָּעוֹלָם שֶׁמְּעוֹרְרִים דְּבָרִים לְמַעְלָה, שֶׁהֲרֵי בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר כֹּחַ אַחֵר לְמַעְלָה, וְזֶה בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת. וְהַיְנוּ טַעַם הַלּוּלָב וְהַיְנוּ טַעַם הַשּׁוֹפָר. וּכְמוֹ הֵם בְּגָוֶן זֶה עֶשֶׂר אֶצְבָּעוֹת מְעוֹרְרוֹת הַשְּׁכִינָה לִשְׁרוֹת עֲלֵיהֶן. מִתְעוֹרְרוֹת עֶשֶׂר מַעֲלוֹת אֲחֵרוֹת לְהָאִיר, וְהַכֹּל בְּשָׁעָה אַחַת.</p>\n<p>וְעַל כָּךְ אָסוּר לְבֶן אָדָם לִזְקֹף אֶצְבָּעוֹת בִּזְקִיפוּת לְחִנָּם, אֶלָּא בַּתְּפִלָּה וּבִבְרָכוֹת וּבַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי בֵּאַרְנוּ, שֶׁהֵם הַמְּעוֹרְרִים אֶת הַשֵּׁם הַקָּדוֹשׁ וְסוֹד הָאֱמוּנָה. זְקִיפוּת הָאֶצְבָּעוֹת, מְמֻנִּים בְּאוֹתָהּ זְקִיפוּת שֶׁלָּהֶן עֲשָׂרָה שַׁלִּיטִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַכֹּהֵן צָרִיךְ לְבָרֵךְ בְּעַיִן טוֹבָה בְּהַסְכָּמַת הַשְּׁכִינָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>בְּאוֹתָהּ שָׁעָה שֶׁבְּרָכָה זוֹ יוֹצֵאת מִפִּי הַכֹּהֵן, אוֹתָן שִׁשִּׁים אוֹתִיּוֹת יוֹצְאוֹת וְטָסוֹת בָּרָקִיעַ, וּמְמֻנִּים שִׁשִּׁים גְּדוֹלִים עַל כָּל אוֹת וְאוֹת, וְכֻלָּם מוֹדִים עַל כָּל הַבְּרָכוֹת הַלָּלוּ. מָה הַטַּעַם שִׁשִּׁים אוֹתִיּוֹת בַּבְּרָכוֹת הַלָּלוּ? מִשּׁוּם שֶׁיִּשְׂרָאֵל הֵם שִׁשִּׁים רִבּוֹא, וְסוֹד שִׁשִּׁים רִבּוֹא עוֹמְדִים בָּעוֹלָם, וְכָל אֶחָד וְאֶחָד הוּא (רבוא) אֶחָד.</p>\n<p>הַשֵּׁם הַקָּדוֹשׁ שֶׁיּוֹצֵא מִזֶּה עוֹלֶה לְמַעְלָה עַד אוֹתוֹ הַכִּסֵּא שֶׁלְּמַעְלָה. וְהַכֹּל, שְׁכִינָה עֶלְיוֹנָה וּשְׁכִינָה תַּחְתּוֹנָה, מוֹדִים לַכֹּהֵן בְּאוֹתָן הַבְּרָכוֹת וְעַל אוֹתָם שִׁשִּׁים מְמֻנִּים. וְעַל זֶה כָּתוּב, וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרֲכֵם. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אֶת יִשְׂרָאֵל. (ע\"כ רעיא מהימנא).</p>\n<p>מִצְוָה אַחַר זוֹ - בִּרְכַּת כֹּהֲנִים. יְבָרֶכְךְ ה', יָאֵר ה', יִשָּׂא ה'. מָקוֹר מִשְּׁלֹשָׁה שֵׁמוֹת אֵלּוּ: יוֹד הֵ\"א וָא\"ו הֵ\"א (יו\"ד ה\"י וא\"ו ה\"י). קְדֻשָּׁה, אֶהְיֶ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה, שֶׁמְּקוֹרוֹ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַקִּשּׁוּר שֶׁל שְׁנֵיהֶם, הַיִּחוּד שֶׁל שְׁנֵיהֶם - אֲדנָ\"י, שֶׁבּוֹ א\"י, שֶׁרְמוּזִים איהדונה\"י (יאהדונה\"י, וזה העמוד האמצעי, והשכינה היא יאהדונה\"י) (מקור מג' שמות אלו יו\"ד ה\"י וי\"ו ה\"י שרמוזים יאהדונה\"י, וזה העמוד האמצעי, השכינה איההדונה\"י) (אידהונה\"י), וּרְמוּזִים א\"י רְבִיעִי מִשְּׁנֵי שֵׁמוֹת מְפֹרָשִׁים שֶׁרְשׁוּמִים בָּהֶם.</p>"],[9522012292,"<p>וְשָׂמוּ אֶת שְׁמִי. מַה זֶּה וְשָׂמוּ אֶת שְׁמִי? אָמַר רַבִּי יְהוּדָה, יְתַקְּנוּ, כְּמוֹ שֶׁכָּתוּב (במדבר ד) וְשָׂמוּ אוֹתָם אִישׁ אִישׁ עַל עֲבדָתוֹ וְאֶל מַשָּׂאוֹ. לְהַתְקִין בְּבִרְכָתָם כְּתָרִים שֶׁל יָמִין לְיָמִין, וּכְתָרִים שֶׁל שְׂמֹאל לִשְׂמֹאל כָּרָאוּי, שֶׁצָּרִיךְ שֶׁלֹּא יִטְעוּ בָהֶם לְהַתְקִין הַכֹּל כְּדֵי שֶׁיִּתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וְאִם יַעֲשׂוּ כָּךְ, מַה כָּתוּב? וַאֲנִי אֲבָרַכֵם. לְמִי? לְאוֹתָם כֹּהֲנִים, שֶׁכָּתוּב (בראשית כז) וּמְבָרֲכֶיךְ בָּרוּךְ. וְכָתוּב (שם יב) וַאֲבָרְכָה מְבָרֲכֶיךְ. הֵם מְבָרְכִים אֶת הָעָם, וַאֲנִי אֲבָרֵךְ אוֹתָם, וּלְפִיכָךְ כָּתוּב וְשָׂמוּ, וְלֹא כָתוּב יֹאמְרוּ אוֹ יִזְכְּרוּ.</p>\n<p>לָמַדְנוּ, כָּל כֹּהֵן שֶׁלֹּא אוֹהֲבִים אוֹתוֹ הָעָם, לֹא יִפְרֹשׂ יָדָיו. וּמַעֲשֶׂה הָיָה בְּכֹהֵן אֶחָד שֶׁקָּם וּפָרַשׂ יָדָיו, וְעַד שֶׁלֹּא הִשְׁלִים נַעֲשָׂה גַּל עֲצָמוֹת. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא בֵרַךְ בַּחֲבִיבוּת. וְקָם אָחֵר וּפָרַשׂ יָדָיו וּבֵרַךְ, וְהִתְתַּקֵּן אוֹתוֹ הַיּוֹם. כָּל כֹּהֵן שֶׁאֵינוֹ אוֹהֵב אֶת הָעָם אוֹ הָעָם לֹא אוֹהֲבִים אוֹתוֹ, לֹא יִפְרֹשׂ יָדָיו לְבָרֵךְ אֶת הָעָם, שֶׁכָּתוּב (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ, אֶלָּא יְבָרֵךְ.</p>\n<p>לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, בֹּא וּרְאֵה מַה כָּתוּב בְּאוֹתוֹ בִּלְעָם הָרָשָׁע. בְּשָׁעָה שֶׁנִּמְסַר לוֹ לְבָרֵךְ אֶת יִשְׂרָאֵל, הָיָה מַשְׁגִּיחַ בְּעַיִן רָעָה כְּדֵי שֶׁלֹּא תִתְקַיֵּם הַבְּרָכָה, וְהָיָה תּוֹלֶה דְבָרָיו בְּאוֹתָהּ עַיִן רָעָה, שֶׁכָּתוּב (במדבר כד) נְאֻם בִּלְעָם בְּנוֹ בְעֹר. מַה זֶּה בְּנוֹ בְעֹר? מֵאוֹתוֹ שֶׁהָיָה שׂוֹנֵא אוֹתוֹ יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם. וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן, שֶׁסְּתוּם הָעַיִן טוֹב מֵהֶם, כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ וְלֹא תִתְקַיֵּם הַבְּרָכָה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, כָּךְ הוּא בְּוַדַּאי, שֶׁנִּמְצֵאת פְּתִיחַת (שנמצאת פקיחת) עַיִן לְבָרֵךְ, שֶׁכָּתוּב (דניאל ט) פְּקַח עֵינֶיךְ, כְּדֵי לְבָרֵךְ. וּבִרְכַּת רַב הַמְנוּנָא סָבָא כָּךְ הָיָה אוֹמֵר: הַקָּדוֹשׁ בָּרוּךְ הוּא יִפְקַח עֵינוֹ עָלֶיךְ. וּבְאוֹתוֹ רָשָׁע כָּתוּב שְׁתֻם הָעָיִן, כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ עַל יָדוֹ. וְאָמַר רַבִּי יִצְחָק, לָכֵן צָרִיךְ הַכֹּהֵן לְבָרֵךְ בְּעַיִן טוֹבָה, בִּרְכָתוֹ תִתְקַיֵּם. וְשֶׁלֹּא מְבָרֵךְ בְּעַיִן טוֹבָה, כָּתוּב (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עָיִן וְאַל תִּתְאָו לְמַטְעַמֹּתָיו. כְּלוֹמַר, אַל תְּבַקֵּשׁ מִמֶּנּוּ בְּרָכָה כְּלָל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, בּא רְאֵה, כָּתוּב (דברים כג) וְלֹא אָבָה ה' אֱלֹהֶיךְ לִשְׁמֹעַ אֶל בִּלְעָם וְגוֹ'. לִשְׁמֹעַ אֶל בִּלְעָם?! אֶל בָּלָק הָיָה צָרִיךְ לוֹ לִהְיוֹת, שֶׁהֲרֵי בָּלָק עָשָׂה הַכֹּל! מַה זֶּה אֶל בִּלְעָם? אֶלָּא מִשּׁוּם שֶׁהָיָה סוֹתֵם עֵינָיו כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ יִשְׂרָאֵל. לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְבִלְעָם: רָשָׁע, אַתָּה סוֹתֵם עֵינֶיךְ כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ בָנַי - אֲנִי אֶפְקַח עֵינַי, וְכָל הַדְּבָרִים שֶׁתֹּאמַר, אֶהְפֹּךְ אוֹתָם לִבְרָכָה. זֶהוּ שֶׁכָּתוּב (שם) וַיַּהֲפֹךְ ה' אֱלֹהֶיךְ לְּךְ אֶת הַקְּלָלָה לִבְרָכָה כִּי אֲהֵבְךְ וְגוֹ'.</p>\n<p>וְעַל כֵּן כָּתוּב, (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ כִּי נָתַן מִלַּחְמוֹ לַדָּל. מַה זֶּה מִלַּחְמוֹ? כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (ויקרא כא) לֶחֶם אֱלֹהָיו מִקָּדְשֵׁי הַקְּדָשִׁים וְגוֹ'. מַשְׁמָע שֶׁקָּדְשֵׁי הַקְּדָשִׁים, לֶחֶם אֱלֹהָיו יָצָא מִמֶּנּוּ, וְלָכֵן כִּי נָתַן מִלַּחְמוֹ לַדָּל. לָמַדְנוּ כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים מִתְבָּרְכִים רַק בִּגְלַל יִשְׂרָאֵל.</p>\n<p>שֶׁלְּמַדְנוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס בִּירוּשָׁלַיִם שֶׁל מַעְלָה עַד שֶׁיִּכָּנְסוּ יִשְׂרָאֵל בִּירוּשָׁלַיִם שֶׁל מַטָּה, שֶׁנֶּאֱמַר (הושע יא) בְּקִרְבְּךְ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר. כְּלוֹמַר, כָּל זְמַן שֶׁהַשְּׁכִינָה כָּאן בַּגָּלוּת, הַשֵּׁם שֶׁלְּמַעְלָה לֹא נִשְׁתַּלֵּם, וְכָל הַתִּקּוּנִים לֹא נִתְקְנוּ, כִּבְיָכוֹל נִשְׁאָר הַשֵּׁם הַקָּדוֹשׁ חָסֵר.</p>\n<p>רַבִּי אַבָּא הָיָה הוֹלֵךְ לְלוֹד, פָּגַע בּוֹ רַבִּי זֵירָא בַּר רַב. אָמַר לוֹ, הֲרֵי רָאִיתִי פְּנֵי הַשְּׁכִינָה, וּמִי שֶׁרוֹאֶה פְּנֵי הַשְּׁכִינָה, צָרִיךְ לָלֶכֶת וְלָרוּץ אַחֲרֶיהָ. זֶהוּ שֶׁכָּתוּב (הושעו) וְנֵדְעָה נִרְדְּפָה לָדַעַת אֶת ה'. וְכָתוּב (ישעיה ב) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' וְגוֹ'. כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה וְגוֹ'. וַאֲנִי רוֹצֶה לָלֶכֶת אַחֲרֶיךְ וְלִלְמֹד מֵאוֹתָם דְּבָרִים מְעֻלִּים שֶׁאַתֶּם טוֹעֲמִים כָּל יוֹם מֵהַחֶדֶר הַקָּדוֹשׁ.</p>"],[9522012293,"<p>מַה זֶּה שֶׁכָּתוּב, (בראשית טו) וְהֶאֱמִן בַּה' וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה? אִם הַקָּדוֹשׁ בָּרוּךְ הוּא חָשַׁב אוֹתָהּ לְאַבְרָהָם אוֹ אַבְרָהָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא? וַאֲנִי שָׁמַעְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָשַׁב אוֹתָהּ לְאַבְרָהָם, וְלֹא הִתְיַשֵּׁב בְּלִבִּי. אָמַר לוֹ, כָּךְ בֵּאַרְנוּ, וְלֹא הָיָה כָּךְ. בֹּא רְאֵה, וַיַּחְשְׁבֶהָ, לֹא כָתוּב וַיַּחְשֹׁב לוֹ, אֶלָּא וַיַּחְשְׁבֶהָ, וַדַּאי שֶׁאַבְרָהָם חָשַׁב אוֹתָהּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא. שֶׁלָּמַדְנוּ, כָּתוּב וַיּוֹצֵא אֹתוֹ הַחוּצָה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, צֵא מֵאִצְטַגְנִינוּת שֶׁלְּךְ, לֹא אוֹתָהּ הַדֶּרֶךְ לָדַעַת שְׁמִי, אַתָּה רוֹאֶה וַאֲנִי רוֹאֶה, אַבְרָם אֵינוֹ מוֹלִיד, אַבְרָהָם מוֹלִיד. מִכָּאן וָהָלְאָה הִשְׁתַּדְּלוּ בְדֶרֶךְ אַחֶרֶת, כֹּ\"ה יִהְיֶה זַרְעֶךְ. מַה זֶּה כֹּ\"ה? הִיא כֶּתֶר עֲשִׂירִי הַקָּדוֹשׁ שֶׁל הַמֶּלֶךְ לָדַעַת אֶת שְׁמוֹ, וְהִיא הַכֶּתֶר שֶׁהַדִּינִים מִתְעוֹרְרִים מִמֶּנָּה.</p>\n<p>וְלָמַדְנוּ, כֹּה יִהְיֶה זַרְעֶךְ מַמָּשׁ. בְּאוֹתָהּ שָׁעָה שָׂמַח אַבְרָהָם לְהִסְתַּכֵּל וְלָדַעַת אֶת שְׁמוֹ וּלְהִדָּבֵק בּוֹ, מִשּׁוּם שֶׁהִתְבַּשֵּׂר בְּכֹ\"ה, וְאַף עַל גַּב שֶׁמִּתְעוֹרְרִים מִמֶּנָּה הַדִּינִים, חָשַׁב אַבְרָהָם לְאוֹתוֹ הַכֶּתֶר, אַף עַל גַּב שֶׁהִיא דִין, כְּאִלּוּ הִיא רַחֲמִים. זֶהוּ שֶׁכָּתוּב וַיַּחְשְׁבֶהָ. מַה זֶּה וַיַּחְשְׁבֶהָ? אֶת אוֹתוֹ הַכֶּתֶר, צְדָקָה וְרַחֲמִים. אָמַר רַבִּי יִצְחָק, כֹּ\"ה הִיא כֶּתֶר עֲשִׂירִי, וְנִקְרֵאת צֶדֶק, וּמִמֶּנָּה מִתְעוֹרְרִים הַדִּינִים. וְאַבְרָהָם, אַף עַל גַּב שֶׁיָּדַע שֶׁמֵּהַצֶּדֶק הַזֶּה מִתְעוֹרְרִים הַדִּינִים, הוּא חָשַׁב אוֹתָהּ צְדָקָה שֶׁלֹּא מִתְעוֹרְרִים מִמֶּנָּה הַדִּינִים, בִּגְלַל שֶׁהִיא רַחֲמִים.</p>"],[9522012294,"<p>עוֹד אָמַר רַבִּי אַבָּא, מַה שֶּׁכָּתוּב (שם כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים א כט) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ. וְכָתוּב כֹּה תְבָרֲכוּ. שֶׁבִּגְלַל יִשְׂרָאֵל מִתְבָּרֶכֶת הַכֹּ\"ה עַל יְדֵי הַכֹּהֵן, בִּשְׁבִיל שֶׁיִּתְבָּרְכוּ יִשְׂרָאֵל לְמַטָּה, וְתִמָּצֵא בְרָכָה בַּכֹּל. וְלֶעָתִיד לָבֹא (כתוב) כְּמוֹ שֶׁנֶּאֱמַר, (תהלים קלד) יְבָרֶכְךְ ה' מִצִּיּוֹן וְגוֹ'. (שם קלה) בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם.</p>"],[9522012295,"<p>וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה וְגוֹ'. שָׁנָה רַבִּי יוֹסֵי, בַּיּוֹם שֶׁנִּכְנְסָה כַּלָּה לַחֻפָּה. בַּמָּה בֵּאַרְנוּ בְּיוֹם כַּלּוֹת מֹשֶׁה? אֶלָּא מְלַמֵּד שֶׁעַל יְדֵי מֹשֶׁה נִכְנְסָה. אָמַר רַבִּי יְהוּדָה, וְכִי עַד עַכְשָׁו הִתְעַכְּבָה שֶׁלֹּא נִכְנְסָה לִמְקוֹמָהּ, וַהֲרֵי כָּתוּב (שמות מ) וְלֹא יָכֹל מֹשֶׁה לָבוֹא אֶל אֹהֶל מוֹעֵד וְגוֹ'? אָמַר רַבִּי יִצְחָק, אֵין מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה.</p>\n<p>וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה, וַדַּאי כַּלָּתוֹ שֶׁל מֹשֶׁה. שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, מַהוּ שֶׁכָּתוּב (תהלים סח) עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי וְגוֹ'? אֶלָּא בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות ג) שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ, הִזְדַּעֲזַע הָהָר. אָמַר מִיכָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, הֲתִרְצֶה לִסְתֹּר אָדָם? וַהֲרֵי כָּתוּב (בראשית ה) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם, וְאֵין נִמְצֵאת הַבְּרָכָה אֶלָּא בְּמִי שֶׁהוּא זָכָר וּנְקֵבָה, וְאַתָּה אוֹמֵר לְהִפָּרֵד מֵאִשְׁתּוֹ?</p>\n<p>אָמַר לוֹ: הֲרֵי קִיֵּם מֹשֶׁה פְּרִיָּה וּרְבִיָּה, כָּעֵת אֲנִי רוֹצֶה שֶׁיִּשָּׂא אֶת הַשְּׁכִינָה, וּבִשְׁבִילוֹ תֵרֵד הַשְּׁכִינָה לָדוּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי. וּמַהוּ הַשֶּׁבִי? שְׁכִינָה שֶׁנִּשְׂאָה לְךְ. לָקַחְתָּ מַתָּנוֹת בָּאָדָם. בְּאָדָם לֹא כָתוּב, אֶלָּא בָּאָדָם הַיָּדוּעַ לְמַעְלָה. וּבַיּוֹם שֶׁיָּרְדָה הַשְּׁכִינָה, אוֹתוֹ יוֹם שֶׁנִּשְׂאָה לְמֹשֶׁה הִיא יָרְדָה, זֶהוּ שֶׁכָּתוּב כַּלּוֹת מֹשֶׁה, כַּלַּת מֹשֶׁה מַמָּשׁ.</p>\n<p>וּבִיהוֹשֻׁעַ שֶׁפָּנָיו כִּפְנֵי הַלְּבָנָה, כָּתוּב (יהושע ה) שַׁל נַעַלְךְ, שֶׁלֹּא נִפְרַד אֶלָּא בִּזְמַנִּים יְדוּעִים, שֶׁהֲרֵי הַשְּׁכִינָה לֹא נִשְׂאָה לוֹ כָּל כָּךְ וְלֹא נִרְאֲתָה לוֹ, שֶׁכָּתוּב (שם) וַיִּפֹּל יְהוֹשֻׁעַ אֶל (על) פָּנָיו אַרְצָה. אֲבָל כָּאן כַּלַּת מֹשֶׁה וַדַּאי. מַתָּנוֹת בָּאָדָם, מַתְּנַת כָּתוּב. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁרִבּוֹנוֹ חָפֵץ בִּיקָרוֹ עַל כָּל שְׁאָר בְּנֵי הָעוֹלָם.</p>"],[9522012296,"<p>וַיֹּאמֶר ה' אֶל מֹשֶׁה נָשִׂיא אֶחָד לַיּוֹם. מַהוּ לַיּוֹם? אָמַר רַבִּי יְהוּדָה, יָמִים שֶׁלְּמַעְלָה שֶׁהִתְחַנְּכוּ לְהִתְבָּרֵךְ בְּאוֹתָם שְׁנֵים עָשָׂר תְּחוּמִים שֶׁנִּפְרָדִים, וְכָל אֶחָד הִתְתַּקֵּן וְהִתְחַנֵּךְ בִּבְרָכָה עַל יְדֵי אוֹתָם שֶׁלְּמַטָּה. לָמַדְנוּ, כֻּלָּם מִתְבָּרְכִים בִּגְלַל מִזְבֵּחַ שֶׁלְּמַעְלָה, וַאֲפִלּוּ הַתַּחְתּוֹן, וַאֲפִלּוּ עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת מִתְבָּרְכִים.</p>\n<p>שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, אִלְמָלֵא לֹא הִקְרִיבוּ שְׁנֵים עָשָׂר נְשִׂיאִים אֵלּוּ, לֹא יָכֹל הָעוֹלָם לַעֲמֹד לִפְנֵי שְׁנֵים עָשָׂר נְשִׂיאֵי יִשְׁמָעֵאל, שֶׁכָּתוּב, (בראשית כה) שְׁנֵים עָשָׂר נְשִׂיאִים לְאֻמֹּתָם. מִשֶּׁהִקְרִיבוּ אֵלּוּ שֶׁל יִשְׂרָאֵל, לָקְחוּ שִׁלְטוֹן שֶׁל הַכֹּל, מִשּׁוּם כָּךְ נָשִׂיא אֶחָד לַיּוֹם.</p>\n<p>וְכָל מַה שֶּׁהִקְרִיבוּ, כְּדֻגְמָה שֶׁלְּמַעְלָה הִקְרִיבוּ, כְּדֵי שֶׁיִּתְבָּרְכוּ כֻלָּם. אֵילִם שִׁשִּׁים, עַתּוּדִים שִׁשִּׁים, כְּמוֹ שֶׁכָּתוּב (שיר השירים ג) שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ, שֶׁבְּצַד הַגְּבוּרָה. כַּף אַחַת עֲשָׂרָה זָהָב וְגוֹ', וַהֲרֵי נִתְבָּאֵר. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיק עֲלֵיהֶם בְּרָכוֹת וּמַקְשִׁיב לִתְפִלּוֹתֵיהֶם, וַעֲלֵיהֶם כָּתוּב (תהלים קב) פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָּתָם וְגוֹ'.</p>"],[9522012297,"<p>לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, עַד מָתַי נֵשֵׁב בְּקִיּוּם עַמּוּד אֶחָד? כָּתוּב (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תּוֹרָתֶךְ. הַיָּמִים קְטַנִּים, וּבַעֲלֵי הַחוֹב דּוֹחֵק. הַכָּרוֹז קוֹרֵא כָּל יוֹם, וְקוֹצְרֵי הַשָּׂדֶה קְטַנִּים הֵם, וְהֵם בְּשׁוּלֵי הַכֶּרֶם, לֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים לְאֵיזֶה מָקוֹם הוֹלְכִים כָּרָאוּי.</p>\n<p>הִתְכַּנְּסוּ הַחֲבֵרִים לְבֵית הָאִדְּרָא, לְבוּשִׁים שִׁרְיוֹן סַיִף, וּרְמָחִים בִּידֵיכֶם! הִזְדָּרְזוּ בְתִקּוּנֵיכֶם, בְּעֵצָה, בְּחָכְמָה, בְּשֵׂכֶל, בְּדַעַת, בְּמַרְאֶה, בַּיָּדַיִם, בָּרַגְלַיִם. הַמְלִיכוּ עֲלֵיהֶם לְמִי שֶׁבִּרְשׁוּתוֹ חַיִּים וּמָוֶת, לִגְזֹר דִּבְרֵי אֱמֶת, דְּבָרִים שֶׁקְּדוֹשִׁים עֶלְיוֹנִים מַקְשִׁיבִים לָהֶם וּשְׂמֵחִים לְשָׁמְעָם וְלָדַעַת אוֹתָם.</p>\n<p>יָשַׁב רַבִּי שִׁמְעוֹן וּבָכָה וְאָמַר, אוֹי אִם אֲגַלֶּה! אוֹי אִם לֹא אֲגַלֶּה! הַחֲבֵרִים שֶׁהָיוּ שָׁם שָׁתְקוּ. עָמַד רַבִּי אָמַר וְאָמַר לוֹ, אִם נוֹחַ לִפְנֵי מַר לְגַלּוֹת, הֲרֵי כָּתוּב (שם כה) סוֹד ה' לִירֵאָיו, וַהֲרֵי חֲבֵרִים אֵלּוּ הֵם יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּכְבָר נִכְנְסוּ בְּאִדְּרַת בֵּית הַמִּשְׁכָּן, מֵהֶם נִכְנְסוּ, מֵהֶם יָצְאוּ.</p>\n<p>שָׁנִינוּ, נִמְנוּ הַחֲבֵרִים לִפְנֵי רַבִּי שִׁמְעוֹן, וְנִמְצְאוּ רַבִּי אֶלְעָזָר בְּנוֹ, וְרַבִּי אַבָּא, וְרַבִּי יְהוּדָה, וְרַבִּי יוֹסֵי בַּר יַעֲקֹב, וְרַבִּי יִצְחָק, וְרַבִּי חִזְקִיָּה בַּר רַב, וְרַבִּי חִיָּיא, וְרַבִּי יוֹסֵי, וְרַבִּי יֵיסָא. יָדַיִם נָתְנוּ לְרַבִּי שִׁמְעוֹן, וְאֶצְבָּעוֹת זָקְפוּ לְמַעְלָה, וְנִכְנְסוּ בְשָׂדֶה בֵּין הָעֵצִים וְיָשְׁבוּ. קָם רַבִּי שִׁמְעוֹן וְהִתְפַּלֵּל תְּפִלָּתוֹ, יָשַׁב בְּתוֹכָם וְאָמַר, כָּל אֶחָד יָשִׂים יָדוֹ בְּחָזְקוֹ. שָׂמוּ יְדֵיהֶם, וְלָקַח אוֹתָם. פָּתַח וְאָמַר, (דברים כז) אָרוּר הָאִישׁ אֲשֶׁר יַעֲשֶׂה פֶסֶל וּמַסֵּכָה (וגו') מַעֲשֵׂה יְדֵי חָרָשׁ וְשָׂם בַּסָּתֶר וְעָנוּ כָל הָעָם וְאָמְרוּ אָמֵן.</p>\n<p>פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, עֵת לַעֲשׂוֹת לַה', מַדּוּעַ עֵת לַעֲשׂוֹת לַה'? מִשּׁוּם הֵפֵרוּ תּוֹרָתֶךְ. מַה זֶּה הֵפֵרוּ תּוֹרָתֶךְ? תּוֹרָה שֶׁלְּמַעְלָה שֶׁהִיא מִתְבַּטֶּלֶת אִם לֹא יַעֲשֶׂה בְּתִקּוּנֵי זֶה. וּלְעַתִּיק הַיָּמִים נֶאֱמַר. כָּתוּב (דברים לג) אַשְׁרֶיךְ יִשְׂרָאֵל מִי כָמוֹךְ, וְכָתוּב (שמות טו) מִי כָמוֹךְ בָּאֵלִים ה'.</p>\n<p>קָרָא לְרַבִּי אֶלְעָזָר בְּנוֹ, הוֹשִׁיבוֹ לְפָנָיו, וּלְרַבִּי אַבָּא מִצַּד אַחֵר, וְאָמַר, אָנוּ כְּלַל הַכֹּל. עַד עַכְשָׁו הִתְתַּקְּנוּ הָעוֹמְדִים. שָׁתְקוּ. שָׁמְעוּ קוֹל, וְאַרְכֻּבּוֹתֵיהֶם נָקְשׁוּ זֶה לָזֶה. אֵיזֶה קוֹל? קוֹל שֶׁל כְּנֻפְיָה הָעֶלְיוֹנָה שֶׁמִּתְכַּנְּסִים.</p>\n<p>שָׂמַח רַבִּי שִׁמְעוֹן וְאָמַר, (חבקוק ג) ה' שָׁמַעְתִּי שִׁמְעֲךְ יָרֵאתִי. שָׁם רָאוּי לִהְיוֹת יָרֵא. אָנוּ בַּחֲבִיבוּת תָּלוּי הַדָּבָר, שֶׁכָּתוּב (דברים ו) וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ, וְכָתוּב (שם ז) מֵאַהֲבַת ה' אֶתְכֶם, וְכָתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם וְגוֹ'.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יא) הוֹלֵךְ רָכִיל מְגַלֶּה סּוֹד וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. הוֹלֵךְ רָכִיל, פָּסוּק זֶה קָשֶׁה, אִישׁ רָכִיל הָיָה לוֹ לוֹמַר, מַה זֶּה הוֹלֵךְ? אֶלָּא מִי שֶׁלֹּא הִתְיַשֵּׁב בְּרוּחוֹ וְאֵינוֹ נֶאֱמָן, אוֹתוֹ דָּבָר שֶׁשָּׁמַע הוֹלֵךְ בְּתוֹכוֹ כְּקָנֶה בְמַיִם עַד שֶׁמּוֹצִיאוֹ הַחוּצָה. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵין רוּחוֹ רוּחַ שֶׁל עֲמִידָה. אֲבָל מִי שֶׁרוּחוֹ רוּחַ עֲמִידָה, כָּתוּב בּוֹ וְנֶאֱמַן רוּחַ מְכַסֶּה דָבָר. וְנֶאֱמַן רוּחַ, קִיּוּם הָרוּחַ. (כמו ותקעתיו יתד במקום נאמן) בָּרוּחַ (בסוד) הַדָּבָר תָּלוּי. וְכָתוּב (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ.</p>\n<p>וְאֵין הָעוֹלָם מִתְקַיֵּם אֶלָּא בְּסוֹד. וְכִי אִם בְּדִבְרֵי הָעוֹלָם צָרִיךְ סוֹד - בִּדְבָרִים סוֹדִיִּים שֶׁל סוֹדוֹת עַתִּיק הַיָּמִים שֶׁלֹּא נִמְסְרוּ אֲפִלּוּ לְמַלְאָכִים עֶלְיוֹנִים עַל אַחַת כַּמָּה וְכַמָּה. אָמַר רַבִּי שִׁמְעוֹן, לַשָּׁמַיִם לֹא אֹמַר שֶׁיַּקְשִׁיבוּ, לָאָרֶץ לֹא אֹמַר שֶׁתִּשְׁמַע, שֶׁהֲרֵי אָנוּ קִיּוּמֵי הָעוֹלָמוֹת. לָמַדְנוּ סוֹדֵי הַסּוֹדוֹת. כְּשֶׁפָּתַח רַבִּי שִׁמְעוֹן בְּסוֹדֵי הַסּוֹדוֹת, הִזְדַּעֲזַע הַמָּקוֹם, וְהַחֲבֵרִים הִתְחַלְחֲלוּ.</p>"],[9522012298,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר. דַּבֵּר אֶל אַהֲרֹן וְאָמַרְתָּ אֵלָיו בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (תהלים יט) וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בָהֶם, וְנָתַן לָהֶם תּוֹרַת אֱמֶת, עֵץ חַיִּים, שֶׁבּוֹ הָאָדָם אוֹחֵז (יורש) חַיִּים לָעוֹלָם הַזֶּה וְחַיִּים לָעוֹלָם הַבָּא. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְאוֹחֵז בָּהּ, יֵשׁ לוֹ חַיִּים (אוחז בחיים). וְכָל מִי שֶׁעוֹזֵב דִּבְרֵי הַתּוֹרָה וְנִפְרָד מֵהַתּוֹרָה, כְּאִלּוּ נִפְרָד מֵהַחַיִּים, מִשּׁוּם שֶׁהִיא חַיִּים, וְכָל דְּבָרֶיהָ חַיִּים. זֶהוּ שֶׁכָּתוּב (משלי ד) כִּי חַיִּים הֵם וְגוֹ'. וְכָתוּב (שם ג) רִפְאוּת תְּהִי לְשָׁרֶךְ וְגוֹ'.</p>\n<p>בֹּא רְאֵה, עֵץ הַחַיִּים אָחוּז מִמַּעְלָה לְמַטָּה. וְשֶׁמֶשׁ זוֹ שֶׁמְּאִירָה לַכֹּל, אוֹרָהּ מַתְחִיל מֵהָרֹאשׁ, וּמִתְפַּשֵּׁט בְּגוּף הָאִילָן בְּדֶרֶךְ יָשָׁר. שְׁנֵי צְדָדִים אֲחוּזִים בּוֹ, אֶחָד לַצָּפוֹן וְאֶחָד לַדָּרוֹם, אֶחָד יָמִין וְאֶחָד שְׂמֹאל, (והם) בְּשָׁעָה שֶׁמְּאִירָה הַשֶּׁמֶשׁ כְּמוֹ שֶׁנִּתְבָּאֵר, מֵאוֹתוֹ גּוּף (נוף) הָאִילָן, מְחַזֵּק לִזְרוֹעַ יָמִין וּמֵאִיר בְּתָקְפּוֹ, וּמִתָּקְפּוֹ מֵאִיר הַשְּׂמֹאל וְנִכְלָל בְּאוֹרוֹ.</p>\n<p>וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ. מַהִי חֻפָּתוֹ? זֶהוּ (שיר השירים א) עֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ בְּיוֹם חֲתֻנָּתוֹ. יֹצֵא מֵחֻפָּתוֹ - זֶהוּ רֹאשׁ שֶׁל כָּל אוֹר, כְּמוֹ שֶׁנֶּאֱמַר בַּפָּסוּק שֶׁלְּאַחֲרָיו, מִקְצֵה הַשָּׁמַיִם מוֹצָאוֹ. זוֹ רֵאשִׁית הַכֹּל שֶׁנִּקְרֵאת מִקְצֵה הַשָּׁמַיִם. וְאָז יצֵא כְּחָתָן מַמָּשׁ, כְּשֶׁיּוֹצֵא לִפְגֹּשׁ אֶת כַּלָּתוֹ אֲהוּבַת נַפְשׁוֹ, וּפוֹרֵשׂ זְרוֹעוֹתָיו וּמְקַבְּלָהּ.</p>\n<p>כְּמוֹ זֶה וְהוּא כְּחָתָן יֹצֵא מֵחֻפָּתוֹ, הוֹלֶכֶת הַשֶּׁמֶשׁ וּמִתְפַּשֶּׁטֶת לַמַּעֲרָב. כֵּיוָן שֶׁמַּעֲרָב מִתְקָרֵב, צַד צָפוֹן מִתְעוֹרֵר מוּלוֹ בַּתְּחִלָּה, וּמִתְקָרֵב לַמַּעֲרָב, וּמְזַוֵּג אוֹתוֹ בִּמְקוֹמוֹ, כְּמוֹ שֶׁנֶּאֱמַר שֶׁכָּתוּב (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי. וְאַחַר כָּךְ צַד דָּרוֹם, שֶׁהוּא יָמִין, שֶׁכָּתוּב וִימִינוֹ תְּחַבְּקֵנִי. אָז יָשִׂישׂ כְּגִבּוֹר לָרוּץ אֹרַח, לְהָאִיר הַלְּבָנָה, וּפֵרְשׁוּהָ. בֹּא רְאֵה, בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת - אֵלּוּ מְנוֹרוֹת עֶלְיוֹנוֹת שֶׁכֻּלָּן מְאִירוֹת כְּאַחַת מֵהַשֶּׁמֶשׁ.</p>"],[9522012299,"<p>רַבִּי אַבָּא פָּתַח, (תהלים פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה ה' בְּאוֹר פָּנֶיךְ יְהַלֵּכוּן. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ, אֲבָל בּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה הַקְּדוֹשָׁה, וְלִמְּדָם דְּרָכָיו לְהִתְדַּבֵּק בּוֹ, וְלִשְׁמֹר מִצְווֹת הַתּוֹרְה לִזְכּוֹת בָּהֶן לָעוֹלָם הַבָּא, וְקֵרְבָם בְּשָׁעָה שֶׁיָּצְאוּ מִמִּצְרַיִם, שֶׁהֲרֵי אָז הוֹצִיאָם מֵרְשׁוּת אַחֶרֶת, וְהֶעֱלָם לְהֵאָחֵז בִּשְׁמוֹ, וְאָז נִקְרְאוּ בְנֵי יִשְׂרָאֵל בְּנֵי חוֹרִין מֵהַכֹּל, שֶׁלֹּא יָשְׁבוּ תַּחַת רָשׁוּת אַחֶרֶת, וְהֶעֱלָם לְהֵאָחֵז בִּשְׁמוֹ, שֶׁעוֹלֶה עַל הַכֹּל, שֶׁשּׁוֹלֵט עַל עֶלְיוֹנִים וְתַחְתּוֹנִים.</p>\n<p>וּמִתּוֹךָ אַהֲבָתָם קָרָא לָהֶם (שמות ז) בְּנִי בְכֹרִי יִשְׂרָאֵל, כְּדֻגְמָה (של הקדשה) עֶלְיוֹנָה. (ועל זה) הָרַג (והרג) כָּל בְּכוֹר שֶׁלְּמַעְלָה וּמַטָּה, וְהִתִּיר קְשָׁרִים וַאֲסוּרִים שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים כְּדֵי לְהוֹצִיאָם, וַעֲשָׂאָם בְּנֵי חוֹרִין מֵהַכֹּל. וְעַל זֶה לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מַלְאָךְ וְלֹא שָׂרָף, אֶלָּא רַק הוּא. וְעוֹד, שֶׁהֲרֵי הוּא יָדַע לְהַבְחִין וְלָדַעַת הַכֹּל וּלְהַתִּיר אֲסוּרִים, וְאֵינָם בִּרְשׁוּת שָׁלִיחַ אַחֵר, אֶלָּא בְּיָדוֹ.</p>\n<p>בֹּא רְאֵה, בְּאוֹתוֹ לַיְלָה שֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג כָּל אוֹתָם בְּכוֹרוֹת כְּמוֹ שֶׁנֶּאֱמַר, בְּשָׁעָה שֶׁיָּרַד הַלַּיְלָה, בָּאוּ מְזַמְּרִים לְזַמֵּר לְפָנָיו. אָמַר לָהֶם, לֹא זְמַן הוּא, שֶׁהֲרֵי שִׁירָה אַחֶרֶת מְזַמְּרִים בָּנַי בָּאָ רֶץ. בְּשָׁעָה שֶׁנֶּחֱלַק הַלַּיְלָה הִתְעוֹרְרָה רוּחַ צָפוֹן, וְאָז עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא נְקָמוֹת, וְיִשְׂרָאֵל עוֹשִׂים שִׁירָה בְּקוֹל רָם, (וישראל מזמרים ואומרים הלל בקול רם) וְאָז עֲשָׂאָם בְּנֵי חוֹרִין מֵהַכֹּל, וּמַלְאָכִים עֶלְיוֹנִים וְכָל מַרְכְּבוֹתֵיהֶם הָיוּ מַקְשִׁיבִים לָהֶם לְקוֹלוֹת יִשְׂרָאֵל. אַחַר שֶׁנִּמּוֹלוּ, רָשְׁמוּ אֶת בָּתֵּיהֶם מֵאוֹתוֹ דָּם וּמִדַּם הַפֶּסַח בִּשְׁלֹשָׁה רִשּׁוּמִים: (שם יב) עַל הַמַּשְׁקוֹף וְעַל שְׁתֵּי הַמְּזוּזֹּת.</p>\n<p>מָה הַטַּעַם? הֲרֵי פֵּרְשׁוּהָ, מִשּׁוּם שֶׁהוּא רֹשֶׁם קָדוֹשׁ, וְהַמַּשְׁחִית כְּשֶׁהוּא יוֹצֵא וְרוֹאֶה אוֹתוֹ דָם שֶׁהָיָה רָשׁוּם עַל אוֹתוֹ פֶּתַח, חָס עַל יִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב וּפָסַח ה' עַל הַפֶּתַח וְגוֹ'. כָּאן יֵשׁ לְהִסְתַּכֵּל, אִם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא וְהָרַג בְּאֶרֶץ מִצְרַיִם וְלֹא שָׁלִיחַ אַחֵר, רֹשֶׁם זֶה שֶׁעַל הַפֶּתַח לְשֵׁם מָה, וַהֲרֵי הַכֹּל גָּלוּי לְפָנָיו? וְעוֹד, מַה זֶּה וְלֹא יִתֵּן הַמַּשְׁחִית? וְלֹא יַשְׁחִית צָרִיךְ לוֹ לִהְיוֹת!</p>\n<p>אֶלָּא וַדַּאי כָּךְ זֶה, שֶׁכָּתוּב (שם) וַה' הִכָּה כָל בְּכוֹר. וַה' - הוּא וּבֵית דִּינוֹ. וְאוֹתוֹ בֵּית דִּין כָּאן נִמְצָא. (מכאן שבכל) וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה כְּדֵי לְהִנָּצֵל, שֶׁהֲרֵי כְּגוֹן זֶה עַל הַמִּזְבֵּחַ, כְּדֵי שֶׁלֹּא יִמָּצֵא הַמַּשְׁחִית.</p>\n<p>זֶה בְמַעֲשֶׂה, וּבִזְמַן שֶׁלֹּא צָרִיךְ אֶת זֶה, כְּמוֹ רֹאשׁ הַשָּׁנָה, שֶׁהוּא יוֹם הַדִּין, וּבַעֲלֵי לָשׁוֹן הָרָע עוֹמְדִים עַל יִשְׂרָאֵל, צְרִיכִים דְּבָרִים, תְּפִלּוֹת וּבַקָּשׁוֹת, וּצְרִיכִים לְהַרְאוֹת מַעֲשֶׂה (ברוח ונפש) כְּמוֹ שֶׁבֵּאַרְנוּ, וַהֲרֵי נִתְבָּאֵר. וּבַמֶּה? בַּשּׁוֹפָר, (להראותשופר) לְעוֹרֵר שׁוֹפָר אַחֵר. וְאָנוּ מוֹצִיאִים בְּאוֹתוֹ קוֹל רַחֲמִים וְדִין כְּאֶחָד, הַכֹּל כָּרָאוּי. כְּמוֹ שֶׁלְּאוֹתוֹ שׁוֹפָר עֶלְיוֹן מוֹצִיא קוֹל שֶׁהוּא כְּלָל שֶׁל אֶחָד. וּלְעוֹרֵר רַחֲמִים אָנוּ הוֹלְכִים, וְלִשְׁבֹּר אֶת בַּעֲלֵי הַדִּין שֶׁלֹּא יִשְׁלְטוּ בַּיּוֹם הַזֶּה. וּכְשֶׁמִּתְעוֹרְרִים הָרַחֲמִים, כָּל הַמְּנוֹרוֹת הָעֶלְיוֹנוֹת מְאִירוֹת מִצַּד זֶה וּמִצַּד זֶה, וְאָז (משלי טז) בְּאוֹר פְּנֵי מֶלֶךְ חַיִּים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁהַכֹּהֵן (הגדול) מִתְכַּוֵּן לְהַדְלִיק נֵרוֹת לְמַטָּה וְהָיָה מַקְרִיב קְטֹרֶת בְּשָׂמִים, בְּאוֹתָהּ שָׁעָה אָז מְנוֹרוֹת עֶלְיוֹנוֹת מְאִירוֹת, וְנִקְשָׁר הַכֹּל כְּאֶחָד, וְשִׂמְחָה וְחֶדְוָה נִמְצֵאת בְּכָל הָעוֹלָמוֹת. זֶהוּ שֶׁכָּתוּב (שם כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, וְעַל זֶה בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת.</p>"],[9522012300,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ. פָּגְעוּ בְּאוֹתָם הָרֵי קַרְדוֹ. עַד שֶׁהָיוּ הוֹלְכִים, הֵרִים רַבִּי אֶלְעָזָר עֵינָיו, וְרָאָה אוֹתָם הָרִים רָמִים, וְהָיוּ חֲשׁוּכִים, וּפָחֲדוּ בְפַחַד. אָמַר רַבִּי אֶלְעָזָר לְאוֹתָם חֲבֵרִים, אִלּוּ אַבָּא כָּאן, לֹא הָיִינוּ פוֹחֲדִים. אֲבָל כֵּיוָן שֶׁאָנוּ שְׁלֹשָׁה וְדִבְרֵי תוֹרָה בֵּינֵינוּ, הַדִּין כָּאן לֹא נִמְצָא.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, כָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ', עַל הָרֵי אֲרָרָט וְגוֹ'. כַּמָּה חֲבִיבִים דִּבְרֵי הַתּוֹרָה, שֶׁבְּכָל דָּבָר וְדָבָר יֵשׁ סוֹדוֹת עֶלְיוֹנִים, וְהַתּוֹרָה כֻּלָּהּ נִקְרֵאת עֶלְיוֹנָה. וְשָׁנִינוּ בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל הַתּוֹרָה: כָּל דָּבָר שֶׁהָיָה בִכְלָל וְיָצָא מִן הַכְּלָל לְלַמֵּד, לֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. שֶׁהֲרֵי הַתּוֹרָה, שֶׁהִיא כְּלָל עֶלְיוֹן, אַף עַל גַּב שֶׁיּוֹצֵא מִמֶּנָּה סִפּוּר אֶחָד בָּעוֹלָם, וַדַּאי לֹא בָאָה לְהַרְאוֹת אֶת אוֹתוֹ סִפּוּר, אֶלָּא לְהַרְאוֹת דְּבָרִים עֶלְיוֹנִים וְסוֹדוֹת עֶלְיוֹנִים. וְלֹא לְלַמֵּד עַל עַצְמוֹ יָצָא, אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. מִשּׁוּם שֶׁאוֹתוֹ סִפּוּר שֶׁל הַתּוֹרָה אוֹ אוֹתוֹ מַעֲשֶׂה, אַף עַל גַּב שֶׁהוּא יוֹצֵא מִכְּלַל הַתּוֹרָה, לֹא לְהַרְאוֹת עַל עַצְמוֹ יָצָא בִּלְבַד, אֶלָּא לְהַרְאוֹת עַל אוֹתוֹ כְּלָל עֶלְיוֹן שֶׁל הַתּוֹרָה כֻּלָּהּ יָצָא.</p>\n<p>כְּגוֹן זֶה, שֶׁכָּתוּב (בראשית ח) וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ עַל הָרֵי אֲרָרָט. וַדַּאי פָּסוּק זֶה יָצָא מִכְּלַל הַתּוֹרָה, וּבָא בְּסִפּוּר הָעוֹלָם. מָה אִכְפַּת לָנוּ אִם שׁוֹרֶה בָזֶה אוֹ בָזֶה, שֶׁהֲרֵי בְּמָקוֹם אֶחָד שֶׁיִּשְׁרֶה? אֶלָּא לְלַמֵּד עַל הַכְּלָל כֻּלּוֹ יָצָא. וְאַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁנִּתְּנָה לָהֶם תּוֹרָה עֶלְיוֹנָה תּוֹרַת אֱמֶת. וּמִי שֶׁאוֹמֵר שֶׁאוֹתוֹ סִפּוּר שֶׁל הַתּוֹרָה, לְהַרְאוֹת עַל אוֹתוֹ סִפּוּר בִּלְבַד הוּא בָּא - תִּפַּח רוּחוֹ. שֶׁאִם כָּךְ, הִיא אֵינָהּ תּוֹרָה עֶלְיוֹנָה, תּוֹרַת אֱמֶת, אֶלָּא וַדַּאי תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה הִיא תּוֹרַת אֱמֶת.</p>\n<p>בֹּא רְאֵה, מֶלֶךְ בָּשָׂר וָדָם לֹא מִכְּבוֹדוֹ לְדַבֵּר דִּבְרֵי הֶדְיוֹט, כָּל שֶׁכֵּן לְכָתְבָם. וְאִם עוֹלֶה בְדַעְתְּךְ שֶׁמֶּלֶךְ עֶלְיוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הָיוּ לוֹ דְּבָרִים קְדוֹשִׁים לִכְתֹּב וְלַעֲשׂוֹת מֵהֶם תּוֹרָה, אֶלָּא שֶׁהוּא כִּנֵּס דִּבְרֵי הֶדְיוֹטוֹת, כְּמוֹ דִּבְרֵי עֵשָׂו, דִּבְרֵי הָגָר, דִּבְרֵי לָבָן בְּיַעֲקֹב, דִּבְרֵי הָאָתוֹן, דִּבְרֵי בִלְעָם, דִּבְרֵי בָלָק, דִּבְרֵי זִמְרִי, וְכִנְּסָם, וְכָל שְׁאָר הַסִּפּוּרִים שֶׁכְּתוּבִים, וְעָשָׂה מֵהֶם תּוֹרָה.</p>\n<p>אִם כָּךְ, לָמָּה נִקְרֵאת תּוֹרַת אֱמֶת, (תהלים יט) תּוֹרַת ה' תְּמִימָה, עֵדוּת ה' נֶאֱמָנָה, פִּקּוּדֵי ה' יְשָׁרִים, מִצְוַת ה' בָּרָה, יִרְאַת ה' טְהוֹרָה, מִשְׁפְּטֵי ה' אֱמֶת, וְכָתוּב הַנֶּחֱמָדִים מִזָּהָב וּמִפָּז רָב, אֵלֶּה אוֹתָם דִּבְרֵי תוֹרָה? אֶלָּא וַדַּאי תּוֹרָה קְדוֹשָׁה עֶלְיוֹנָה הִיא תּוֹרַת אֱמֶת, תּוֹרַת ה' תְּמִימָה, וְכָל דָּבָר וְדָבָר בָּא לְהַרְאוֹת דְּבָרִים (אחרים) עֶלְיוֹנִים. שֶׁאוֹתוֹ דָּבָר שֶׁל אוֹתוֹ סִפּוּר לֹא לְהַרְאוֹת עַל עַצְמוֹ יָצָא בִּלְבַד בָּא, אֶלָּא לְהַרְאוֹת עַל אוֹתוֹ כְּלָל הוּא בָּא, כְּמוֹ שֶׁבֵּאַרְנוּ.</p>\n<p>בֹּא רְאֵה, וַתָּנַח הַתֵּבָה וְגוֹ'. פָּסוּק זֶה כָּךְ, כָּל שֶׁכֵּן אֲחֵרִים, (הפסוק הזה כך הוא, והרי נתבאר) בְּשָׁעָה שֶׁדִּין תָּלוּי עַל הָעוֹלָם וְהַדִּינִים שְׁרוּיִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא דִין לָדוּן הָעוֹלָם בְּאוֹתוֹ כִּסֵּא, כַּמָּה רִשּׁוּמִים נִרְשְׁמוּ בוֹ, כַּמָּה פְתָקִים גְּנוּזִים בְּתוֹכוֹ בְּתוֹךְ תִּיק הַמֶּלֶךְ. כָּל הַסְּפָרִים שֶׁפְּתוּחִים שָׁם נִגְנְזוּ, וּמִשּׁוּם כָּךְ לֹא נִשְׁכַּח דָּבָר מֵהַמֶּלֶךְ, וְכִסֵּא זֶה לֹא נִתְקָן וְלֹא שׁוֹרֶה אֶלָּא בַּחֹדֶשׁ הַשְּׁבִיעִי, שֶׁהוּא יוֹם הַדִּין, יוֹם שֶׁבּוֹ כָּל בְּנֵי הָעוֹלָם נִפְקָדִים בּוֹ, כֻּלָּם עוֹבְרִים לִפְנֵי אוֹתוֹ כִּסֵּא. וְעַל זֶה וַתָּנַח הַתֵּבָה בַּחֹדֶשׁ הַשְּׁבִיעִי, בַּחֹדֶשׁ הַשְּׁבִיעִי וַדַּאי, שֶׁהוּא דִּין הָעוֹלָם.</p>\n<p>עֵל הָרֵי אֲרָרָט - אֵלּוּ (עמודי הכסא) בַּעֲלֵי הַדִּין, בַּעֲלֵי יְבָבָה וִילָלָה, וְכֻלָּם שְׁלוּחִים (שכלם שקטים) בְּאוֹתוֹ יוֹם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכַמָּה בַּעֲלֵי מָגִנִּים מִתְעוֹרְרִים בְּיוֹם זֶה, וְכֻלָּם עוֹמְדִים תַּחַת אוֹתוֹ כִּסֵּא בְּדִין הָעוֹלָם.</p>\n<p>וְיִשְׂרָאֵל מִתְפַּלְלִים תְּפִלָּה בְּאוֹתוֹ יוֹם, וּמְבַקְשִׁים וּמִתְחַנְּנִים לְפָנָיו, וְתוֹקְעִים בַּשּׁוֹפָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וְהוֹפֵךְ דִּין לְרַחֲמִים, וְכָל עֶלְיוֹנִים וְתַחְתּוֹנִים פּוֹתְחִים וְאוֹמְרִים: (שם פט) אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה. וְעַל זֶה צָרִיךְ בְּאוֹתוֹ הַיּוֹם, שֶׁאוֹתוֹ שֶׁתּוֹקֵעַ שֶׁיֵּדַע עִקַּר הַדָּבָר, וִיכַוֵּן בָּהּ בִּתְרוּעָה, וְיַעֲשֶׂה הַדָּבָר בְּחָכְמָה, וְעַל זֶה כָּתוּב אַשְׁרֵי הָעָם יוֹדְעֵי תְרוּעָה, וְלֹא כָתוּב תּוֹקְעֵי תְרוּעָה, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012301,"<p>הָלְכוּ כָּל אוֹתוֹ יוֹם. כְּשֶׁיָּרַד הַלַּיְלָה עָלוּ לְמָקוֹם אֶחָד, וּמָצְאוּ מְעָרָה אַחַת. אָמַר רַבִּי אֶלְעָזָר, יִכָּנֵס אֶחָד לְתוֹךְ הַמְּעָרָה, אִם נִמְצָא מָקוֹם שֶׁהוּא יוֹתֵר מְתֻקָּן. נִכְנַס רַבִּי יוֹסֵי, וְרָאָה מְעָרָה אַחֶרֶת בְּתוֹכָהּ, אוֹר הַנֵּר בָּהּ. שָׁמַע קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת אֶל מוּל פְּנֵי הַמְּנוֹרָה יָאִירוּ שִׁבְעַת הַנֵּרוֹת. כָּאן לָקְחָה כְּנֶסֶת יִשְׂרָאֵל אוֹר, וְהָאֵם הָעֶלְיוֹנָה מִתְעַטֶּרֶת, וְכָל הַנֵּרוֹת מִמֶּנָּה מְאִירִים. בָּהּ שְׁתֵּי שַׁלְהָבוֹת דַּקִּיקוֹת פּוֹרְחוֹת, כֻּלָּם שׁוֹשְׁבִינִים (מסרגים) קְשׁוּרִים לָעֶלְיוֹנָה, וּמִשָּׁם לְמַטָּה.</p>\n<p>שָׁמַע רַבִּי יוֹסֵי וְשָׂמַח. בָּא אֶל רַבִּי אֶלְעָזָר. אָמַר לוֹ רַבִּי אֶלְעָזָר, נִכָּנֵס, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִקְדִּימָנוּ הַיּוֹם הַזֶּה לְהַרְחִישׁ לָנוּ בְנִסִּים. נִכְנְסוּ. כֵּיוָן שֶׁנִּכְנְסוּ, רָאוּ שְׁנֵי בְּנֵי אָדָם שֶׁהָיוּ עוֹסְקִים בַּתּוֹרָה. אָמַר רַבִּי אֶלְעָזָר, (תהלים לו) מַה יָּקָר חַסְדְּךְ אֱלֹהִים וּבְנֵי אָדָם בְּצֵל כְּנָפֶיךְ יֶחֱסָיוּן. קָמוּ אֵלֶּה, וְיָשְׁבוּ כֻלָּם, וְשָׂמְחוּ כֻלָּם. אָמַר רַבִּי אֶלְעָזָר, מַה יָּקָר חַסְדְּךְ אֱלֹהִים, שֶׁמָּצָאנוּ אֶתְכֶם. חֶסֶד עָשָׂה לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמָקוֹם זֶה. עַכְשָׁו הַדְלִיקוּ נֵרוֹת.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, בְּהַעֲלֹתְךְ אֶת הַנֵּרֹת, בְּהַעֲלֹתְךְ מַמָּשׁ, בְּהַדְלָקָתְךְ. שֶׁהֲרֵי כְּאַחַת נַעֲשׂוֹת עַל יְדֵי הַכֹּהֵן שְׁתֵּי עֲבוֹדוֹת, שֶׁהֵן קֶשֶׁר אֶחָד, וּמָהֵן? שֶׁמֶן וּקְטֹרֶת, כְּמוֹ שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב, שֶׁכָּתוּב (שמות ל) וְהִקְטִיר עָלָיו אַהֲרֹן וְגוֹ'. וְכָתוּב וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה. מַה שּׁוֹנֶה כָּאן בְּהֵיטִיבוֹ, וּמַה שּׁוֹנֶה שָׁם וּבְהַעֲלֹת? אָמַר רַבִּי יְהוּדָה, הַכֹּל דָּבָר אֶחָד.</p>\n<p>רַבִּי יוֹסֵי אָמַר, בְּהֵיטִיבוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שיר השירים א) כִּי טוֹבִים דֹּדֶיךְ מִיָּיִן. טוֹבִים - רְווּיֵי יַיִן, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה מד) וַנִּשְׂבַּע לֶחֶם וַנִּהְיֶה טוֹבִים. רַבִּי יְהוּדָה אָמַר, הֲטָבָה מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָמִיד. וּבְהַעֲלֹת, שֶׁהֲרֵי בִּזְמַן שֶׁמֻּשְׁקִים וּמֻרְוִים מֵהַשְׁקָאַת הַנַּחַל, אָז עֶלְיוֹנִים מִתְעַלִּים, וּבְרָכוֹת (עליונות ותחתונות) נִמְצָאוֹת בְּכֻלָּם, וּשְׂמֵחִים בַּכֹּל. וְעַל זֶה וּבְהַעֲלֹת.</p>\n<p>רַבִּי אָחָא אָמַר, בְּשָׁעָה שֶׁעֹמֶק הַכֹּל מֵאִיר, (שסתום הכל מאיר) מֵאִיר בַּנַּחַל, וְהַנַּחַל שׁוֹפֵעַ (מאיר) בְּדֶרֶךְ יָשָׁר לְהַשְׁקוֹת הַכֹּל, וְאָז כָּתוּב בְּהַעֲלֹת (בהיטיבו), מִשּׁוּם שֶׁזֶּה יוֹצֵא מֵעֹמֶק הַכֹּל. בְּהַעֲלֹת, שֶׁבָּא מִצַּד עֶלְיוֹן שֶׁל עֹמֶק (של סתום) הַכֹּל שֶׁנִּקְרָא מַחֲשָׁבָה. וְהַכֹּל דָּבָר אֶחָד. וְאָז כְּנֶסֶת יִשְׂרָאֵל מִתְבָּרֶכֶת, וּבְרָכוֹת נִמְצָאוֹת בְּכָל הָעוֹלָמוֹת.</p>"],[9522012302,"<p>רַבִּי יִצְחָק פָּתַח, כָּתוּב (מלכים א ח) בָּנֹה בָּנִיתִי בֵּית זְבֻל לָךְ מָכוֹן לְשִׁבְתְּךְ עוֹלָמִים. בֵּית זְבֻל, בֵּית זְבוּל וַדַּאי. כְּשֶׁנִּפְקְדוּ בְיָדֶיהָ כָּל גִּנְזֵי הַמֶּלֶךְ וְשׁוֹלֶטֶת בָּהֶם, אָז נִקְרָא בֵית זְבוּל. וְרָקִיעַ אֶחָד יֵשׁ שֶׁנִּקְרָא זְבוּל, שֶׁהֲרֵי זֶה נִמְצָא לְקַבֵּל בְּרָכוֹת וּלְסַדֵּר הַכֹּל, וְזֶה נִקְרָא בֵּית זְבוּל.</p>\n<p>בֹּא רְאֵה, כָּתוּב (דברים לג) וְלִזְבוּלֻן אָמַר שְׂמַח זְבוּלֻן בְּצֵאתֶךְ וְיִשָּׂשכָר בְּאָהֳלֶךְ. מְלַמֵּד שֶׁהִשְׁתַּתְּפוּ כְאֶחָד. זֶה יוֹצֵא וְעוֹרֵךְ קְרָב, וְזֶה יוֹשֵׁב וְעוֹסֵק בַּתּוֹרָה, וְזֶה נוֹתֵן חֵלֶק לָזֶה, וְזֶה נוֹתֵן חֵלֶק לָזֶה. בְּחֵלֶק זְבוּלוּן הַיָּם, וּכְנֶסֶת יִשְׂרָאֵל נִקְרֵאת יָם כִּנֶּרֶת. וְכָךְ רָאוּי, מִשּׁוּם שֶׁתְּכֵלֶת זוֹ יוֹצֵאת מִשָּׁם, וּפֵרְשׁוּהָ, שֶׁהֲרֵי לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה. יָם כִּנֶּרֶת לְמַעְלָה - יָם כִּנֶּרֶת לְמַטָּה, תְּכֵלֶת לְמַעְלָה - תְּכֵלֶת לְמַטָּה, וְהַכֹּל בְּמָקוֹם אֶחָד.</p>\n<p>וְעַל זֶה יָרַשׁ זְבוּלוּן, לָצֵאת לַעֲרֹךְ קְרָב. וּמִנַּיִן לָנוּ שֶׁכָּךְ זֶה? שֶׁכָּתוּב (שם) עַמִּים הַר יִקְרָאוּ שָׁם יִזְבְּחוּ זִבְחֵי צֶדֶק. זִבְחֵי צֶדֶק בְּוַדַּאי. מָה הַטַּעַם? כִּי שֶׁפַע יַמִּים יִינָקוּ. וְיִשָּׂשכָר חֶלְקוֹ בַתּוֹרָה, וְנוֹתֵן לִזְבוּלוּן חֵלֶק שֶׁל הַתּוֹרָה בְּוַדַּאי. וְעַל זֶה הִשְׁתַּתְּפוּ כְאֶחָד, לְהִתְבָּרֵךְ זְבוּלוּן מִיִּשָּׂשכָר, שֶׁבִּרְכַּת הַתּוֹרָה הִיא בִּרְכַּת הַכֹּל.</p>\n<p>רַבִּי אַבָּא אָמַר, יְרֻשַּׁת הַתּוֹרָה בְּוַדַּאי כָּךְ הִיא, וְדַרְגָּה שִׁשִּׁית זוֹ נוֹתֶנֶת שְׂכַר (ששית אחת נותנת שכר) תּוֹרָה, וּמוֹרִישָׁה לָהּ לִכְנֶסֶת יִשְׂרָאֵל, מוֹרִישׁ הַלָּבָן לַתְּכֵלֶת. וְעַל זֶה שָׁנִינוּ, (ברכות א) מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן, שֶׁיִּוָּדְעוּ הַגְּוָנִים, שֶׁהֲרֵי אָז נִקְרָא בֹּקֶ\"ר, וְהַלֹּבֶן בָּא לָעוֹלָם, וְהַתְּכֵלֶת נֶעֱבַר. וְעַל זֶה כָּל קְרָבוֹת הַמֶּלֶךְ וְכָל כְּלֵי זֵין הַמֶּלֶךְ נִמְנוּ בְיָדֶיהָ, וַהֲרֵי בֵּאַרְנוּ.</p>"],[9522012303,"<p>בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. בְּאֵר - זוֹ כְּנֶסֶת יִשְׂרָאֵל. חֲפָרוּהָ שָׂרִים - זֶה אַבָּא וְאִמָּא שֶׁהוֹלִידוּ אוֹתָהּ. כָּרוּהָ נְדִיבֵי הָעָם - אֵלּוּ הָאָבוֹת, שֶׁכָּתוּב (תהלים מז) נְדִיבֵי עַמִּים נֶאֱסָפוּ עַם אֱלֹהֵי אַבְרָהָם וְגוֹ'. בִּשְׁבִיל לְהִתְבָּרֵךְ מֵהֶם עַל יְדֵי דַרְגָּה אַחֶרֶת. וּמִי הַדַּרְגָּה? צַדִּיק שֶׁעוֹמֵד עָלֶיהָ. וְעַל זֶה אָמַרְנוּ, כְּשֶׁבְּאֵר זוֹ נוֹטֶלֶת - בְּסִיּוּעַ הָאָבוֹת נוֹטֶלֶת.</p>\n<p>וְנִקְרֵאת בְּאֵר, וְנִקְרֵאת יָם. נִקְרֵאת בְּאֵר בְּשָׁעָה שֶׁיִּצְחָק יוֹצֵא מְזֻיָּן מִצַּד אִמָּא וּבָא לְהַמְשִׁיךְ אַחֲרֵי זֶה וּמְמַלֵּא אוֹתָהּ, אָז נִקְרֵאת בְּאֵר יִצְחָק, בְּאֵר מִרְיָם, וַהֲרֵי בֵּאַרְנוּ. יָם, כְּשֶׁמְּאִירָה מֵאוֹר עֶלְיוֹן שֶׁל אַבָּא, אָז נִקְרֵאת יָם, שֶׁנְּחָלִים הוֹלְכִים לְתוֹכָהּ, כְּמוֹ שֶׁנֶּאֱמַר (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא.</p>\n<p>וּמִיּוֹם שֶׁגָּלְתָה כְּנֶסֶת יִשְׂרָאֵל בַּגָּלוּת, כָּתוּב (איוב יד) אָזְלוּ מַיִם מִנִּי יָם - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְנָהָר יֶחֱרַב וְיָבֵשׁ - זֶה צַדִּיק. וְעַל זֶה כָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד וְגוֹ'. שֶׁהוּא הָיָה נָהָר עֶלְיוֹן וּמְכֻבָּד שֶׁנִּכְנָס לְתוֹכָהּ, וְהוּא כּוֹנֵס כָּל אוֹתָם נְהָרוֹת וּנְחָלִים שֶׁשּׁוֹפְעִים מִשֶּׁפַע אוֹתוֹ נָהָר קָדוֹשׁ שֶׁלֹּא פוֹסְקִים מֵימָיו לְעוֹלָמִים, שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן הָעֶלְיוֹן, וְהוּא נִכְנָס לְתוֹכָהּ וּמְמַלֵּא אֲגַמֶּיהָ, וּמִשָּׁם יוֹרְשִׁים כָּל הָעוֹלָמוֹת (נזונו ויורשים) בְּרָכוֹת בַּכֹּל.</p>"],[9522012304,"<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁמִּתְבָּרֶכֶת כְּנֶסֶת יִשְׂרָאֵל, כָּל הָעוֹלָמוֹת מִתְבָּרְכִים, וְיִשְׂרָאֵל לְמַטָּה יוֹנְקִים וּמִתְבָּרְכִים בִּגְלָלָהּ. וַהֲרֵי בֵּאַרְנוּ שֶׁהִיא מְגִנָּה עַל יִשְׂרָאֵל, כְּמוֹ שֶׁנִּתְבָּאֵ ר.</p>\n<p>כָּתוּב (שמות יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ וְגוֹ'. מַלְאַךְ הָאֱלֹהִים - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וַהֲרֵי בֵּאַרְנוּ שֶׁאוֹתָהּ שָׁעָה בְּסִיּוּעַ הָאָבוֹת לוֹקַחַת. וּכְשֶׁהֵם נִמְצָאִים אֶצְלָהּ, הַכֹּל נִמְצָאִים. וּמִשּׁוּם כָּךְ נִמְסָר בִּפְסוּקִים אֵלּוּ שֵׁם הַקָּדוֹשׁ, שֶׁכּוֹלֵל בָּהֶם הָאָבוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ. פָּסוּק אֶחָד כַּסֵּדֶר, וְאֶחָד לְמַפְרֵעַ, וְאֶחָד כַּסֵּדֶר.</p>\n<p>וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ וְגוֹ' - זֶה כַּסֵּדֶר, מִשּׁוּם שֶׁאַבְרָהָם נִמְצָא כָּאן וְכָל אוֹתָם שֶׁבָּאִים מִצִּדּוֹ, וְעַל כָּךְ הוּא כַּסֵּדֶר כְּמוֹ זֶה.</p>\n<p>כָּאן הִתְעַטֵּר אַבְרָהָם בְּעַטְרוֹתָיו וְעִטֵּר אֶת כְּנֶסֶת יִשְׂרָאֵל, וְאוֹתִיּוֹת אֵלּוּ כֻּלָּן בְּדֶרֶךְ יָשָׁר לָלֶכֶת בַּיּוֹם, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְעַל זֶה כָּתוּב וַיִּסַּע. אֵימָתַי לוֹקְחִים בְּמַשְׂאוֹתֵיהֶם? הֱוֵה אוֹמֵר בַּיּוֹם, כְּשֶׁמֵּאִיר הַשֶּׁמֶשׁ, וְזֶהוּ פָּסוּק אֶחָד שֶׁהוּא בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת.</p>\n<p>שֵׁנִי שֶׁל יִצְחָק, כָּךְ גַּם שֶׁנִּמְצָא בְּשִׁבְעִים וּשְׁתַּיִם אוֹתִיּוֹת, לְהִמָּצֵא בְדִין לְגַבֵּי הַמִּצְרִים וּלְגַבֵּי יִשְׂרָאֵל בְּרַחֲמִים. וְעַל זֶה כָּתוּב וַיָּבא בֵּין מַחֲנֵה מִצְרַיִם וּבֵין מַחֲנֵה יִשְׂרָאֵל, לְמוּל אֵלֶּה וּלְמוּל אֵלֶּה. וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ, שֶׁכָּךְ הוּא יוֹם שֶׁל יִצְחָק, שֶׁמְּעֻנָּן הָיָה, עָנָן וְחֹשֶׁךְ מִמֶּנּוּ הוּא. וּמִשּׁוּם כָּךְ סִדּוּר הָאוֹתִיּוֹת לְמַפְרֵעַ, (בדרך עקם) וְלֹא בְדֶרֶךְ יָשָׁר כְּמוֹ זֶה.</p>\n<p>וְעַל זֶה כָּל הָאוֹתִיּוֹת לְמַפְרֵעַ, שֶׁכָּתוּב וַיְהִי הֶעָנָן וְהַחֹשֶׁךְ. שֶׁכֵּיוָן שֶׁנִּכְנַס יִצְחָק בְּדִינָיו, לֹא קָרַב זֶה אֶל זֶה. כָּתוּב זֶה אֶל זֶה. אוֹתָם שֶׁבָּאוּ מִצַּד אַבְרָהָם לֹא קָרְבוּ זֶה לָזֶה, שֶׁהֲרֵי לֹא יָכְלוּ, מִשּׁוּם שֶׁבְּאֵר זוֹ נִדְבְּקָה בְיִצְחָק, כְּמוֹ שֶׁנֶּאֱמַר וַיָּאֶר אֶת הַלָּיְלָה. שֶׁכְּשֶׁהִתְמַלְּאָה לְהִתְחַבֵּר (להתחזק) בְּיִצְחָק, לֹא קָרַב זֶה אֶל זֶה וְלֹא יָכֹל לְהִתְקָרֵב, עַד שֶׁבָּא יַעֲקֹב וְהִתְחַבֵּר בְּאַבְרָהָם, וְלָקַח אֶת יִצְחָק וְשָׂם אוֹתוֹ בָּאֶמְצַע, וְאָז הִתְקַשְּׁרָה הָאֱמוּנָה זֶה בָּזֶה וְזֶה בָּזֶה, וְנִצְּלוּ יִשְׂרָאֵל.</p>\n<p>וְשָׁנִינוּ, בְּמָקוֹם שֶׁנִּמְצָאִים הָאָבוֹת, שְׁאָר הַצַּדִּיקִים נִמְצָאִים אִתָּם, וְעַל זֶה שֵׁם זֶה עוֹלֶה לִצְדָדִים אֲחֵרִים מֻפְרָדִים, אַף עַל גַּב שֶׁכֻּלָּם יוֹצְאִים לְדֶרֶךְ אֶחָד.</p>\n<p>כְּשֶׁמְּאִירָה בְּאֵ\"ר זוֹ מִצַּד יִצְחָק וְנִקְשֶׁרֶת בּוֹ, נַעֲשֶׂה יָם הַגָּדוֹל תַּקִּיף, וְגַלִּים חֲזָקִים עוֹלִים וְיוֹרְדִים בְּזַעַף וְרֹגֶז בְּתַקִּיפוּת, נוֹטֵל לְמַעְלָה, עוֹלֶה, וְיוֹרֵד לְמַטָּה. אַבְרָהָם בָּא מוּלוֹ (כנגדו), וּמִתּוֹךְ רֹגֶז וְזַעַף וְחֵמָה וְתַקִּיפוּת זֶה אֶל זֶה לֹא הָיוּ מִתְקָרְבִים, עַד שֶׁבָּא יַעֲקֹב וְשׁוֹכֵךְ הָרֹגֶז, וּמֵמִיךְ וְשׁוֹבֵר גַּלֵּי הַיָּם. זֶהוּ שֶׁכָּתוּב (שמות יד) וַיֵּט מֹשֶׁה אֶת יָדוֹ עַל הַיָּם וַיּוֹלֶךְ ה' אֶת הַיָּם בְּרוּחַ קָדִים עַזָּה וְגוֹ'. מַה זֶּה בְּרוּחַ קָדִים עַזָּה? זוֹ רוּחַ יַעֲקֹב, עַזָּה, תַּקִּיפָה לְמוּלוֹ לִשְׁבֹּר רֹגֶז יָם זֶה. וַיָּשֶׂם אֶת הַיָּם לֶחָרָבָה וַיִּבָּקְעוּ הַמָּיִם, (הוא) רוֹקֵן הַיָּם מִמֵּי רֹגֶז, וְנֶחְלְקוּ הַמַּיִם לְצַד אַבְרָהָם וּלְצַד יַעֲקֹב. זֶהוּ שֶׁכָּתוּב וַיִּבָּקְעוּ הַמָּיִם, לְצַד זֶה וּלְצַד זֶה, וְעַל כָּךְ כָּל הָאוֹתִיּוֹת בְּדֶרֶךְ יָשָׁר כָּרָאוּי.</p>\n<p>אֵלֶּה אוֹתִיּוֹת בְּדֶרֶךְ יָשָׁר בְּצַד יַעֲקֹב, וְכָל אוֹתָם שֶׁבָּאוּ מִצִּדּוֹ. וּכְשֶׁבָּא יַעֲקֹב, הִתְחַבֵּר בְּאַבְרָהָם וְלָקַח אֶת יִצְחָק, וְהִשְׁרָהוּ בָאֶמְצַע. אָז הִתְקַשְּׁרָה הָאֱמוּנָה זֶה בָּזֶה וְזֶה בָּזֶה. וְעַל זֶה מַעֲשֶׂה בְּתִקּוּן בַּשֵּׁם הַקָּדוֹשׁ בְּזִוּוּג הָאָבוֹת נוֹדָע, שֶׁהוּא קֶשֶׁר אֶחָד, קֶשֶׁר נֶאֱמָן, לִהְיוֹת מֶרְכָּבָה שְׁלֵמָה, וּבְזִוּוּג הָאָבוֹת כְּאֶחָד נַעֲשֶׂה הַכֹּל.</p>\n<p>וְיוֹדְעִים הַחֲבֵרִים לָלֶכֶת בְּדֶרֶךְ יָשָׁר, לְהַתְקִין מַעֲשֶׂה כָּרָאוּי, וּבְשֵׁם זֶה קֶשֶׁר הָאָבוֹת, נִמְצְאוּ דְרָכִים לְדִין וּלְרַחֲמִים, לְסִיּוּעַ, לְחֶסֶד, לְיִרְאָה, לְתוֹרָה, לְחַיִּים, לְמָוֶת, לְטוֹב, לְרַע. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה וְיוֹדְעִים לָלֶכֶת בְּדַרְכֵי הַמֶּלֶךְ הַקָּדוֹשׁ. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>"],[9522012305,"<p>הֲרֵי הָאָבוֹת בְּמַסָּעוֹת, בְּמַעֲשִׂים, בִּקְשָׁרִים שֶׁמִּתְקַשְּׁרִים זֶה בָּזֶה. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, אֵין מִי שֶׁיָּקוּם לִפְנֵיהֶם. וְשָׁנִינוּ, בְּמָקוֹם שֶׁהָאָבוֹת נִמְצָאִים, שְׁאָר הַצַּדִּיקִים נִמְצָאִים עֲלֵיהֶם. וְעַל זֶה שֵׁם זֶה עוֹלֶה לִצְדָדִים אֲחֵרִים נִפְרָדִים, אַף עַל גַּב שֶׁכֻּלָּם יוֹצְאִים לְדֶרֶךְ זֶה.</p>\n<p>שִׁבְעָה קִשּׁוּרִים הֵם שֶׁמִּתְקַשְּׁרִים בָּהֶם שְׁלֹשֶׁת הָאָבוֹת וְאַרְבָּעָה אֲחֵרִים. רֹאשׁ וָאֶמְצַע בְּקֶשֶׁר אֶחָד. וְאֵלֶּה אוֹתָם שֶׁחָפְרוּ בְּאֵר מַיִם. שֵׁנִי זֶה אֶל זֶה, וְהֵם קֶשֶׁר אֶחָד בְּשָׁלֹשׁ יוֹדִי\"ן.</p>\n<p>שְׁלִישִׁי שְׁלֵמוּת כָּל הָאֱמוּנָה. רְבִיעִי שְׁנֵי עַמּוּדִים שֶׁהַגּוּף עוֹמֵד עֲלֵיהֶם. הַחֲמִישִׁי טוֹב וָרָע, נָהָר שֶׁמּוֹצִיא עֵץ הַחַיִּים וְהַמָּוֶת, הָעֹמֶק שֶׁל הַכֹּל. שִׁשִּׁי דִּין בְּרַחֲמִים. שְׁבִיעִי בַּתְּחִלָּה נֶאֱמַר בְּאוֹתוֹ רֹאשׁ שֶׁאָמַרְנוּ, מִשּׁוּם שֶׁהוּא אֶמְצַע הַכֹּל. וּמִשּׁוּם שֶׁהוּא אֶמְצַע הַכֹּל, נִקְרָא אֲנִי, עַמּוּד שֶׁכָּל הָעֲנָפִים נֶאֱחָזִים מִסְּבִיבוֹ.</p>\n<p>שֶׁבַע דְּרָגוֹת אֵלּוּ, מִדַּרְגָּה אַחַת לְדַרְגָּה אַחַת (אחרת), נוֹדַעַת מֶרְכָּבָה אַחַת בְּכָל אֵלּוּ שֶׁנֶּאֱחָזִים בָּהּ. וְכֵן מִדַּרְגָּה לְדַרְגָּה, וְכֻלָּם מִתְנַהֲגִים אַחֲרֶיהָ שֶׁל אוֹתָהּ דַּרְגָּה שֶׁנִּפְקְדָה עֲלֵיהֶם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁדְּרָגוֹת אֵלּוּ נִמְצָאוֹת, כָּל הָאֱמוּנָה נִמְצֵאת. וְאֵלּוּ שִׁבְעַת הָעֲנָנִים שֶׁסָּבְבוּ אֶת יִשְׂרָאֵל. בִּגְלַל זֶה כְּשֶׁנּוֹטֶלֶת הַשְּׁכִינָה - בָּאָבוֹת הִיא נוֹטֶלֶת. וּכְשֶׁאֵלֶּה נוֹטְלִים, כָּל הַדְּרָגוֹת הָאֲחֵרוֹת נוֹטְלוֹת בָּהֶם, וְאָז מִתְעַטֶּרֶת כְּנֶסֶת יִשְׂרָאֵל כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, זְבוּלוּן שֶׁאָמַרְנוּ יוֹרֵשׁ יָם כִּנֶּרֶת. יָם כִּנֶּרֶת סְתָם, וְכָךְ רָאוּי. אִם כָּךְ, יְהוּדָה מַה חֵלֶק יֵשׁ בּוֹ? אֶלָּא יְהוּדָה נָטַל מַלְכוּת הַכֹּל וְנֶאֱחַז בָּהּ בְּכָל הַצְּדָדִים.</p>"],[9522012306,"<p>רַבִּי אֶלְעָזָר אָמַר, בְּפָרָשָׁה זוֹ הֲרֵי נֶאֱמַר הַמַּעֲשֶׂה שֶׁל הַמְּנוֹרָה וְתִקּוּנֶיהָ וְכָל מַה שֶּׁבָּהּ, מַדּוּעַ כָּךְ בְּפַעַם אַחֶרֶת? אֶלָּא כֵּיוָן שֶׁהַנְּשִׂיאִים הִקְרִיבוּ (למעלה) קָרְבַּן הַמִּזְבֵּחַ וְכָל תִּקּוּן שֶׁרָאוּי לוֹ, בָּא הַכָּתוּב וְדִבֵּר שׁוּב עַל מַעֲשֵׂה הַמְּנוֹרָה שֶׁהוּא תִקּוּן עַל יָדוֹ שֶׁל אַהֲרֹן, שֶׁהֲרֵי לְמַעְלָה מְנוֹרָה, וְכָל הַנֵּרוֹת (התקונים) שֶׁלָּהּ, עַל יְדֵי אַהֲרֹן הַכֹּל מְאִירִים.</p>\n<p>בֹּא רְאֵה, הַמִּזְבֵּח, שְׁנֵים עָשָׂר נְשִׂיאִים הָיוּ לְחַנְּכוֹ וּלְהַתְקִינוֹ. וַהֲרֵי פֵּרְשׁוּהָ, שְׁנֵים עָשָׂר הֵם הַשְּׁבָטִים לְאַרְבָּעָה צְדָדִים, אַרְבָּעָה דְגָלִים, וְכֻלָּם שְׁנֵים עָשָׂר, וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה. הַמְּנוֹרָה נִמְנֵית בְּשִׁבְעָה נֵרוֹת לְהִדָּלֵק עַל יְדֵי הַכֹּהֵן, וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה. וְהַמְּנוֹרָה עַל אוֹת עוֹמֶדֶת וּבְנֵס נֶעֶשְׂתָה, וַהֲרֵי פֵּרְשׁוּהָ בְּמַעֲשֵׂה הַמְּנוֹרָה.</p>\n<p>וּמִזְבֵּחַ פְּנִימִי וּמְנוֹרָה עוֹמְדִים כְּאֶחָד לְשִׂמְחַת הַכֹּל, שֶׁכָּתוּב (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב. וּבֵאַרְנוּ שֶׁשְּׁנֵי מִזְבְּחוֹת הָיוּ: אֶחָד פְּנִימִי שֶׁל הַכֹּל, וְזֶה עוֹמֵד לְחֶדְוָה, וְאֶחָד בַּחוּץ לְהַקְרִיב קָרְבָּנוֹת. וּמֵהַפְּנִימִי הַזֶּה יוֹצֵא לָזֶה שֶׁבַּחוּץ. וּמִי שֶׁרוֹאֶה וְיִסְתַּכֵּל, יֵדַע חָכְמָה עֶלְיוֹנָה, סוֹד הַדָּבָר אֲדנָי יְהֹוָה, וְעַל כָּךְ לֹא נִקְרְבָה הַקְּטֹרֶת אֶלָּא בְּשָׁעָה שֶׁשֶּׁמֶן נִמְצָא.</p>\n<p>מָצָאנוּ בְסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, שֶׁהַקְּטֹרֶת הִיא לְחֶדְוָה וּלְסַלֵּק הַמָּוֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁהַדִּין נִמְצָא מִזֶּה שֶׁבַּחוּץ, וְשִׂמְחָה וְחֶדְוָה וְקֶשֶׁר שֶׁמֵּאִיר מֵאוֹתוֹ פְּנִימִי שֶׁכָּל שִׂמְחָה בּוֹ קַיֶּמֶת. וּכְשֶׁזֶּה מִתְעוֹרֵר, כָּל הַדִּין מִסְתַּלֵּק מִזֶּה וְלֹא יָכוֹל לַעֲשׂוֹת דִּין, וּמִשּׁוּם זֶה קְטֹרֶת עוֹמֶדֶת לְבַטֵּל הַמָּוֶת, וְעַל זֶה קְטֹרֶת הִיא קֶשֶׁר הַכֹּל, וְזוֹ נִקְרֶבֶת בַּפְּנִימִי. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיהֶם כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'.</p>"],[9522012307,"<p>קַח אֶת הַלְוִיִּם וְגוֹ'. הֲרֵי פֵּרְשׁוּהָ שֶׁצָּרִיךְ לְטַהֲרָם (להנהיגם) וּלְהַמְשִׁיכָם לְהִתְקַשֵּׁר בִּמְקוֹמָם, מִשּׁוּם שֶׁהֵם זְרוֹעַ שְׂמֹאל וְצַד הַדִּין. וְכָל מִי שֶׁבָּא מִצַּד הַדִּין, צָרִיךְ שֶׁלֹּא יַרְבֶּה שֵׂעָר, מִשּׁוּם שֶׁמַּרְבֶּה דִין בָּעוֹלָם. וְעַל כָּךְ אִשָּׁה כְּמוֹ זֶה, שֶׁלֹּא תִתְרָאֶה שַׂעֲרָה הַחוּצָה, וּצְרִיכָה לְכַסּוֹת רֹאשָׁהּ וּלְכַסּוֹת שְׂעָרָהּ, וּבֵאַרְנוּ וַהֲרֵי נִתְבָּאֵר. וְאָז מִתְבָּרְכִים כָּל אֵלּוּ שֶׁבָּאִים מִצַּד הַדִּין. וְעַל כָּךְ כָּתוּב בַּלְוִיִּם, וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם וְגוֹ', וְהֶעֱבִירוּ תַעַר וְגוֹ'. וְנֶאֱמַר כִּי הַלְוִיִּם לֹא עוֹלִים לִמְקוֹמָם עַד שֶׁיָּרִים אוֹתָם הַכֹּהֵן, מִשּׁוּם שֶׁהַיָּמִין מַנְהִיג תָּמִיד לַשְּׂמֹאל.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בַּיּוֹם שֶׁעוֹלִים הַלְוִיִּם לִמְקוֹמָם, בִּשְׁנֵי פָרִים. מָה הַטַּעַם פָּרִים? אֶלָּא הֵם כְּפָרִים לְקַבֵּל בִּשְׂמֹאל אֶת הַפָּרָה הַזּוֹ שֶׁנִּקְרֵאת פָּרָה אֲדֻמָּה. הַכֹּהֵן, כָּל הַכֹּחַ וְכָל תִּקּוּן תָּלוּי בּוֹ, מִשּׁוּם שֶׁכָּל כֹּחַ הַגּוּף עוֹמֵד בִּזְרוֹעַ יָמִין, וְעַל כָּךְ הַכֹּהֵן הוּא זְרוֹעַ שֶׁל כָּל יִשְׂרָאֵל, וּבוֹ עוֹמֵד לְהַתְקִין הַכֹּל וּלְהַתְקִין עוֹלָם, (מה הטעם פרים, ' אלא הם שמאל כמו הפרים לקבל בשמאל. בא ראה, הכהן זרוע ימין של כל ישראל היה, ובו עומד להתקין העולם ולהתקין הכל, משום שכל כח הגוף בזרוע הימין עומד, וכל התקון בו תלוי) וְעִם כָּל זֶה לֹא נִמְצָא לְבַדּוֹ, אֶלָּא בְּגוּף וּשְׂמֹאל, וְהַגּוּף הוּא עִקַּר הַכֹּל.</p>"],[9522012308,"<p>זֹאת אֲשֶׁר לַלְוִיִּם וְגוֹ'. בֹּא רְאֵה, לֵוִי בֶּן עֶשְׂרִים וְחָמֵשׁ שָׁנִים יַעֲבֹד, בֶּן חֲמִשִּׁים שָׁנִים עוֹלֶה לִמְקוֹמוֹ וּמִתְעַטֵּר, וְעֶשְׂרִים וְחָמֵשׁ יַעֲבֹד, שֶׁהֲרֵי אָדָם (בא ראה, לוי בן עשרים וחמש שנים עולה למקומו ומתעטר, ועשרים וחמש שנים יעבד, עד שעולה לדרגת חמשים), כְּשֶׁעוֹלֶה לְדַרְגָּה זוֹ שֶׁל חֲמִשִּׁים שָׁנִים וָהָלְאָה, יוֹרֵד מִתֹּקֶף הָאֵשׁ שֶׁבּוֹ. וְכֵיוָן שֶׁהָאֵשׁ וְהַחֲמִימוּת מִתְקָרֶרֶת, הֲרֵי הוּא פּוֹגֵם לְאוֹתוֹ מָקוֹם שֶׁנִּקְשָׁר בּוֹ.</p>\n<p>וְעוֹד, שֶׁקּוֹל זִמְרָה לֹא כָּל כָּךְ נִקְשָׁר בּוֹ, וְקוֹל צָרִיךְ שֶׁלֹּא יִפָּגֵם, אֶלָּא צָרִיךְ לְהִתְחַזֵּק, שֶׁהֲרֵי בִּמְקוֹם הַדִּין הַקָּשֶׁה עוֹמֵד, וְלֹא בְחֻלְשָׁה. וּמִשּׁוּם זֶה צָרִיךְ שֶׁלֹּא יִפְגֹּם אוֹתוֹ מָקוֹם שֶׁהוּא קָשׁוּר בּוֹ, שֶׁהוּא דִּין הַקָּשֶׁה, וְלֹא הַחַלָּשׁ, וְעַל זֶה לֹא צָרִיךְ לְהַרְאוֹת חֻלְשָׁה כְּלָל בְּכָל הַצְּדָדִים. אַשְׁרֵי הָאִישׁ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְיֵדַע דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא סוֹטֶה לְיָמִין וְלִשְׂמֹאל, שֶׁכָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה'.</p>"],[9522012309,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּמִדְבַּר סִינַי וְגוֹ'. אָמַר רַבִּי אַבָּא, מָה הַטַּעַם הִזְהִירָם כָּאן עַל פֶּסַח, וַהֲרֵי נִתְבָּאֵר לָהֶם בְּמִצְרַיִם? אֶלָּא בַּשָּׁנָה הַשֵּׁנִית זֶה הָיָה, שֶׁחָשְׁבוּ יִשְׂרָאֵל שֶׁפֶּסַח זֶה הוּא רַק בְּמִצְרַיִם, וְכֵיוָן שֶׁעָשׂוּ אוֹתוֹ פַּעַם אַחַת בְּמִצְרַיִם, חָשְׁבוּ שֶׁלֹּא צָרִיךְ יוֹתֵר. בָּא הַקָּדוֹשׁ בָּרוּךְ הוּא וְהִזְהִירָם עָלָיו, שֶׁלֹּא יַחְשְׁבוּ שֶׁעָבַר זְמַנּוֹ בְּמִצְרַיִם וְלֹא יִצְטָרֵךְ. בִּגְלַל זֶה בְּמִדְבַּר סִינַי בַּשָּׁנָה הַשֵּׁנִית, לְהַתְקִין לָהֶם לְדוֹרֵי דוֹרוֹת.</p>\n<p>וְאַף עַל גַּב שֶׁהִזְהִירָם בְּמִצְרַיִם, עַכְשָׁו צִוָּה לָהֶם פַּעַם אַחֶרֶת בְּאוֹתוֹ מָקוֹם שֶׁבּוֹ נִתְּנוּ כָּל מִצְווֹת הַתּוֹרָה. וְעַל כָּךְ בַּשָּׁנָה הַשֵּׁנִית. מַה זֶּה בַּשָּׁנָה הַשֵּׁנִית בַּחֹדֶשׁ הָרִאשׁוֹן? אֶלָּא סוֹד עֶלְיוֹן הוּא שָׁנָה אַחַת וְחֹדֶשׁ אֶחָד. מַה בֵּין זֶה לָזֶה? חֹדֶשׁ זוֹ הַלְּבָנָה. שָׁנָה זֶה הַשֶּׁמֶשׁ, שֶׁמֵּאִיר לַלְּבָנָה. וְאָז הָיָה בִּזְמַן שֶׁכָּל הַמִּצְווֹת נִמְסְרוּ בוֹ.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אוֹי לְאוֹתוֹ אִישׁ שֶׁאָמַר שֶׁתּוֹרָה זוֹ בָּאָה לְהַרְאוֹת סִפּוּרִים בְּעָלְמָא וְדִבְרֵי הֶדְיוֹטוֹת. שֶׁאִם כָּךְ, אֲפִלּוּ בִּזְמַן זֶה אָנוּ יְכוֹלִים לַעֲשׂוֹת תּוֹרָה בְּדִבְרֵי הֶדְיוֹטוֹת, וּבְשֶׁבַח יוֹתֵר מִכֻּלָּם. אִם לְהַרְאוֹת דְּבַר הָעוֹלָם, אֲפִלּוּ אוֹתָם סוֹפְרִים בָּעוֹלָם יֵשׁ בֵּינֵיהֶם דְּבָרִים יוֹתֵר עֶלְיוֹנִים. אִם כָּךְ, נֵלֵךְ אַחֲרֵיהֶם וְנַעֲשֶׂה מֵהֶם תּוֹרָה כְּמוֹ זֶה. אֶלָּא כָּל דִּבְרֵי הַתּוֹרָה דְּבָרִים עֶלְיוֹנִים הֵם וְסוֹדוֹת עֶלְיוֹנִים.</p>\n<p>בֹּא רְאֵה, עוֹלָם עֶלְיוֹן וְעוֹלָם תַּחְתּוֹן בְּמִשְׁקָל אֶחָד נִשְׁקְלוּ. יִשְׂרָאֵל לְמַטָּה - מַלְאָכִים עֶלְיוֹנִים לְמַעְלָה. בַּמַּלְאָכִים הָעֶלְיוֹנִים כָּתוּב, (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת. (זה במקום עליון) בְּשָׁעָה שֶׁיּוֹרְדִים לְמַטָּה (אף על גב שיורדים), מִתְלַבְּשִׁים בִּלְבוּשׁ הָעוֹלָם הַזֶּה. וְאִם לֹא יִתְלַבְּשׁוּ בִּלְבוּשׁ כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, לֹא יוּכְלוּ לַעֲמֹד בָּעוֹלָם הַזֶּה, וְהָעוֹלָם לֹא יִסְבֹּל אוֹתָם. וְאִם בְּמַלְאָכִים כָּךְ, הַתּוֹרָה שֶׁבָּרְאָה אוֹתָם וּבָרְאָה אֶת כָּל הָעוֹלָמוֹת וְעוֹמְדִים בִּגְלָלָהּ עַל אַחַת כַּמָּה וְכַמָּה, כֵּיוָן שֶׁיָּרְדָה לָעוֹלָם הַזֶּה, אִם לֹא תִתְלַבֵּשׁ בִּלְבוּשֵׁי הָעוֹלָם הַזֶּה, לֹא יוּכַל הָעוֹלָם לִסְבֹּל.</p>\n<p>וְעַל זֶה סִפּוּר זֶה שֶׁל הַתּוֹרָה, לְבוּשׁ הַתּוֹרָה הוּא. מִי שֶׁחוֹשֵׁב שֶׁאוֹתוֹ לְבוּשׁ הִיא הַתּוֹרָה מַמָּשׁ וְלֹא דָּבָר אַחֵר - תִּפַּח רוּחוֹ, וְלֹא יִהְיֶה לוֹ חֵלֶק לָעוֹלָם הַבָּא. בִּגְלַל זֶה אָמַר דָּוִד, (שם קיט) גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךְ. מַה שֶּׁתַּחַת לְבוּשׁ הַתּוֹרָה.</p>\n<p>בֹּא רְאֵה, יֵשׁ לְבוּשׁ שֶׁנִּרְאֶה לַכֹּל, וְאוֹתָם הַטִּפְּשִׁים כְּשֶׁרוֹאִים לְבוּשׁ עַל בֶּן אָדָם שֶׁנִּרְאֶה יָפֶה, לֹא מִסְתַּכְּלִים יוֹתֵר. חוֹשְׁבִים שֶׁאוֹתוֹ לְבוּשׁ הוּא הַגּוּף, וְחוֹשְׁבִים שֶׁהַגּוּף הִיא הַנְּשָׁמָה.</p>\n<p>כְּמוֹ זֶה הַתּוֹרָה יֵשׁ לָהּ גּוּף, וְהֵם מִצְווֹת הַתּוֹרָה שֶׁנִּקְרָאִים גּוּפֵי תוֹרָה. גּוּף זֶה מִתְלַבֵּשׁ בִּלְבוּשִׁים, שֶׁהֵם סִפּוּרֵי הָעוֹלָם הַזֶּה. טִפְּשֵׁי הָעוֹלָם לֹא מִסְתַּכְּלִים, רַק בְּאוֹתוֹ לְבוּשׁ, שֶׁהוּא סִפּוּר הַתּוֹרָה, וְלֹא יוֹדְעִים יוֹתֵר, וְלֹא מִסְתַּכְּלִים בְּמַה שֶּׁתַּחַת אוֹתוֹ לְבוּשׁ. אוֹתָם שֶׁיּוֹדְעִים יוֹתֵר לֹא מִסְתַּכְּלִים בַּלְּבוּשׁ, אֶלָּא בַּגּוּף שֶׁהוּא תַחַת אוֹתוֹ לְבוּשׁ. הַחֲכָמִים עַבְדֵי הַמֶּלֶךְ הָעֶלְיוֹן, שֶׁהֵם עָמְדוּ בְּהַר סִינַי, לֹא מִסְתַּכְּלִים אֶלָּא רַק בַּנְּשָׁמָה, שֶׁהִיא עִקַּר הַכֹּל, תּוֹרָה מַמָּשׁ. (ולעולם) וְלֶעָתִיד לָבֹא עֲתִידִים לְהִסְתַּכֵּל בַּנְּשָׁמָה שֶׁל נִשְׁמַת הַתּוֹרָה.</p>\n<p>בֹּא רְאֵה, כָּךְ גַּם לְמַעְלָה יֵשׁ לְבוּשׁ, וְגוּף, וּנְשָׁמָה, וּנְשָׁמָה לִנְשָׁמָה. הַשָּׁמַיִם וְחֵילוֹתֵיהֶם אֵלֶּה אוֹתָם לְבוּשִׁים, וּכְנֶסֶת יִשְׂרָאֵל זֶה הַגּוּף שֶׁמְּקַבֵּל אֶת הַנְּשָׁמָה שֶׁהִיא תִפְאֶרֶת יִשְׂרָאֵל, וְעַל כָּךְ הִיא גּוּף לַנְּשָׁמָה. נְשָׁמָה שֶׁאָמַרְנוּ זוֹ תִפְאֶרֶת יִשְׂרָאֵל, שֶׁהִיא תּוֹרָה מַמָּשׁ. וּנְשָׁמָה לִנְשָׁמָה זֶהוּ הָעַתִּיק הַקָּדוֹשׁ, וְהַכֹּל אָחוּז זֶה בָּזֶה.</p>\n<p>אוֹי לְאוֹתָם רְשָׁעִים שֶׁאוֹמְרִים שֶׁהַתּוֹרָה הִיא רַק סִפּוּר בְּעָלְמָא, וְהֵם מִסְתַּכְּלִים בִּלְבוּשׁ זֶה וְלֹא יוֹתֵר. אַשְׁרֵי הַצַּדִּיקִים שֶׁמִּסְתַּכְּלִים בַּתּוֹרָה כָּרָאוּי. יַיִן אֵינוֹ יוֹשֵׁב, רַק בְּקַנְקַן. כָּךְ הַתּוֹרָה אֵינָהּ יוֹשֶׁבֶת אֶלָּא בִּלְבוּשׁ זֶה, וְעַל כָּךְ לֹא צָרִיךְ לְהִסְתַּכֵּל אֶלָּא בְּמַה שֶּׁיֵּשׁ תַּחַת הַלְּבוּשׁ. וְעַל כָּךְ כָּל הַדְּבָרִים הַלָּלוּ וְכָל הַסִּפּוּרִים הַלָּלוּ הֵם לְבוּשִׁים.</p>"],[9522012310,"<p>וְיַעָשׂוּ בְנֵי יִשְׂרָאֵל אֶת הַפָּסַח בְּמוֹעֲדוֹ. מַה זֶּה וְיַעֲשׂוּ? אָמַר רַבִּי יוֹסֵי, הֲרֵי נִתְבָּאֵר, כָּל מִי שֶׁמַּרְאֶה מַעֲשֶׂה לְמַטָּה כָּרָאוּי, כְּאִלּוּ עֲשָׂאוֹ לְמַעְלָה, שֶׁהֲרֵי בִּגְלָלוֹ הִתְעוֹרֵר דָּבָר זֶה, כִּבְיָכוֹל, כְּאִלּוּ הוּא עֲשָׂאוֹ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>אִישׁ אִישׁ כִּי יִהְיֶה טָמֵא וְגוֹ'. אִישׁ אִישׁ - שְׁתֵּי פְעָמִים, לָמָּה? אֶלָּא אִישׁ שֶׁהוּא אִישׁ וְרָאוּי לְקַבֵּל נְשָׁמָה עֶלְיוֹנָה, וְהוּא פָּגַם עַצְמוֹ שֶׁלֹּא שׁוֹרָה עָלָיו שְׁכִינָה (תחלה) (נשמה) עֶלְיוֹנָה. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא גָּרַם וְהוּא טִמֵּא אֶת עַצְמוֹ. וְעַל זֶה אִישׁ אִישׁ. אִישׁ שֶׁרָאוּי לִהְיוֹת אִישׁ, וְהוּא מְטַמֵּא אֶת עַצְמוֹ שֶׁלֹּא תִשְׁרֶה עָלָיו קְדֻשָּׁה שֶׁל מַעְלָה.</p>\n<p>אוֹ בְדֶרֶךְ רְחוֹקָה - זֶהוּ אֶחָד מֵעֲשָׂרָה שֶׁהֵם נְקוּדִים בַּתּוֹרָה, וְכֻלָּם בָּאִים לְהַרְאוֹת דָּבָר. מַה זֶּה בְּדֶרֶךְ רְחוֹקָה? מִשּׁוּם שֶׁאָדָם שֶׁהוּא מְטַמֵּא אֶת עַצְמוֹ, מְטַמְּאִים אוֹתוֹ מִלְמַעְלָה. כֵּיוָן שֶׁמְּטַמְּאִים אוֹתוֹ מִלְמַעְלָה, הֲרֵיהוּ בְדֶרֶךְ רְחוֹקָה. מֵאוֹתוֹ מָקוֹם וְדֶרֶךְ שֶׁזֶּרַע יִשְׂרָאֵל אֲחוּזִים בּוֹ, הֲרֵי בְּדֶרֶךְ רְחוֹקָה אָחוּז, שֶׁהִתְרַחֵק (מלהתקרב) לִקְרַב אֲלֵיכֶם וּלְהִתְקַשֵּׁר בּכֶם כְּמוֹ שֶׁאַתֶּם מִתְקַשְּׁרִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, וַהֲרֵי כָּתוּב כִּי יִהְיֶה טָמֵא לָנֶפֶשׁ אוֹ בְדֶרֶךְ רְחוֹקָה, שֶׁנִּרְאֶה שְׁנֵי דְבָרִים מִמַּשְׁמָע שֶׁכָּתוּב אוֹ. אָמַר רַבִּי יוֹסֵי, כָּאן עַד שֶׁלֹּא מְטַמְּאִים אוֹתוֹ, כָּאן אַחַר שֶׁטִּמְּאוּ אוֹתוֹ. וּמַשְׁמָע אֲפִלּוּ זֶה אוֹ זֶה לֹא תִשְׁרֶה עָלָיו קְדֻשָּׁה שֶׁלְּמַעְלָה, וְלֹא יַעֲשׂוּ פֶסַח בִּזְמַן שֶׁיִּשְׂרָאֵל עוֹשִׂים אוֹתוֹ.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי בַּחֹדֶשׁ הַשֵּׁנִי עוֹשֶׂה אִם לֹא תִקֵּן עַצְמוֹ - לֹא! אֶלָּא כֵּיוָן שֶׁנִּטְהַר וְתִקֵּן עַצְמוֹ, הֲרֵי הַחֹדֶשׁ הַשֵּׁנִי לַעֲשׂוֹת פֶּסַח. מִכָּאן, כָּל אִישׁ שֶׁמְּטַהֵר עַצְמוֹ, מְטַהֲרִים אוֹתוֹ.</p>\n<p>שֶׁאִם תֹּאמַר שֶׁבְּדַרְגָּה עֶלְיוֹנָה יוֹתֵר עוֹמֵד בַּחֹדֶשׁ הַשֵּׁנִי - לֹא כָּךְ! שֶׁהֲרֵי יִשְׂרָאֵל זֶרַע קֹדֶשׁ שֶׁעָשׂוּ פֶסַח בִּזְמַנּוֹ, לָקְחוּ אֶת הַלְּבָנָה וְאֶת הַשֶּׁמֶשׁ כְּאֶחָד, וּמִי שֶׁלּוֹקֵחַ יְסוֹד בַּתְּחִלָּה - לוֹקֵחַ הַבִּנְיָן. מָה הַיְסוֹד? אַל תֹּאמַר יְסוֹד עֶלְיוֹן שֶׁל צַדִּיק הָעוֹלָם, אֶלָּא יְסוֹד שֶׁל אֶבֶן טוֹבָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קיח) אֶבֶן מָאֲסוּ הַבּוֹנִים הָיְתָה לְרֹאשׁ פִּנָּה. וְזוֹהִי הָאֶבֶן שֶׁשּׁוֹרֶה עָלֶיהָ מִי שֶׁשּׁוֹרֶה.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַדַּאי הַכֹּל אֲפִלּוּ בַּחֹדֶשׁ הַשֵּׁנִי, אֲבָל אֵינוֹ כְּמִי שֶׁנּוֹטֵל בִּזְמַנּוֹ. מָה הַטַּעַם? זֶה שֶׁנּוֹטֵל פֶּסַח בִּזְמַנּוֹ, נוֹטֵל מִמַּטָּה לְמַעְלָה וְלֹא יוֹרֵד, מִשּׁוּם שֶׁמַּעֲלִים בַּקֹּדֶשׁ וְלֹא מוֹרִידִים. וְזֶה שֶׁנּוֹטֵל אַחַר זְמַנּוֹ, יוֹרֵד מִמַּעְלָה לְמַטָּה. בִּגְלַל זֶה שָׁוִים בַּכֹּל, וְלֹא שָׁוִים. שֶׁזֶּה עוֹלֶה וְלֹא יוֹרֵד, וְזֶה יוֹרֵד וְלֹא עוֹלֶה. בִּגְלַל כָּךְ מִי שֶׁמַּקְרִיב פֶּסַח בִּזְמַנּוֹ, יֵשׁ לוֹ שֶׁבַח יוֹתֵר. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁזַּכָּאִים בַּכֹּל, שֶׁזַּכָּאִים בַּתּוֹרָה, וְכָל מִי שֶׁזּוֹכֶה בַתּוֹרָה, זוֹכֶה לוֹ בַּשֵּׁם הַקָּדוֹשׁ. אַשְׁרֵיהֶם יִשְׂרָאֵל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>מִצְוָה לַעֲשׂוֹת פֶּסַח שֵׁנִי עַל אֵלּוּ שֶׁלֹּא יָכְלוּ אוֹ שֶׁנִּטְמְאוּ בְטֻמְאָה אַחֶרֶת. אִם סוֹד הַפֶּסַח סוֹד הָאֱמוּנָה שֶׁיִּשְׂרָאֵל נִכְנָסִים בָּהּ, שׁוֹלֵט בְּנִיסָן, וְאָז הוּא זְמַן לְשִׂמְחָה, אֵיךְ יָכְלוּ אֵלֶּה שֶׁלֹּא יָכְלוּ אוֹ שֶׁנִּטְמְאוּ לַעֲשׂוֹת בַּחֹדֶשׁ הַשֵּׁנִי, שֶׁהֲרֵי עָבַר הַזְּמַן?</p>\n<p>אֶלָּא כֵּיוָן שֶׁכְּנֶסֶת יִשְׂרָאֵל מִתְעַטֶּרֶת בְּעַטְרוֹתֶיהָ בְּנִיסָן, לֹא מַעֲבִירָה כְתָרֶיהָ וְעַטְרוֹתֶיהָ מִמֶּנָּה שְׁלֹשִׁים יוֹם. וְכָל אוֹתָם שְׁלֹשִׁים יוֹם מִיּוֹם שֶׁיָּצְאוּ יִשְׂרָאֵל מִפֶּסַח, יוֹשֶׁבֶת הַמַּלְכָּה בְּעַטְרוֹתֶיהָ, וְכָל חֵילוֹתֶיהָ בְּחֶדְוָה. מִי שֶׁרוֹצֶה לִרְאוֹת אֶת הַמַּלְכָּה יוּכַל לִרְאוֹת. הַכָּרוֹז מַכְרִיז: כָּל מִי שֶׁלֹּא יָכוֹל לִרְאוֹת אֶת הַמַּלְכָּה, יָבֹא וְיִרְאֶה עַד שֶׁלֹּא יִנָּעֲלוּ הַשְּׁעָרִים. אֵימָתַי הַכָּרוּז מַכְרִיז? בְּאַרְבָּעָה עָשָׂר לַחֹדֶשׁ הַשֵּׁנִי, שֶׁהֲרֵי מִשָּׁם וְעַד שִׁבְעָה יָמִים הַשְּׁעָרִים פְּתוּחִים. מִכָּאן וָהָלְאָה יִנָּעֲלוּ הַשְּׁעָרִים. וְעַל זֶה פֶּסַח שֵׁנִי.</p>\n<p>מִצְוָה זוֹ - שְׁחִיטַת הַפֶּסַח בִּזְמַנּוֹ. וְאַחֲרָיו פֶּסַח רִאשׁוֹן וּפֶסַח שֵׁנִי לֶאֱכֹל אוֹתָם כְּמִשְׁפָּטָן. וּטְמֵאִים לִהְיוֹת נִדְחִים לְפֶסַח שֵׁנִי, שֶׁהִיא מִצְוָה שְׁלִישִׁית. תַּנָּאִים וְאָמוֹרָאִים, יֵשׁ בְּנֵי אָדָם כְּמוֹ חֻלִּין שֶׁל טָהֳרָה מִצַּד מִיכָאֵל, וּכְמוֹ חֻלִּין שֶׁל הֶקְדֵּשׁ, כְּגוֹן בְּשַׂר קֹדֶשׁ, וְהֵם מִצַּד גַּבְרִיאֵל. כֹּהֵן וְלֵוִי. וְיֵשׁ בְּנֵי אָדָם שֶׁהֵם כְּמוֹ יָמִים טוֹבִים, וְהֵם קֹדֶשׁ קָדָשִׁים.</p>"],[9522012311,"<p>שְׁכִינָה הִיא פֶּסַח רִאשׁוֹן מִיָּמִין, וּפֶסַח שֵׁנִי מִשְּׂמֹאל. פֶּסַח רִאשׁוֹן מִיָּמִין, שֶׁשָּׁם חָכְמָ\"ה. פֶּסַח שֵׁנִי מִשְּׂמֹאל, שֶׁשָּׁם בִּינָה. וּמִשּׁוּם שֶׁבִּגְבוּרָה עוֹבְרִים כָּל הָאִשִּׁים הַנָּכְרִיִּים, שֶׁהֵם כְּקַשׁ וְתֶבֶן לְגַבֵּי אֵשׁ שֶׁל גְּבוּרָה, הַטְּמֵאִים נִדְחִים לְפֶסַח שֵׁנִי.</p>\n<p>וְכָל טֻמְאָה נִדָּה, וּמְצֹרָע, וְזָב וְזָבָה וְיוֹלֶדֶת, בְּאֵשׁ הַגְּבוּרָה הוּא שׂוֹרֵף. שֶׁהַנְּשָׁמָה הִיא כְּלִי שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא לֹא שׁוֹרֶה בָּהּ עַד שֶׁמִּתְלַבֶּנֶת בְּאֵשׁ הַגְּבוּרָה, שֶׁכָּתוּב (ירמיהכג) הֲלֹא כֹה דְבָרִי כָּאֵשׁ נְאֻם ה'. וּבְאֵשׁ זוֹ, אִם בַּרְזֶל הוּא - מִתְפּוֹצֵץ, וְאִם אֶבֶן הוּא - נִמּוֹחַ.</p>\n<p>וּבְיָמִין, שֶׁשָּׁם תּוֹרָה שֶׁבִּכְתָב, שֶׁהִיא מַיִם - (ויקרא יב) וְטָהֳרָה מִמְּקוֹר דָּמֶיהָ, וְנִטְהָר בָּהּ מְצֹרָע, וּטְמֵא מֵת, וְזָב, וְטָמֵא בְּכָל מִינֵי שֶׁרֶץ. זֶהוּ שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם וְגוֹ'.</p>\n<p>בָּעַמּוּד הָאֶמְצָעִי כְּלִי מִתְיַחֶדֶת בְּבַעְלָהּ, שֶׁהִיא אִשָּׁה, אַחַר שֶׁמִּתְקַדֶּשֶׁת בִּשְׂמֹאל וְנִטְהֶרֶת בְּמֵי מִקְוֶה בְּיָמִין, וְאוֹמְרִים עַל כְּלֵי פֶסַח: כֵּלִים שֶׁנִּשְׁתַּמְּשׁוּ בָהֶם בְּצוֹנֵן, מַטְבִּילָם בְּצוֹנֵן וְהֵם טְהוֹרִים. אוֹתָן נְשָׁמוֹת שֶׁהֵן מִצַּד הָרַחֲמִים, וְהֵן רַחֲמָנִים, בַּעֲלֵי חֵן וָחֶסֶד, לֹא צְרִיכִים לְהִטָּהֵר בְּמַיִם פּוֹשְׁרִים כְּבֵינוֹנִיִּים. כָּל שֶׁכֵּן בְּחַמֵּי חַמִּים, שֶׁבָּהֶם נִטְהָרִים רְשָׁעִים גְּמוּרִים שֶׁמְּחַמְּמִים עַצְמָם בְּאֵשׁ יֵצֶר הָרָע, וַעֲלֵיהֶם נֶאֱמַר (במדבר לא) כָּל דָּבָר אֲשֶׁר יָבֹא בָאֵשׁ, בִּגְלַל שֶׁזֻּהַמְתָּם רַבָּה. אֲבָל צַדִּיקִים גְּמוּרִים בְּצוֹנֵן, שֶׁעֲלֵיהֶם נֶאֱמַר, כָּל הַמֵּשִׂים רֶוַח בֵּין הַדְּבֵקִים מְצַנְּנִין לוֹ גֵּיהִנֹּם.</p>\n<p>וְאִם נְשָׁמוֹת חָמְרִיּוֹת, שֶׁהֵם כִּכְלֵי חֶרֶס - שְׁבִירָתָן זוֹהִי טָהֳרָתָן, כְּמוֹ שֶׁנֶּאֱמַר נִשְׁבָּרוּ, נִטְהָרוּ. וְסוֹד הַדָּבָר - (תהלים נא) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה וְגוֹ'. אֲבָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה שֶׁבִּכְתָב וּבַתּוֹרָה שֶׁבְּעַל פֶּה, שֶׁהֵם אֵשׁ וּמַיִם, וְאוֹתָם שֶׁמִּשְׁתַּדְּלִים בְּסוֹדוֹת הַתּוֹרָה, שֶׁהִיא אוֹר, שֶׁכָּתוּב בָּהּ (משלי ו) וְתוֹרָה אוֹר, הֵם נִטְהָרִים בָּהּ.</p>"],[9522012312,"<p>וְעוֹד בְּפֶרֶק הָרוֹאֶה: הָרוֹאֶה תְמָרִים בַּחֲלוֹם, תַּמּוּ עֲווֹנוֹתָיו. זֶהוּ שֶׁכָּתוּב (איכה ד) תַּם עֲוֹנֵךְ בַּת צִיּוֹן. מִשּׁוּם שֶׁתְּמָרִים, בּוֹ תָּם, דַּרְגַּת יַעֲקֹב, שֶׁנֶּאֱמַר בּוֹ (בראשית כה) וְיַעֲקֹב אִישׁ תָּם. עֲבֵרוֹת מָרוֹת, וְעַל כָּךְ תְּמָרִים - שָׁם תָּ\"ם, וְשָׁם מָ\"ר.</p>\n<p>כָּאן רָמוּז, וַיִּמְתְּקוּ הַמָּיִם. זֶהוּ שֶׁכָּתוּב (שמות טו) וַיּוֹרֵהוּ ה' עֵץ, וַיִּמְתְּקוּ הַמָּיִם. מִכָּאן, מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה שֶׁהִיא עֵץ, עֲווֹנוֹתָיו, שֶׁנֶּאֱמַר בָּהֶן (שם א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹחֵל לוֹ, וְיַחְזְרוּ מְתוּקִים.</p>\n<p>שֶׁיָּבֹאוּ יָמִים שֶׁיִּתְקַיֵּם בָּהֶם כִּיצִיאַת מִצְרַיִם, שֶׁנֶּאֱמַר בָּהּ (שם) וַיָּמָת יוֹסֵף וְכָל אֶחָיו וְכֹל הַדּוֹר הַהוּא. וּבַגָּלוּת הָאַחֲרוֹנָה אֵין מִיתָה, אֶלָּא עֹנִי, שֶׁעָנִי חָשׁוּב כְּמֵת, לְקַיֵּם בָּהֶם (צפניה ג) וְהִשְׁאַרְתִּי בְקִרְבֵּךְ (בך) עַם עָנִי וָדָל וְחָסוּ בְּשֵׁם ה'. לְהִתְקַיֵּם בָּהֶם (שמואל ב כב) וְאֶת עַם עָנִי תּוֹשִׁיעַ. וַעֲשִׁירִים אֵלּוּ שֶׁיִּשָּׁאֲרוּ בָהֶם, יִתְקַיֵּם בָּהֶם (שמות ה) נִרְפִּים אַתֶּם נִרְפִּים. נִרְפִּים הֵם בַּתּוֹרָה, נִרְפִּים הֵם לַעֲשׂוֹת טוֹבוֹת עִם בַּעֲלֵי תוֹרָה וְאַנְשֵׁי חַיִל הַמְּסוֹבְבִים מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ.</p>\n<p>וְנִרְפִּים הֵם בְּכֹבֶד הַמַּס. שֶׁאִם תֹּאמַר, כְּבֵדִים הֵם בְּכֹבֶד הַמַּס וְלֹא עוֹשִׂים טוֹבוֹת - בִּגְלַל זֶה (שם) תִּכְבַּד הָעֲבֹדָה עַל הָאֲנָשִׁים וְיַעֲשׂוּ בָהּ, שֶׁכֹּבֶד הַמַּס עֲלֵיהֶם, וְאַל יִשְׁעוּ בְּדִבְרֵי שָׁקֶר, שֶׁהֵם מְשַׁקְּרִים וְאוֹמְרִים שֶׁכֹּבֶד הַמַּס עֲלֵיהֶם, וּמִשּׁוּם זֶה לֹא יַעֲשׂוּ טוֹבוֹת. הֵם מְשַׁקְּרִים בְּדִבְרֵיהֶם, וְאוֹמְרִים שֶׁמֵּהַכֹּבֶד שֶׁתִּכְבַּד עֲלֵיהֶם, תֶּבֶן אֵין נִתָּן, מָמוֹן הַשֶּׁקֶר שֶׁבּוֹ טוֹעִים (מדברים) לַקָּדוֹשׁ-בָּרוּךְ-הוּא. וּמִשּׁוּם שֶׁלֹּא מְדַבְּרִים בּוֹ וְלֹא חָסוּ בְּשֵׁם ה', אֵין נִתָּן לַעֲבָדֶיךְ.</p>\n<p>וְאֵלֶּה שֶׁיֵּשׁ לָהֶם נִסְתָּר וְגָנוּז הַמָּמוֹן מִבִּפְנִים, שֶׁהוּא תֹּכֶן, כְּמוֹ תּוֹךְ הָאוֹצָר וְתֵבָה, מִתְקַיֵּם בָּהֶם וְתֹכֶן לְבֵנִים תִּתֵּנוּ. וְזֶה כְּסָפִים לְבָנִים שֶׁיִּהְיוּ בְּאוֹתוֹ דוֹר.</p>\n<p>בְּאוֹתוֹ זְמַן, (שמות טו) שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט, וְהֵם בַּעֲלֵי מִשְׁנָה. גַּם כָּאן וַיָּבאוּ מָרָתָה, חוֹזֶרֶת לָהֶם תוֹרָה שֶׁבְּעַל פֶּה מָרָה בִּדְחָקִים רַבִּים, בַּעֲנִיּוּת, שֶׁיִּתְקַיֵּם בָּהֶם (שם א) וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבדָה קָשָׁה - זוֹ קֻשְׁיָא. בְּחֹמֶר - זֶה קַל וָחֹמֶר. וּבִלְבֵנִים - זֶה לִבּוּן הֲלָכָה. וּבְכָל עֲבֹדָה בַּשָּׂדֶה - זוֹ בָּרַיְתָא. אֵת כָּל עֲבֹדָתָם אֲשֶׁר עָבְדוּ בָהֶם בְּפָרֶךְ - זֶה תֵּיק\"וּ.</p>\n<p>וְרוֹעָה הַנֶּאֱמָן, שָׁם הִתְקַיֵּם בְּךְ, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. וּבְעֵץ הַדַּעַת הַזֶּה טוֹב וָרָע, שֶׁהוּא אִסּוּר וְהֶתֵּר, וּבְאוֹתָם סוֹדוֹת שֶׁהִתְגַּלּוּ עַל יָדְךְ, וַיִּמְתְּקוּ הַמָּיִם. כְּמוֹ מֶלַח שֶׁמַּמְתִּיק אֶת הַבָּשָׂר, כָּךְ יִתְמַתְּקוּ בְסוֹדוֹת שֶׁמִּתְגַּלִּים עַל יָדְךְ כָּל אוֹתָן קֻשְׁיוֹת וּמַחֲלוֹקוֹת שֶׁל מַיִם מְרִירִים שֶׁל תּוֹרָה שֶׁבְּעַל פֶּה, יַחְזְרוּ מְתוּקִים מֵי הַתּוֹרָה. וְיִסּוּרֶיךְ, בְּסוֹדוֹת אֵלּוּ שֶׁהִתְגַּלּוּ עַל יָדְךְ, יִהְיוּ לְךְ מְתוּקִים, וְיַחְזְרוּ לְךְ כָּל הַדְּחָקִים שֶׁלְּךְ כַּחֲלוֹמוֹת שֶׁעָבְרוּ. וַחֲלֹ\"ם בְּהִפּוּךְ אוֹתִיּוֹת - מֶלַ\"ח, שֶׁמַּמְתִּיק אֶת הַבָּשָׂר. גַּם יִסּוּרִים מְמַתְּקִים, כְּמוֹ שֶׁפֵּרְשׁוּהָ.</p>\n<p>וְלָרְשָׁעִים חוֹזְרִים הַיִּסּוּרִים מֶלַח סְדוֹמִית, שֶׁמְּעַוֵּר אֶת הָעֵינַיִם, לְקַיֵּם בָּהֶם (איוב יא) וְעֵינֵי רְשָׁעִים תִּכְלֶינָה. וְהֵם עֵרֶב רַב רְשָׁעִים, שֶׁיִּתְקַיֵּם בָּהֶם בְּאוֹתוֹ זְמַן, (דניאל יב) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים וְהִרְשִׁיעוּ רְשָׁעִים. יִתְלַבְּנוּ - אֵלֶּה בַּעֲלֵי מִשְׁנָה. וְיִצָּרְפוּ - הֵם זֶרַע קֹדֶשׁ שֶׁל שְׁאָר הָעָם. זֶהוּ שֶׁכָּתוּב (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף. וְהִרְשִׁיעוּ רְשָׁעִים - אֵלֶּה עֵרֶב רַב.</p>"],[9522012313,"<p>וְהַמַּשְׂכִּלִים יָבִינוּ (דניאל שם) - אֵלּוּ בַּעֲלֵי קַבָּלָה, שֶׁנֶּאֱמַר בָּהֶם (שם) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. אֵלּוּ אוֹתָם שֶׁמִּשְׁתַּדְּלִים בְּזֹהַר זֶה שֶׁנִּקְרָא סֵפֶר הַזֹּהַר, שֶׁהוּא כְּמוֹ תֵּבַת נֹחַ שֶׁמִּתְכַּנְּסִים בָּהּ שְׁנַיִם מֵעִיר וְשֶׁבַע מִמַּלְכוּת, וְלִפְעָמִים אֶחָד מֵעִיר וּשְׁנַיִם מִמִּשְׁפָּחָה, שֶׁבָּהֶם יִתְקַיֵּם (שמות א) כָּל הַבֵּן הַיִּלּוֹד הַיְאֹרָה תַּשְׁלִיכֻהוּ. וְזֶה אוֹרָה שֶׁל סֵפֶר זֶה, וְהַכֹּל עַל הַסִּבָּה שֶׁלְּךְ.</p>\n<p>וּמִי גָרַם זֶה? עוֹרֵב, שֶׁאַתָּה תִהְיֶה בְּאוֹתוֹ זְמַן כְּיוֹנָה, שֶׁשָּׁלִיחַ אַחֵר שֶׁנִּקְרָא בְשִׁמְךְ, כָּעוֹרֵב שֶׁנִּשְׁלַח בַּתְּחִלָּה וְלֹא חָזַר בַּשְּׁלִיחוּת, שֶׁהִשְׁתַּדֵּל בַּשְּׁקָצִים, שֶׁנֶּאֱמַר בָּהֶם עַמֵּי הָאָרֶץ שֶׁקֶץ, בִּגְלַל מָמוֹנָם, וְלֹא הִשְׁתַּדֵּל בִּשְׁלִיחוּתוֹ לְהַחֲזִיר צַדִּיקִים בִּתְשׁוּבָה, כְּאִלּוּ לֹא עָשָׂה שְׁלִיחוּת רִבּוֹנוֹ.</p>\n<p>וּבְךָ יִתְקַיֵּם סוֹד הַיּוֹנָה שֶׁנִּכְנַס בְּעִמְקֵי תְהוֹם רַבָּה, כָּךְ תִּכָּנֵס אַתָּה בְּעָמְקֵי תְּהוֹמֵי הַתּוֹרָה. זֶהוּ שֶׁכָּתוּב (יונה ב) וַתַּשְׁלִיכֵנִי מְצוּלָה בִּלְבַב יַמִּים. וְיִהְיוּ חָכְמָה חֶסֶד נֵצַח לְיָמִין, שֶׁבִּגְלָלָם אָמַר דָּוִד (תהלים קיח) יְמִין ה' רוֹמֵמָה יְמִין ה' עֹשָׂה חָיִל. וְשָׁלֹשׁ מִשְּׂמֹאל יִתְקַשְּׁרוּ כְאֶחָד, שֶׁהֵם בִּינָה גְּבוּרָה הוֹד, וְשָׁלֹשׁ דְּרָגוֹת שֶׁבָּאֶמְצַע - כֶּתֶר תִּפְאֶרֶת יְסוֹד - שֶׁאֲחוּזוֹת בְּיָמִין וּשְׂמֹאל.</p>\n<p>וּמִשּׁוּם שֶׁרָאָה אוֹתְךְ נָבִיא מִתְקַשֵּׁר בִּשְׁלֹשׁ דַּרְגוֹת הָאֶמְצַע, פָּתַח עָלֶיךְ פָּסוּק זֶה, (ישעיהנב) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. וּמִשּׁוּם שֶׁאַתָּה תִהְיֶה אָחוּז בִּשְׁנֵי מְשִׁיחִים, אָמַר דָּוִד עַל שְׁלֹשָׁה יְמִינִים שֶׁל מָשִׁיחַ בֶּן דָּוִד, יְמִין ה' שָׁלֹשׁ פְּעָמִים. כְּנֶגֶד שְׁלֹשָׁה שְׂמָאלִים שֶׁאָחוּז בָּהֶם מָשִׁיחַ בֶּן אֶפְרַיִם, אָמַר מִצַּד אֶחָד שְׂמֹאל, גְּבוּרָה, לֹא אָמוּת. כִּי אֶחְיֶה - מִצַּד שְׂמֹאל שֶׁל הוֹ\"ד שֶׁלְּךְ, שֶׁנֶּאֱמַר בּוֹ וְנִתַּן הַהוֹד לְמֹשֶׁה, נִתַּן בְּךְ מִצַּד בִּינָה.</p>\n<p>מִשּׁוּם שֶׁבּוֹ הָיִיתָ חָרֵב וְיָבֵשׁ בַּכֹּל, בִּגְלַל מָשִׁיחַ בֶּן אֶפְרַיִם, בְּתוֹרָתְךְ, בִּנְבִיאוּתְךְ עָלָיו, בְּגוּפְךְ שֶׁסָּבַלְתָּ כַּמָּה מִינֵי יִסּוּרִים כְּדֵי שֶׁהוּא לֹא יָמוּת, וּבִקַּשְׁתָּ עָלָיו רַחֲמִים, נֶאֱמַר בּוֹ כִּי אֶחְיֶה, מִצַּד הַבִּינָה. וּמִשּׁוּם זֶה לֹא אָמוּת - מִצַּד הַגְּבוּרָה. כִּי אֶחְיֶה - מִצַּד הַבִּינָה, עֵץ הַחַיִּים, שֶׁהִתְגַּבְּרָה עָלָיו קְרִיאַת שְׁמַע שֶׁל שַׁחֲרִית, וְקוֹשֵׁר אוֹתוֹ בְּקֶשֶׁר שֶׁל תְּפִלִּין בִּימִין אַבְרָהָם, שֶׁהוּא שַׁחֲרִית.</p>\n<p>וַאֲסַפֵּר מַעֲשֵׂי יָהּ - מִצַּד הַהוֹד. יַסֹּר יִסְּרַנִּי יָּהּ - חָכְמָה וּבִינָה, מִיָּמִין וּמִשְּׂמֹאל, בִּשְׁלֹשָׁה יְמָנִים וּבִשְׁלֹשָׁה שְׂמָאלִים. וְלַמָּוֶת לֹא נְתָנָנִי - הָעַמּוּד הָאֶמְצָעִי בְּג' שֶׁכּוֹלֵל כֶּתֶר וְצַדִּיק, וְהוּא בֶּן יָ\"הּ. וּמִיָּד יָקוּם ו' לְה' בְּיָ\"הּ, בְּיָמִין וּשְׂמֹאל, בְּרַחֲמִים וְתַחֲנוּנִים, בְּכַמָּה פִיּוּסִים לָהּ וּלְבָנֶיהָ. זֶהוּ שֶׁכָּתוּב (עמוס ט) בַּיּוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִיד הַנֹּפֶלֶת. וּמִשּׁוּם זֶה אָמַר הַנָּבִיא (ירמיה לא) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם.</p>\n<p>קָם רוֹעֶה הַנֶּאֱמָן וְנָשַׁק לוֹ וּבֵרַךְ אוֹתוֹ, וְאָמַר, וַדַּאי שְׁלִיחַ רִבּוֹנְךְ אַתָּה אֵלֵינוּ. פָּתְחוּ תַנָּאִים וְאָמוֹרָאִים וְאָמְרוּ, רוֹעֶה הַנֶּאֱמָן, אַתָּה הָיִיתָ יוֹדֵעַ כָּל זֶה, וְעַל יָדְךְ הִתְגַּלְּתָה, אֲבָל בָּעֲנָוָה שֶׁלְּךְ, שֶׁנֶּאֱמַר בְּךְ (במדבר יב) וְהָאִישׁ מֹשֶׁה עָנָו מְאֹד, בִּמְקוֹמוֹת אֵלּוּ שֶׁאַתָּה מִתְבַּיֵּשׁ לְהַחֲזִיק טוֹבָה אֵלֶיךְ, מִנָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָנוּ וְלַמְּנוֹרָה הַקְּדוֹשָׁה לִהְיוֹת בְּיָדְךְ וּבְפִיךְ בִּמְקוֹמוֹת אֵלּוּ.</p>"],[9522012314,"<p>וּבְיוֹם הָקִים אֶת הַמִּשְׁכָּן. רַבִּי חִיָּיא פָּתַח, (תהלים קיב) פִּזַּר נָתַן לָאֶבְיוֹנִים צִדְקָתוֹ עֹמֶדֶת לָעַד קַרְנוֹ תָּרוּם בְּכָבוֹד. פִּזַּר לָאֶבְיוֹנִים, מַה זֶּה פִּזַּר? כְּמוֹ שֶׁנֶּאֱמַר (משלי יא) יֵשׁ מְפַזֵּר וְנוֹסָף עוֹד. יָכוֹל פִּזּוּר בְּעָלְמָא? בָּא לְהַשְׁמִיעֵנוּ פִּזַּר נָתַן לָאֶבְיוֹנִים. כֵּיוָן שֶׁנָּתַן לַעֲנִיִּים, פִּזּוּר זֶה נָאֶה. מַה זֶה וְנוֹסָף עוֹד? בַּכֹּל. וְנוֹסָף עוֹד - בְּעֹשֶׁר. וְנוֹסָף עוֹד - בְּחַיִּים.</p>\n<p>פָּסוּק זֶה כָּךְ צָרִיךְ לוֹ לִהְיוֹת: יֵשׁ מְפַזֵּר וְיוֹסֵף עוֹד. מַה זֶּה וְנוֹסָף? אֶלָּא אוֹתוֹ מָקוֹם שֶׁשּׁוֹרָה בּוֹ מִיתָה, הוּא גּוֹרֵם לוֹ שֶׁיִּתּוֹסֵף מֵחַיִּים שֶׁלְּמַעְלָה לְהוֹסִיף לוֹ. אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא, הַפָּסוּק מֵעִיד שֶׁכָּל מִי שֶׁנּוֹתֵן לַעֲנִיִּים, מְעוֹרֵר עֵץ הַחַיִּים לְהוֹסִיף לְאוֹתוֹ עֵץ הַמָּוֶת, וְאָז נִמְצָא חַיִּים וְשִׂמְחָה לְמַעְלָה. וְהָאָדָם שֶׁגּוֹרֵם אֶת זֶה, בְּשָׁעָה שֶׁצָּרִיךְ לוֹ, אוֹתוֹ עֵץ הַחַיִּים עוֹמֵד עָלָיו, וְאוֹתוֹ עֵץ הַמָּוֶת מֵגֵן עָלָיו, וּמִשּׁוּם כָּךְ וְנוֹסָף עוֹד (כמו שנאמר).</p>\n<p>צִדְקָתוֹ עֹמֶדֶת לָעַד (תהלים קיא). מַה זֶּה עֹמֶדֶת לָעַד? עוֹמֶדֶת עַל הָאָדָם לְזַמֵּן לוֹ קִיּוּם וְחַיִּים. כְּמוֹ שֶׁהוּא נָתַן לוֹ חַיִּים וְעוֹרֵר לְגַבֵּי הַחַיִּים, כָּךְ גַּם נוֹתְנִים לוֹ, וְאֵלּוּ שְׁנֵי אִילָנוֹת (נותנים לו) עוֹמְדִים עָלָיו לְהַצִּילוֹ וּלְהוֹסִיף לוֹ חַיִּים.</p>\n<p>קַרְנוֹ תָרוּם בְּכָבוֹד. בֹּא רְאֵה, הָעוֹלָם שֶׁאָמַרְנוּ, אוֹתָהּ קֶרֶן תָּרוּם, וּבַמֶּה? בַּכָּבוֹד שֶׁלְּמַעְלָה, שֶׁאִישׁ זֶה גָּרַם לְחַבְּרָם כְּאֶחָד, וּלְרוֹקֵן בְּרָכוֹת לְמַעְלָה וּמַטָּה.</p>\n<p>רַבִּי אַבָּא אָמַר, בְּכָל זְמַן שֶׁהַמִּשְׁכָּן מוּקָם בְּמַעֲשֵׂי בְּנֵי אָדָם, אָז אוֹתוֹ יוֹם, יוֹם שֶׁל שִׂמְחַת הַכֹּל, וְשֶׁמֶן מִשְׁחַת קֹדֶשׁ מִתְרוֹקֵן בְּאוֹתָם נֵרוֹת, וּמְאִירִים כֻּלָּם. מִי שֶׁגּוֹרֵם אֶת זֶה, גּוֹרֵם לוֹ (באותו עולם הבא) שֶׁיִּנָּצֵל בָּעוֹלָם הַזֶּה, וְיִהְיוּ לוֹ חַיִּים בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (משלי יא) וּצְדָקָה תַּצִּיל מִמָּוֶת, וְכָתוּב (שם ד) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.</p>"],[9522012315,"<p>עָשֵׂה לְךְ שְׁתֵּי חֲצוֹצְרֹת כֶּסֶף וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח, (יחזקאל א) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים. וּבְלֶכֶת הַחַיּוֹת, בָּרְשׁוּת שֶׁלְּמַעְלָה הָיוּ הוֹלְכִים. שֶׁאִם תֹּאמַר שֶׁזֶּה לְמַעְלָה לְמַעְלָה - לֹא. לְמַטָּה. אֶלָּא כְּמוֹ זֶה מִלִּפְנֵי הַפָּנִים, וְזֶה לְאַחַר הַפָּנִים.</p>\n<p>רוּחַ מֵאַרְבַּע רוּחוֹת בְּאַרְבָּעָה מָדוֹרִים וּבְאַרְבָּעָה צְדָדִים, בְּזִיוָם שֶׁנִּבְרְאוּ בְּהִדּוּר הַפָּנִים הַמְּאִירוֹת. בִּגְלַל זֶה כְּעֵין (נאש\"ר) כְּמַרְאֵה הַחַיּוֹת, שֶׁהֵם אַרְבַּע זָוִיּוֹת, דְּגָלִים פְּרוּשִׂים, אַרְיֵ\"ה נֶשֶׁ\"ר שׁוֹ\"ר אָדָ\"ם, שֶׁכּוֹלֵל כֻּלָּם אַרְבָּעָה מַלְאָכִים שֶׁשּׁוֹלְטִים וְכוֹלְלִים הַכֹּל.</p>\n<p>דֶּגֶל רִאשׁוֹן, מֶרְכָּבָה מְזֻיֶּנֶת, אַרְיֵ\"ה, מִיכָאֵ\"ל, רָשׁוּם בִּפְרִישַׂת הַדֶּגֶל הַפָּרוּשׂ לְיָמִין. מִזְרָח רֵאשִׁית הַשֶּׁמֶשׁ הוֹלֵךְ בְּמַשָּׂאוֹ בְּאוֹר. שְׁנֵי מְמֻנִּים תַּחַת יָדָיו, יוֹפִיאֵ\"ל צַדְקִיאֵ\"ל. אֶחָד לְלַמֵּד (לתורה), וְאֶחָד לָלֶכֶת בַּשּׁוּק שֶׁהוֹלֵךְ.</p>\n<p>כְּשֶׁאֵלֶּה לוֹקְחִים, לוֹקְחִים כַּמָּה מֶרְכָּבוֹת מְזֻיָּנוֹת מִצַּד יָמִין, וְהַכֹּל אֶחָד. לְצַד שְׂמֹאל הַשֶּׁמֶשׁ הוֹלֵךְ (לוקח כאחד לצד השמאל, השמש הולך) וּמֵאִיר וּמְעַטֵּר אוֹתָם. אֶלֶף וּרְבָבוֹת מְמֻנִּים תַּחְתָּיו, וְכֻלָּם בְּיִרְאָה וּבְאֵימָה, בְּזִיעַ וּבְרֶתֶת.</p>\n<p>אַרְיֵה מוֹשִׁיט יַד יְמִינוֹ, כּוֹנֵס לְכָל חֵילוֹתָיו אֵלָיו. שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אֶלֶף אֲרָיוֹת סְבִיב אוֹתוֹ אַרְיֵ\"ה, וְהוּא בֵינֵיהֶם בָּאֶמְצַע.</p>\n<p>כְּשֶׁגּוֹעָה הָאַרְיֵה הַזֶּה, הָרְקִיעִים מִזְדַּעְזְעִים, וְכָל הַחֲיָלוֹת וְהַמֶּרְכָּבוֹת מִזְדַּעְזְעִים מִיִּרְאָתוֹ. מֵאוֹתוֹ קוֹל מִתְלַהֵט נְהַר דִּי נוּר, וְיוֹרֵד בְּאֶלֶף וַחֲמֵשׁ מֵאוֹת דַּרְגוֹת הַגֵּיהִנֹּם שֶׁל מַטָּה. אָז מִזְדַּעְזְעִים כָּל רִשְׁעֵי הַגֵּיהִנֹּם, וְהָאֵשׁ לוֹהֶטֶת, וְעַל זֶה כָּתוּב (עמוס ג) אַרְיֵה שָׁאָג מִי לֹא יִירָא.</p>\n<p>גּוֹעָה פַּעַם שְׁנִיָּה - שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים אֶלֶף אֲרָיוֹת, כֻּלָּם גּוֹעִים. מוֹשִׁיט יַד שְׂמֹאלוֹ - כָּל בַּעֲלֵי הַדִּין לְמַטָּה פּוֹחֲדִים וְנִכְפִּים תַּחַת אוֹתָהּ יָד, וְאוֹתָהּ יָד פּוֹשֶׁטֶת עֲלֵיהֶם, וְכֻלָּם תַּחְתֶּיהָ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) יָדְךְ בְּעֹרֶף אֹיְבֶיךְ.</p>\n<p>אַרְבַּע כְּנָפַיִם לְכָל אֶחָד וְאֶחָד מֵאֵשׁ לְבָנָה. כֻּלָּם לוֹהֲטִים. כָּל פָּנִים שֶׁל כַּפְתּוֹר וָפֶרַח בְּלֹבֶן שֶׁל אוֹתָהּ אֵשׁ שְׁקוּעִים.</p>\n<p>אַרְבַּע פָּנִים לְכָל אֶחָד וְאֶחָד לְאַרְבָּעָה צְדָדִים, כֻּלָּם מְאִירִים בְּלֹבֶן הַשֶּׁמֶשׁ. אֶחָד לְצַד מִזְרָח מֵאִיר בְּשִׂמְחָה, וְאֶחָד לְצַד מַעֲרָב, (זה כונס) שֶׁהִכְנִיס מְאוֹרוֹ. וְאֶחָד לְצַד צָפוֹן, חָשׁוּךְ בְּלִי אוֹר, כְּצֵל הַשֶּׁמֶשׁ לְגַבֵּי הַשֶּׁמֶשׁ. הַצֵּל חָשׁוּךְ, הַשֶּׁמֶשׁ מֵאִיר. מִשּׁוּם שֶׁהַשֶּׁמֶשׁ וְהַצֵּל - יָמִין וּשְׂמֹאל, וְהוֹלְכִים כְּאֶחָד. חֲשׁוּכִים (חשבון) שֶׁהוֹלְכִים עִמּוֹ, כָּל אֵלּוּ שֶׁלּוֹקְחִים כְּלֵי זַיִן.</p>\n<p>וְכֻלָּם מִיָּמִין וּמִשְּׂמֹאל בִּשְׁלֹשָׁה רָאשִׁים. רֹאשׁ אֶחָד שֶׁלּוֹ, שִׁבְעִים וְאַרְבָּעָה אֶלֶף וְשֵׁשׁ מֵאוֹת. אֵלֶּה אוֹתָם רֹאשׁ אֶחָד. יוֹצְאִים כֹּחַ בְּיָמִין שֶׁהוּא הֵרִים עֲלֵיהֶם, פְּרָט לְכָל אוֹתָם מְמֻנִּים שֶׁלְּמַטָּה, תַּחַת אֵלֶּה. שִׁלְטוֹנִים אֵלֶּה עַל אֵלֶּה, דְּרָגוֹת תַּחְתּוֹנוֹת עִם עֶלְיוֹנוֹת, שֶׁאֵין לָהֶם חֶשְׁבּוֹן.</p>\n<p>רֹאשׁ שֵׁנִי, שֶׁהוֹלֵךְ בָּרֹאשׁ הָרִאשׁוֹן, חֶשְׁבּוֹנוֹ חֲמִשִּׁים וְאַרְבָּעָה אֶלֶף וְאַרְבַּע מֵאוֹת, פְּרָט לְכָל הַמְמֻנִּים הַלָּלוּ שֶׁתַּחַת לְאַרְבָּעָה צְדָדִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן. רֹאשׁ שְׁלִישִׁי, שֶׁהוֹלֵךְ אַחֲרֵיהֶם, חֲמִשִּׁים וְשִׁבְעָה אֶלֶף וְאַרְבַּע מֵאוֹת. כְּמוֹ שֶׁנּוֹטֵל הַיָּמִין, כָּךְ גַּם נוֹטֵל הַשְּׂמֹאל. כָּךְ גַּם מִלִּפְנֵיהֶם, כָּךְ גַּם מֵאַחֲרֵיהֶם.</p>\n<p>כֵּיוָן שֶׁנּוֹסֵעַ רִאשׁוֹן - וְהוּרַד הַמִּשְׁכָּן. וְכָל הַלְוִיִּם אוֹמְרִים שִׁירָה. בַּעֲלֵי הַתִּשְׁבָּחוֹת כֻּלָּם מִצִּדּוֹ. וְאָז כָּתוּב, (יחזקאל א) כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים.</p>"],[9522012316,"<p>דֶּגֶל שֵׁנִי, מֶרְכָּבָה מְזֻיֶּנֶת, נֶשֶׁ\"ר, אוּרִיאֵ\"ל, דָּרוֹ\"ם. וּשְׁנֵי מְמֻנִּים עִמּוֹ - שַׁמְשִׁיאֵ\"ל, חַסְדִּיאֵ\"ל. נֶשֶׁר זֶה עוֹלֶה, וְכָל בַּעֲלֵי הַכְּנָפַיִם מִלְּפָנָיו. כַּמָּה מֶרְכָּבוֹת עוֹלוֹת בְּכָל הַצְּדָדִים, כָּל אַחַת וְאַחַת בְּחֹזֶק הַשֶּׁמֶשׁ.</p>\n<p>רוּחַ שֶׁל רוּחַ פְּנִימִית יוֹצֵאת, וְאוֹתָהּ הָרוּחַ מַגִּיעָה לַנֶּשֶׁר הַזֶּה, וְעוֹלִים אֵיבָרָיו וּמְכַסִּים אֶת הַגּוּף, כְּמוֹ שֶׁנֶּאֱמַר (איוב לט) הֲמִבִּינָתְךְ יַאֲבֶר נֵץ יִפְרֹשׂ כְּנָפָיו לְתֵימָן. כְּמוֹ דֻגְמַת כְּעֵין (דברים לב) כְּנֶשֶׁר יָעִיר קִנּוֹ, נֶשֶׁר נֵץ זֶה עִם יוֹנָה, עִם נֵץ, וְכָל בַּעֲלֵי הַכְּנָפַיִם כֻּלָּם מְצַפְצְפִים וּשְׂמֵחִים. אֶחָד מִצַּד (עמוד אחד) לְפָנָיו עוֹלֶה מִמַּטָּה לְמַעְלָה. כַּמָּה צִפֳּרִים יוֹרְדוֹת וְעוֹלוֹת, מְצַפְצְפוֹת וּשְׂמֵחוֹת, הוֹלְכוֹת וּמְשׁוֹטְטוֹת.</p>\n<p>כְּשֶׁנּוֹסֵעַ, מוֹשִׁיט כָּנָף יָמִין, כּוֹנֵס לְכָל חֵילָיו, שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים אֶלֶף בַּעֲלֵי כְנָפַיִם בִּשְׁנֵי גוּפִים, נֶשֶׁ\"ר וְאַרְיֵ\"ה כְּאֶחָד. מֵרִים קוֹל, כָּל הָאֲחֵרִים עוֹלִים וְיוֹרְדִים, מְצַפְצְפִים מִצִּדָּם מִכַּמָּה דְרָגוֹת.</p>\n<p>שְׁלֹשָה רָאשִׁים הֵם כְּאֶחָד בְּמַחֲנוֹת אֵלּוּ, וְכֻלָּם בְּחֶשְׁבּוֹן אֶחָד. וְחֶשְׁבּוֹן הָרָאשִׁים הַלָּלוּ - רֹאשׁ אֶחָד, אַרְבָּעִים וְשִׁשָּׁה אֶלֶף וַחֲמֵשׁ מֵאוֹת. רֹאשׁ שֵׁנִי, חֲמִשִּׁים וְתִשְׁעָה אֶלֶף וּשְׁלֹשׁ מֵאוֹת. רֹאשׁ שְׁלִישִׁי, אַרְבָּעִים וַחֲמִשָּׁה אֶלֶף וְשׁשׁ מֵאוֹת וַחֲמִשִּׁים.</p>\n<p>מִשְּׁנֵי צְדָדִים אֵלּוּ יוֹצְאִים שְׁנֵי כָרוֹזִים שֶׁהוֹלְכִים לִפְנֵי כָּל הַמַּחֲנוֹת, כְּשֶׁשְּׁנֵי אֵלֶּה מַכְרִיזִים: כָּל הַחֲיָלוֹת וְכָל הַמַּחֲנוֹת, חַיּוֹת קְטַנּוֹת עִם גְּדוֹלוֹת, כֻּלָּם מִתְכַּנְּסִים. מִי רָאָה נְסִיעַת כָּל הָרְקִיעִים, כֻּלָּם נוֹסְעִים בְּמַשָּׂא בַּמַּחֲנוֹת לִפְנֵי אוֹתוֹ מִשְׁכָּן.</p>\n<p>בְּשָׁעָה שֶׁאֶחָד מֵהֶם, אוֹתוֹ שֶׁבָּא מִצַּד אַרְיֵה, פּוֹשֵׁט קוֹל כְּדֵי שֶׁלֹּא יִזְדַּעְזְעוּ כָּל אוֹתָם קוֹלוֹת, אָז מִתְכַּנְּסוֹת כָּל אוֹתָן מַחֲנוֹת. בְּשָׁעָה שֶׁאַחֵר קוֹרֵא, נִשְׁבָּר הַקּוֹל וְלֹא פוֹשֵׁט, כָּל אוֹתָן הַמַּחֲנוֹת שֶׁל הַנֶּשֶׁר הַזֶּה, כֻּלָּן מִתְכַּנְּסוֹת לִנְסֹע בְּמַסָּעָם. כְּנֶגֶד אֵלּוּ שְׁתֵּי חֲצוֹצְרוֹת כֶּסֶף, כְּגוֹן זֶה הַכֹּל לְמַטָּה. בֹּא רְאֵה, כְּשֶׁאֵלֶּה נוֹסְעִים, מַה כָּתוּב? (יחזקאל א) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם, אוֹתָם שֶׁמִּתְכַּנְּסִים אֲלֵיהֶם, כְּמוֹ שֶׁהָרֹאשׁ מִסְתַּכֵּל, כָּךְ גַּם כֻּלָּם.</p>"],[9522012317,"<p>דֶּגֶל שְׁלִישִׁי, שׁוֹר, גַּבְרִיאֵל, צָפוֹן. שְׁנֵי מְמֻנִּים עִמּוֹ, קַפְצִיאֵ\"ל חִזְקִיאֵ\"ל. הַשּׁוֹר הַזֶּה מִצַּד שְׂמֹאל. קַרְנָיו עוֹלוֹת בֵּין שְׁתֵּי עֵינָיו. רוֹגֵז בְּהִסְתַכְּלוּת, עֵינַיִם לוֹהֲטוֹת כְּאֵשׁ שֶׁל נוּר דּוֹלֵק. נוֹגֵחַ וְרוֹפֵס בְּרַגְלָיו וְלֹא חָס.</p>\n<p>כְּשֶׁגּוֹעָה הַשּׁוֹר הַזֶּה, יוֹצְאִים מִנֶּקֶב תְּהוֹם רַבָּה כַּמָּה חֲבוּרוֹת מַכִּים (מחבלים), כֻּלָּם גּוֹעִים וּמְשׁוֹטְטִים לְפָנָיו, וְהַחֵמֶת וְהַתִּיק שֶׁבּוֹ שֶׁל כָּל עֲווֹנוֹת תְּלוּיִים לְפָנָיו, שֶׁהֲרֵי כָּל עֲבֵרוֹת הָעוֹלָם כְּתוּבִים בְּסֵפֶר וְעוֹלִים.</p>\n<p>שִׁבְעָה נַהֲרוֹת אֵשׁ שׁוֹפְעִים לְפָנָיו. כְּשֶׁצָּמֵא הוֹלֵךְ לְאוֹתוֹ נְהַר דִּינוּר, וְשׁוֹאֵב אוֹתוֹ בִּגְמִיעָה אַחַת. וְאוֹתוֹ נָהָר מִתְמַלֵּא כְּבַתְּחִלָּה וְלֹא נִהְיֶה אַכְזָב. כָּל אוֹתָם חֲיָלוֹת שׁוֹאֲבִים אֵשׁ אוֹכֶלֶת אֵשׁ. וְאִלְמָלֵא שֶׁמִּצַּד אַרְיֵה יוֹצֵא נָהָר אֶחָד שֶׁל מַיִם שֶׁמְּכַבִּים אֶת הַגֶּחָלִים שֶׁלָּהֶם, לֹא יוּכַל הָעוֹלָם לִסְבֹּל.</p>\n<p>חֹשֶׁךָ הַשֶּׁמֶשׁ שָׁם נִמְצָא, לֹא נִמְצָא אוֹר. כַּמָּה חֲיָלוֹת שֶׁל שׁוֹמְרֵי חֹק הוֹלְכִים וּמְשׁוֹטְטִים בַּחֹשֶׁךְ, וְאוֹתוֹ נָהָר שֶׁדּוֹלֵק בַּצַּד הַזֶּה, אֵשׁ שְׁחֹרָה חֲשׁוּכָה. וְאִם תֹּאמַר שֶׁאֵין אֵשׁ לְבָנָה, אֵשׁ שְׁחֹרָה, אֵשׁ אֲדֻמָּה, אֵשׁ שֶׁל שְׁנֵי גְוָנִים - אַל תֹּאמַר, שֶׁהֲרֵי וַדַּאי כָּךְ זֶה! וְעִם כָּל זֶה לְמַעְלָה לְמַעְלָה כָּךְ נִמְצָא, וּמִשָּׁם שׁוֹפֵעַ לַתַּחְתּוֹנִים הַלָּלוּ.</p>\n<p>שָׁנִינוּ, הַתּוֹרָה בַּמֶּה נִמְצֵאת? אֵשׁ לְבָנָה, וְאֵשׁ שְׁחֹרָה עַל גַּבֵּי לְבָנָה. בִּשְׁנֵי סוּגֵי אֵשׁ נִמְצֵאת הַתּוֹרָה. בּא רְאֵה, הָאֵשׁ אַחַת הִיא, וּמִתְחַלֶּקֶת לְאַרְבָּעָה. הַמַּיִם אֶחָד הֵם, וּמִתְחַלְּקִים לְאַרְבָּעָה. הָרוּחַ אַחַת הִיא, וּמִתְחַלֶּקֶת לְאַרְבָּעָה.</p>\n<p>שְׁלֹשָה רָאשִׁים נִמְצָאִים (מתחברים) בְּמֶרְכָּבוֹת אֵלּוּ. חֶשְׁבּוֹנָם - רֹאשׁ אֶחָד, שִׁשִּׁים וּשְׁנַיִם אֶלֶף וּשְׁבַע מֵאוֹת. רֹאשׁ שֵׁנִי, אַרְבָּעִים וְאֶחָד אֶלֶף וַחֲמֵשׁ מֵאוֹת. רֹאשׁ שְׁלִישִׁי, חֲמִשִּׁים וּשְׁלֹשָׁה אֶלֶף וְאַרְבַּע מֵאוֹת. פְּרָט לְכָל אֵלּוּ הַדְּרָגוֹת הָאֲחֵרוֹת שֶׁנִּפְרָדוֹת בְּצִדֵּיהֶן, וְאֵין לָהֶן חֶשְׁבּוֹן. כֻּלָּן דְּרָגוֹת עַל דְּרָגוֹת, פְּרָט לְכַמָּה חֲיָלוֹת שֶׁל שׁוֹמְרֵי חֹק שֶׁהֵם לְמַטָּה, חֲצוּפִים כַּכֶּלֶב, נוֹשְׁכִים כַּחֲמוֹר. אוֹי לְמִי שֶׁנִּמְצָא לִפְנֵיהֶם, וְדִין שֶׁלָּהֶם בְּצַד רְבִיעִי.</p>"],[9522012318,"<p>דֶּגֶל רְבִיעִי, אָדָ\"ם, רְפָאֵ\"ל, מַעֲרָב. יַחַד אִתּוֹ רְפוּאָה. בַּצַּד שֶׁאָדָם נִכְלָל, דִּין עֶלְיוֹן עָלָיו מִתְרַפֵּא. זֶה (אחד) אוֹחֵז בְּקַרְנֵי הַשּׁוֹר, כְּשֶׁרוֹצֶה לְהַכְנִיסָם לִתְהוֹם רַבָּה, וְכוֹפֵת אוֹתָם שֶׁלֹּא יִשָּׂרֵף הָעוֹלָם. לְאַחַר זֶה שׁוֹרֶה קוֹל דְּמָמָה דַּקָּה, דִּין. (כאן) דָּבָר בַּחֲשַׁאי, לֹא נִשְׁמָע דְּבַר הֲבָרָה כְּלָל.</p>\n<p>בְּצַד זֶה שׁוֹרֶה מִי שֶׁשּׁוֹרֶה, עוֹלֶה מִי שֶׁעוֹלֶה, הַשֶּׁמֶשׁ מִתְכַּנֵּס לְהָאִיר לְמָקוֹם זֶה. בִּגְלַל זֶה וּתְקַעְתֶּם תְּרוּעָה בְּצַד דָּרוֹם. אֲבָל כָּאן לֹא זֶה וְלֹא זֶה. מַדּוּעַ תְּרוּעָה? לִכְפּוֹת צַד צָפוֹן, וְלָכֵן צַד צָפוֹן לְאָחוֹר.</p>\n<p>בֹּא רְאֵה, שְׁתֵּי חֲצוֹצְרֹת, מִשּׁוּם שֶׁהֵם מִצַּד שְׁנַיִם שֶׁאָמַרְנוּ, מִמִּזְרָח וּמִדָּרוֹם. הֵן עֲתִידוֹת לִשְׁבֹּר דִּינִים וְלִכְפּוֹתָם. וְעַל זֶה הֵן מִכֶּסֶף. וּמִשּׁוּם זֶה, וּבְיוֹם שִׂמְחַתְכֶם וּבְמוֹעֲדֵיכֶם וְגוֹ', וּתְקַעְתֶּם בַּחֲצֹצְרֹת. סְתָם, בֵּין לְמַעְלָה בֵּין לְמַטָּה. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִכְבוֹדָם וְנָתַן לָהֶם חֵלֶק עֶלְיוֹן עַל כָּל שְׁאָר הָעַמִּים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בְּתִשְׁבְּחוֹתֵיהֶם. זֶהוּ שֶׁכָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל וְגוֹ'.</p>"],[9522012319,"<p>וַיְהִי בִּנְסֹעַ הָאָרֹן וַיֹּאמֶר מֹשֶׁה וְגוֹ'. רַבִּי אֶלְעָזָר אָמַר, כָּאן יֵשׁ לְהִסְתַּכֵּל, נ' שֶׁהִיא (מנזרת) מְחַזֶּרֶת לְאָחוֹר, כָּאן בִּשְׁנֵי מְקוֹמוֹת, לָמָּה? וְאִם תֹּאמַר נ' כְּפוּפָה, הֲרֵי יָדוּעַ נ' כְּפוּפָה נְקֵבָה. נ' פְּשׁוּטָה, כְּלָל שֶׁל זָכָר וּנְקֵבָה. וַהֲרֵי בֵּאַרְנוּ בְּמָקוֹם זֶה, וַיְהִי בִּנְסֹעַ הָאָרֹן. לָמָּה חָזַר לְאַחַר כָּךְ כְּמוֹ זֶה?</p>\n<p>בֹּא רְאֵה, נ' בְּאַשְׁרֵי יוֹשְׁבֵי בֵיתֶךְ לֹא נֶאֶמְרָה, מִשּׁוּם שֶׁהִיא בַּגָּלוּת, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, שֶׁכָּתוּב (עמוס ה) נָפְלָה לֹא תוֹסִיף קוּם בְּתוּלַת יִשְׂרָאֵל וְגוֹ'. אֶלָּא מַה כָּתוּב לְמַעְלָה? וַאֲרוֹן בְּרִית ה' נֹסֵעַ לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשֶׁת יָמִים לָתוּר לָהֶם מְנוּחָה. כֵּיוָן שֶׁהָיָה נוֹסֵעַ הָאָרוֹן, נוּ\"ן נוֹסַעַת עָלָיו (עמו), וַהֲרֵי הַשְּׁכִינָה יוֹשֶׁבֶת עַל גַּבֵּי הָאָרוֹן. בֹּא רְאֵה חֲבִיבוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְגַבֵּי יִשְׂרָאֵל, שֶׁהֲרֵי אַף עַל גַּב שֶׁהֵם סוֹטִים מִדֶּרֶךְ הַיָּשָׁר, הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא רוֹצֶה לְעָזְבָם, וּבְכָל זְמַן מַחֲזִיר פָּנָיו לְמוּלָם, שֶׁאִם לֹא כָּךְ, לֹא יַעַמְדוּ בָעוֹלָם.</p>\n<p>בֹּא רְאֵה, הָאָרוֹן הָיָה נוֹסֵעַ לִפְנֵיהֶם דֶּרֶךְ שְׁלֹשָׁה יָמִים, נ' לֹא הָיְתָה נִפְרֶדֶת מִמֶּנּוּ, וְנוֹסַעַת עִמּוֹ. וּמִתּוֹךְ אַהֲבַת יִשְׂרָאֵל מַחֲזִיר פָּנָיו וּמִסְתּוֹבֵב מִלְּגַבֵּי הָאָרוֹן, כְּמוֹ עֹפֶר הָאַיָּלִים, כְּשֶׁהוּא הוֹלֵךְ, מַחֲזִיר פָּנָיו לַמָּקוֹם שֶׁמִּשָּׁם יָצָא. וְעַל כֵּן בִּנְסֹעַ הָאָרֹן, נוּ\"ן מְסוֹבֶבֶת פָּנִים לְמוּל יִשְׂרָאֵל, וְכִתְפֵי הַגּוּף לְגַבֵּי הָאָרוֹן.</p>\n<p>וְעַל כָּךְ, כְּשֶׁהָאָרוֹן הָיָה נוֹסֵעַ, מֹשֶׁה אָמַר קוּמָה ה', לֹא תַעֲזֹב אוֹתָם, הַחֲזֵר פָּנִים אֵלֵינוּ, וְאָז נוּ\"ן חוֹזֶרֶת לְגַבֵּיהֶם כְּצוּרָה זוֹ, כְּמִי שֶׁמַּחֲזִיר פָּנָיו לְמִי שֶׁאוֹהֵב. וּכְשֶׁהָיָה מַתְחִיל הָאָרוֹן (וישראל) לִשְׁרוֹת, אָז הֶחֱזִירָה נוּ\"ן פָּנֶיהָ מִיִּשְׂרָאֵל, וְהָחְזְרָה לְגַבֵּי הָאָרוֹן, וּבַכֹּל הָחֳזַר.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, אֶלְעָזָר, בְּוַדַּאי כָּךְ הוּא, אֲבָל כָּאן לֹא הֶחֱזִיר פָּנָיו מִיִּשְׂרָאֵל, שֶׁאִם כָּךְ, צְרִיכָה נוּ\"ן לְהִתְהַפֵּךְ מִגָּוֶן שֶׁל אַחֵר עֶלְיוֹן (שלמעלה), זֶה מְנֻזָּר לְאָחוֹר, וְזֶה בְּדֶרֶךְ יָשָׁר לְגַבֵּי הָאָרוֹן.</p>\n<p>אֶלָּא וַדַּאי לֹא הֶחֱזִיר פָּנָיו מֵהֶם. וּמֶה עָשָׂה בְּשָׁעָה שֶׁהָאָרוֹן הִתְחִיל לְהַשְׁרוֹת? אָמַר מֹשֶׁה שׁוּבָה ה', וְאָז שׁוֹרֶה הָאָרוֹן, וְהַשְּׁכִינָה עוֹמֶדֶת בְּצַד אַחֵר, וְהַפָּנִים מוּל יִשְׂרָאֵל וּמוּל הָאָרוֹן. (ומשום כך) וְאָז הַכֹּל נִכְלָל (לתוכה) לַכִּוּוּן, לָאָרוֹן וּלְיִשְׂרָאֵל. אֶלָּא שֶׁיִּשְׂרָאֵל גָּרְמוּ אַחַר כָּךְ, שֶׁכָּתוּב וַיְהִי הָעָם כְּמִתְאֹנֲנִים.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אֲנִי שֶׁאָמַרְתִּי מִסִּפְרוֹ שֶׁל רַב יֵיבָא סָבָא, שֶׁאָמַר שֶׁבֵּין מִצַּד זֶה וּבֵין מִצַּד זֶה חָזַר. אָמַר לוֹ, נָאֶה אָמַר, אֲבָל זֶה שֶׁאָמַרְנוּ, כָּךְ תִּמְצָא בְּסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְכָךְ זֶה בְּוַדַּאי.</p>"],[9522012320,"<p>וְהַמָּן כִּזְרַע גַּד הוּא. אָמַר רַבִּי יוֹסֵי, לְהַעֲמִיד זֶרַע וַחֲיָלוֹת בָּאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר (בראשיתמט) גָּד גְּדוּד יְגוּדֶנּוּ. מַה זֶּרַע גָּד נָטְלוּ חֶלְקָם בְּאֶרֶץ אַחֶרֶת, כָּךְ הַמָּן שָׁרָה עַל יִשְׂרָאֵל מִחוּץ לָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>דָּבָר אַחֵר כִּזְרַע גַּד הוּא - כִּזְרַע גָּד לָבָן, וְנִקְפֶּה כְּשֶׁיּוֹרֵד לָאֲוִיר, וְנִטְחַן (והתגשם) (ונבלע) בַּגּוּף, וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים. וְעֵינוֹ כְּעֵין הַבְּדלַח, כְּמוֹ אוֹתוֹ בְּדוֹלַח שֶׁהוּא לָבָן, כְּגוֹן הַיָּמִין (לבן העין) שֶׁלְּמַעְלָה. (כזרע גד, כך לא נקראו בארץ מצרים, אבל לכך מכשפים זרע כזרע גד הוא, כזרעגדלבן, וכחוכאשריורדמלמעלהלמטה).</p>"],[9522012321,"<p>אָמַר רַבִּי יִצְחָק, מַה שּׁוֹנֶה (שאמר) מֹשֶׁה בְּדָבָר זֶה (חלש) לְמַעְלָה כִּנְקֵבָה, שֶׁכָּתוּב אִם כָּךְ אַתְּ עֹשֶׂה לִּי? אַתְּ?! אַתָּה צָרִיךְ לוֹ לִהְיוֹת! אֶלָּא לְמָקוֹם שֶׁהַמָּוֶת שׁוֹרֶה בּוֹ הוּא אָמַר, וְאוֹתוֹ מָקוֹם שֶׁל הַנְּקֵבָה הוּא. בִּגְלַל זֶה אָמַר הָרְגֵנִי נָא הָרוֹג, וְזֶה עֵץ הַמָּוֶת. וַהֲרֵי בֵּאַרְנוּ שֶׁבְּעֵץ הַחַיִּים לֹא שׁוֹרֶה הַמָּוֶת. וְעַל כָּךְ חָזַר לְגַבֵּי אִילַן הַמָּוֶת וְאָמַר אַתְּ, וְלֹא אָמַר אַתָּה, וְכָךְ צָרִיךְ לוֹ.</p>\n<p>מִיָּד - וַיֹּאמֶר ה' אֶל מֹשֶׁה אֶסְפָה לִּי שִׁבְעִים אִישׁ וְגוֹ'. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, אַתָּה רוֹצֶה מָוֶת בְּכָל זְמַן - הֲרֵי לְךְ, וְאָצַלְתִּי מִן הָרוּחַ וְגוֹ'. בּא רְאֵה שֶׁכָּאן יָדַע מֹשֶׁה שֶׁהוּא יָמוּת וְלֹא יִכָּנֵס לָאָרֶץ, שֶׁהֲרֵי אֶלְדָּד וּמֵידָד הָיוּ אוֹמְרִים דָּבָר זֶה.</p>\n<p>עַל כָּךְ לֹא צָרִיךְ לוֹ לָאָדָם בְּשָׁעָה שֶׁהָרֹגֶז שׁוֹרֶה בּוֹ לְקַלֵּל עַצְמוֹ, שֶׁהֲרֵי כַּמָּה עוֹמְדִים עָלָיו שֶׁמְּקַבְּלִים אוֹתוֹ דָּבָר. בִּזְמַן אַחֵר שֶׁרָצָה מִיתָה, לֹא קִבְּלוּ מִמֶּנּוּ, מִשּׁוּם שֶׁהַכֹּל הָיָה לְתוֹעֶלֶת יִשְׂרָאֵל. כָּעֵת אֵינוֹ, אֶלָּא מִתּוֹךְ רֹגֶז וְדחַק, וּמִשּׁוּם זֶה קִבְּלוּ מִמֶּנּוּ. וְעַל כָּךְ נִשְׁאֲרוּ לְאַחַר כָּךְ אֶלְדָּד וּמֵידָד וְאָמְרוּ אֶת זֶה, שֶׁמֹּשֶׁה יִתְאַסֵּף, וִיהוֹשֻׁעַ יַכְנִיסָם לְיִשְׂרָאֵל לָאָרֶץ.</p>\n<p>וּמִשּׁוּם זֶה בָּא יְהוֹשֻׁעַ לְמֹשֶׁה וְקִנֵּא עַל מֹשֶׁה, וּמֹשֶׁה לֹא הִשְׁגִּיחַ בִּכְבוֹדוֹ, וְעַל כָּךְ אָמַר, אֲנִי מֹשֶׁה כְּלָאֵם. מַה זֶּה כְּלָאֵם? מָנַע מֵהֶם אוֹתָם דְּבָרִים, כְּמוֹ שֶׁנֶּאֱמַר (שמות לו) וַיִּכָּלֵא הָעָם מֵהָבִיא. (בראשית ח) וַיִּכָּלֵא הַגֶּשֶׁם מִן הַשָּׁמָיִם. מְנִיעוּת מַמָּשׁ. וּמֹשֶׁה לֹא רָצָה. צֵא וּרְאֵה עַוְנְתָנוּתוֹ שֶׁל מֹשֶׁה, מַה כָּתוּב? הַמְקַנֵּא אַתָּה לִי וְגוֹ'. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהוּא עָלָה עַל כָּל הַנְּבִיאִים הָעֶלְיוֹנִים (של העולם). אָמַר רַבִּי יְהוּדָה, כָּל שְׁאָר הַנְּבִיאִים לְגַבֵּי מֹשֶׁה כִּלְבָנָה לְגַבֵּי הַשֶּׁמֶשׁ.</p>"],[9522012322,"<p>רַבִּי אַבָּא הָיָה יוֹשֵׁב לַיְלָה אֶחָד וְעוֹסֵק בַּתּוֹרָה, וְהָיוּ עִמּוֹ רַבִּי יוֹסֵי וְרַבִּי חִזְקִיָּה. אָמַר רַבִּי יוֹסֵי, כַּמָּה אוֹתָם בְּנֵי הָאָדָם חַזְקֵי לֵב, שֶׁלֹּא מַשְׁגִּיחִים בְּדִבְרֵי אוֹתוֹ עוֹלָם כְּלוּם. אָמַר רַבִּי אַבָּא, בְּשַׂר הַלֵּב שֶׁאָחוּז בְּכָל אֵיבְרֵי הַגּוּף עוֹשֶׂה לָהֶם. פָּתַח וְאָמַר, (קהלת ו) יֵשׁ רָעָה אֲשֶׁר רָאִיתִי תַּחַת הַשָּׁמֶשׁ וְרַבָּה הִיא עַל הָאָדָם. יֵשׁ רָעָה - זֶה הוּא חֹזֶק רַע שֶׁל הַלֵּב, שֶׁרוֹצֶה לִשְׁלֹט בְּדִבְרֵי הָעוֹלָם הַזֶּה וְלֹא מַשְׁגִּיחַ בְּדִבְרֵי הָעוֹלָם הַהוּא דָּבָר.</p>\n<p>מַדּוּעַ הִיא רָעָה? הַפָּסוּק אַחַר כָּךְ מוֹכִיחַ, שֶׁכָּתוּבּ אִישׁ אֲשֶׁר יִתֶּן לוֹ הָאֱלֹהִים עֹשֶׁר וּנְכָסִים וְגוֹ'. פָּסוּק זֶה קָשֶׁה, כֵּיוָן שֶׁכָּתוּב וְאֵינֶנּוּ חָסֵר לְנַפְשׁוֹ מִכֹּל אֲשֶׁר יִתְאַוֶּה, לָמָּה וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ, שֶׁהֲרֵי אֵינוֹ חָסֵר לְנַפְשׁוֹ כְּלוּם? אֶלָּא סוֹד הוּא, וְכָל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ מִתְלַבְּשִׁים הֵם בִּדְבָרִים אֲחֵרִים, כְּדִבְרֵי הַתּוֹרָה שֶׁמִּתְלַבְּשִׁים בְּסִפּוּרֵי הָעוֹלָם.</p>\n<p>בֹּא רְאֵה, אַף עַל גַּב שֶׁרוֹצִים לְהִסְתַּכֵּל בַּלְּבוּשׁ, כָּעֵת פָּסוּק זֶה כָּךְ אוֹמֵר, שֶׁאָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה וְנוֹתֵן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא עֹשֶׁר כְּדֵי שֶׁיִּזְכֶּה בּוֹ לָעוֹלָם הַבָּא וְתִשָּׁאֵר אֶצְלוֹ הַקֶּרֶן. מַהִי הַקֶּרֶן? אוֹתָהּ שֶׁעוֹמֶדֶת, שֶׁהוּא מָקוֹם לִצְרֹר בּוֹ הַנְּשָׁמָה. בִּגְלַל זֶה צָרִיךְ לְהַשְׁאִיר אַחֲרָיו לְאוֹתָהּ קֶרֶן, וְקֶרֶן זוֹ יְקַבְּלָהּ לְאַחַר שֶׁיֵּצֵא מֵהָעוֹלָם הַזֶּה.</p>\n<p>מִשּׁוּם שֶׁקֶּרֶן זוֹ הִיא עֵץ הַחַיִּים שֶׁל אוֹתוֹ עוֹלָם, וְלֹא עוֹמֵד בָּעוֹלָם הַזּה אֶלָּא אוֹתוֹ פְּרִי שֶׁיּוֹצֵא מִמֶּנּוּ, וְלָכֵן אוֹכֵל הָאָדָם פִּרְיוֹ, שֶׁזּוֹכֶה בָּעוֹלָם הַזֶּה, וְהַקֶּרֶן קַיֶּמֶת לְאוֹתוֹ עוֹלָם לִזְכּוֹת בָּהּ בְּחַיִּים עֶלְיוֹנִים שֶׁלְּמַעְלָה.</p>\n<p>וּמִי שֶׁמְּטַמֵּא עַצְמוֹ וְנִמְשָׁךְ אַחַר עַצְמוֹ וְלֹא מְחַסֵּר לְנַפְשׁוֹ וּלְעַצְמוֹ כְּלוּם, וְאוֹתוֹ עֵץ נִשְׁאָר וְלֹא שָׂם אוֹתוֹ מוּלוֹ בְּיִרְאָה וּלְקַבְּלוֹ לְמַעְלָה, אָז - וְלֹא יַשְׁלִיטֶנּוּ הָאֱלֹהִים לֶאֱכֹל מִמֶּנּוּ, וְלִזְכּוֹת בְּאוֹתוֹ עֹשֶׁר. וַדַּאי אָדָם אַחֵר יֹאכְלֶנּוּ, כְּמוֹ שֶׁנֶּאֱמַר (איוב כז) יָכִין וְצַדִּיק יִלְבָּשׁ. בִּגְלַל זֶה צָרִיךְ הָאָדָם לִזְכּוֹת בְּמַה שֶּׁנָּתַן לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ עוֹלָם, וְאָז אוֹכֵל מִמֶּנּוּ בָּעוֹלָם הַזֶּה, וְתִשָּׁאֵר לוֹ אוֹתָהּ קֶרֶן לְעוֹלָם אַחֵר, לִהְיוֹת צָרוּר בִּצְרוֹר הַחַיִּים. אָמַר רַבִּי יוֹסֵי, וַדַּאי.</p>\n<p>עוֹד אָמַר רַבִּי יוֹסֵי, כָּתוּב אִם כָּכָה אַתְּ עֹשֶׂה לִּי הָרְגֵנִי נָא וְגוֹ'. וְכִי מֹשֶׁה, שֶׁהוּא עָנָו מִכָּל בְּנֵי הָעוֹלָם, מִשּׁוּם שֶׁשָּׁאֲלוּ מִמֶּנּוּ יִשְׂרָאֵל לֶאֱכֹל מָסַר עַצְמוֹ לְמִיתָה? לָמָּה? אָמַר רַבִּי אַבָּא, דָּבָר זֶה לָמַדְנוּ וְסוֹד עֶלְיוֹן הוּא. מֹשֶׁה לֹא הֵרַע לְפָנָיו וְלֹא שָׁאַל מִיתָה עַל שֶׁשָּׁאֲלוּ יִשְׂרָאֵל.</p>\n<p>בֹּא וּרְאֵה, מֹשֶׁה נֶאֱחַז, וְהָיָה עוֹלֶה בְּמַה שֶּׁלֹּא נֶאֱחַז נָבִיא אַחֵר. (שהרי היה אחוז בצדקה) וּבְשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה (שמות טז) הִנְנִי מַמְטִיר לָכֶם לֶחֶם מִן הַשָּׁמָיִם, שָׂמַח מֹשֶׁה וְאָמַר, וַדַּאי כָּעֵת אוֹתָהּ שְׁלֵמוּת נִמְצֵאת בִּי, שֶׁהֲרֵי בִּגְלָלִי נִמְצָא מָן לְיִשְׂרָאֵל. כֵּיוָן שֶׁרָאָה מֹשֶׁה שֶׁחָזְרוּ לָרֶדֶת לְדַרְגָּה אַחֶרֶת וְשָׁאֲלוּ בָשָׂר, וְאָמְרוּ (במדבר כא) וְנַפְשֵׁנוּ קָצָה בַּלֶּחֶם הַקְּלוֹקֵל, אָמַר, אִם כָּךְ זֶה, הֲרֵי דַּרְגָּתִי פְגוּמָה, שֶׁהֲרֵי בִּגְלָלִי יֹאכְלוּ יִשְׂרָאֵל מָן בַּמִּדְבָּר. הֲרֵי אֲנִי פָגוּם, וְאַהֲרֹן פָּגוּם, וְנַחְשׁוֹן בֶּן עַמִּינָדָב פָּגוּם.</p>\n<p>אָמַר, וְאִם כָּכָה אַתְּ עֹשֶׂה לִּי הָרְגֵנִי נָא הָרֹג, שֶׁנֶּחְשַׁבְתִּי נְקֵבָה בְּמַאֲכָלָהּ, (ואני יורד מהשמים, שהוא דרגה עליונה, לרדת לדרגת נקבה, ואני עדיף משאר נביאי העולם. ועל זה אמר, ואל אראה (אחותי) ברעתי, כמת, ודאי לרדת לדרגה תחתונה.</p>"],[9522012323,"<p>אז, ויאמר ה' אל משה אספה לי שבעים איש. אתה שאלת מקום שמיתה לא תצטרך, מקום שלא תהא פגום בדרגה שלך, ועל זה כתוב ואצלתי מן הרוח אשר עליך, שכלם הם שנאחזו שם). (ואני ירדתי מן השמים לארץ. את עשה לי, לרדת למקום הנקבה ולפגם מקומי ודרגתי. אם כך, הרגני נא הרג אם נא מצאתי חן בעיניך ואל אראה ברעתי. רעתי היא ודאי לאחז בדרגה תחתונה. אז, ויאמרה'אלמשהאספהלישבעים איש מזקני ישראל. הרי הם לתתלהם אכל אחר, ולא תהיה פגום בדרגתך. ועל זה, ואצלתי מן הרוח אשר עליך ושמתי עליהם. מה הטעם, ' משום שהם נאחזו בלבנה וכו') בַּלְּבָנָה, וְרָצָה הַשֶּׁמֶשׁ לְהָאִיר לָהּ. וְעַל כָּךְ וְשַׂמְתִּי עֲלֵיהֶם, כְּדֵי לְהָאִיר מֵהַשֶּׁמֶשׁ, כְּאוֹר הַלְּבָנָה. (ומשום זה אכל זה לא) בָּא עַל יְדֵי מֹשֶׁה, כְּדֵי שֶׁלֹּא יִפָּגֵם.</p>\n<p>אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִכְבוֹדוֹ, עָלָיו כָּתוּב (משלי כג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ וְגוֹ'. יִשְׂמַח אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְתָגֵל יוֹלַדְתֶּךְ - זוֹ אֵם מֹשֶׁה שֶׁלְּמַטָּה. הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֲבוֹ יוֹתֵר מִכָּל נְבִיאֵי הָעוֹלָם לְלֹא אֶמְצָעִי כְּלָל, (שהרי משה נתעלה על כל נביאי העולם ללא אמצעי כלל, כמו) שֶׁכָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ, וַהֲרֵי בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת.</p>"],[9522012324,"<p>וַיִּצְעַק מֹשֶׁה אֶל ה' לֵאמֹר אֵל נָא רְפָא נָא לָהּ. הֲרֵי פֵּרְשׁוּהָ, וְהוּא סוֹד הַשֵּׁם הַקָּדוֹשׁ מֵאַחַת עֶשְׂרֵה אוֹתִיּוֹת, וְלֹא רָצָה מֹשֶׁה לְהִתְפַּלֵּל יוֹתֵר, מִשּׁוּם שֶׁעַל שֶׁלּוֹ לֹא רָצָה לְהַטְרִיחַ יוֹתֵר לַמֶּלֶךְ. בִּגְלַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה בִּכְבוֹד מֹשֶׁה. וּבְכָל מָקוֹם הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹד הַצַּדִּיקִים יוֹתֵר עַל שֶׁלּוֹ. וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִתְבֹּעַ עֶלְבּוֹן יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת וּלְשַׂמְּחָם בְּחֶדְוַת צִיּוֹן, שֶׁכָּתוּב (ירמיה לא) וּבָאוּ וְרִנְּנוּ בִמְרוֹם צִיּוֹן וְגוֹ'. וְאָז (ישעיה נט) וּבָא לְצִיּוֹן גּוֹאֵל וְגוֹ'. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522012325,"<p>וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר שְׁלַח לְךְ אֲנָשִׁים וְיָתֻרוּ אֶת אֶרֶץ כְּנַעַן וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (איוב לח) הֲמִיָּמֶיךְ צִוִּיתָ בֹּקֶר יִדַּעְתָּה שַׁחַר מְקֹמוֹ. כָּתוּב שַׁחַר, הֵ\"א הִתְרַחֲקָה מִשַּׁחַר. מָה הַטַּעַם? אֶלָּא אָמַר רַבִּי חִיָּיא, בְּשָׁעָה שֶׁנּוֹטֶה הָעֶרֶב וְהַשֶּׁמֶשׁ נוֹטֶה לְהִכָּנֵס, אָז נֶחֱלָשׁ כֹּחוֹ, וְאָז שׁוֹלֵט, הַשְּׂמֹאל וְנִמְצָא דִּין בָּעוֹלָם וּמִתְפַּשֵּׁט (למעלה). וְאָז צָרִיךְ הָאָדָם לְהִתְפַּלֵּל וּלְכַוֵּן רָצוֹן (להתפלל שימצא רצון) לִפְנֵי רִבּוֹנוֹ.</p>"],[9522012326,"<p>שֶׁאָמַר רַבֵּי יֵיסָא, כְּשֶׁנּוֹטֶה הַשֶּׁמֶשׁ וְנֶחֱלָשׁ, אָז נִפְתָּח פֶּתַח אֶחָד בַּשֶּׁמֶשׁ וּמִתְכַּנֵּס כֹּחוֹ, וְהַשְּׂמֹאל שׁוֹלֵט, וְיִצְחָק כּוֹרֶה בְּאֵר תַּחְתָּיו.</p>\n<p>כֵּיוָן שֶׁנִּכְנָס הַלַּיְלָה, הַשְּׁטָר שֶׁל הַכְּרִיתָה מָצוּי בְּאוֹצָרוֹ, וְכַמָּה קְבוּצוֹת מְחַבְּלִים מַזִּיקִים (נזרקים) מִתְפַּשְּׁטִים בָּעוֹלָם, וְכֻלָּם מְשׁוֹטְטִים בְּעִרְבּוּבְיָה, וְהוֹלְכִים וְצוֹחֲקִים בְּנַפְשׁוֹת הָרְשָׁעִים (שלבני אדם) וּמוֹדִיעִים לָהֶם דְּבָרִים, מֵהֶם כּוֹזְבִים וּמֵהֶם אֱמֶת, וּמִי שֶׁנִּמְצָא בֵינֵיהֶם, נִתְּנָה לוֹ רְשׁוּת לְחַבֵּל, וְכָל בְּנֵי הָעוֹלָם יְשֵׁנִים (והתכנסו) וְטוֹעֲמִים טַעַם מָוֶת, וַהֲרֵי בֵּאַרְנוּ.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁמִתְעוֹרֶרֶת רוּחַ צָפוֹן, אָז מִתְקַבֶּלֶת כְּנֶסֶת יִשְׂרָאֵל בִּשְׂמֹאל, (ומתחברים כאחד) וְשׁוֹרֶה בַּזְּרוֹעַ בִּמְקוֹמָהּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים שֶׁבְּגַן עֵדֶן, וְאָז כָּל מִי שֶׁמִּתְעוֹרֵר לַעֲסֹק בַּתּוֹרָה בְּאוֹתָהּ שָׁעָה מִשְׁתַּתֵּף יַחַד אִתָּהּ, מִשּׁוּם שֶׁהִיא (יושבת) וְכָל אוּכְלוּסֶיהָ מְשַׁבְּחִים לַמֶּלֶךְ הָעֶלְיוֹן, וְכָל אֵלּוּ שֶׁנִּמְצָאִים (שהשתתפו אתה) בְּתִשְׁבְּחוֹת הַתוֹרָה, כֻּלָּם כְּתוּבִים בִּבְנֵי הַהֵיכָל וְנִקְרָאִים בִּשְׁמוֹתָם, וְאֵלֶּה רְשׁוּמִים בַּיּוֹם.</p>\n<p>בֹּא וּרְאֵה, שֵׁם קָדוֹשׁ אֶחָד יֵשׁ בְּאוֹתִיּוֹת חֲקוּקוֹת, שֶׁהוּא שׁוֹלֵט מֵחֲצוֹת הַלַּיְלָה וְאֵילָךְ, וְהֵן אוֹתִיּוֹת (כל\"ך סעפ\"ה יאעוצ\"ה) ם' שֶׁל מנצפ\"ךָּ כּוֹלֵל אוֹתָם. ם פֵּרְשׁוּהָ (ישעיה ט) לְםַרְבֵּה הַמִּשְׂרָה. נ' הָיְתָה סְתוּמָה לָזֶה וְלָזֶה, וְאָז כְּתָרִים כְּלוּלִים הוּא ו' (י') שֶׁל הַשֵּׁם הַקָּדוֹשׁ הִתְקִינוֹ, וְסָתַם מַבּוּעֶיהָ. אַחַר שֶׁיָּלְדָה, פְּתוּחָה הָיְתָה בְרֹאשׁ אֶחָד שֶׁל הַפֶּתַח.</p>\n<p>כְּשֶׁחָרַב בֵּית הַמִּקְדָּשׁ נִסְתְּמוּ הַמַּבּוּעִים מִכָּל הַצְּדָדִים, (אות זו כוללת אותיות) וְנִכְלְלוּ אוֹתִיּוֹת אֲחֵרוֹת, וְהֵן שֶׁבַע. שָׁלֹשׁ מִצַּד זֶה, וְאַרְבַּע מִצַּד זֶה. כל\"ךָּ. וְסִימָן - (שיר השירים ד) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָּךְ. ן' זָכָר וּנְקֵבָה כְּלוּלִים כְּאֶחָד, זֶה כּוֹלֵל שָׁלֹשׁ מִכָּאן וְשָׁלֹשׁ מִכָּאן, וְהֵם שֵׁשׁ. וּבֵאַרְנוּ, בִּשְׁתֵּי אוֹתִיּוֹת אֵלֶּה, ם' ן', נִכְלְלוּ שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת. הָסֵר מֵהֶן שְׁתַּיִם, אַחַת לְמָקוֹם אֶחָד, וְאַחַת לְמָקוֹם אֶחָד.</p>\n<p>כל\"ך סעפ\"ה יאעוצ\"ה, כָּךְ נֶחְקְקוּ הָאוֹתִיּוֹת, וְסוֹד זֶה בְּכִי תֵצֵא לַמִּלְחָמָה, פָּסוּק שֶׁכָּתוּב (דברים כב) כִּי יִהְיֶה נַעֲרָה בְתוּלָה. נַעֲרָ כָּתוּב. אַחַר שֶׁהִסְתַּלֵּק הַלַּיְלָה וְהַבֹּקֶר מֵאִיר, אָז ה' עוֹלָה וְנִכְלֶלֶת בְּאוֹר עֶלְיוֹן, וְאָז - יִדַּעְתָּה שַּׁחַר מְקוֹמוֹ, שֶׁיָּדַע (שודאי) שַׁחַר מְקוֹמוֹ שֶׁל הֵ\"א, וְנִכְלָל בְּתוֹכוֹ.</p>"],[9522012327,"<p>בֹּא וּרְאֵה, מֹשֶׁה הָיָה הַשֶּׁמֶשׁ, וְרָצָה לְהִכָּנֵס לָאָרֶץ. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, מֹשֶׁה, כְּשֶׁבָּא אוֹר הַשֶּׁמֶשׁ, נִכְלֶלֶת הַלְּבָנָה בְתוֹכוֹ. כָּעֵת שֶׁאַתָּה שֶׁמֶשׁ, אֵיךְ יָקוּמוּ כְאֶחָד שֶׁמֶשׁ וּלְבָנָה? הַלְּבָנָה אֵינָהּ מְאִירָה אֶלָּא בְּשָׁעָה שֶׁמִּתְכַּנֶּסֶת הַשֶּׁמֶשׁ, אֲבָל כָּעֵת אֵינְךְ יָכוֹל. אִם תִּרְצֶה לָדַעַת מִמֶּנָּה, שְׁלַח לְךְ אֲנָשִׁים, לְעַצְמְךְ, כְּדֵי לָדַעַת.</p>\n<p>בֹּא וּרְאֵה, מֹשֶׁה, אִם תֹּאמַר שֶׁהוּא לֹא יָדַע שֶׁלֹּא יִכָּנֵס לָאָרֶץ בִּזְמַן זֶה - לֹא כָּךְ, אֶלָּא יָדַע, וְרָצָה לָדַעַת מִמֶּנָּה עַד שֶׁלֹּא יִסְתַּלֵּק, וְשָׁלַח אֶת הַמְרַגְּלִים הַלָּלוּ. כֵּיוָן שֶׁלֹּא הֵשִׁיבוּ דָבָר כָּרָאוּי, לֹא שָׁלַח פַּעַם אַחֶרֶת, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶרְאָה לוֹ, שֶׁכָּתוּב (דברים לב) עֲלֵה אֶל הַר הָעֲבָרִים הַזֶּה וּרְאֵה אֶת הָאָרֶץ. וְכָתוּב (שם לד) וַיַּרְאֵהוּ ה' אֶת כָּל הָאָרֶץ. וְלֹא זֶה בִּלְבַדּוֹ, אֶלָּא כָּל אֵלּוּ שֶׁעֲתִידִים לַעֲמֹד בְּכָל דּוֹר וָדוֹר, כֻּלָּם הֶרְאָה לְמֹשֶׁה. וְנִתְבָּאֵר, וּפֵרְשׁוּהָ הַחֲבֵרִים.</p>\n<p>כֵּיוָן שֶׁהֻתַּר מֹשֶׁה לִשְׁלֹחַ, מָה אָמַר לָהֶם? הֲיֶשׁ בָּהּ עֵץ. וְכִי מַהוּ שֶׁאָמַר? וְאִם תֹּאמַר שֶׁלֹּא יָדַע? אֶלָּא (לפנינויאמר דבר, אבלכאן) כָּךְ אָמַר מֹשֶׁה: אִם יֵשׁ בָּהּ עֵץ, הֲרֵי יָדַעְתִּי שֶׁאֲנִי אֶכָּנֵס לְשָׁם. אֵיזֶה עֵץ? זֶה עֵץ הַחַיִּים. וְשָׁם לֹא הָיָה, אֶלָּא בְּגַן עֵדֶן שֶׁבָּאָרֶץ. אָמַר, אִם יֵשׁ בָּהּ עֵץ זֶה, אֲנִי אֶכָּנֵס לְשָׁם. וְאִם לֹא, לֹא אוּכַל אֲנִי לְהִכָּנֵס.</p>"],[9522012328,"<p>אָמַר רַבִּי חִיָּיא, כָּתוּב (במדבר טו) וַיִּמְצְאוּ אִישׁ מְקוֹשֵׁשׁ עֵצִים בְּיוֹם הַשַּׁבָּת. אֵיזֶה עֵצִים כָּאן? וּמַה הוּא זֶה? אֶלָּא זֶה צְלָפְחָד, וְהָיָה מְדַקְדֵּק עַל הָעֵצִים הַלָּלוּ אֵיזֶה גָדוֹל מֵהָאַחֵר, וְלֹא חָשַׁשׁ לִכְבוֹד רִבּוֹנוֹ, וְהֶחֱלִיף שַׁבָּת לְשַׁבָּת. זֶהוּ שֶׁכָּתוּב (שם כז) כִּי בְחֶטְאוֹ מֵת, בְּחֵטְא ו' מֵת. (וסוד הכל ודאי מקושש עצים) בִּגְלַל זֶה הָיָה דִינוֹ סָתוּם, וְלֹא הִתְפָּרֵשׁ דִּינוֹ כְּדִינִים אֲחֵרִים, מִשּׁוּם שֶׁדָּבָר זֶה צָרִיךְ בַּחֲשַׁאי וְנִסְתָּר וְלֹא גָלוּי, וְעַל זֶה לֹא נֶאֱמַר בְּגָלוּי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה כָבוֹד לִכְבוֹדוֹ.</p>\n<p>רַבִּי יוֹסֵי אָמַר, שְׁאָר הָעֵצִים יַחַד עִם שַׁבָּת הָיָה מְקוֹשֵׁשׁ, וְקִבֵּל עֹנֶשׁ לְפִי שָׁעָה וְהִתְכַּפֵּר חֶטְאוֹ. וְעַל זֶה הִתְקַשָּׁה מֹשֶׁה בְּדִין הַבָּנוֹת, שֶׁלֹּא יָדַע אִם הִתְכַּפֵּר לִהְיוֹת לִבְנוֹתָיו חֵלֶק וְנַחֲלָה אִם לֹא. כֵּיוָן שֶׁהִזְכִּיר שְׁמוֹ (של צלפחד) הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שם) כֵּן בְּנוֹת צְלָפְחָד דּבְרֹת, נוֹדַע שֶׁהִתְכַּפֵּר חֶטְאוֹ.</p>\n<p>בֹּא וּרְאֵה, שְׁנֵי עֵצִים הֵם, אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, בָּזֶה חַיִּים וּבָזֶה מָוֶת. מִי שֶׁמַּחֲלִיפָם, גּוֹרֵם לוֹ מָוֶת בָּעוֹלָם הַזֶּה, וְאֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא. וְעַל זֶה אָמַר שְׁלֹמֹה, (משלי כה) דְּבַשׁ מָצָאתָ אֱכֹל דַּיֶּךָּ וְגוֹ'.</p>\n<p>אָרוֹן וְתוֹרָה בְּאֶחָד עוֹמְדִים. תּוֹרָה הָעִקָּר. הָאָרוֹן הַבַּיִת. וְעַל זֶה אָרֹן חָסֵר בְּלִי וָא\"ו בְּכָל מָקוֹם; אֲרֹן הַבְּרִית, אֲרֹן הָעֵדֻת. בְּכָל מָקוֹם אַהֲרֹן זְרוֹעַ יָמִין, פְּרָט לְאֶחָד, שֶׁכָּתוּב (במדבר ג) כָּל פְּקוּדֵי הַלְוִיִּם אֲשֶׁר פָּקַד מֹשֶׁה וְאַהֲרֹן, נָקוּד לְמַעְלָה.</p>\n<p>אָמַר רַבִּי יִצְחָק, מֹשֶׁה נָקַט עֵץ הַחַיִּים, וְלָכֵן רָצָה לָדַעַת אִם הָיָה מָצוּי בָּאָרֶץ אִם לֹא, וּמִשּׁוּם זֶה אָמַר הֲיֶשׁ בָּהּ עֵץ אִם אַיִן וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ. שֶׁהֲרֵי עֵץ הַחַיִּים נֶחְמָד לַכֹּל. וְהֵם לֹא הֵבִיאוּ אֶלָּא עֲנָבִים וְרִמּוֹנִים וּתְאֵנִים, בְּאִילָן אַחֵר תְּלוּיִים וַאֲחוּזִים.</p>\n<p>בֹּא וּרְאֵה, שְׁלַח לְךְ אֲנָשִׁים, בִּשְׁבִילְךְ. רַבִּי יְהוּדָה פָּתַח, (משלי כה) כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר צִיר נֶאֱמָן לְשֹׁלְחָיו וְנֶפֶשׁ אֲדנָיו יָשִׁיב. כְּצִנַּת שֶׁלֶג בְּיוֹם קָצִיר, שֶׁמְּהַנֶּה אֶת הַגּוּף וְאֶת הַנֶּפֶשׁ. צִיר נֶאֱמָן לְֹשלְחָיו, אֵלּוּ כָּלֵב וּפִנְחָס שֶׁהָיוּ שְׁלִיחִים נֶאֱמָנִים לִיהוֹשֻׁעַ. וְנֶפֶשׁ אֲדנָיו יָשִׁיב, שֶׁהֶחֱזִירוּ שְׁכִינָה לָדוּר בָּהֶם בְּיִשְׂרָאֵל, וְלֹא הִסְתַּלְּקָה מֵהֶם.</p>\n<p>וְאֵלּו שֶׁשָּׁלַח מֹשֶׁה גָּרְמוּ בְכִיָּה לְדוֹרוֹת אַחֲרוֹנִים, וְגָרְמוּ לְהִסְתַּלֵּק מִיִּשְׂרָאֵל כַּמָּה אֲלָפִים וּרְבָבוֹת, וְגָרְמוּ לְסַלֵּק שְׁכִינָה מֵהָאָרֶץ מִבֵּין יִשְׂרָאֵל. אוֹתָם שֶׁשָּׁלַח יְהוֹשֻׁעַ, וְנֶפֶשׁ אֲדנָיו יָשִׁיב.</p>"],[9522012329,"<p>רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יֵיסָא לְרַבִּי חִזְקִיָּה, אֲנִי רוֹאֶה בְפָנֶיךְ שֶׁבְּתוֹכְךְ יֵשׁ הִרְהוּר. אָמַר לוֹ, הֲרֵי וַדַּאי בְּפָסוּק זֶה הִסְתַּכַּלְתִּי בוֹ. כֵּיוָן שֶׁאָמַר שְׁלֹמֹה, (קהלת ג) כִּי מִקְרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה מִקְרֶה אֶחָד לָהֶם וְגוֹ'. וְשָׁנִינוּ, שֶׁכָּל דִּבְרֵי שְׁלֹמֹה הַמֶּלֶךְ כֻּלָּם נִסְתָּרִים מִדַּרְגוֹת הַחָכְמָה. אִם כָּךְ, בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל, שֶׁהֲרֵי נִמְצָא בּוֹ פֶּתַח לְאוֹתָם שֶׁאֵינָם בְּנֵי הָאֱמוּנָה.</p>\n<p>אָמַר לוֹ, וַדַּאי כָּךְ זֶה, וְיֵשׁ בּוֹ לָדַעַת וּלְהִסְתַּכֵּל. בֵּין כָּךְ רָאוּ אָדָם שֶׁהָיָה בָּא, וּבִקֵּשׁ מֵהֶם מַיִם, שֶׁהָיָה צָמֵא וְעָיֵף מֵחֹזֶק הַשֶּׁמֶשׁ. אָמְרוּ לוֹ, מִי אַתָּה? אָמַר לָהֶם? יְהוּדִי אֲנִי, וַאֲנִי עָיֵף וְצָמֵא. אָמְרוּ, עָסַקְתָּ בַּתּוֹרָה? אָמַרלָהֶם, עַד שֶׁאֲנִי אִתְּכֶם בִּדְבָרִים, אֶעֱלֶה לָהָר הַזֶּה, וְשָׁם אֶקַּח מַיִם וְאֶשְׁתֶּה.</p>\n<p>הוֹצִיא רַבִּי יֵיסָא כְּלִי אֶחָד מָלֵא מַיִם וְנָתַן לוֹ. אַחַר שֶׁשָּׁתָה, אָמַר, נַעֲלֶה אִתְּךְ לַמַּיִם. עָלָה לָהָר, וְנִמְצְאוּ חוּט מַיִם דַּקִּיק, וּמִלְּאוּ כְלִי אֶחָד. יָשְׁבוּ. אָמַר לָהֶם אוֹתוֹ הָאָדָם, כָּעֵת תִּשְׁאֲלוּ, שֶׁהֲרֵי אֲנִי הִשְׁתַּדַּלְתִּי בַתּוֹרָה עַל יְדֵי בְּנִי אֶחָד, שֶׁאֲנִי הִכְנַסְתִּיו לְבֵית רַב וּבִגְלָלוֹ הִרְוַחְתִּי בַתּוֹרָה. אָמַר רַבִּי חִזְקִיָּה, אִם עַל יְדֵי בִנְךְ - טוֹב הוּא. אֲבָל הַדָּבָר שֶׁאָנוּ בוֹ, אֲנִי רוֹאֶה שֶׁלְּמָקוֹם אַחֵר רוֹצֶה לַעֲלוֹת. אָמַר אוֹתוֹ הָאָדָם, אֱמֹר דְּבָרְךְ, שֶׁלִּפְעָמִים בְּתַרְמִיל הֶעָנִי תִּמְצָא מַרְגָּלִית.</p>\n<p>אָמַר לוֹ פָּסוּק זֶה שֶׁאָמַר שְׁלֹמֹה. סָח לוֹ. אָמַר לוֹ, וְכִי (כמו) בַּמָּה אַתֶּם נִפְרָדִים מִשְּׁאָר בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים? אָמְרוּ לוֹ, וּבַמֶּה? אָמַר לָהֶם, עַל זֶה אָמַר שְׁלֹמֹה פָּסוּק זֶה, וְלֹא אָמַר זֶה מֵעַצְמוֹ כִּשְׁאָר אוֹתָם דְּבָרִים, אֶלָּא חָזַר עַל אוֹתָם דְּבָרִים שֶׁל טִפְּשֵׁי הָעוֹלָם שֶׁאוֹמְרִים כָּךְ. וּמָה אוֹמְרִים? כִּי מִקְרֶה (בני) הָאָדָם וּמִקְרֶה הַבְּהֵמָה וְגוֹ'. טִפְּשִׁים שֶׁלֹּא יוֹדְעִים וְלֹא מִסְתַּכְּלִים בַּחָכְמָה, אוֹמְרִים שֶׁהָעוֹלָם הַזֶּה הוֹלֵךְ בְּמִקְרֶה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא לֹא מַשְׁגִּיחַ עֲלֵיהֶם, אֶלָּא מִקְרֶה (בני) הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְרֶה אֶחָד וְגוֹ'.</p>\n<p>וּכְשֶׁשְּׁלֹמֹה הִסְתַּכֵּל בַּטִּפְּשִׁים הַלָּלוּ שֶׁאוֹמְרִים אֶת זֶה, קָרָא לָהֶם בְּהֵמָה, שֶׁהֵם עוֹשִׂים עַצְמָם בְּהֵמָה מַמָּשׁ מִשּׁוּם שֶׁאוֹמְרִים דְּבָרִים אֵלּוּ. וּמִנַּיִן לָנוּ? הַפָּסוּק שֶׁעָלָיו מוֹכִיחַ, שֶׁכָּתוּב (קהלת ג) אָמַרְתִּי אֲנִי בְּלִבִּי עַל דִּבְרַת בְּנֵי הָאָדָם לְבָרָם הָאֱלֹהִים וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. אָמַרְתִּי אֲנִי בְּלִבִּי, וְחָשַׁבְתִּי בָזֶה לְהִסְתַּכֵּל עַל מָה? עַל דִּבְרַת בְּנֵי הָאָדָם, עַל אוֹתוֹ דְּבַר טִפְּשׁוּת שֶׁהֵם אוֹמְרִים לְבָרָם הָאֱלֹהִים לְבַדָּם, וְלֹא יִתְחַבְּרוּ יַחַד עִם בְּנֵי אָדָם אֲחֵרִים שֶׁיֵּשׁ לָהֶם אֱמוּנָה, וְלִרְאוֹת שְׁהֶם בְּהֵמָה הֵמָּה לָהֶם. וְלִרְאוֹת בָּהֶם אוֹתָם בְּנֵי אֱמוּנָה שֶׁהֵם בְּהֵמָה מַמָּשׁ, וְדַעְתָּם כַּבְּהֵמָה. הֵמָּה לָהֶם - בִּלְבַדָּם, וְלֹא לְהַכְנִיס אֶת בְּנֵי הָאֱמוּנָה בְּדַעַת וְטִפְּשׁוּת זוֹ, וְעַל כָּךְ הֵמָּה לָהֶם, וְלֹא לַאֲחֵרִים. וּמַה דַּעְתָּם? כִּי מִקְרֶה בְנֵי הָאָדָם וּמִקְרֶה הַבְּהֵמָה וּמִקְרֶה אֶחָד לְכֻלָּם וְגוֹ'. תִּפַּח רוּחָם שֶׁל אוֹתָן בְּהֵמוֹת, אוֹתָם טִפְּשִׁים אוֹ מְחֻסְּרֵי אֱמוּנָה. אוֹי לָהֶם! אוֹי לְנַפְשָׁם! טוֹב לָהֶם שֶׁלֹּא יָבוֹאוּ לָעוֹלָם!</p>\n<p>וּמַה הֱשִׁיבָם שְׁלֹמֹה עַל זֶה? הַפָּסוּק אַחֲרָיו, וְאָמַר, וּמִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ. מִי יוֹדֵעַ בְּאוֹתָם טִפְּשִׁים שֶׁלֹּא יוֹדְעִים בִּכְבוֹד הַמֶּלֶךְ הָעֶלְיוֹן וְלֹא מִסְתַּכְּלִים בַּתּוֹרָה, רוּחַ בְּנֵי הָאָדָם הָעֹלָה הִיא לְמָעְלָה, לְמָקוֹם עֶלְיוֹן, לְמָקוֹם נִכְבָּד, לְמָקוֹם קָדוֹשׁ, לְהִזּוֹן מֵאוֹר עֶלְיוֹן, מֵאוֹר הַמֶּלֶךְ הַקָּדוֹשׁ, לִהְיוֹת צָרוּר בִּצְרוֹר הַחַיִּים, וְנִמְצָא לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ עוֹלָה תְמִימָה, וְזוֹהִי הָעֹלָה הִיא לְמָעְלָה.</p>\n<p>וְרוּחַ הַבְּהֵמָה הַיֹּרֶדֶת הִיא לְמַטָּה לָאָרֶץ, וְלֹא לְאוֹתוֹ מָקוֹם שֶׁהָיָה כָּל אָדָם, שֶׁכָּתוּב בּוֹ (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְכָתוּב (משלי כ) נֵר ה' נִשְׁמַת אָדָם. אֵיךְ אוֹמְרִים אוֹתָם טִפְּשִׁים שֶׁאֵינָם מִבְּנֵי הָאֱמוּנָה, וְרוּחַ אֶחָד לַכֹּל (קהלת ג) ? תִּפַּח רוּחָם! עֲלֵיהֶם כָּתוּב (תהלים לה) יִהְיוּ כְּמֹץ לִפְנֵי רוּחַ וּמַלְאַךְ ה' דּוֹחֶה. אֵלֶּה יִשָּׁאֲרוּ בַגֵּיהִנֹּם לְאוֹתָן דְּרָגוֹת תַּחְתּוֹנוֹת, וְלֹא יַעֲלוּ לְדוֹרֵי דוֹרוֹת. עֲלֵיהֶם כָּתוּב (שם קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ וּרְשָׁעִים עוֹד אֵינָם בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. בָּאוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא וְנָשְׁקוּ רֹאשׁוֹ. אָמְרוּ, וּמַה כָּל זֶה הָיָה אִתְּךְ וְלֹא יָדַעְנוּ? אַשְׁרֵי הַשָּׁעָה הַזּוֹ שֶׁפָּגַשְׁנוּ אוֹתְךְ.</p>\n<p>עוֹד אָמַר, וְכִי עַל זֶה בִּלְבַד תָּמַהּ שְׁלֹמֹה, וַהֲרֵי בְּמָקוֹם אַחֵר אָמַר כְּמוֹ זֶה? פָּתַח וְאָמַר, (קהלת ט) זֶה רָע בְּכֹל אֲשֶׁר נַעֲשָׂה תַּחַת הַשֶּׁמֶשׁ. זֶה רָע וַדַּאי. מַהוּ זֶה רָע? זֶהוּ מִי שֶׁשּׁוֹפֵךְ זֶרַע בְּרֵיקָנוּת וּמְחַבֵּל דְּרָכָיו, מִשּׁוּם שֶׁזֶּה אֵין מְדוֹרוֹ בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, וְלֹא יִהְיֶה לוֹ חֵלֶק לָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע. עַל זֶה אָמַר, זֶה רָע, שֶׁלֹּא יִהְיֶה לוֹ מָדוֹר לְמַעְלָה. כִּי מִקְרֶה אֶחָד לַכֹּל וְגַם לֵב בְּנֵי הָאָדָם מָלֵא רָע (משום זה) וְהוֹלֵלוֹת בִּלְבָבָם בְּחַיֵּיהֶם (קהלת ט). שְׁטוּת תְּקוּעָה בְּלִבָּם, וְהֵם מְחֻסְּרֵי אֱמוּנָה, וְאֵין לָהֶם חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וּבְאוֹתָם בְּנֵי אֱמוּנָה, לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב (שם) וְאַחֲרָיו אֶל הַמֵּתִים.</p>\n<p>בֹּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְהִיר לִבְנֵי הָעוֹלָם וְאָמַר, (דברים ל) וּבָחַרְתָּ בַּחַיִּים לְמַעַן תִּחְיֶה, (בעולם הזה, ובעולם הבא) וְהַחַיִּים שֶׁל אוֹתוֹ עוֹלָם הֵם. אוֹתָם רְשָׁעִים מְחֻסְּרֵי אֱמוּנָה מָה אוֹמְרִים? כִּי מִי אֲשֶׁר יִבְחַר וְגוֹ'. אַף עַל גַּב שֶׁיִּבְחַר אָדָם בְּזֶה הָעוֹלָם (באותו עולם) כְּמוֹ שֶׁאָמַר - לֹא כְלוּם הוּא, שֶׁהֲרֵי מָסוּר בְּיָדֵינוּ, (קהלת שם) אֶל כָּל הַחַיִּים יֵשׁ בִּטָּחוֹן, וּמָסוּר הוּא בְיָדֵינוּ, (שם) כִּי לְכֶלֶב חַי הוּא טוֹב מִן הָאַרְיֵה הַמֵּת. אֵיךְ יִהְיֶה לָנוּ חַיִּים בְּאוֹתוֹ עוֹלָם? וְעַל כֵּן זֶה רָע וַדַּאי, שֶׁלֹּא יָדוּרוּ בַּמֶּלֶךְ הָעֶלְיוֹן וְלֹא יִהְיֶה לָהֶם בּוֹ חֵלֶק. וְאַף עַל גַּב שֶׁכָּל הַפְּסוּקִים הַלָּלוּ תִּמְצָא סִמּוּכִין לַחֲבֵרִים בִּדְבָרִים אֲחֵרִים, אֲבָל שְׁלֹמֹה בָּא לְגַלּוֹת עַל אוֹתָם רְשָׁעִים מְחֻסְּרֵי אֱמוּנָה שֶׁאֵין לָהֶם חֵלֶק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>אָמַר לוֹ, הֲתִרְצֶה שֶׁנִּתְחַבֵּר אִתְּךְ וְתֵלֵךְ אִתָּנוּ? אָמַר לָהֶם, אִם אֶעֱשֶׂה כָּךְ, הַתּוֹרָה תִּקְרָא עָלַי כְּסִיל! וְלֹא עוֹד, אֶלָּא שֶׁאֶתְחַיֵּב בְּנַפְשִׁי. אָמְרוּ לוֹ, לָמָּה? אָמַר לָהֶם, שֶׁהֲרֵי אֲנִי שָׁלִיחַ, וּשְׁלָחוּנִי בִשְׁלִיחוּת, וּשְׁלֹמֹה הַמֶּלֶךְ אָמַר, (משלי כו) מְקַצֶּה רַגְלַיִם חָמָס שּתֶה שֹׁלֵחַ דְּבָרִים בְּיַד כְּסִיל. בּא וּרְאֵה, הַמְרַגְּלִים, עַל שֶׁלֹּא נִמְצְאוּ בְּנֵי הָאֱמוּנָה וּשְׁלוּחֵי אֱמוּנָה, הִתְחַיְּבוּ בְנַפְשָׁם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. נְשָׁקָם וְהָלַךְ לוֹ.</p>\n<p>הָלְכוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא. עַד שֶׁהָיוּ הוֹלְכִים פָּגְעוּ בְּאוֹתָם בְּנֵי אָדָם. שָׁאֲלוּ אֶת רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא עָלָיו. אָמְרוּ, מַה שְּׁמוֹ שֶׁל אוֹתוֹ אָדָם? אָמְרוּ, רַבִּי חַגַּי הוּא, וְחָבֵר בֵּין הַחֲבֵרִים הוּא, וּשְׁלָחוּהוּ הַחֲבֵרִים מִבָּבֶל לָדַעַת דְּבָרִים מֵרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי וּשְׁאָר הַחֲבֵרִים. אָמַר רַבִּי יֵיסָא, וַדַּאי זֶהוּ רַבִּי חַגַּי, שֶׁכָּל יָמָיו לֹא רָצָה לְהַרְאוֹת עַצְמוֹ בְּמַה שֶּׁיָּדַע, וְעַל זֶה אָמַר לָנוּ שֶׁהֲרֵי בְּנוֹ זָכָה לוֹ בַּתּוֹרָה, מִשּׁוּם שֶׁאָמַר הַפָּסוּק, (שם) רָאִיתָ אִישׁ חָכָם בְּעֵינָיו תִּקְוָה לִכְסִיל מִמֶּנּוּ. וַדַּאי שָׁלִיחַ נֶאֱמָן הוּא, (ואשריו הוא שליח נאמן) וְאַשְׁרָיו מִי שֶׁשָּׁלַח דְּבָרָיו בִּידֵי שָׁלִיחַ נֶאֱמָן.</p>\n<p>בֹּא וּרְאֵה, אֱלִיעֶזֶר עֶבֶד אַבְרָהָם מִבְּנֵי כְנַעַן הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (הושע יב) כְּנַעַן בְּיָדוֹ מֹאזְנֵי מִרְמָה. וְעַל כְּנַעַן כָּתוּב, (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. וּמִשּׁוּם שֶׁהָיָה שָׁלִיחַ נֶאֱמָן, מַה כָּתוּב בּוֹ? (שם כד) בּא בְּרוּךְ ה'. בְּרוּךְ ה' מַמָּשׁ. וְעַל זֶה נִכְתַּב כָּךְ בַּתּוֹרָה, מִשּׁוּם שֶׁיָּצָא מֵאוֹתָהּ קְלָלָה וְהִתְבָּרֵךְ. וְלֹא דַי לוֹ שֶׁיָּצָא מִמֶּנָּה, אֶלָּא שֶׁהִתְבָּרֵךְ בְּשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלָמַדְנוּ שֶׁבָּא מַלְאָךְ, וְהִכְנִיס דָּבָר זֶה בְּפִי לָבָן.</p>\n<p>וַיִּשְׁלַח אֹתָם מֹשֶׁה וְגוֹ', כֻּלָּם אֲנָשִׁים. כֻּלָּם צַדִּיקִים הָיוּ וְרָאשֵׁי יִשְׂרָאֵל הָיוּ, אֲבָל הֵם לָקְחוּ לְעַצְמָם עֵצָה רָעָה. מַדּוּעַ נָטְלוּ עֵצָה זוֹ? אֶלָּא אָמְרוּ, אִם יִכָּנְסוּ יִשְׂרָאֵל לָאָרֶץ - יַעֲבִירוּ אוֹתָנוּ מִלִּהְיוֹת רָאשִׁים, וִימַנֶּה מֹשֶׁה רָאשִׁים אֲחֵרִים, שֶׁהֲרֵי אָנוּ זָכִינוּ בַמִּדְבָּר לִהְיוֹת רָאשִׁים, אֲבָל בָּאָרֶץ לֹא נִזְכֶּה. וְעַל שֶׁלָּקְחוּ עֵצָה רָעָה לְעַצְמָם, מֵתוּ הֵם וְכָל אוֹתָם שֶׁלָּקְחוּ דִבְרֵיהֶם.</p>"],[9522012330,"<p>אֵלֶּה שְׁמוֹת הָאֲנָשִׁים אֲשֶׁר שָׁלַח מֹשֶׁה וְגוֹ'. אָמַר רַבִּי יִצְחָק, מֹשֶׁה הִסְתַּכֵּל וְיָדַע שֶׁלֹּא יַצְלִיחוּ בְדַרְכֵיהֶם, וְאָז הִתְפַּלֵּל עַל יְהוֹשֻׁעַ. וְאָז כָּלֵב הָיָה בְדחַק, וְאָמַר מָה אֶעֱשֶׂה? הֲרֵי יְהוֹשֻׁעַ הוֹלֵךְ בְּסִיּוּעַ עֶלְיוֹן שֶׁל מֹשֶׁה, שֶׁשָּׁלַח בּוֹ אוֹר הַלְּבָנָה, וְהוּא הֵאִיר עָלָיו בִּתְפִלָּתוֹ מִשּׁוּם שֶׁהוּא שֶׁמֶשׁ. מֶה עָשָׂה כָּלֵב? נִשְׁמַט מֵהֶם וְהָלַךְ לְקִבְרֵי הָאָבוֹת, וְהִתְפַּלֵּל שָׁם תְּפִלָּתוֹ.</p>\n<p>אָמַר רַבִּי יְהוּדָה, דֶּרֶךְ אַחֵר לָקַח, וְעִקֵּם שְׁבִילִים, וְהִגִּיעַ עַל קִבְרֵי הָאָבוֹת וְהִסְתַּכֵּן בְּעַצְמוֹ, שֶׁהֲרֵי כָּתוּב וְשָׁם אֲחִימָן וְשֵׁשַׁי וְתַלְמַי יְלִידֵי הָעֲנָק. אֲבָל מִי שֶׁהוּא בְדחַק, לֹא מִסְתַּכֵּל עַל דָּבָר. כָּךְ כָּלֵב, מִשּׁוּם שֶׁהָיָה בְדחַק, לֹא הִסְתַּכֵּל עַל דָּבָר, וּבָא לְהִתְפַּלֵּל עַל קִבְרֵי הָאָבוֹת לְהִנָּצֵל מֵעֵצָה זוֹ.</p>\n<p>וַיִּקְרָא מֹשֶׁה לְהוֹשֵׁעַ בִּן נוּן יְהוֹשֻׁעַ. רַבִּי יִצְחָק אָמַר, וְכִי הוֹשֵׁעַ קְרָאוֹ הַפָּסוּק? וַהֲרֵי כָּתוּב (שמות יז) וַיֹּאמֶר מֹשֶׁה אֶל יְהוֹשֻׁעַ. (שם לג) יְהוֹשֻׁעַ בִּן נוּן נַעַר. (שם יז) וַיַּחֲלֹשׁ יְהוֹשֻׁעַ. אֶלָּא אָמַר לוֹ מֹשֶׁה, יָהּ יוֹשִׁיעֲךְ מֵהֶם.</p>\n<p>רַבִּי אַבָּא אָמַר, כֵּיוָן שֶׁשְּׁלָחוֹ לְהִכָּנֵס לְשָׁם, הִצְטָרֵךְ לִהְיוֹת שָׁלֵם, וּבַמֶּה? בַּשְּׁכִינָה. שֶׁעַד אוֹתָהּ שָׁעָה נִקְרָא נַעַר, כְּמוֹ שֶׁבֵּאַרְנוּ, וּבְאוֹתָהּ שָׁעָה קְשָׁרוֹ מֹשֶׁה אֵלֶיהָ. וְאַף עַל גַּב שֶׁמָּצָאנוּ יְהוֹשֻׁעַ בַּתְּחִלָּה, הַפָּסוּק קְרָאוֹ כָּךְ עַל שֶׁעָתִיד לְהִקָּרֵא כָּךְ. אָמַר מֹשֶׁה, וַדַּאי זֶה לֹא צָרִיךְ לְהִכָּנֵס לְשָׁם, אֶלָּא בַּשְּׁכִינָה, וְכָךְ רָאוּי.</p>\n<p>הֲיְשִׁ בָּהּ עֵץ אִם אַיִן וְגוֹ'. רַבִּי חִיָּיא אָמַר, וְכִי לֹא הָיָה יוֹדֵעַ מֹשֶׁה שֶׁיֵּשׁ בָּהּ כַּמָּה עֵצִים מְשֻׁנִּים זֶה מִזֶּה? וַהֲרֵי הוּא שִׁבַּח אוֹתָהּ לְיִשְׂרָאֵל כַּמָּה פְעָמִים, וְהוּא הִסְתַּפֵּק בָּזֶה?! וַהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לְמֹשֶׁה בַּתְּחִלָּה שֶׁהִיא אֶרֶץ זָבַת חָלָב וּדְבַשׁ. אָמַר רַבִּי יוֹסֵי, בָּזֶה הִתְעוֹרְרוּ הַחֲבֵרִים, שֶׁכָּתוּב (איוב א) אִישׁ הָיָה בְאֶרֶץ עוּץ אִיּוֹב שְׁמוֹ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, רָמַז לָהֶם רֶמֶז חָכְמָה עַל מַה שֶּׁשָּׁאֲלוּ בַתְּחִלָּה, שֶׁכָּתוּב (שמות יז) הֲיֵשׁ ה' בְּקִרְבֵּנוּ אִם אָיִן. אָמַר, שָׁם תִּרְאוּ אִם הִיא רְאוּיָה לָזֶה אוֹ לָזֶה. אָמַר לָהֶם, אִם תִּרְאוּ שֶׁפְּרִי הָאָרֶץ כִּשְׁאָר אַרְצוֹת הָעוֹלָם - יֵשׁ בָּהּ עֵץ הַחַיִּים, וְלֹא מִמָּקוֹם יוֹתֵר עֶלְיוֹן. וְאִם תִּרְאוּ שֶׁפְּרִי הָאָרֶץ יָתֵר וּמְשֻׁנֶּה מִכָּל מָקוֹם בָּעוֹלָם, תֵּדְעוּ שֶׁהֲרֵי מֵהָעַתִּיק הַקָּדוֹשׁ שׁוֹפֵעַ וְנִמְשָׁךְ אוֹתוֹ שִׁנּוּי עֶלְיוֹן מִכָּל מְקוֹמוֹת הָעוֹלָם. וּבָזֶה תֵּדְעוּ - הֲישׁ בָּהּ עֵ\"ץ אִם אַיִ\"ן, וְזֶה צְרִיכִים אַתֶּם בַּתְּחִלָּה (שבמעיכם רציתם) לָדַעַת זֶה, שֶׁכָּתוּב הֲיֵשׁ ה' בְּקִרְבֵּנוּ. בְּקִרְבֵּנוּ דַּוְקָא, אוֹ אִם אַיִן. וְעַל זֶה וְהִתְחַזַּקְתֶּם וּלְקַחְתֶּם מִפְּרִי הָאָרֶץ, לָדַעַת שִׁנּוּי שֶׁלּוֹ.</p>\n<p>וְהַיָּמִים יְמֵי בִּכּוּרֵי עֲנָבִים. וְהַיָּמִים, מַה בָּא לוֹמַר, שֶׁהֲרֵי וְאָז בִּכּוּרֵי עֲנָבִים מַסְפִּיק לוֹ? אֶלָּא וְהַיָּמִים - אוֹתָם הַנּוֹדָעִים, כֻּלָּם הָיוּ מְחֻבָּרִים בְּאוֹתוֹ זְמַן בְּאוֹתוֹ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן, כְּמוֹ שֶׁשָּׁנִינוּ עֲנָבִים הָיוּ, וְעַל זֶה וְהַיָּמִים - אוֹתָם הַיְדוּעִים - יְמֵי בִּכּוּרֵי עֲנָבִים דַּוְקָא.</p>\n<p>וַיַּעָלוּ בַנֶּגֶב וַיָּבא עַד חֶבְרוֹן. וַיָּבאוּ צָרִיךְ לִהְיוֹת! אֶלָּא אָמַר רַבִּי יוֹסֵי, כָּלֵב הוּא שֶׁבָּא לְהִתְפַּלֵּל עַל קִבְרֵי הָאָבוֹת. אָמַר כָּלֵב, יְהוֹשֻׁעַ הֲרֵי בֵּרְכוֹ מֹשֶׁה בְּסִיּוּעַ עֶלְיוֹן קָדוֹשׁ וְיָכוֹל לְהִנָּצֵל מֵהֶם, וַאֲנִי מָה אֶעֱשֶׂה? נִמְלַךְ לְבַקֵּשׁ בַּקָּשָׁה עַל קִבְרֵי הָאָבוֹת כְּדֵי שֶׁיִּנָּצֵל מִסּוֹדוֹתֵיהֶם (מעצה רעה) שֶׁל שְׁאָר מְרַגְּלִים.</p>\n<p>רַבִּי יִצְחָק אָמַר, מִי שֶׁהָיָה רָשׁוּם מִכֻּלָּם, זֶה נִכְנַס בּוֹ, שֶׁבּוֹ תָּלוּי הַכֹּל. וּבֹא וּרְאֵה, מִי הוּא מִשְּׁאָר אֲחֵרִים שֶׁיָּכוֹל לְהִכָּנֵס לְשָׁם? שֶׁהֲרֵי כָּתוּב וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי, וּמִפַּחְדָּם מִי יָכוֹל לְהִכָּנֵס בַּמְּעָרָה? אֶלָּא הַשְּׁכִינָה נִכְנְסָה שָׁם עִם כָּלֵב, לְבַשֵּׂר לָאָבוֹת שֶׁהֲרֵי הִגִּיעַ זְמַן לְהַכְנִיס בְּנֵיהֶם לָאָרֶץ שֶׁנִּשְׁבַּע לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ וַיָּבא עַד חֶבְרוֹן.</p>\n<p>לָמַדְנוּ, אֲחִימָן שֵׁשַׁי וְתַלְמַי מִמִּי יָצְאוּ? זֶרַע הָיוּ מֵאוֹתָם נְפִילִים שֶׁהִפִּילָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָרֶץ וְהוֹלִידוּ מִבְּנוֹת הָאָרֶץ, וּמֵהֶם יָצְאוּ גִבּוֹרֵי עוֹלָם, כְּמוֹ שֶׁכָּתוּב (בראשית ו) הֵמָּה הַגִּבּרִים אֲשֶׁר מֵעוֹלָם אַנְשֵׁי הַשֵּׁם. אֲשֶׁר מֵעוֹלָם, שַׁמָּשֵׁי (משנברא) הָעוֹלָם נִמְצְאוּ. אַנְשֵׁי הַשֵּׁם, אֲחִימָן שֵׁשַׁי וְתַלְמַי.</p>\n<p>וַיָּבֹאוּ עַד נַחַל אֶשְׁכֹּל וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (ישעיה מב) כֹּה אָמַר הָאֵל ה' בּוֹרֵא הַשָּׁמַיִם וְנוֹטֵיהֶם וְגוֹ'. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִסְתַּכֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא. כַּמָּה יֵשׁ לָהֶם לְהִסְתַּכֵּל בְּדִבְרֵי תוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ מַקְרִיב כָּל קָרְבְּנוֹת הָעוֹלָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְכַפֵּר לוֹ עַל כָּל חֲטָאָיו, וּמְתַקְּנִים לוֹ כַּמָּה כִסְאוֹת לָעוֹלָם הַבָּא.</p>"],[9522012331,"<p>רַבִּי יְהוּדָה הָיָה הוֹלֵךְ בַּדֶּרֶךְ יַחַד עִם רַבִּי אַבָּא. שָׁאַל אוֹתוֹ, אָמַר, דָּבָר אֶחָד אֲנִי רוֹצֶה לִשְׁאֹל; כֵּיוָן שֶׁיָּדַע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁעָתִיד הָאָדָם לַחֲטֹא לְפָנָיו וְלִגְזֹר עָלָיו מִיתָה, מַדּוּעַ בְּרָאוֹ? שֶׁהֲרֵי הַתּוֹרָה הָיְתָה אַלְפַּיִם שָׁנִים עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וְכָתוּב בָּהּ בַּתּוֹרָה, (במדבר יט) אָדָם כִּי יָמוּת בְּאֹהֶל. (שם כז) אִישׁ כִּי יָמוּת. וַיָּמָת. וַיְחִי פְּלוֹנִי וַיָּמָת. מָה רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לָאָדָם בָּעוֹלָם הַזֶּה, שֶׁאֲפִלּוּ אִם יִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה יָמוּת, וְאִם לֹא יִשְׁתַּדֵּל בַּתּוֹרָה יָמוּת, הַכֹּל בְּדֶרֶךְ אֶחָד, פְּרָט לִפְרִישׁוּת אוֹתוֹ עוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ט) כַּטּוֹב כַּחוֹטֶא.</p>\n<p>אָמַר לוֹ, דַּרְכֵי רִבּוֹנְךְ וּגְזֵרוֹת רִבּוֹנְךְ מַה לְּךְ לִטְרֹחַ בָּהֶם? מַה שֶּׁיֵּשׁ לְךְ רְשׁוּת לָדַעַת וּלְהִסְתַּכֵּל - שְׁאַל, וּמַה שֶּׁאֵין לְךְ רְשׁוּת לָדַעַת - כָּתוּב (שם ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ, שֶׁדַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּסְתָרָיו גְּנוּזִים עֶלְיוֹנִים, שֶׁהוּא נִסְתָּר וְגָנוּז אֵין לָנוּ לִשְׁאֹל. אָמַר לוֹ, אִם כָּךְ, הֲרֵי הַתּוֹרָה כֻּלָּהּ נִסְתֶּרֶת וּגְנוּזָה, שֶׁהֲרֵי הִיא שֵׁם קָדוֹשׁ עֶלְיוֹן, וּמִי שֶׁמִּתְעַסֵּק בַּתּוֹרָה כְּאִלּוּ הִתְעַסֵּק בִּשְׁמוֹ הַקָּדוֹשׁ, וְאִם כָּךְ אֵין לָנוּ לִשְׁאֹל וּלְהִסְתַּכֵּל.</p>\n<p>אָמַר לוֹ, כָּל הַתּוֹרָה נִסְתֶּרֶת וּגְלוּיָה, וּשְׁמוֹ הַקָּדוֹשׁ נִסְתָּר וְגָלוּי, וְכָתוּב (דברים כט) הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ וְהַנִּגְלֹת לָנוּ וּלְבָנֵינוּ. הַנִּגְלֹת לָנוּ, שֶׁיֵּשׁ לָנוּ רְשׁוּת לִשְׁאֹל וּלְעַיֵּן וּלְהִסְתַּכֵּל בָּהֶם וְלָדַעַת בָּהֶם. אֲבָל הַנִּסְתָּרֹת לַה' אֱלֹהֵינוּ, שֶׁלּוֹ הֵם, וְלוֹ נִרְאִים, שֶׁמִּי יָכוֹל לָדַעַת וּלְהִתְדַּבֵּק בְּדַעְתּוֹ הַנִּסְתֶּרֶת, וְכָל שֶׁכֵּן לִשְׁאֹל?</p>"],[9522012332,"<p>בֹּא וּרְאֵה, אֵין רְשׁוּת לִבְנֵי הָעוֹלָם לוֹמַר דְּבָרִים נִסְתָּרִים וּלְפָרְשָׁם, פְּרָט לַמְּנוֹרָה הַקְּדוֹשָׁה רַבִּי שִׁמְעוֹן, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. וּמִשּׁוּם שֶׁדּוֹרוֹ רָשׁוּם לְמַעְלָה וּלְמַטָּה, וְעַל זֶה דְּבָרִים נֶאֱמָרִים בְּגָלוּי עַל יָדוֹ, וְלֹא יִהְיֶה דוֹר כְּדוֹר שֶׁהוּא שָׁרוּי בְּתוֹכוֹ, עַד שֶׁיָּבא מֶלֶךְ הַמָּשִׁיחַ.</p>\n<p>אֲבָל בּא וּרְאֵה, כָּתוּב (בראשית א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אֹתוֹ. (בכל הוא כעין דגמה שלמעלה. בא ראה) סוֹד הַדָּבָר - שְׁלֹשָׁה עוֹלָמוֹת יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁהוּא נִסְתָּר בְּתוֹכָם. עוֹלָם רִאשׁוֹן, אוֹתוֹ עֶלְיוֹן נִסְתַּר הַכֹּל, שֶׁלֹּא מִסְתַּכֵּל בּוֹ וְלֹא נוֹדָע בּוֹ, פְּרָט לוֹ שֶׁהוּא גָנוּז בְּתוֹכוֹ.</p>\n<p>עוֹלָם שֵׁנִי, שֶׁהוּא קָשׁוּר בְּאוֹתוֹ שֶׁלְּמַעְלָה, וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע מִמֶּנּוּ, כְּמוֹ שֶׁכָּתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק, זֶה הַשַּׁעַר לַה'. וְזֶהוּ עוֹלָם שֵׁנִי.</p>\n<p>עוֹלָם שְׁלִישִׁי, אוֹתוֹ עוֹלָם תַּחְתּוֹן מֵהֶם שֶׁנִּמְצָא בּוֹ פֵּרוּד, וְזֶהוּ עוֹלָם שֶׁמַּלְאָכִים עֶלְיוֹנִים שׁוֹרִים בְּתוֹכוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בּוֹ וְלֹא נִמְצָא. נִמְצָא בּוֹ כָּעֵת. כְּשֶׁרוֹצִים לְהִסְתַּכֵּל וְלָדַעַת אוֹתוֹ, מִסְתַּלֵּק מֵהֶם, וְלֹא נִרְאֶה, עַד שֶׁכֻּלָּם שׁוֹאֲלִים אַיֵּה מְקוֹם כְּבוֹדוֹ. (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. וְזֶהוּ עוֹלָם שֶׁלֹּא נִמְצָא בוֹ תָּמִיד.</p>\n<p>כְּמוֹ זֶה, (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם. אָז יֵשׁ לוֹ שְׁלֹשָׁה עוֹלָמוֹת. עוֹלָם רִאשׁוֹן - הָעוֹלָם הַזֶּה שֶׁנִּקְרָא עוֹלַם הַפֵּרוּד, וְהָאָדָם נִמְצָא בּוֹ וְלֹא נִמְצָא. כְּשֶׁרוֹצִים לְהִסְתַּכֵּל בּוֹ, מִסְתַּלֵּק מֵהֶם וְלֹא נִרְאֶה.</p>\n<p>עוֹלָם שֵׁנִי - עוֹלָם שֶׁהוּא קָשׁוּר בְּאוֹתוֹ עוֹלָם עֶלְיוֹן, וְזֶהוּ גַּן עֵדֶן שֶׁבָּאָרֶץ, שֶׁזֶּהוּ קָשׁוּר בְּעוֹלָם עֶלְיוֹן אַחֵר, וּמִזֶּה נוֹדָע וּמִתְיַדֵּעַ עוֹלָם אַחֵר.</p>\n<p>עוֹלָם שְׁלִישִׁי - עוֹלָם עֶלְיוֹן טָמִיר, גָּנוּז וְנִסְתָּר, שֶׁאֵין מִי שֶׁיֵּדַע אוֹתוֹ, כְּמוֹ שֶׁכָּתוּב (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. וְהַכֹּל כְּדֻגְמָה עֶלְיוֹנָה, (ראשון שאמרתי ובאמת) שֶׁכָּתוּב (בראשית ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם.</p>\n<p>(בא ראה, ודאי) עֵל זֶה כָּתוּב, (דברים יד) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם וְגוֹ', כְּמוֹ שֶׁפֵּרְשׁוּהָ. וְאֵלּוּ הֵם בְּצֶלֶם אֱלֹהִים, וְאֵלּוּ יוֹרְשִׁים יְרֻשָּׁה עֶלְיוֹנָה כְּמוֹ שֶׁלּוֹ. וְעַל זֶה מֻזְהָרִים בַּתּוֹרָה (דברים יד) לֹא תִתְגֹּדְדוּ וְלֹא תָשִׂימוּ קָרְחָה. שֶׁהֲרֵי לֹא נֶאֱבָד, וַהֲרֵי מָצוּי בְּעוֹלָמוֹת טוֹבִים עֶלְיוֹנִים וּמְכֻבָּדִים, לִהְיוֹת שְׂמֵחִים כְּשֶׁמִּסְתַּלֵּק (צדיק) מֵהָעוֹלָם הַזֶּה.</p>\n<p>וּבֹא וּרְאֵה, אִלְמָלֵא לֹא חָטָא אָדָם, לֹא יִטְעַם טַעַם הַמָּוֶת בָּעוֹלָם הַזֶּה בִּזְמַן שֶׁיִּכָּנֵס לְעוֹלָמוֹת אֲחֵרִים. אֲבָל מִשּׁוּם שֶׁחָטָא, טוֹעֵם טַעַם הַמָּוֶת עַד שֶׁלֹּא יִכָּנֵס לְאוֹתָם עוֹלָמוֹת, וּמִתְפַּשֶּׁטֶת הָרוּחַ מִגּוּף זֶה, וּמַשְׁאִירוֹ בָּעוֹלָם הַזֶּה, וְהָרוּחַ מִתְרַחֶצֶת בִּנְהַר דִּינוּר לְקַבֵּל עָנְשָׁהּ. וְאַחַר כָּךְ נִכְנֶסֶת לְגַן עֵדֶן שֶׁבָּאָרֶץ, וּמִזְדַּמֵּן לָהּ כְּלִי אוֹר אַחֵר, כְּפַרְצוּף הַגּוּף שֶׁל הָעוֹלָם הַזֶּה מַמָּשׁ. וּמִתְלַבֶּשֶׁת וְנִתְקֶנֶת בּוֹ, וְשָׁם הוּא מְדוֹרָהּ תָּמִיד. וְנִקְשֶׁרֶת בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת בַּנְּשָׁמָה, וְעוֹלָה וּמִתְעַטֶּרֶת לְמַעְלָה לְמַעְלָה. זֶהוּ שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וְגוֹ'.</p>\n<p>לָמָּה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ? אֶלָּא סוֹד הַדָּבָר, בִּגְלַל הִתְחַדְּשׁוּת הַלְּבָנָה שֶׁמִּתְעַטֶּרֶת (עטרות) לְהָאִיר מֵהַשֶּׁמֶשׁ בְּאוֹתוֹ זְמַן. וְכֵן מִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ. מִדֵּי שַׁבָּת - זוֹ הַלְּבָנָה. בְּשַׁבַּתּוֹ - זֶה הַשֶּׁמֶשׁ. שֶׁהָאוֹר בָּא לָהּ מִשָּׁם. וְעַל זֶה הַכֹּל דָּבָר אֶחָד. וְזֶה בֵּרוּר הַדָּבָר, פְּרָט לָרְשָׁעִים שֶׁכָּתוּב בָּהֶם מִיתָה לְכָל הָעוֹלָמוֹת, כָּרֵת מִכָּל הָעוֹלָמוֹת, וּמֻשְׁמָדִים מֵהַכֹּל כְּשֶׁלֹּא נִכְנָסִים בִּתְשׁוּבָה. אָמַר רַבִּי יְהוּדָה, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי וְהִרְוַחְתִּי דְבָרִים הַלָּלוּ וְעָמַדְתִּי עֲלֵיהֶם.</p>"],[9522012333,"<p>אָמַר רַבִּי שִׁמְעוֹן, מִפָּרָשָׁה זוֹ לָמַדְנוּ סוֹד חָכְמָה, וְנִשְׁמָעִים מִמֶּנָּה סוֹדוֹת עֶלְיוֹנִים וְנִכְבָּדִים. בּא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ בַּתּוֹרָה וְאוֹמֵר: לְכוּ בִדְרָכַי, הִשְׁתַּדְּלוּ בַעֲבוֹדָתִי, וַהֲרֵינִי מַכְנִיסְכֶם לְעוֹלָמוֹת טוֹבִים, לְעוֹלָמוֹת עֶלְיוֹנִים. בְּנֵי אָדָם שֶׁלֹּא יוֹדְעִים, לֹא מַאֲמִינִים וְלֹא מִסְתַּכְּלִים, אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא: לְכוּ תְּרַגְּלוּ אוֹתוֹ עוֹלָם טוֹב, אוֹתוֹ עוֹלָם עֶלְיוֹן שֶׁל כִּסּוּפִים. הֵם אוֹמְרִים: אֵיךְ נוּכַל לְרַגֵּל אוֹתוֹ וְלָדַעַת כָּל זֶה?</p>\n<p>מַה כָּתוּב? עֲלוּ זֶה בַּנֶּגֶב. הִשְׁתַּדְּלוּ בַתּוֹרָה וְתִרְאוּ שֶׁהֲרֵי הִיא עוֹמֶדֶת לִפְנֵיכֶם, וּמִמֶּנָּה תֵדְעוּ אוֹתוֹ. וּרְאִיתֶם אֶת הָאָרֶץ מַה הִיא וְגוֹ'. תִּרְאוּ מִמֶּנָּה אוֹתוֹ עוֹלָם, שֶׁהֲרֵי יְרֻשָּׁה שֶׁל חֵלֶק שֶׁאֲנִי מַכְנִיסְכֶם בָּהּ. וְאֶת הָעָם הַיֹּשֵׁב עָלֶיהָ - אוֹתָם צַדִּיקִים שֶׁבְּגַן עֵדֶן, שֶׁעוֹמְדִים שׁוּרוֹת שׁוּרוֹת בְּכָבוֹד עֵלְיוֹן בִּדְרָגוֹת עֶלְיוֹנוֹת.</p>\n<p>הֶחָזָקֹ הוּא הֲרָפֶה. בָּהּ תִּרְאוּ אִם זָכוּ לְכָל זֶה כְּשֶׁהִתְגַּבְּרוּ עַל יִצְרָם וּשְׁבָרוּהוּ, אִם לֹא. אוֹ כְּשֶׁהִתְחַזְּקוּ בַתּוֹרָה לַעֲסֹק בָּהּ יוֹמָם וָלַיְלָה. אוֹ אִם הֲרָפוּ יְדֵיהֶם מִמֶּנָּה, וְזָכוּ לְכָל זֶה. הַמְעַט הוּא אִם רָב, אִם רַבִּים אֵלּוּ שֶׁהִשְׁתַּדְּלוּ בַעֲבוֹדָתִי וְהִתְחַזְּקוּ בַתּוֹרָה מִשּׁוּם שֶׁזָּכוּ לְכָל זֶה, אִם לֹא.</p>\n<p>וּמָה הָאָרֶץ הַשְּׁמֵנָה הִיא אִם רָזָה. מֵהַתּוֹרָה תֵּדְעוּ מָה הָאָרֶץ, מָה אוֹתוֹ עוֹלָם, אִם מַרְבֶּה טוֹבָה עֶלְיוֹנָה לְיוֹשְׁבֶיהָ, אוֹ אִם מַמְעִיט מִמֶּנּוּ כְּלוּם. הֲיֶשׁ בָּהּ עֵץ אִם אַיִן. הֲיֶשׁ בָּהּ עֵץ הַחַיִּים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, אוֹ שֶׁצְּרוֹר הַחַיִּים נִמְצָא בְתוֹכָהּ, אִם לֹא.</p>\n<p>וַיַּעָלוּ בַנֶּגֶב וַיָּבֹא עַד חֶבְרוֹן. וַיַּעֲלוּ בַנֶּגֶב, בְּנֵי אָדָם נִכְנָסִים לְתוֹכָהּ בַּנֶּגֶב, בְּלֵב עָצֵל, כְּמִי שֶׁמִּשְׁתַּדֵּל בְּחִנָּם, בְּיֹבֶשׁ, שֶׁחוֹשֵׁב שֶׁאֵין בָּהּ שָׂכָר. רוֹאֶה שֶׁעֹשֶׁר הָעוֹלָם הַזֶּה אָבַד בִּגְלָלָהּ, חוֹשֵׁב שֶׁהוּא הַכֹּל. בַּנֶּגֶב, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ח) חָרְבוּ הַמַּיִם, וּמְתַרְגְּמִים נְגִיבוּ.</p>"],[9522012334,"<p>אַחַר כָּךְ - וַיָּבא עַד חֶבְרוֹן. עַד שֶׁבָּא לְהִתְחַבֵּר בָּהּ, קוֹרֵא וְשׁוֹנֶה בָּהּ. וְשָׁם אֲחִימָן שֵׁשַׁי וְתַלְמַי (במדבר י״ג:כ״ב), שָׁם רוֹאֶה פִלּוּגִים רַבִּים, טָמֵא וְטָהוֹר, אָסוּר וּמֻתָּר, (כשר ופסול) עֳנָשִׁים וּשְׂכָרִים. אֵלֶּה אוֹתָם דַּרְכֵי הַתּוֹרָה, דִּקְדּוּקֵי הַתּוֹרָה. יְלִידֵי הָעֲנָק, שֶׁנּוֹלְדוּ מִצַּד הַגְּבוּרָה.</p>\n<p>וְחֶבְרוֹן שֶׁבַע שָׁנִים נִבְנְתָה - אֵלֶּה אוֹתָם שִׁבְעִים פָּנִים שֶׁל הַתּוֹרָה. שִׁבְעִים פָּנִים יֵשׁ לָהּ, לְכָל צַד עֶשֶׂר. וְחֶבְרוֹן, זוֹ הַתּוֹרָה, מִי שֶׁמִּשְׁתַּדֵּל בָּהּ נִקְרָא חָבֵר. לִפְנֵי צֹעַן מִצְרָיִם. שָׁנִינוּ, יֵשׁ תּוֹרָה מוּל תּוֹרָה, וְהַיְנוּ תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וְזֶה (מלכות) חֶבְרוֹן. מִתּוֹרָה שֶׁבִּכְתָב יוֹצֵאת, כְּמוֹ שֶׁנֶּאֱמַר (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. וְזוֹ נִבְנְתָה שֶׁבַע שָׁנִים, שֶׁבִּגְלַל זֶה נִקְרֵאת בַּת שֶׁבַע, לִפְנֵי צֹעַן מִצְרָיִם, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ה) וַתֵּרֶב חָכְמַת שְׁלֹמֹה מֵחָכְמַת כָּל בְּנֵי קֶדֶם וּמִכָּל חָכְמַת מִצְרָיִם.</p>\n<p>וַיָּבֹאוּ עַד נַחַל אֶשְׁכּוֹל - אֵלֶּה אוֹתָם דִּבְרֵי אַגָּדָה, דְּרָשָׁה, שֶׁתְּלוּיִים מִצַּד הָאֱמוּנָה. וַיִּכְרְתוּ מִשָּׁם זְמוֹרָה וְגוֹ', לוֹמְדִים מִשָּׁם רָאשֵׁי פְרָקִים, רָאשֵׁי דְבָרִים, אוֹתָם שֶׁבְּנֵי הָאֱמוּנָה שְׂמֵחִים בִּדְבָרִים, וּמִתְבָּרְכִים דְּבָרִים בְּתוֹכָם, וּמִסְתַּכְּלִים שֹׁרֶשׁ אֶחָד וְעִקָּר אֶחָד, וְלֹא נִמְצָא בָהֶם פֵּרוּד. אוֹתָם שֶׁלֹּא נִמְצָאִים בְּנֵי אֱמוּנָה וְלֹא לוֹמְדִים תּוֹרָה לִשְׁמָהּ, שָׂמִים אֶת הָאֱמוּנָה בְּפֵרוּד. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם, בְּפֵרוּד. מַהוּ בַמּוֹט? כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכא) אַל יִתֵּן לַמּוֹט רַגְלֶךְ. וּמִן הָרִמֹּנִים וּמִן הַתְּאֵנִים, הַכֹּל שָׁוִים לִדְבָרִים אֵלֶּה לְצַד אַחֵר, לְצַד הַמִּינִים, לְצַד הַפֵּרוּד.</p>\n<p>זְהִוּ שֶׁכָּתוּב וַיָּשֻׁבוּ מִתּוּר הָאָרֶץ. וַיָּשֻׁבוּ, שָׁבִים לְצַד הָרָע וְשָׁבִים מִדֶּרֶךְ הָאֱמֶת. אוֹמְרִים, מָה אִכְפַּת לָנוּ? עַד הַיּוֹם לֹא רָאִינוּ טוֹב לָעוֹלָם. עָמַלְנוּ בָהּ, הַבַּיִת רֵיק, יָשַׁבְנוּ בְקָלוֹן בָּעָם, וּלְאוֹתוֹ עוֹלָם מִי יִזְכֶּה וּמִי יִכָּנֵס לְתוֹכוֹ? טוֹב לָנוּ שֶׁלֹּא טָרַחְנוּ כָּל זֶה. וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוֹ', הֲרֵי עָמַלְנוּ וְעָיַפְנוּ בִּשְׁבִיל לָדַעַת חֵלֶק אוֹתוֹ עוֹלָם. וְגַם זָבַת חָלָב וּדְבַשׁ הִיא, טוֹב הוּא אוֹתוֹ עוֹלָם עֶלְיוֹן, כְּמוֹ שֶׁיָּדַעְנוּ בַתּוֹרָה, אֲבָל מִי יָכוֹל לִזְכּוֹת בּוֹ?</p>\n<p>אֶפֶס כִּי עַז הָעָם, תַּקִּיף הוּא, שֶׁלֹּא יַחֲשִׁיב כָּל הָעוֹלָם כְּלָל, מִשּׁוּם שֶׁיִּהְיֶה לוֹ עֹשֶׁר רַב לְהִשְׁתַּדֵּל בּוֹ, מִי הוּא שֶׁיִּזְכֶּה בָּהּ? וַדַּאי אֶפֶס כִּי עַז הָעָם הַיֹּשֵׁב בָּאָרֶץ. מִי שֶׁרוֹצֶה לִזְכּוֹת בָּהּ, צָרִיךְ לִהְיוֹת חָזָק בְּעֹשֶׁר, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) וְעָשִׁיר יַעֲנֶה עַזּוֹת. וְהֶעָרִים גְּדֹלֹת בְּצֻרוֹת, בָּתִּים מְלֵאִים כָּל טוֹב שֶׁלֹּא יֶחֶסְרוּ מֵהַכֹּל. וְעִם כָּל זֶה, וְגַם יְלִדֵי הָעֲנָק רָאִינוּ שָׁם, צָרִיךְ גּוּף חָזָק, גִּבּוֹר כַּאֲרִי. (שימצא שם תמיד) מִשּׁוּם שֶׁהִיא מַתֶּשֶׁת כֹּחוֹ שֶׁל אָדָם לְהִשְׁתַּדֵּל בְּאוֹתוֹ אִסּוּר וְהֶתֵּר, טָמֵא וְטָהוֹר, כָּשֵׁר וּפָסוּל. מִי יָכוֹל לִזְכּוֹת בָּהּ?</p>\n<p>וְעוֹד, עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. אִם יֹאמַר אָדָם שֶׁאֲפִלּוּ שֶׁיִּזְכֶּה לְכָל זֶה, עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, הֲרֵי יֵצֶר הָרָע, הַקָּטֵגוֹר, מְקַטְרֵג עַל הָאָדָם, שֶׁנִּמְצָא תָמִיד בַּגּוּף. וְהַחִתִּי וְהָאֱמֹרִי וְגוֹ', כַּמָּה מְקַטְרְגִים נִמְצָאִים שָׁם, (כדי) שֶׁלֹּא יָכוֹל הָאָדָם לְהִכָּנֵס לְאוֹתוֹ עוֹלָם כְּלָל, מִי יִזְכֶּה בּוֹ וּמִי יִכָּנֵס לְתוֹכוֹ? בַּדְּבָרִים הַלָּלוּ (במדבר לב) וַיָּנִיאוּ אֶת לֵב בְּנֵי יִשְׂרָאֵל, מִשּׁוּם שֶׁהוֹצִיאוּ שֵׁם רַע עָלֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר וַיֹּצִיאוּ דִּבַּת הָאָרֶץ.</p>\n<p>אוֹתָם בְּנֵי הָאֱמוּנָה מָה אוֹמְרִים? אִם חָפֵץ בָּנוּ ה' (וגו') וּנְתָנָהּ לָנוּ. כֵּיוָן שֶׁיִּשְׁתַּדֵּל אָדָם בִּרְצוֹן הַלֵּב לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא צָרִיךְ מִמֶּנּוּ אֶלָּא הַלֵּב, וְיִשְׁמְרוּ אוֹתוֹ רִשּׁוּם קָדוֹשׁ, שֶׁכָתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ.</p>\n<p>אֲבָל, אַךְ בַּה' אַל תִּמְרֹדוּ. צָרִיךְ שֶׁלֹּא תִמְרְדוּ בַתּוֹרָה, שֶׁהַתּוֹרָה לֹא צְרִיכָה עֹשֶׁר וְלֹא כְּלֵי כֶסֶף וְזָהָב. וְאַתֶּם אַל תִּירְאוּ אֶת עַם הָאָרֶץ, שֶׁהֲרֵי גּוּף שָׁבוּר, אִם יִשְׁתַּדֵּל בַּתּוֹרָה, יִמְצָא רְפוּאָה בַּכֹּל. זֶהוּ שֶׁכָּתוּב (משלי ג) רִפְאוּת תְּהִי לְשָׁרֶךְ וְשִׁקּוּי לְעַצְמוֹתֶיךְ. וְכָתוּב (שם ד) וּלְכָל בְּשָׂרוֹ מַרְפֵּא. וְכָל אוֹתָם מְקַטְרְגִים מַכְרִיזִים וְאוֹמְרִים: פַּנּוּ מָקוֹם לִפְלוֹנִי עֶבֶד הַמֶּלֶךְ!</p>\n<p>בִּגְלַל זֶה אַל תִּירְאוּ, כִּי לַחְמֵנוּ הֵם. הֵם בְּעַצְמָם מְזַמְּנִים מְזוֹנוֹת בְּכָל יוֹם לְכָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א יז) וְאֶת הָעֹרְבִים צִוִּיתִי לְכַלְכֶּלְךְ, וְכָתוּב (שם) וְהָעוֹרְבִים מְבִיאִים לוֹ לֶחֶם וּבָשָׂר. סָר צִלָּם מֵעֲלֵיהֶם. מַהוּ צִלָּם? זֶה תֹקֶף הַדִּין הַקָּשֶׁה. מָה הַטַּעַם סָר? מִשּׁוּם שֶׁה' אִתָּנוּ אַל תִּירָאֻם. הַכֹּל זָז בִּגְלַל הַתּוֹרָה. אַשְׁרֵי חֵלֶק אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה לִשְׁמָהּ, שֶׁהֲרֵי מִתְקַשְּׁרִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא מַמָּשׁ, וְנִקְרָאִים אַחִים וְרֵעִים. זֶהוּ שֶׁכָּתוּב (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָּא שָׁלוֹם בָּךְ.</p>\n<p>וַיָּבֹאוּ עַד נַחַל אֶשְׁכּוֹל וְגוֹ'. רַבִּי אַבָּא אָמַר, כָּרְתוּ אוֹתוֹ אֶשְׁכּוֹל, בָּאוּ לַהֲרִימוֹ, לֹא יָכְלוּ. בָּאוּ לְקַחְתּוֹ, לֹא יָכְלוּ. בָּאוּ כָלֵב וִיהוֹשֻׁעַ וּלְקָחוּהוּ וְהֶעֱלוּהוּ, וְעָלָה עַל יָדָם. זֶהוּ שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט בִּשְׁנָיִם. בִּשְׁנָיִם, בְּאוֹתָם שְׁנַיִם יְחִידִים. זְמוֹרָה מָה רָצוּ? אֶלָּא אֶשְׁכּוֹל הָיָה תָלוּי בָּהּ, וּבְעוֹד שֶׁהָיָה מְחֻבָּר בִּמְקוֹמוֹ, נִקְרָא זְמוֹרָה. אַחַר כָּךְ קְרָאוֹ מוֹט, שֶׁכָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט, אוֹתוֹ הַנּוֹדָע, אוֹתוֹ שֶׁכָּרְתוּ.</p>\n<p>מִכָּאן יָדְעוּ יְהוֹשֻׁעַ וְכָלֵב שֶׁהֵם רְאוּיִם לְהִכָּנֵס לָאָרֶץ וְלִהְיוֹת לָהֶם בָּהּ חֵלֶק וְנַחֲלָה. עַד שֶׁבָּאוּ, נִמְלְכוּ עֲלֵיהֶם כֻּלָּם. עָמַד כָּלֵב בִּפְרִי, אָמַר: פְּרִי פְּרִי, אִם בִּגְלָלְךְ אָנוּ נֶהֱרָגִים, מָה אָנוּ בְחֶלְקְךְ? מִיָּד עָשָׂה עַצְמוֹ קַל וְנִתַּן לָהֶם.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, לֹא נָתְנוּ לָאֲחֵרִים, שֶׁהֲרֵי כָּתוּב וַיִּשָּׂאֻהוּ בַמּוֹט, וְכָתוּב בִּשְׁנָיִם, וּבְכֻלָּם לֹא הָיוּ שְׁנַיִם כְּמוֹתָם. וּמִכָּאן לָמַד יְהוֹשֻׁעַ אַחַר כָּךְ, שֶׁכָּתוּב (יהושע ב) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִּׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים. וּשְׁנַיִם אֵלֶּה הֲרֵי פֵּרְשׁוּהָ הַקַּדְמוֹנִים. וּכְשֶׁהִגִּיעוּ אֶל יִשְׂרָאֵל, נָתְנוּ לָהֶם, וְהֵם נִשְׁאֲרוּ וְעָשׂוּ עַצְמָם כְּשִׁירַיִם.</p>\n<p>רַבִּי יִצְחָק אָמַר, כְּשֶׁהָיוּ מַגִּיעִים לְאוֹתָם עֲנָקִים, הָיוּ שָׂמִים אוֹתוֹ מַטֶּה שֶׁל מֹשֶׁה לִפְנֵיהֶם, וְנִצְּלוּ. וּמִנַּיִן לָנוּ שֶׁאוֹתוֹ מַטֶּה נָתַן לָהֶם? זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר אֲלֵהֶם עֲלוּ זֶה בַּנֶּגֶב. כָּתוּב כָּאן עֲלוּ זֶה, וְכָתוּב שָׁם (שמות ד) וְאֶת הַמַּטֶּה הַזֶּה וְגוֹ', וּבִגְלָלוֹ נִצְּלוּ. שֶׁאִם תֹּאמַר שֶׁהָעֲנָקִים הַלָּלוּ עָזְבוּ אוֹתָם? אֶלָּא בָּאוּ לְקַחְתָּם, וְהָיוּ שָׂמִים מוּלָם אוֹתוֹ מַטֶּה, וְנִצּוֹלִים (ובורחים) מִלִּפְנֵיהֶם. רַבִּי יְהוּדָה אָמַר, מָסֹרֶת שֵׁם הַקָּדוֹשׁ מָסַר לָהֶם מֹשֶׁה, וּבִגְלָלוֹ נִצְּלוּ מֵהֶם.</p>\n<p>רַבִּי חִיָּיא אָמַר, שְׁלֹשָׁה שֵׁמוֹת נִקְרְאוּ: נְפִילִים, עֲנָקִים, רְפָאִים. וְכֻלָּם הֶאֱרִיכוּ יָמִים. נְפִילִים נִקְרְאוּ בַתְּחִלָּה. אַחַר כָּךְ כְּשֶׁהִתְחַבְּרוּ בִּבְנוֹת בְּנֵי הָאָדָם וְהוֹלִידוּ מֵהֶם, נִקְרְאוּ עֲנָקִים. אַחַר כָּךְ שֶׁהָיוּ הוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם הַזֶּה וּמִתְרַפִּים מֵאוֹתוֹ שֶׁלְּמַעְלָה, נִקְרְאוּ רְפָאִים.</p>\n<p>אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (איוב כו) הָרְפָאִים יְחוֹלָלוּ, (דברים ב) רְפָאִים יֵחָשְׁבוּ אַף הֵם כַּעֲנָקִים. אָמַר לוֹ, כָּךְ הוּא, מִשּׁוּם שֶׁעֲנָקִים בָּאוּ מִצַּד זֶה וּמִצַּד זֶה וְהִתְחַזְּקוּ יוֹתֵר בָּאָרֶץ. כְּמוֹ זֶה רְפָאִים, וּמֵהֶם יָצְאוּ, וְהָיוּ מַאֲרִיכִים יָמִים. וּכְשֶׁנֶּחֱלָשִׁים, נֶחֱלָשׁ חֲצִי גוּף, וַחֲצִי עוֹמֵד. כֵּיוָן שֶׁחֲצִי הַגּוּף הָיָה מֵת, הָיוּ לוֹקְחִים עֵשֶׂב מֵעִשְׂבֵי הַשָּׂדֶה וְזוֹרְקִים לְפִיהֶם וּמֵתִים. וּמִשּׁוּם שֶׁהֵם רָצוּ לַהֲרֹג עַצְמָם, נִקְרְאוּ רְפָאִים. אָמַר רַבִּי יִצְחָק, זוֹרְקִים עַצְמָם לַיָּם הַגָּדוֹל, וְטוֹבְעִים וּמֵתִים. זֶהוּ שֶׁכָּתוּב הָרְפָאִים יְחוֹלָלוּ מִתַּחַת מַיִם וְשֹׁכְנֵיהֶם.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, אִלְמָלֵא הָיוּ נִכְנָסִים יִשְׂרָאֵל לָאָרֶץ בְּסִימַן (באמנות) לָשׁוֹן הָרָע, לֹא הָיָה הָעוֹלָם עוֹמֵד אֲפִלּוּ רֶגַע אֶחָד. מִי אֻמָּן שֶׁל לָשׁוֹן הָרָע? הַנָּחָשׁ. וְסוֹד הַדָּבָר - מִשֶּׁבָּא הַנָּחָשׁ עַל חַוָּה הִטִּיל בָּהּ זֻהֲמָה. אָמַר רַבִּי שִׁמְעוֹן, וְעַל הַכֹּל מוֹחֵל הַקָּדוֹשׁ בָּרוּךְ הוּא, פְּרָט לְלָשׁוֹן הָרָע, מִשּׁוּם שֶׁכָּתוּב (תהלים יב) אֲשֶׁר אָמְרוּ לִלְשֹׁנֵנוּ נַגְבִּיר שְׂפָתֵינוּ אִתָּנוּ מִי אָדוֹן לָנוּ.</p>\n<p>בֹּא וּרְאֵה כַּמָּה עָשָׂה אוֹתוֹ לָשׁוֹן הָרָע; גָּזַר עַל אֲבוֹתֵינוּ שֶׁלֹּא יִכָּנְסוּ לָאָרֶץ, וּמֵתוּ אֵלֶּה שֶׁאָמְרוּ, וְנִגְזְרָה בְכִיָּה לְדוֹרֵי דוֹרוֹת. (כל שכן כאן שהוציא לשון הרע על הכל) כִּבְיָכוֹל כֵּיוָן שֶׁהוֹצִיאוּ עַל הָאָרֶץ הַקְּדוֹשָׁה, כְּאִלּוּ הוֹצִיאוּ עָלָיו. בִּגְלַל זֶה קִנֵּא הַקָּדוֹשׁ בָּרוּךְ הוּא עַל זֶה, (כלומר קנא לשמו) וְעָמְדוּ יִשְׂרָאֵל כֻּלָּם לְהִשָּׁמֵד מֵהָעוֹלָם אִלְמָלֵא תְפִלַּת מֹשֶׁה.</p>\n<p>וַיְסַפְּרוּ לוֹ וַיֹּאמְרוּ וְגוּ'. אָמַר רַבִּי חִיָּיא, מַה שּׁוֹנֶה כָּאן וַיְסַפְּרוּ, וְלֹא כָתוּב וַיַּגִּידוּ אוֹ וַיֹּאמְרוּ? אֶלָּא כָּל אֶחָד מְלַמֵּד דָּבָר לְבַדּוֹ. וַיַּגִּידוּ - בְּכָל מָקוֹם רֶמֶז הוּא רוֹמֵז בְּחָכְמָה, וַהֲרֵי נִתְבָּאֵר. וַיֹּאמֶר - אֲמִירָה בְּעָלְמָא. וַיֹּאמְרוּ - הִרְהוּר הַלֵּב. וַיֹּאמְרוּ - פְּקֻדָּה. וַהֲרֵי בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת. וַיְסַפְּרוּ - פֵּרוּשׁ הַדָּבָר בְּכָל מָקוֹם.</p>\n<p>בָּאנוּ אֶל הָאָרֶץ. הָלַכְנוּ הָיָה צָרִיךְ לוֹ לִהְיוֹת! אֶלָּא בָּאנוּ, נִכְנַסְנוּ לְשָׁם לְאוֹתָהּ אֶרֶץ שֶׁהָיִיתָ מְשַׁבְּחָהּ בְּכָל יוֹם וְהָיִיתָ אוֹמֵר שֶׁאֵין כְּמוֹתָהּ, וְגַם זָבַת חָלָב וּדְבַשׁ הִיא. רַבִּי יִצְחָק אָמַר, מִי שֶׁרוֹצֶה לוֹמַר כָּזָב, אוֹמֵר דְּבַר אֱמֶת בַּהַתְחָלָה, כְּדֵי שֶׁיַּאֲמִינוּ לוֹ כְּזָבָיו.</p>\n<p>רַבִּי חִיָּיא אָמַר, (אלא) כָּךְ אָמְרוּ: נִכְנַסְנוּ לְאוֹתָהּ אֶרֶץ שֶׁהָיִיתָ מְשַׁבְּחָהּ כָּל יוֹם וְאָמַרְתָּ שֶׁאֵין כָּמוֹהָ, (וגם זבת חלב ודבש היא), וְהֵרַמְתָּ שִׁבְחָהּ עַל הַכֹּל - וְלֹא כָּךְ, שֶׁהֲרֵי זֶה פִּרְיָהּ, אֶשְׁכּוֹל אֶחָד מֵאוֹתָם קְטַנִּים קָטְפוּ. אָמְרוּ: אִם לָזֶה הוֹרִישׁ הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל וְסָבְלוּ כָּל אוֹתָן צָרוֹת וַעֲיֵפוּת, הֲרֵי בְּאֶרֶץ מִצְרַיִם יֵשׁ אֶשְׁכּוֹלוֹת וּפֵרוֹת הָאָרֶץ יוֹתֵר, עַל אֶחָד שְׁנַיִם.</p>\n<p>אֶפֶס כִּי עַז הָעָם. דֶּרֶךְ הָעוֹלָם שֶׁאוֹתָם גִּבּוֹרִים עוֹרְכֵי הַקְּרָב יוֹשְׁבִים בַּחוּץ לִשְׁמֹר הַדְּרָכִים, וְכָאן אֲפִלּוּ אוֹתָם בְּנֵי הָעִיר תַּקִּיפִים גִּבּוֹרִים. וְהֶעָרִים בְּצֻרוֹת, שֶׁאֲפִלּוּ כָּל מַלְכֵי הָעוֹלָם יִתְכַּנְּסוּ עֲלֵיהֶם, לֹא יַעֲשׂוּ בָהֶם פְּגָם. אָמַר רַבִּי יוֹסֵי, כָּל מַה שֶּׁאָמְרוּ, בְּלָשׁוֹן הָרָע אָמְרוּ, וְהַקָּשֶׁה מֵהַכֹּל - שֶׁכָּתוּב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב. לְבֶן אָדָם שֶׁנְּשָׁכוֹ נָחָשׁ, כְּשֶׁרוֹצִים לְהַפְחִיד אוֹתוֹ, אוֹמְרִים: הִנֵּה נָחָשׁ כָּאן.</p>\n<p>רַבִּי אַבָּא אָמַר, וַדַּאי זֶה קָשֶׁה מִכָּל מַה שֶּׁאָמְרוּ, כְּלוֹמַר, אוֹתוֹ שֶׁעוֹרֵךְ קְרָב בַּכֹּל הֲרֵי כָּאן זָמִין. וּבְאֵיזֶה מָקוֹם? בְּאֶרֶץ הַנֶּגֶב, שֶׁהֲרֵי הוּא הַמָּקוֹם לְהִכָּנֵס בּוֹ. מִיָּד - וַתִּשָּׂא כָּל הָעֵדָה וַיִּתְּנוּ אֶת קוֹלָם. קָבְעוּ בְכִיָּה לְדוֹרוֹת, לְעוֹלָמִים, בְּאוֹתוֹ לַיְלָה.</p>\n<p>אָמַר רַבִּי יוֹסֵי, עֵצָה לָקְחוּ עַל הַכֹּל לְהוֹצִיא שֵׁם רַע. מַה זֶּה עַל הַכֹּל? עַל הָאָרֶץ וְעַל הַקָּדוֹשׁ בָּרוּךְ הוּא. אָמַר רַבִּי יִצְחָק, עַל הָאָרֶץ בְּסֵדֶר, עַל הַקָּדוֹשׁ בָּרוּךְ הוּא מִנַּיִן? אָמַר לוֹ, מִמַּשְׁמָע שֶׁכָּתוּב אֶפֶס כִּי עַז הָעָם. מִי יָכוֹל לָהֶם? כִּי עַז הָעָם דַּוְקָא. וְכָתוּב עֲמָלֵק יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, וְאָז גָּרְמוּ כָּל זֶה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִידָם מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגוֹ'.</p>\n<p>וְעַתָּה יִגְדַּל נָא כֹּחַ ה'. רַבִּי אָחָא וְרַבִּי יוֹסֵי אָמְרוּ, אַשְׁרֵיהֶם יִשְׂרָאֵל מֵעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם וְהִתְכַּנָּה בָהֶם וְהִתְפָּאֵר בָּהֶם, שֶׁהֲרֵי הָעוֹלָם לֹא נִבְרָא אֶלָּא בִּשְׁבִיל יִשְׂרָאֵל שֶׁיִּשְׁתַּדְּלוּ בַתּוֹרָה, מִשּׁוּם שֶׁאֶחָד בְּאֶחָד הִתְקַשְּׁרוּ, וְיִשְׂרָאֵל לְמַטָּה בָּעוֹלָם הַזֶּה הֵם קִיּוּמוֹ, וְקִיּוּם שֶׁל כָּל שְׁאָר הָעַמִּים. אֵימָתַי? בִּזְמַן שֶׁעוֹשִׂים רְצוֹן רִבּוֹנָם.</p>"],[9522012335,"<p>בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אָדָם בָּעוֹלָם, הִתְקִינוֹ כְּדֻגְמָה עֶלְיוֹנָה (מכבדת), וְנָתַן לוֹ כֹּחוֹ וְתָקְפּוֹ בְּאֶמְצַע הַגּוּף, שֶׁשָּׁם שׁוֹרֶה הַלֵּב, שֶׁהוּא חֹזֶק (ומזון) כָּל הַגּוּף וּמִשָּׁם נִזּוֹן כָּל הַגּוּף. (וכל אותם איברים שבגוף משם נזונו) וַהֲרֵי הַלֵּב אָחוּז וּמִתְחַזֵּק בְּמָקוֹם עֶלְיוֹן שֶׁלְּמַעְלָה (ואחוזבו), שֶׁהוּא מֹחַ הָרֹאשׁ שֶׁשּׁוֹרֶה לְמַעְלָה, וְזֶה נִקְשָׁר בָּזֶה.</p>\n<p>וּבְצוּרָה זוֹ הִתְקִין הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם וְעָשָׂה (אותו) גוּף אֶחָד, וְהִתְקִין אֵיבְרֵי הַגּוּף סְבִיב הַלֵּב, וְהַלֵּב שׁוֹרֶה בְּאֶמְצַע כָּל הַגּוּף. וְכָל אוֹתָם אֵיבָרִים נִזּוֹנִים מֵאוֹתוֹ לֵב, שֶׁהוּא חֹזֶק הַכֹּל, וְהַכֹּל בּוֹ תְּלוּיִים. וְאוֹתוֹ לֵב נִקְשָׁר וְנֶאֱחָז בַּמֹּחַ הָעֶלְיוֹן שֶׁשּׁוֹרֶה לְמַעְלָה.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם, הִשְׁרָה (סדר) אֶת יָם הָאוֹקְיָנוֹס סְבִיב יִשּׁוּב כָּל הָעוֹלָם, וְיִשּׁוּב כָּל שִׁבְעִים הָאֻמּוֹת כֻּלָּם סְבִיב לִירוּשָׁלַיִם, וִירוּשָׁלַיִם שׁוֹרָה בְּאֶמְצַע כָּל הַיִּשּׁוּב, וְהִיא מְסוֹבֶבֶת לְהַר הַבַּיִת, וְהַר הַבַּיִת סְבִיב עֶזְרוֹת יִשְׂרָאֵל, וְאוֹתָן עֲזָרוֹת סוֹבְבוֹת לְלִשְׁכַּת הַגָּזִית, שֶׁשָּׁם יוֹשְׁבִים סַנְהֶדְרִין גְּדוֹלָה. וְשָׁנִינוּ שֶׁאֵין יְשִׁיבָה בָּעֲזָרָה, אֶלָּא לְמַלְכֵי בֵּית דָּוִד לְבַדָּם.</p>\n<p>וְלִשְׁכַּת הַגָּזִית סְבִיב הַמִּזְבֵּחַ, וְהַמִּזְבֵּחַ סְבִיב בֵּית הָאוּלָם, וְהָאוּלָם לַהֵיכָל, וְהַהֵיכָל לְבֵית קֹדֶשׁ הַקְּדָשִׁים, שֶׁשָּׁם שׁוֹרָה הַשְּׁכִינָה וְכַפֹּרֶת וּכְרוּבִים וְאָרוֹן. וְכָאן הוּא הַלֵּב שֶׁל כָּל הָאָרֶץ וְהָעוֹלָם, וּמִכָּאן נִזּוֹנוּ כָּל אוֹתָם מְקוֹמוֹת הַיִּשּׁוּב, שֶׁהֵם אֵיבְרֵי הַגּוּף. וְלֵב זֶה נִזּוֹן מִמֹּחַ הָרֹאשׁ וְנֶאֱחָז זֶה בָּזֶה. זֶהוּ שֶׁכָּתוּב (שמות טו) מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. כְּמוֹ זֶה לְמַעְלָה לְמַעְלָה, וְהוּא בְסוֹד הַמֶּלֶךְ הָעֶלְיוֹן, בְּסוֹד נִכְבָּד נִסְתָּר.</p>\n<p>הַיָּם הָעֶלְיוֹן כְּנֶגֶד זֶה. שֶׁיֵּשׁ יָם לְמַעְלָה מִן הַיָּם, וְיָם מִן יָם. בֹּא וּרְאֵה, נְהַר דִּינוּר סוֹבֵב לְכַמָּה מֶרְכָּבוֹת. כְּנֶגְדּוֹ שִׁבְעִים צְדָדִים חֲקוּקִים מִשֶּׁבַע דְּלֵקוֹת, וְהֵם סוֹבְבִים לְאוֹתָם שַׁמָּשִׁים שֶׁלְּתוֹכָם. וְאֵלֶּה סוֹבְבִים לְאַרְבַּע מֶרְכָּבוֹת, וְאֵלּוּ סוֹבְבִים לְאוֹתָהּ עִיר קְדוֹשָׁה שֶׁרוֹבֶצֶת עֲלֵיהֶם.</p>\n<p>וְלָמַדְנוּ, שָׁם עֲזָרוֹת לִפְנִים מֵעֲזָרוֹת. וְאֵין יְשִׁיבָה בָּעֲזָרָה שֶׁל שָׁם, אֶלָּא לְמַלְכֵי בֵּית דָּוִד לְבַדָּם, וְשָׁם נִמְצָאִים וְיוֹשְׁבִים. וְסַנְהֶדְרִין גְּדוֹלָה נִמְצָאִים שָׁם בְּלִשְׁכַּת הַגָּזִית, וְאוֹתוֹ בֵּית דִּין עֲלֵיהֶם, שֶׁמְּשַׁמֵּשׁ לְמָקוֹם שֶׁמְּשַׁמֵּשׁ. וְהַדִּין נִתָּן מִשָּׁם לִקְדוֹשִׁים עֶלְיוֹנִים, עַד שֶׁמַּגִּיעַ לַמָּקוֹם שֶׁנִּקְרָא קֹדֶשׁ הַקְּדָשִׁים שֶׁבּוֹ הַכֹּל, וְשָׁם הַלֵּב שׁוֹרֶה, וְזֶה נִזּוֹן מִמֹּחַ הָעֶלְיוֹן, וְנֶאֱחָז זֶה בָּזֶה.</p>\n<p>כְּמוֹ זֶה לְמַעְלָה לְמַעְלָה, וְהוּא בְּסוֹד מֶלֶךְ הָעֶלְיוֹן, בְּסוֹד נִכְבָּד סָתוּם, עַד שֶׁנִּמְצָא, שֶׁהַכֹּל נִזּוֹן מִמֹּחַ עֶלְיוֹן סָתוּם שֶׁל הַכֹּל. וּכְשֶׁיִּסְתַּכְּלוּ עַל הַדְּבָרִים, הַכֹּל נִקְשָׁר זֶה בָּזֶה וְזֶה בָזֶה.</p>\n<p>בֹּא וּרְאֵה, כְּשֶׁמֵּאִיר הָעַתִּיק הַסָּתוּם בַּמֹּחַ, וְהַמֹּחַ מֵאִיר לַלֵּב, בְּדֶרֶךְ נֹעַם ה'. וַהֲרֵי בֵּאַרְנוּ, וְזֶהוּ כֹּחַ ה'. אוֹתוֹ כֹּחַ שֶׁבָּא מֵהָעַתִּיק הַקָּדוֹשׁ, סְתוּם כָּל הַסְּתוּמִים, יִגְדַּל נָא, שֶׁיִּתְרַבֶּה וְיִגְדַּל לְמַעְלָה לְמַעְלָה וְיֻשְׁפַּע וְיִמָּשֵׁךְ לְמַטָּה. כַּאֲשֶׁר דִּבַּרְתָּ, כְּמוֹ שֶׁפֵּרְשׁוּהָ. לֵאמֹר, לְלַמֵּד מִכָּאן לְכָל הַדּוֹרוֹת הָאַחֲרוֹנִים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. לֵאמֹר, לוֹמַר לָזֶה בִּשְׁעַת צָרָה, לוֹמַר זֶה בִּשְׁעַת רְוָחָה. וּמַה הוּא? ה' אֶרֶךְ אַפַּיִם וְגוֹ', וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים.</p>\n<p>אָמַר רַבִּי יִצְחָק, אֱמֶת לָמָּה עוֹלֶה מִכָּאן? אָמַר רַבִּי חִיָּיא, הֵם גָּרְמוּ שֶׁעָלָה מִכָּאן, שֶׁהֲרֵי בְּשֶׁקֶר דִּבְּרוּ עַצְמָם. בְּאוֹתָהּ מִדָּה שֶׁאָדָם מוֹדֵד, בָּהּ מוֹדְדִים לוֹ. וְכֵן שְׁאָר הָאֲחֵרִים הִסְתַּלְּקוּ, שֶׁלֹּא יָכֹל מֹשֶׁה לְאָמְרָם, מִשּׁוּם שֶׁהֵם גָּרְמוּ. סָלַחְתִּי כִּדְבָרֶךְ, כִּדְבָרֶךְ מַמָּשׁ, וַהֲרֵי הִתְעוֹרְרוּ הַחֲבֵרִים, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522012336,"<p>זְהִ עִם זֶה, מַה שֶּׁלֹּא יָכְלוּ לְדַבֵּר מִקֹּדֶם זֶה. יָצְאוּ מֵאוֹתוֹ פֶּתַח, וְיָשְׁבוּ בְגִנָּה תַּחַת אִילָנוֹת. אָמְרוּ זֶה לָזֶה, כֵּיוָן שֶׁאָנוּ כָאן וְרָאִינוּ כָּל זֶה, אִם נָמוּת כָּאן, וַדַּאי נִכָּנֵס לָעוֹלָם הַבָּא. יָשְׁבוּ. שֵׁנָה נָפְלָה עֲלֵיהֶם וְנִרְדְּמוּ. בֵּין כָּךְ בָּא אוֹתוֹ מְמֻנֶּה וֶהֱעִירָם. אָמַר לָהֶם, קוּמוּ צְאוּ לְתוֹךְ פַּרְדֵּס שֶׁבַּחוּץ. יָצְאוּ. רָאוּ אוֹתָם בַּעֲלֵי מִקְרָא שֶׁהָיו אוֹמְרִים בְּאוֹתוֹ פָּסוּק, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ - הֲרֵי בְּמָקוֹם אַחֵר לֹא. וְשָׁם יָמֻתוּ - הֲרֵי בְּמָקוֹם אַחֵר לֹא. וְזֶה בַגּוּפִים, אֲבָל בַּנְּשָׁמוֹת לֹא כְּמוֹ בְּנֵי הַגָּן.</p>\n<p>אָמַר לָהֶם אוֹתוֹ מְמֻנֶּה, צְאוּ. יָצְאוּ עִמּוֹ. אָמַר לָהֶם, שְׁמַעְתֶּם דָּבָר לְתוֹךְ אוֹתָהּ דַּרְגָּה? אָמְרוּ, שָׁמַעְנוּ, שֶׁהֲרֵי קוֹל אֶחָד הָיָה אוֹמֵר: מִי שֶׁפָּסַק - יִפָּסֵק, וּמִי שֶׁקִּצֵּר - יִתְקַצֵּר. מִי שֶׁקִּצֵּר - יִתְאָרֵךְ. אָמַר לָהֶם, יְדַעְתֶּם מַה זֶּה? אָמְרוּ, לֹא. אָמַר לָהֶם, רְאִיתֶם אוֹתוֹ נֶשֶׁר גָּדוֹל וְאוֹתוֹ תִּינוֹק שֶׁמְּלַקֵּט עֲשָׂבִים? זֶה הָיָה רַבִּי אִילָאִי מִנְּצִיבִין, הוּא וּבְנוֹ, וְהִגִּיעַ לְכָאן, וְרָאָה הוּא וּבְנוֹ הַתִּינוֹק מְעָרָה זוֹ. כֵּיוָן שֶׁנִּכְנְסוּ לְתוֹךְ הַחֹשֶׁךְ, לֹא יָכְלוּ לִסְבֹּל, וּמֵתוּ.</p>\n<p>וְאוֹתוֹ תִּינוֹק בְּנוֹ עוֹמֵד כָּל יוֹם לִפְנֵי בְצַלְאֵל בְּשָׁעָה שֶׁיּוֹרֵד מֵהַיְשִׁיבָה הָעֶלְיוֹנָה, וְאוֹמֵר לְפָנָיו שְׁלֹשָׁה דְבָרִים, עַד שֶׁלֹּא יִפְתַּח בְּצַלְאֵל בְּסוֹדוֹת סְתוּמִים שֶׁל הַחָכְמָה, שֶׁכָּל דְּבָרָיו סוֹדוֹת סְתוּמִים הֵם, (ישעיה סד) שֶׁעַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ. (מי) זֶה שֶׁאָמַר מִי שֶׁפָּסַק יִפָּסֵק. מִי שֶׁפּוֹסֵק דִּבְרֵי תוֹרָה עַל דְּבָרִים בְּטֵלִים, יִפָּסְקוּ חַיָּיו מֵהָעוֹלָם הַזֶּה, וְדִינוֹ עוֹמֵד בְּאוֹתוֹ עוֹלָם. מִי שֶׁקִּצֵּר יִתְקַצֵּר - מִי שֶׁקִּצֵּר אָמֵן וְלֹא מַאֲרִיךְ בּוֹ תּוֹךְ מְנוּחָה, יִתְקַצֵּר מֵחַיֵּי הָעוֹלָם הַזֶּה. מִי שֶׁקִּצֵּר יִתְאָרֵךְ - מִי שֶׁאוֹמֵר אֶחָד, צָרִיךְ לַחְטֹף אָלֶ\"ף וּלְקַצֵּר קְרִיאָתָהּ, וְלֹא יְעַכֵּב בָּאוֹת הַזֹּאת כְּלָל. מִי שֶׁעָשָׂה כֵּן, יִתְאָרְכוּ חַיָּיו.</p>\n<p>אָמְרוּ לוֹ, עוֹד אָמַר, שְׁנַיִם הֵם, וְאֶחָד הִשְׁתַּתֵּף בָּהֶם, וְהֵם שְׁלֹשָׁה. וּכְשֶׁהָיוּ שְׁלֹשָׁה, הֵם אֶחָד. אָמַר לָהֶם, אֵלֶּה שְׁנֵי שֵׁמוֹת שֶׁל שְׁמַע יִשְׂרָאֵל, שֶׁהֵם ה' ה'. אֱלֹהֵינוּ הִשְׁתַּתֵּף בָּהֶם, וְהוּא חוֹתַם הַטַּבַּעַת, אֱמֶת. וּכְשֶׁמִּתְחַבְּרִים כְּאֶחָד, הֵם אֶחָד בְּיִחוּד אֶחָד.</p>\n<p>עוֹד אָמַר, שְׁנַיִם הֵם, וְאֶחָד חָזַר. כְּשֶׁשּׁוֹלֵט, טָס עַל כַּנְפֵי הָרוּחַ וְשָׁט בְּמָאתַיִם אֶלֶף, וְנִסְתָּר. אָמַר לָהֶם, אֵלּוּ שְׁנֵי כְרוּבִים שֶׁהָיָה רוֹכֵב בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא. וּמִיּוֹם שֶׁנִּגְנַז יוֹסֵף מֵאֶחָיו, נִגְנַז הוּא (אחד), וְנִשְׁאַר אֶחָד אֵצֶל בִּנְיָמִין. זֶהוּ שֶׁכָּתוּב (תהלים יח) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף וַיֵּדֶא עַל כַּנְפֵי רוּחַ. וְנִגְנַז בְּמָאתַיִם אֶלֶף עוֹלָמוֹת, וְנִסְתַּר אוֹתוֹ שֶׁרוֹכֵב עָלָיו, שֶׁהֵם מָאתַיִם אֶלֶף גְּנָזִים, הֵם שֶׁלּוֹ בָּרוּךְ הוּא.</p>\n<p>צְאוּ מִכָּאן, אַשְׁרֵיכֶם. יָצְאוּ. נָתַן לָהֶם אוֹתוֹ מְמֻנֶּה שׁוֹשַׁנָּה (אחרת) אַחַת וְיָצְאוּ. כְּשֶׁיָּצְאוּ, נִסְתַּם פִּי הַמְּעָרָה וְלֹא נִרְאָה כְּלָל. רָאוּ אוֹתוֹ נֶשֶׁר שֶׁהָיָה יוֹרֵד מֵאוֹתוֹ עֵץ וְנִכְנַס לִמְעָרָה אַחֶרֶת. הֵרִיחוּ הֵם בְּאוֹתָהּ שׁוֹשַׁנָּה וְנִכְנְסוּ לְשָׁם, מָצְאוּ אוֹתוֹ נֶשֶׁר עַל פִּי הַמְּעָרָה. אָמַר לָהֶם, הִכָּנְסוּ צַדִּיקֵי אֱמֶת חֲבֵרִים, שֶׁהֲרֵי לֹא רָאִיתִי שִׂמְחַת הַחַבְרוּתָא מִיּוֹם שֶׁאֲנִי כָּאן, אֶלָּא בָכֶם.</p>\n<p>נִכְנְסוּ, הִגִּיעוּ לְפַרְדֵּס אַחֵר, וְאוֹתוֹ נֶשֶׁר עִמָּהֶם. כְּשֶׁהִגִּיעוּ לְאוֹתָם בַּעֲלֵי מִשְׁנָה, חָזַר אוֹתוֹ נֶשֶׁר בִּדְמוּת אָדָם בִּלְבוּשׁ נִכְבָּד מֵאִיר כְּמוֹתָם, וְיָשַׁב אִתָּם כְּאֶחָד. אָמַר לְאוֹתָם שֶׁיּוֹשְׁבִים, תְּנוּ כָבוֹד לְבַעֲלֵי הַמִּשְׁנָה שֶׁבָּאוּ לְכָאן, שֶׁהֲרֵי רִבּוֹנָם הֶרְאָה לָהֶם נִפְלָאוֹת גְּדוֹלוֹת כָּאן. אָמַר אֶחָד מֵהֶם, יֵשׁ בָּכֶם סִימָן? אָמְרוּ, הֵן. הוֹצִיאוּ שְׁנֵי שׁוֹשַׁנִּים וְהֵרִיחוּ בָהֶם. אָמְרוּ, שְׁבוּ בַּעֲלֵי הַיְשִׁיבָה, שְׁבוּ צַדִּיקֵי אֱמֶת. אָחֲזוּ בָהֶם וְיָשְׁבוּ. בְּאוֹתָהּ שָׁעָה לָמְדוּ שָׁם שְׁלֹשִׁים הֲלָכוֹת שֶׁלֹּא יָדְעוּ מִקֹּדֶם, וְסוֹדוֹת תּוֹרָה אֲחֵרִים.</p>\n<p>חָזְרוּ לִפְנֵי אוֹתָם בַּעֲלֵי מִקְרָא, וּמָצְאוּ שֶׁהָיוּ אוֹמְרִים, (שם פב) אֲנִי אָמַרְתִּי אֱלֹהִים אַתֶּם וּבְנֵי עֶלְיוֹן כֻּלְּכֶם. אֲנִי אָמַרְתִּי, בְּשָׁעָה שֶׁהִקְדַּמְתֶּם עֲשִׂיָּה לַשְּׁמִיעָה, שֶׁהֲרֵי אֱלֹהִים אַתֶּם וְגוֹ'. כֵּיוָן שֶׁנִּמְשַׁכְתֶּם אַחַר יֵצֶר הָרָע - אָכֵן כְּאָדָם תְּמוּתוּן וְגוֹ'. מַה מִּיתָתוֹ שֶׁל אָדָם מוֹרִידָתוֹ לֶעָפָר כְּדֵי שֶׁיִּמָּחֶה אוֹתוֹ יֵצֶר הָרָע שֶׁבְּתוֹכוֹ, וְאוֹתוֹ יֵצֶר הָרָע הוּא שֶׁמֵּת וְנִתְעַכֵּל בְּתוֹכוֹ.</p>\n<p>אָמַר אוֹתוֹ זָקֵן שֶׁעֲלֵיהֶם, גַּם כָּךְ כָּתוּב, וּפִגְרֵיכֶם אַתֶּם יִפְּלוּ בַּמִּדְבָּר הַזֶּה. מַה זֶּה פִּגְרֵיכֶם? זֶה יֵצֶר הָרָע, כּוֹלֵל זָכָר וּנְקֵבָה. חֶסְרוֹנוֹת שֶׁיֵּשׁ בָּכֶם, שֶׁיֵּצֶר הָרָע יוֹרֵד תָּמִיד לְחִסָּרוֹן, וְלֹא עוֹלֶה. בַּקֹּדֶשׁ מַעֲלִים וְלֹא מוֹרִידִים. בַּטֻּמְאָה מוֹרִידִים תָּמִיד וְלֹא מַעֲלִים. וְעַל זֶה נִקְרְאוּ פִגְרֵיכֶם, חֶסְרוֹנוֹתֵיכֶם, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ל) אֲשֶׁר פִּגְּרוּ מֵעֲבֹר אֶת (ה) נַּחַל וְגוֹ'. סוֹף הַפָּסוּק מוֹכִיחַ, שֶׁכָּתוּב יִפְּלוּ, וְלֹא תִפְּלוּ. וְעַל כָּךְ, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ אוֹתָם פְּגָרִים וְשָׁם יָמוּתוּ, מִשּׁוּם שֶׁרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁמִיד אוֹתָם פְּגָרִים מֵהָעוֹלָם לְעוֹלָם.</p>\n<p>אָמַר לָהֶם רַבִּי אִילָאִי, צַדִּיקֵי אֱמֶת, הִכָּנְסוּ וּרְאוּ, שֶׁהֲרֵי רְשׁוּת נִמְסְרָה לָכֶם לְהִכָּנֵס עַד אוֹתוֹ מָקוֹם שֶׁפָּרֹכֶת פְּרוּסָה. אַשְׁרֵי חֶלְקְכֶם. קָמוּ וְנִכְנְסוּ לְתוֹךְ מָקוֹם אֶחָד, וְהָיוּ שָׁם בַּעֲלֵי אַגָּדָה, וּפְנֵיהֶם מְאִירִים כְּאוֹר הַשֶּׁמֶשׁ. אָמְרוּ, מִי אֵלֶּה? אָמַר לָהֶם, אֵלֶּה בַּעֲלֵי אַגָּדָה, וְרוֹאִים בְּכָל יוֹם אוֹר הַתּוֹרָה כָּרָאוּי. עָמְדוּ וְשָׁמְעוּ כַּמָּה דְבָרִים חֲדָשִׁים בַּתּוֹרָה, וְלֹא נִתְּנָה לָהֶם רְשׁוּת לְהִכָּנֵס לְתוֹכָם.</p>\n<p>אָמַר לָהֶם רַבִּי אִילָאִי, הִכָּנְסוּ לְמָקוֹם אַחֵר וְתִרְאוּ. נִכְנְסוּ לְתוֹךְ גִּנָּה אַחֶרֶת, וְרָאוּ גַם כָּךְ כּוֹרִים קְבָרִים, וּמִיָּד מֵתִים, וְחוֹזְרִים חַיִּים בְּגוּפוֹת מְאִירִים קְדוֹשִׁים. אָמְרוּ לוֹ, מַה זֶּה? אָמַר לָהֶם, זֶה עוֹשִׂים בְּכָל יוֹם, וּמִיָּד שֶׁשּׁוֹכְבִים, מִתְעַכֶּלֶת אוֹתָהּ זֻהֲמָה רָעָה שֶׁקִּבְּלוּ בַתְּחִלָּה, וְעוֹמְדִים מִיָּד בְּגוּפִים חֲדָשִׁים מְאִירִים, בְּאוֹתָם גּוּפִים קְדוֹשִׁים שֶׁעָמְדוּ עַל הַר סִינַי, כְּמוֹ שֶׁאַתֶּם רוֹאִים, עָמְדוּ כֻלָּם עַל הַר סִינַי בְּגוּפִים לְלֹא לִכְלוּךְ כְּלָל. כֵּיוָן שֶׁהִמְשִׁיכוּ עֲלֵיהֶם יֵצֶר הָרָע, חָזְרוּ בְגוּפִים אֲחֵרִים שֶׁל גּוּפִים רִאשׁוֹנִים, גּוּפִים נָכְרִיִּים, זֶהוּ שֶׁכָּתוּב (שמות לג) וַיִּתְנַצְּלוּ בְנֵי יִשְׂרָאֵל אֶת עֶדְיָם מֵהַר חוֹרֵב.</p>\n<p>קוֹל הִתְעוֹרֵר: לְכוּ הִתְכַּנְּסוּ, הֲרֵי אָהֳלִיאָב עוֹמֵד עַל עָמְדוֹ, וְכָל אוֹתָן קָתֶדְרָאוֹת עִמּוֹ. לְשָׁעָה פָּרְחוּ כֻלָּם וְלֹא רָאוּ דָבָר. נִשְׁאֲרוּ לְבַד תַּחַת אִילָנוֹת הַגִּנָּה. רָאוּ פֶּתַח אַחֵר, נִכְנְסוּ לְשָׁם, רָאוּ הֵיכָל אֶחָד, נִכְנְסוּ וְיָשְׁבוּ שָׁם. שְׁנֵי עֲלָמִים הָיוּ שָׁם. הֵרִימוּ עֵינַיִם, וְרָאוּ מִשְׁכָּן אֶחָד מְרֻקָּם בְּכָל מִינֵי צִיּוּרִים וּגְוָנִים שֶׁל הָעוֹלָם, וְעָלָיו פְּרוּסָה פְּרִיסַת אוֹר נוֹצֶצֶת שֶׁלֹּא יְכוֹלוֹת הָעֵינַיִם לְהִסְתַּכֵּל. (וכפי שני מילין ראו תוך אותו המשכן עד מקום פריסת הפרכת שלא ראו) מִשָּׁם וָהָלְאָה לֹא רָאוּ כְלוּם.</p>\n<p>הִרְכִּינוּ אָזְנַיִם, וְשָׁמְעוּ קוֹל אֶחָד שֶׁהָיָה אוֹמֵר: בְּצַלְאֵל רְבִיעִי הוּא לְאוֹרוֹת עֶלְיוֹנִים. יוֹסֵף רְבִיעִי הוּא תּוֹךְ אוֹרוֹת אָדָם הָרִאשׁוֹן. עֲלִיָּה שֶׁל מַעְלָה חֲבִיבַת הַכֹּל, עָלֶיהָ כָּתוּב (במדבר כח) וְנִסְכּוֹ רְבִיעִית הַהִין בַּקֹּדֶשׁ וְגוֹ'. מִי שֶׁיִּסְתַּכֵּל וְיִרְאֶה, יִסָּמְאוּ עֵינָיו. מִי שֶׁלֹּא יִסְתַּכֵּל, יִרְאֶה וְיִפָּתְחוּ עֵינָיו. עֵץ שֶׁל שְׁמֹנֶה עֶשְׂרֵה, כְּשֶׁמִּתְכּוֹפֵף, יִזְקֹף וְיַעֲמֹד. אִם לֹא מִתְכּוֹפֵף, נָחָשׁ רַע יֹאכַל אוֹתוֹ. מִי שֶׁמַּכְנִיס שְׁנֵי כְרוּבִים לִפְנִים, רְצוֹנוֹ יֵעָשֶׂה. מִי שֶׁמְּעַיֵּן רָחוֹק מֵרְצוֹנוֹ, קָרְבַּן הַתִּינוֹק שָׁלֵם לְהִתְקַבֵּל. פָּסַק אוֹתוֹ הַקּוֹל.</p>\n<p>אָמְרוּ אוֹתָם שְׁנֵי עֲלָמִים, סִימָן יֵשׁ בָּכֶם? אָמְרוּ, הֵן. הוֹצִיאוּ שְׁנֵי שׁוֹשַׁנִּים וְהֵרִיחוּ בָהֶם. אָמְרוּ, שְׁבוּ עַד שֶׁתִּשְׁמְעוּ שְׁנֵי דְבָרִים בְּסוֹדוֹת עַתִּיקִים מִתּוֹךְ רָאשֵׁי הַיְשִׁיבָה, וְיִהְיוּ תָמִיד בְּסוֹד בְּתוֹכֲכֶם. אָמְרוּ, הֵן.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כָּל הַדְּבָרִים הַלָּלוּ וְכָל מַה שֶּׁרָאוּ, כָּתְבוּ. וּכְשֶׁהִגִּיעוּ לְכָאן, הָיָה כָּתוּב (תהלים לט) אֶשְׁמְרָה דְרָכַי מֵחֲטוֹא בִלְשׁוֹנִי. וַאֲנִי שָׁאַלְתִּי לַאֲבִי אַבָּא, כַּמָּה הָיוּ אוֹתָם שְׁנֵי דְבָרִים? וְאָמַר לִי, חַיֶּיךְ בְּנִי, אוֹתָם שְׁנֵי דְבָרִים בָּנוּ עוֹלָמוֹת וְהֶחֱרִיבוּ עוֹלָמוֹת מִי שֶׁהִשְׁתַּמֵּשׁ בָּהֶם.</p>\n<p>כֵּיוָן שֶׁשָּׁמְעוּ שְׁנֵי דְבָרִים אֵלּוּ, אָמְרוּ אוֹתָם תִּינוֹקוֹת, צְאוּ צְאוּ! אֵין לָכֶם רְשׁוּת יוֹתֵר לִשְׁמֹעַ! הוֹצִיא אֶחָד מֵהֶם תַּפּוּחַ אֶחָד, וְנָתַן לָהֶם וְאָמַר, הָרִיחוּ בָזֶה, הָרִיחוּ בוֹ. וְיָצְאוּ, וּמִכָּל מַה שֶּׁרָאוּ לֹא שָׁכְחוּ כְלוּם. יָצְאוּ.</p>\n<p>הֲרֵי מְמֻנֶּה אַחֵר בָּא וְאָמַר לָהֶם, חֲבֵרִים, רַבִּי אִילָאִי שְׁלָחַנִי אֲלֵיכֶם, חַכּוּ לִי כָּאן עַל פִּי הַמְּעָרָה, וְהוּא יָבֹא וְיוֹדִיעַ לָכֶם דְּבָרִים עֶלְיוֹנִים שֶׁלֹּא יְדַעְתֶּם. שֶׁהוּא תָּבַע מִתּוֹךְ הַיְשִׁיבָה שֶׁיִּהְיֶה לוֹ רְשׁוּת לְגַלּוֹת לָכֶם דְּבָרִים. יָצְאוּ אִתּוֹ וְחִכּוּ עַל פִּי הַמְּעָרָה, וְהָיוּ מַחֲזִירִים דְּבָרִים זֶה לָזֶה מִכָּל מַה שֶּׁרָאוּ וְלָמְדוּ שָׁם.</p>\n<p>בֵּין כָּךְ הֲרֵי רַבִּי אִילָאִי בָּא מֵאִיר כַּשֶּׁמֶשׁ. אָמַר לוֹ, תּוֹרָה חֲדָשָׁה שָׁמַעְתָּ? אָמַר לָהֶם, בְּוַדַּאי! וְנָתְנוּ לִי רְשׁוּת לוֹמַר לָכֶם דְּבָרִים. הִתְחַבְּרוּ כְאֶחָד עַל פִּי הַמְּעָרָה וְיָשְׁבוּ. אָמַר לָהֶם, צַדִּיקִים אַתֶּם, שֶׁרִבּוֹנְכֶם הֶרְאָה לָכֶם כְּמוֹ הָעוֹלָם הַבָּא, וַהֲרֵי אֵין לָכֶם פַּחַד וְאֵימָה. אָמְרוּ, וַדַּאי הֲרֵי נִשְׁכַּח מֵאִתָּנוּ דֶּרֶךְ בְּנֵי אָדָם, וּתְמִיהָה הִיא עַל כָּל מַה שֶּׁרָאִינוּ בָהָר הַזֶּה.</p>\n<p>אָמַר לָהֶם, רְאִיתֶם הָרִים אֵלֶּה? כֻּלָּם רָאשֵׁי יְשִׁיבוֹת לָעָם הַזֶּה שֶׁבַּמִּדְבָּר. וְזָכוּ כָּעֵת מַה שֶּׁלֹּא זָכוּ כְּשֶׁהָיוּ בַחַיִּים. וְאֵלֶּה רָאשֵׁי יְשִׁיבוֹת, כֻּלָּם בְּרָאשֵׁי חֳדָשִׁים וְשַׁבָּתוֹת וּמוֹעֲדִים מִתְכַּנְּסִים לְהַר אַהֲרֹן הַכֹּהֵן וּמִתְעוֹרְרִים אֵלָיו, וְנִכְנָסִים לְתוֹךְ יְשִׁיבָתוֹ וּמִתְחַדְּשִׁים שָׁם בְּטֹהַר הַטַּל הַקָּדוֹשׁ שֶׁיּוֹרֵד עַל רֹאשׁוֹ, וְשֶׁמֶן מִשְׁחָה שֶׁשּׁוֹפֵעַ עָלָיו, וְעִמּוֹ מִתְחַדְּשִׁים כֻּלָּם בְּחִדּוּשִׁים אֲהוּבִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ, עַד שֶׁנִּקְרָא כָּאן יְשִׁיבַת הָאַהֲבָה.</p>\n<p>וְהוּא לוֹקֵחַ בְּכָל יְשִׁיבָה, בְּסֵתֶר דַּקִּיק מִתְעוֹפְפִים כַּנְּשָׁרִים לְתוֹךְ יְשִׁיבַת הָאוֹר, וְהִיא יְשִׁיבַת מֹשֶׁה, וְכֻלָּם עוֹמְדִים בַּחוּץ וְלֹא נִכְנָסִים פְּנִימָה, פְּרָט לְאַהֲרֹן לְבַדּוֹ, וּלְפִי שָׁעָה נִקְרָאִים בְּשֵׁם.</p>\n<p>וְאֵין מִי שֶׁיִּרְאֶה אֶת מֹשֶׁה, שֶׁהֲרֵי אוֹתוֹ מַסְוֶה שֶׁעַל פָּנָיו פָּרוּשׂ לְפָנָיו, וְשִׁבְעָה עַנְנֵי כָבוֹד סְבִיבוֹ. אַהֲרֹן עוֹמֵד תּוֹךְ הַפַּרְגּוֹד שֶׁלְּמַטָּה מִמֹּשֶׁה. וּפַרְגּוֹד פּוֹסֵק, וְלֹא פוֹסֵק בְּתוֹכָם. וְכָל רָאשֵׁי הַיְשִׁיבוֹת מִחוּץ לְפָרֹכֶת הַפַּרְגּוֹד הַזֶּה, וְכָל הַשְּׁאָר מִחוּץ לְאוֹתָם עֲנָנִים. וּכְפִי חִדּוּשֵׁי אוֹר הַתּוֹרָה שֶׁמְּאִירָה, כָּךְ מְאִירִים אוֹתָם עֲנָנִים.</p>\n<p>וְנִהְיִים קְלוּשִׁים בְּדַקִּיקוּת הָאוֹר, עַד שֶׁנִּרְאֶה אוֹתוֹ מַסְוֶה, וּמִתּוֹךְ אוֹתוֹ מַסְוֶה רוֹאִים אוֹר שֶׁמֵּאִיר יוֹתֵר מִכָּל אוֹרוֹת הָעוֹלָם, וְהֵם פְּנֵי מֹשֶׁה. פָּנָיו לֹא נִרְאִים כְּלָל, וְאֵין מִי שֶׁיִּרְאֶה אוֹתָם, פְּרָט לְאוֹתוֹ אוֹר שֶׁיּוֹצֵא מִתּוֹךְ אוֹתוֹ מַסְוֶה אַחַר כָּל אוֹתָם הָעֲנָנִים.</p>\n<p>מֹשֶׁה אָמַר דָּבָר סְתָם לְאַהֲרֹן, וְאַהֲרֹן מְפָרֵשׁ לִגְדוֹלֵי הַיְשִׁיבוֹת. בַּמֶּה מְפָרֵשׁ? בְּכָל אוֹתָם מַבּוּעִים שֶׁנִּסְתְּמוּ מִמֶּנּוּ כְּשֶׁהִגִּיעַ זְמַנּוֹ שֶׁל יְהוֹשֻׁעַ. וְכָעֵת הוּא מַחֲזִיר לָהֶם בְּכַמָּה פְלָאוֹת, וּמְקוֹרוֹת וּמַבּוּעִים וּנְחָלִים שֶׁנּוֹבְעִים מִכָּל דָּבָר וְדָבָר.</p>\n<p>כָּל נָשִׁים צִדְקָנִיּוֹת שֶׁל הַדּוֹר הַזֶּה בָּאוֹת לְמִרְיָם גַּם כָּאן בַּזְּמַנִּים הַלָּלוּ, וְאָז עוֹלוֹת כֻּלָּן כְּתִמְרוֹת עָשָׁן לְתוֹךְ הַמִּדְבָּר הַזֶּה, וְאוֹתוֹ יוֹם נִקְרָא יוֹם הַהִלּוּלָא. נָשִׁים בְּלֵילֵי שַׁבָּתוֹת וּבְלֵילֵי יָמִים טוֹבִים, כֻּלָּן בָּאוֹת לְמִרְיָם, וְיוֹדְעוֹת הִשְׁתַּדְּלוּת בַּיְדִיעָה שֶׁל רִבּוֹן הָעוֹלָם. אַשְׁרֵי דּוֹר זֶה מִכָּל דּוֹרוֹת הָעוֹלָם. יוֹצְאִים מִישִׁיבַת מֹשֶׁה, וּפוֹרְחִים לִישִׁיבַת הָרָקִיעַ, וְאֵלֶּה שֶׁנִּרְאִים פּוֹרְחִים לַיְשִׁיבָה הָעֶלְיוֹנָה. עַל אוֹתוֹ דּוֹר כָּתוּב, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו.</p>"],[9522012337,"<p>פָּתַח רַבִּי אִילָאִי וְאָמַר, (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ. מַה בֵּין תָּם לְתָמִים? בְּאַבְרָהָם כָּתוּב, (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים. יַעֲקֹב שֶׁהִשְׁתַּלֵּם יוֹתֵר, כָּתוּב בּוֹ, (שם כה) וְיַעֲקֹב אִישׁ תָּם. לָמָּה נִקְרָא אִישׁ תָּם? מִשּׁוּם שֶׁלֹּא נִשְׁאַר בּוֹ פְּסֹלֶת כְּלָל, שֶׁהֲרֵי פְּרִיעָה הָיְתָה בּוֹ.</p>\n<p>בַּמֶּה נִפְרַע (פריעה היתה בו שנפרע) וְנִטְהַר מֵאוֹתָהּ פְּסֹלֶת? מִשּׁוּם שֶׁאוֹתוֹ מָקוֹם שֶׁמְּחַזֵּק פְּסֹלֶת, שֶׁלְּתוֹךְ מְקוֹם הַפְּרִיעָה שׁוֹרֶה, הוּא שׁוֹר, דְּמוּת הַשְּׂמֹאל שֶׁל כִּסֵּא שֶׁלּוֹ. וְאוֹתוֹ שׁוֹר נִקְרָא שׁוֹר תָּם, שֶׁהֲרֵי מֶרְכֶּבֶת הַכִּסֵּא, רֹשֶׁם שֶׁל בְּרִית יֵשׁ בּוֹ. וְעַל זֶה שׁוֹר זֶה נִקְרָא תָם, וְיַעֲקֹב אָחוּז בּוֹ בְּתוֹכוֹ, וּבְשׁוֹר זֶה עוֹשִׂים פְּרִיעָה, וּמַעֲבִירִים זֻהֲמַת הַפְּסֹלֶת כֻּלָּהּ.</p>\n<p>בְּמִשְׁנַת בְּצַלְאֵל כָּתוּב, (שם ל) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל. בְּשָׂרָה כָּתוּב פְּקִידָה, וּבְרָחֵל כָּתוּב זְכִירָה. לָמָּה? מִשּׁוּם שֶׁזָּכוֹר נִרְשַׁם בְּיַעֲקֹב, שֶׁהוּא בְּרִית שָׁלֵם כְּשֶׁנַּעֲשָׂה (כשנולד) יוֹסֵף, וּבַמֶּה? כְּשֶׁנָּטַל שׁוֹר עִמּוֹ שֶׁלֹּא יִתְחַזֵּק לַצַּד הָאַחֵר, וּמִשּׁוּם זֶה נִקְרָא יוֹסֵף בְּכוֹר שׁוֹר, בְּכוֹר שֶׁל אוֹתוֹ שׁוֹר שֶׁלָּקַח יַעֲקֹב (דברים לג) בְּכוֹר שׁוֹרוֹ. וַדַּאי, וְאוֹתוֹ שׁוֹר שׁוֹר תָּם,</p>\n<p>(בראשית כה) וְיַעֲקֹב אִישׁ תָּם. רִבּוֹן וְשַׁלִּיט, בַּעַל הַבַּיִת, שֶׁאוֹתוֹ שׁוֹר תָּם שָׁרוּי בְּתוֹכוֹ. מִשּׁוּם שֶׁיֵּשׁ שׁוֹר מוּעָד בְּצַד עָרְלָה פְּרִיעָה. וְכַמָּה מְמֻנִּים עַל הַחֻקִּים יוֹצְאִים מִמֶּנּוּ עַד דַּרְגָּה אַחֲרוֹנָה שֶׁנִּקְרֵאת שְׁאִיָּ\"ה, אוֹתוֹ שֶׁמַּפִּיל בָּתֵּי הָעוֹלָם שֶׁלֹּא דָרִים בָּהֶם אֲנָשִׁים. וְכֻלָּם יוֹצְאִים מֵאוֹתוֹ שׁוֹר מוּעָד. וְזֶה בְּחִבּוּר עִם חֲמוֹר רַע. וּמִשּׁוּם זֶה (דברים כב) לֹא תַחֲרֹשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, כְּדֵי לֹא לְעוֹרֵר אוֹתָם.</p>\n<p>וּבְאוֹתָהּ יְשִׁיבַת בְּצַלְאֵל, וְכֵן בִּשְׁתֵּי יְשִׁיבוֹת, וְיַעֲקֹב אִישׁ תָּם, בַּעְלָהּ שֶׁל אוֹתוֹ תָּם. וּמִיהוּ א'? סוֹד וָ\"ו. וּכְשֶׁהָיוּ כְּלַל זָכָר וּנְקֵבָה כְּאֶחָד, אָז נוֹטֵל כָּל אוֹתִיּוֹת אֵלֶּה את\"ם, וְהוּא אֱמֶ\"ת. (מיכה ז) תִּתֵּן אֱמֶת לְיַעֲקֹב. כְּלַל זָכָר וּנְקֵבָה כְּאֶחָד, שְׁלֵמוּת הַכֹּל.</p>\n<p>אַבְרָהָם לֹא הִצְטַוָּה עַל פְּרִיעָה, וּכְשֶׁנִּכְנַס, נִכְנַס לְתָם זֶה וּלְתוֹךְ דַּרְגוֹתָיו, שֶׁנִּקְרְאוּ כְאֶחָד יָם, וְהַיְנוּ תָּמִים. אַחַר כָּךְ הִתְעַלָּה אַבְרָהָם, וְנִכְנַס פְּנִימָה, וְנִקְשַׁר עִם יָמִין הָעֶלְיוֹן.</p>\n<p>תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ וַדַּאי, כְּמוֹ שֶׁהוּא תָּמִים, כְּלָל אֶחָד, גַּם אַתָּה תִהְיֶה עִמּוֹ תָּמִים, עִמּוֹ וַדַּאי. בַּמֶּה נַעֲשֶׂה בֶּן אָדָם תָּמִים, שֶׁיִּהְיֶה תָ\"ם יָ\"ם? תָּ\"ם - כְּמוֹ שֶׁנִּתְבָּאֵר. יָ\"ם - כָּל אוֹתָן דְּרָגוֹת קְדוֹשׁוֹת שֶׁלּוֹ נִקְרָאִים יָ\"ם, וְלֹא נִפְרָדִים מִמֶּנּוּ לְעוֹלָמִים. (שתי נסחאות) גַּם אַתָּה כְּמוֹ זֶה, לְהַעֲבִיר מִמְּךְ דְּרָגוֹת נָכְרִיּוֹת, וּלְהִתְקַשֵּׁר בְּתָמִים, לִהְיוֹת בְּךְ דְּרָגוֹת קְדוֹשׁוֹת, סוֹד שֶׁל הַיָּ\"ם, וְדַרְגָּה קְדוֹשָׁה תָּ\"ם, כְּנֶגֶד א' סוֹד שֶׁל יַעֲקֹב. בֶּן אָדָם צָרִיךְ לִהְיוֹת בְּכָל יוֹם תָּ\"ם יָ\"ם כְּמוֹ זֶה מַמָּשׁ.</p>\n<p>כָּעֵת פֵּרַשׁ מַה שֶּׁפֵּרַשׁ בַּיְשִׁיבָה, שֶׁהַלְּבָנָה הַקְּדוֹשָׁה יָפָה הִיא בְּלֹבֶן, וְכָל הַגְּוָנִים נוֹצְצִים בָּהּ וּמְרֻקָּמִים, וְהִיא כְּאוֹתוֹ יֹפִי וְלֹבֶן הַשֶּׁמֶשׁ מַמָּשׁ. וּבְאוֹתוֹ הַיָּם שֶׁלָּהּ בְּתוֹךְ שִׁבְעִים שָׁנָה יוֹצֵא דָג אֶחָד, וּמוֹצִיא מִמֶּנָּה גָּוֶן תְּכֵלֶת, וְהִיא לוֹקַחַת גָּוֶן זֶה וּמַתְקִינָה אוֹתוֹ, וּמִתְחַפָּה בַחוּץ בַּגָּוֶן הַזֶּה. לֹא שֶׁגָּוֶן זֶה הוּא לְבוּשָׁהּ, שֶׁהֲרֵי (משלי לא) שֵׁשׁ וְאַרְגָּמָן לְבוּשָׁהּ. אֲבָל צִפּוּי חִיצוֹנִי הוּא הַגָּוֶן הַזֶּה. כְּמוֹ זֶה הָיָה הַמִּשְׁכָּן, שֶׁכֻּלּוֹ בְּיֹפִי מְרֻקָּם לִפְנִים, וְאַחַר כָּךְ - (במדבר ד) וּפָרְשׂוּ בֶגֶד כְּלִיל תְּכֵלֶת. מָה הַטַּעַם? מִשּׁוּם שֶׁתַּחַת יָם זֶה יֵשׁ מְצוּלוֹת יָ\"ם, כְּלָל שֶׁל זָכָר וּנְקֵבָה, וְיֵשׁ לָהֶם עַיִן הָרָע לְהִסְתַּכֵּל. וּכְשֶׁמִּסְתַּכְּלִים, מִזְדַּמֵּן לְעֵינֵיהֶם צֶבַע תְּכֵלֶת, וְלֹא יְכוֹלָה עֵינָם לִשְׁלֹט, וְהִיא מִתְתַּקֶּנֶת לִפְנִים בְּכָל גְּוָנִים מְרֻקָּמִים כָּרָאוּי, מִתְתַּחְמִים לְאַרְבַּעַת צִדְדֵי הָעוֹלָם.</p>\n<p>כְּמוֹ זֶה בֶּן אָדָם שֶׁלּוֹבֵשׁ צִיצִית, נַעֲשֶׂה בְּכָל יוֹם תָּמִים. תָּ\"ם, בְּאַרְבַּע כְּנָפַיִם מְתֻקָּנוֹת כָּרָאוּי. יָ\"ם, בְּאוֹתוֹ תְּכֵלֶת שֶׁל הַדָּג שֶׁל שִׁבְעִים דַּרְגוֹת הַיָּם, צַד הָרָע כְּשֶׁמִּסְתַּכֵּל בָּאָדָם זֶה לֹא יָכוֹל לְהַזִּיקוֹ בְּעַיִן הָרָע, וְאָז הוּא תָּם יָ\"ם עִם ה' אֱלֹהָיו מַמָּשׁ בְּתִקּוּן אֶחָד, הוּא לְמַעְלָה, וְהוּא לְמַטָּה.</p>\n<p>אַחַר כָּךְ מִסְתַּלֶּקֶת הִיא לְתוֹךְ דְּרָגוֹת עֶלְיוֹנוֹת. גַּם כָּךְ הַבֶּן אָדָם עוֹלֶה הוּא אַחַר כָּךְ בַּתְּפִלִּין לְתוֹךְ דְּרָגוֹת עֶלְיוֹנוֹת. וְעַל זֶה תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ, עִמּוֹ וַדַּאי. וַדַּאי בְּשָׁעָה אַחַת, בְּרֶגַע אֶחָד, הִיא מְתֻקֶּנֶת לְמַעְלָה, וּבֶן אָדָם מְתֻקָּן לְמַטָּה.</p>\n<p>אָמַר רַבִּי אִילָאִי, כָּל אֵלּוּ שֶׁל כָּאן, כְּמוֹ זֶה מְתֻקָּנִים לִהְיוֹת כָּל אֶחָד תָּמִים עִם ה'. וְעַל סוֹד זֶה, בַּמִּדְבָּר הַזֶּה יִתַּמּוּ. אִם תֹּאמְרוּ שֶׁכְּשֶׁנֶּאֱמַר, לְרַע נֶאֱמַר - כָּךְ זֶה בְּוַדַּאי, שֶׁהָיָה לָהֶם לִהְיוֹת כָּל אֶחָד תָּמִים עִם ה' בָּאָרֶץ הַקְּדוֹשָׁה, מָקוֹם שֶׁה' שָׁרוּי שָׁם, לִהְיוֹת פָּנִים בְּפָנִים כְּאֶחָד עִמּוֹ, וְכָעֵת כָּל אֶחָד הָיָה תָמִים בְּמִדְבָּר זֶה לַחוּץ, מָקוֹם רָחוֹק מִשָּׁם, שֶׁלֹּא יִסְתַּכֵּל פָּנִים בְּפָנִים אִתּוֹ לִהְיוֹת עִם ה' כָּרָאוּי. וְשָׁם יָמוּתוֹ, כְּמוֹ שֶׁרְאִיתֶם שֶׁעוֹשִׂים בְּכָל יוֹם.</p>\n<p>אַשְׁרֵי חֶלְקְכֶם, חֲבֵרִים קְדוֹשִׁים, שֶׁזְּכִיתֶם לְכָל זֶה. שְׁתֵּי מְעָרוֹת אֵלֶּה אֲחֵרוֹת שֶׁלָּכֶם, שֶׁלֹּא תִמְצְאוּ כָּל זֶה שָׁם, שֶׁהֵם תּוֹךְ יְשִׁיבַת מֹשֶׁה יוֹשְׁבִים מֵרָחוֹק. וְעַל זֶה כָּתוּב בְּמֹשֶׁה, (במדבר יב) עָנָו מְאֹד מִכָּל הָאָדָם. וְנָבִיא עֶלְיוֹן קִבְּלָם לִישִׁיבָתוֹ מִיּוֹם שֶׁהֻתַּר לִרְאוֹת כָּל זֶה עַד אוֹתָהּ שָׁעָה שִׁבְעָה יָמִים. וַהֲרֵי לֹא הָיוּ מִסְתַּכְּלִים בָּעוֹלָם הַזֶּה כְּלוּם.</p>\n<p>אָמַר לוֹ רַבִּי אִילָאִי, צַדִּיקִים קְדוֹשִׁים, אֹמַר לָכֶם דְּבָרִים שֶׁשְּׁמַעְתֶּם. וְדָבָר רִאשׁוֹן כְּשֶׁתֵּדְעוּ מְדִידַת הַמִּשְׁחָה בְּשֵׁם חָקוּק מְפֹרָשׁ, תֵּדְעוּ (שאף על גב) שֶׁבְּצַלְאֵל הוּא רְבִיעִי שֶׁל אוֹרוֹת עֶלְיוֹנִים, שֶׁכָּתוּב (שמות לא) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. מִי שֶׁלֹּא הִסְתַּכֵּל, רוֹאֶה וְנִפְקָח.</p>\n<p>מִי שֶׁלֹּא הִסְתַּכֵּל בְּאוֹתָם שְׁלֹשָׁה דְבָרִים טְמִירִים, מַה לְמַעְלָה מַה לְּמַטָּה וְכוּ', עָתִיד הוּא לְהִפָּקֵחַ בַּתּוֹרָה וְלִפְקֹחַ בָּהּ עֵינָיו. עֵץ שֶׁל שְׁמוֹנָה עָשָׂר, שִׁדְרַת הַבֶּן אָדָם, כְּשֶׁמִּתְכּוֹפֵף לִפְנֵי רִבּוֹנוֹ, יִזְקֹף וְיַעֲמֹד לִתְחִיַּת הַמֵּתִים. אִם לֹא כוֹפֵף בְּמוֹדִים, נַעֲשֶׂה נָחָשׁ, וְאֵין לוֹ תְקוּמָה לְאוֹתוֹ הַזְּמַן.</p>\n<p>מִי שֶׁנִּכְנָס לְבֵין שְׁנֵי כְרוּבִים פְּנִימָה, מִי שֶׁנִּכְנָס שִׁעוּר שְׁנֵי פְתָחִים לְתוֹךְ בֵּית הַכְּנֶסֶת, נִדְבָּק בְּרִבּוֹנוֹ, וּרְצוֹנוֹ נַעֲשֶׂה. מִי שֶׁמְּעַיֵּן בִּתְפִלָּתוֹ וּמִסְתַּכֵּל בָּהּ, רָחוֹק מֵרְצוֹנוֹ שֶׁשּׁוֹאֵל. קָרְבַּן הַתִּינוֹק כְּשֶׁמַּקְרִיב אָדָם בְּנוֹ לְבֵית סֵפֶר אוֹ לְמִילָה, זֶה קָרְבָּן שָׁלֵם לְהִתְקַבֵּל. מִכָּאן וּלְהָלְאָה, אֲהוּבִים, לְכוּ.</p>"],[9522012338,"<p>אֶלְעָזָר בְּנִי, יָפֶה אָמַרְתָּ כְּפִי מַה שֶּׁלָּמַדְתָּ. אֲבָל חַס וְשָׁלוֹם, שֶׁאַף עַל גַּב שֶׁרָחֵל הָיְתָה עֲקָרָה בְּאוֹתוֹ זְמַן, יַעֲקֹב חָכָם הָיָה. וְאִלְמָלֵא לֹא יָדַע יַעֲקֹב שֶׁלֵּאָה אִשְׁתּוֹ, לֹא קָבַר אוֹתָהּ בַּמְּעָרָה לְהִתְחַבֵּר עִמּוֹ בְּחִבּוּר אֶחָד, וְיִקְבֹּר אוֹתָהּ מִחוּץ לָאָרֶץ. אֲבָל אֶת לֵאָה הִכְנִיס לְתוֹךְ הָאָרֶץ, וְרָחֵל שָׂם בַּחוּץ. מֵת יַעֲקֹב, נִקְבַּר בְּתוֹכָהּ בְּחִבּוּר אֶחָד.</p>\n<p>כְּמוֹ שֶׁעָשׂוּ כָּל שְׁאָר הָאָבוֹת, גַּם כֵּן אָדָם. מֵתָה חַוָּה בַּתְּחִלָּה, וּקְבָרָהּ שָׁם, וְשָׁם יָדַע אָדָם שֶׁזֶּה מָקוֹם רָאוּי לוֹ. מֵת אָדָם, נִקְבַּר בְּתוֹכָהּ בְּחִבּוּר אֶחָד. מֵתָה שָׂרָה, נִקְבְּרָה שָׁם, וְחַוָּה רָאֲתָה וְשָׂמְחָה לִקְרָאתָהּ וְקָמָה וְקִבַּלְתָּהּ. שִׁעוּר חַוָּה לְגַבֵי שָׂרָה, שִׁעוּר שֶׁל שְׁתֵּי אַמּוֹת וְלֹא יוֹתֵר. מֵת אַבְרָהָם, נִקְבַּר לְיַד שָׂרָה בְּחִבּוּר אֶחָד. מֵתָה רִבְקָה, נִקְבְּרָה שָׁם, וְשָׂרָה רָאֲתָה וְקָמָה וְקִבַּלְתָּהּ. מֵת יִצְחָק, נִקְבַּר אִתָּהּ בְּחִבּוּר אֶחָד. מֵתָה לֵאָה, נִקְבְּרָה שָׁם, וְרִבְקָה רָאֲתָה וְקָמָה וְקִבַּלְתָּהּ. מֵת יַעֲקֹב, הִתְחַבֵּר אִתָּהּ בְּחִבּוּר אֶחָד. וְכֻלָּם זָכָר וּנְקֵבָה כְּאֶחָד בְּחִבּוּר אֶחָד.</p>\n<p>סִדּוּרָם אֵיךְ שׁוֹכְנִים? נָשִׁים לְיַד נָשִׁים, וּזְכָרִים לְיַד זְכָרִים. אָדָם בָּרֹאשׁ, חַוָּה סְמוּכָה לוֹ. שָׁרָה לְיַד חַוָּה. אַבְרָהָם סָמוּךְ לְשָׂרָה. יִצְחָק סָמוּךְ לְאַבְרָהָם. רִבְקָה סְמוּכָה לְיִצְחָק. לֵאָה סְמוּכָה לְרִבְקָה. יַעֲקֹב סָמוּךְ לְלֵאָה. נִמְצָא אָדָם בְּצַד זֶה וְיַעֲקֹב בְּצַד זֶה, זֶה רֹאשׁ וְזֶה סוֹף.</p>\n<p>בְּסֵפֶר שְׁלֹמֹה הַמֶּלֶךְ הוּא כָּרָאוּי, וְכָךְ זֶה: אָדָם וְחַוָּה בַּתְּחִלָּה, וְשָׂרָה וְאַבְרָהָם סְמוּכִים לָהֶם. יִצְחָק וְרִבְקָה לְזָוִית אַחֶרֶת, בְּדֶרֶךְ יָשָׁר בְּשׁוּרָה אַחַת. יַעֲקֹב וְלֵאָה בָּאֶמְצַע. וְאוֹתָם נָשִׁים לְיַד נָשִׁים, וּזְכָרִם לְיַד זְכָרִים. וְאָדָם וְחַוָּה, שָׂרָה וְאַבְרָהָם, יַעֲקֹב וְלֵאָה, רִבְקָה וְיִצְחָק. אָדָם בְּצַד זֶה, וְיִצְחָק בְּצַד זֶה, וְיַעֲקֹב בָּאֶמְצַע. יִצְחָק לְיַד אָבִיו לֹא דֶרֶךְ הָעוֹלָם. וְעִם כָּל זֶה יַעֲקֹב צָרִיךְ בָּאֶמְצַע.</p>\n<p>וּבְכָל הַזּוּגוֹת הַלָּלוּ, כְּמוֹ שֶׁנִּקְבְּרוּ - כָּךְ יָקוּמוּ וְכָךְ יִמָּצְאוּ. לֵאָה תִּשְׂמַח עִם מָשִׁיחַ בֶּן דָּוִד שֶׁיֵּצֵא מִמֶּנָּה לִפְנִים. רָחֵל תִּשְׂמַח בְּמָשִׁיחַ בֶּן יוֹסֵף שֶׁיֵּצֵא מִמֶּנָּה מִחוּץ לִירוּשָׁלַיִם, וְהַכֹּל לִמְקוֹמוֹתֵיהֶ ם.</p>"],[9522012339,"<p>אֵלֶּה כָּאן וְאֵלֶּה כָּאן. שֶׁהֵם (מגדלים) מַרְגָּלִיּוֹת שֶׁל אֶבֶן טוֹבָה כֻּלָּם. בֵּין כָּל הַמִּגְדָּלִים יֵשׁ מִגְדָּל אֶחָד שֶׁל אֶבֶן טוֹבָה בָּאֶמְצַע, וְזֶה עוֹלֶה לְרוּם הָרָקִיעַ, וְלֹא נִרְאֶה כָּעֵת, עַד אוֹתוֹ זְמַן שֶׁיִּתְגַּלֶּה. רֹאשׁ הַיְשִׁיבָה רָאָה אוֹתוֹ, וְהָיָה רָשׁוּם שָׁם פָּסוּק זֶה לְמַעְלָה, (משלי יח) מִגְדַּל עֹז שֵׁם ה' בּוֹ יָרוּץ צַדִּיק וְנִשְׂגָּב. וּפֵרַשׁ רֹאשׁ הַיְשִׁיבָה פָּסוּק זֶה, מִגְדַּל עֹז - זוֹ כְּנֶסֶת יִשְׂרָאֵל. בּוֹ יָרוּץ צַדִּיק - בּוֹ רְצוֹן הַצַּדִּיק תָּמִיד. וְעַל זֶה, וְנִשְׂגָּב אוֹתוֹ מִגְדָּל שֶׁלֹּא יִפֹּל לְעוֹלָמִים כְּמוֹ שֶׁהָיָה.</p>\n<p>וְרַבִּי כְּרוּסְפְּדַאי חֲמוּד הַלֵּב פֵּרַשׁ פָּסוּק זֶה עַד שֶׁלֹּא הִסְתַּלֵּק, וּפֵרַשׁ יָפֶה. מִגְדַּל עֹז - זוֹ תֵבָה. וְסֵפֶר תּוֹרָה שֶׁהוּא עֹז, לָשִׂים בּוֹ, וּלְהוֹצִיאוֹ מִתּוֹךְ הַהֵיכָל, דְּמוּת הֵיכָל הַפְּנִימִי, שֶׁמִּמֶּנּוּ יָצְאָה תוֹרָה, וְאוֹתוֹ מִגְדָּל שֵׁם ה' הוּא וּדְמוּתוֹ, וְצָרִיךְ בְּשֵׁשׁ דְּרָגוֹת.</p>\n<p>בּוֹ יָרוּץ צַדִּיק, בַּמֶּה? בְּמִגְדָּל אוֹ בְּסֵפֶר תּוֹרָה? אֶלָּא הַפָּסוּק נִדְרָשׁ בָּזֶה וּבָזֶה. כְּשֶׁדּוֹרְשִׁים בְּמִגְדָּל, צָרִיךְ צַדִּיק זֶה שֶׁיִּהְיֶה חַזַּן הַכְּנֶסֶת צַדִּיק אֱמֶת, וּדְמוּת שֶׁל צַדִּיק עֶלְיוֹן. כְּשֶׁדּוֹרְשִׁים בְּסֵפֶר תּוֹרָה, מִי שֶׁעוֹלֶה לַסֵּפֶר תּוֹרָה לִקְרֹא בַתּוֹרָה, צָרִיךְ צַדִּיק, וְצַדִּיק נִקְרָא. מִי נִקְרָא צַדִּיק מִכֻּלָּם? הַשִּׁשִּׁי שֶׁעוֹלֶה מֵאוֹתָם שִׁבְעָה. אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁהוּא לֹא עוֹלֶה כָּל יָמָיו, אֶלָּא שִׁשִּׁי לְאוֹתָם שֶׁעוֹלִים. בּוֹ יָרוּץ צַדִּיק, בְּסֵפֶר תּוֹרָה יָרוּץ דִּבְרֵי צַדִּיק זֶה. וְנִשְׂגָּב מִמָּה? מִפַּחַד מַלְאַךְ הַמָּוֶת, שֶׁהֲרֵי מַאֲרִיךְ יָמִים. וְנִשְׂגָּב שֶׁלֹּא יִנָּזֵק לְעוֹלָם.</p>\n<p>בְּאוֹתוֹ מִגְדָּל שֶׁעוֹלֶה בֵּין אוֹתָם מִגְדָּלִים קַיָּם אוֹר אֶחָד בִּדְמוּת סֵפֶר תּוֹרָה. כְּשֶׁבָּאָה אוֹתָהּ צִפּוֹר, לוֹקַחַת אוֹתוֹ מִגְדָּל מִמְּקוֹמוֹ, וְעוֹמֶדֶת תּוֹךְ אֶמְצַע הָעֲזָרָה תּוֹךְ כַּנְפֵי הַכְּרוּבִים הָיָה. (ומה שהיה), רוּמוֹ לְרוּם הַשָּׁמַיִם נִשְׁפָּל וְנִכְנָס תַּחַת אוֹתָם כְּרוּבִים, וְחוֹמוֹתָיו בֵּין רָאשֵׁי הַכְּרוּבִים.</p>\n<p>שְׁלֹש מֵאוֹת פְּתָחִים שָׁם, בַּפֶּתַח הָאֶמְצָעִי עוֹמֵד מָאוֹר זֶה, דְּמוּת סֵפֶר תּוֹרָה, בּוֹ עָתִיד מֶלֶךְ יִשְׂרָאֵל לִקְרֹא בְּפָרָשַׁת הַקְהֵל, וְזֶה יִהְיֶה מֶלֶךְ הַמָּשִׁיחַ, וְלֹא אַחֵר.</p>\n<p>וּבְאוֹתוֹ סֵפֶר תּוֹרָה שֶׁל אוֹתוֹ אוֹר, אִי חָסִיד קָדוֹשׁ, אַשְׁרֵי מִי שֶׁמִּפִּיו יִשְׁמְעוּ קוֹל נְעִימוּת שֶׁל דְּבָרָיו מֵאוֹתָם דְּבָרִים סְתוּמִים שֶׁפֵּרַשׁ בַּתּוֹרָה. בְּכָל רֹאשׁ חֹדֶשׁ וְשַׁבָּתוֹת וּמוֹעֲדִים וְחַגִּים, כְּשֶׁרוֹצִים כָּל בְּנֵי הַיְשִׁיבָה לַעֲלוֹת לְמַעְלָה לְתוֹךְ יְשִׁיבַת הָרָקִיעַ, כֻּלָּם מִתְכַּנְּסִים אֶל מֶלֶךְ הַמָּשִׁיחַ, וְהוּא מְפָרֵשׁ דְּבָרִים, וּמִתּוֹךְ מְתִיקוּת דְּבָרָיו בְּעֶרְגָּה עוֹלִים. כָּל עֲשֶׂרֶת הַדְּבָרִים גְּנוּזִים לְךְ מֵאוֹתָם דְּבָרִים שֶׁפֵּרַשׁ לַיּוֹם שֶׁל הַשְּׁאֵלוֹת שֶׁלְּךְ.</p>\n<p>כְּשֶׁעוֹמֵד אוֹתוֹ מִגְדָּל בְּאֶמְצַע הָעֲזָרָה וּפֶתַח זֶה פּוֹתֵחַ, פּוֹתְחִים אוֹתָם כְּרוּבִים פִּיהֶם, וּפוֹרְשִׂים כַּנְפֵיהֶם, וּמֵאִיר אוֹר עֶלְיוֹן עַל אוֹתוֹ פֶּתַח. וְאוֹתוֹ סֵפֶר תּוֹרָה נִפְתָּח, וְאוֹתָם כְּרוּבִים פּוֹתְחִים וְאוֹמְרִים: (תהלים לא) מָה רַב טוּבְךְ אֲשֶׁר צָפַנְתָּ לִּירֵאֶיךְ וְגוֹ'. נִסְגָּרִים הַפְּתָחִים, וְסֵפֶר הַתּוֹרָה נִגְלָל.</p>\n<p>מִי רָאָה אוֹר הַמֵּאִיר שֶׁל אוֹתוֹ סֵפֶר תּוֹרָה, כֻּלּוֹ אוֹר מֵאִיר, אוֹתִיּוֹת שֶׁלּוֹ, שַׁלְהֲבוֹת אֵשׁ מֵאַרְבָּעָה גְוָנִים שֶׁהֵם מֵעוֹלָם עֶלְיוֹן, כֻּלָּם בּוֹלְטִים וְנוֹצְצִים, אֵין מִי שֶׁיָּכוֹל לַעֲמֹד בָּהֶם פְּרָט לַמָּשִׁיחַ.</p>\n<p>נִסְגָּר פֶּתַח זֶה, וּכְרוּבִים שׁוֹכְכִים, וְאוֹתוֹ מִגְדָּל פּוֹרֵחַ וְעוֹמֵד בִּמְקוֹמוֹ בֵּין שְׁאָר הַמִּגְדָּלִים.</p>"],[9522012340,"<p>בְּאוֹתוֹ פֶּתַח אֶמְצָעִי יֵשׁ עֲטֶרֶת פָּז עֶלְיוֹנָה וְנִכְבָּדָה גְּנוּזָה, שֶׁלֹּא נִרְאֵית כָּעֵת, גְּלוּפָה וַחֲקוּקָה בְּכָל מִינֵי אֲבָנִים יְקָרוֹת, וַעֲתִידָה לִהְיוֹת עַל רֹאשׁ מֶלֶךְ הַמָּשִׁיחַ כְּשֶׁעוֹלֶה בְּאוֹתוֹ מִגְדָּל, וּשְׁנֵי נְשָׁרִים, זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, לוֹקְחִים אוֹתוֹ בִּידֵיהֶם.</p>\n<p>כְּשֶׁעוֹלֶה מֶלֶךְ הַמָּשִׁיחַ, מִתְתַּקְּנִים הַנְּשָׁרִים, וְלוֹקְחִים עֲטָרָה זוֹ בְּשָׁעָה שֶׁיַּתְחִיל לִקְרֹא, יִפָּתַח פֶּתַח אַחֵר, וּמִשָּׁם תֵּצֵא אוֹתָהּ יוֹנָה שֶׁשָּׁלַח נֹחַ בִּימֵי הַמַּבּוּל, שֶׁכָּתוּב (בראשית ח) וַיְשַׁלַּח אֶת הַיּוֹנָה. הַיּוֹנָה, אוֹתָהּ הַנּוֹדַעַת, וְלֹא דִבְּרוּ בָהּ הַקַּדְמוֹנִים וְלֹא יָדְעוּ מַה הִיא, אֶלָּא מִכָּאן יָצְאָה וְעָשְׂתָה שְׁלִיחוּתָהּ.</p>\n<p>וּבְשָׁעָה שֶׁכָּתוּב וְלֹא יָסְפָה שׁוּב אֵלָיו עוֹד, לֹא יָדַע אָדָם לְאָן הָלְכָה, וְהִיא שָׁבָה לִמְקוֹמָהּ וְנִגְנְזָה בְּפֶתַח זֶה, וְהִיא תִּקַּח עֲטָרָה בְּפִיהָ וְתָשִׂים עַל רֹאשׁ מֶלֶךְ הַמָּשִׁיחַ, הִגִּיעַ וְלֹא הִגִּיעַ, וְאָז כָּתוּב, (תהלים כא) תָּשִׁית לְרֹאשׁוֹ עֲטֶרֶת פָּז.</p>\n<p>וְכֵיוָן שֶׁיִּקְרָא מֶלֶךְ הַמָּשִׁיחַ בְּסֵפֶר תּוֹרָה, יָקוּמוּ שְׁנֵי נְשָׁרִים, זֶה מִכָּאן וְזֶה מִכָּאן, וְיוֹנָה מִתְכּוֹפֶפֶת, וּמֶלֶךְ הַמָּשִׁיחַ יוֹרֵד, וַעֲטָרָה עַל רֹאשׁוֹ, עַד מַדְרֵגָה אַחֲרוֹנָה. וּשְׁנֵי נְשָׁרִים פּוֹרְחִים לְמַעְלָה עַל רֹאשׁוֹ, וְיוֹנָה שָׁבָה וַעֲטָרָה בְּפִיהָ, וִיקַבְּלוּ אוֹתָהּ שְׁנֵי נְשָׁרִים אֵלּוּ.</p>\n<p>דָּוִד הַמֶּלֶךְ נִקְרָא זַיִת רַעֲנָן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים נב) וַאֲנִי כְּזַיִת רַעֲנָן בְּבֵית וְגוֹ'. עֲלֵה זַיִת - זֶה מֶלֶךְ הַמָּשִׁיחַ בֶּן דָּוִד. וְזֶהוּ שֶׁרָמְזָה יוֹנָה זוֹ בִּימֵי נֹחַ, שֶׁכָּתוּב (בראשית ח) וְהִנֵּה עֲלֵה זַיִת טָרָף בְּפִיהָ. אוֹתוֹ עֲלֵה זַיִת טָרַף וְנֶחְטַף לִכְבוֹדוֹ, בַּמֶּה? בְּפִיהָ. שֶׁעוֹמֶדֶת עַל רֹאשׁוֹ, וּמְקַבֵּל כָּבוֹד מִיּוֹנָה זוֹ. וּמַה שֶּׁכָּתוּב טָרָף וְלֹא טָרְפָה, (אלא) כַּזָּכָר הַזֶּה שֶׁעוֹשֶׂה חַיִל וּמְנַצֵּחַ. בִּישִׁיבַת הָרָקִיעַ יוֹנָה זָכָר הוּא. מִתּוֹךְ שֶׁנִּקְרָא יוֹנָה כָּתוּב כִּנְקֵבָה, וְכָתוּב כְּזָכָר בִּזְמַן שֶׁמְּקַבֵּל כָּבוֹד זֶה.</p>\n<p>מִגְדָּל זֶה כְּשֶׁשָּׁב לִמְקוֹמוֹ, מֵאִיר כְּאוֹר עֵין הַשֶּׁמֶשׁ, שֶׁכָּתוּב (תהלים פט) כִּסְאוֹ כַּשֶּׁמֶשׁ נֶגְדִּי, וְאַף שֶׁכִּסֵּא אַחֵר יִהְיֶה לוֹ בְּנִסִּים וְאוֹתוֹת גְּדוֹלִים. בְּרֹאשׁ מִגְדָּל זֶה יֵשׁ עוֹפוֹת אֵשׁ (דרור) שֶׁמְּצַפְצְפִים, כְּשֶׁעוֹלֶה הַבּקֶר, צִפְצוּף שֶׁל נְעִימוּת, שֶׁאֵין נֹעַם וְנִגּוּן כְּאוֹתָהּ נְעִימוּת.</p>\n<p>לְמַעְלָה מִכֻּלָּם מִינִים אֲחֵרִים וְיוֹנִים אֲחֵרִים שֶׁפּוֹרְחִים בָּאֲוִיר, עוֹלִים וְיוֹרְדִים, יוֹרְדִים וְעוֹלִים, לֹא שׁוֹכְכִים לְעוֹלָמִים. אוֹתִיּוֹת גְּדוֹלוֹת וְאוֹתִיּוֹת קְטַנּוֹת פּוֹרְחוֹת בֵּינֵיהֶם.</p>"],[9522012341,"<p>אִי חָסִיד קָדוֹשׁ, בְּשָׁעָה שֶׁהָאוֹתִיּוֹת פּוֹרְחוֹת, רוֹאֶה הָאָדָם בְּאוֹתִיּוֹת גְּדוֹלוֹת. כָּתוּב בָּאֲוִיר לְפִי שָׁעָה, בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. (והארץ היתה תהו ובהו וגו', מכאן חוזרות האותיות הגדולות כבתחלה) מַכּוֹת אוֹתִיּוֹת קְטַנּוֹת בָּהֶם וּפוֹרְחוֹת, וְנִרְאֶה מֵהֶן כָּתוּב, וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וְגוֹ', וַיַּרְא אֱלֹהִים אֶת הָאוֹר וְגוֹ'. אַחַר כָּךְ חוֹזְרוֹת אוֹתִיּוֹת קְטַנּוֹת וּמַכּוֹת בְּאוֹתִיּוֹת גְּדוֹלוֹת, וְנִרְאֶה מֵהֶן שֶׁכָּתוּב, וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ וְגוֹ'. וְכֵן כָּל מַעֲשֵׂה בְרֵאשִׁית, פְּלָאוֹת גְּדוֹלוֹת, וְשִׂמְחָה לָעֵינַיִם מַעֲשִׂים שֶׁל אוֹתִיּוֹת אֵלּוּ. אַשְׁרֵי הָעָם שֶׁלְּכָל זֶה מְצַפִּים.</p>\n<p>אִי חָסִיד קָדוֹשׁ, מִי שֶׁשּׁוֹמֵר בְּרִית, שָׂם אוֹתוֹ אַחֲרָיו, וְהוּא לַהַתְחָלָה. וְאִם תֹּאמַר, מִי שׁוֹמֵר לְאָחוֹר? הֲרֵי שְׁמִירָה גְדוֹלָה וְעֶלְיוֹנָה מֵהַכֹּל שֶׁשּׁוֹמְרוֹ. וּמִי הוּא? צַדִּיק עֶלְיוֹן בְּאַהֲבָה רַבָּה. נִכְנָס בֵּין צַדִּיק וְצֶדֶק, וְנִמְצָא שָׁמוּר מִכָּל הַצְּדָדִים. אַשְׁרֵי מִי שֶׁשּׁוֹמֵר בְּרִית זוֹ. וְעַל כֵּן יִשְׂרָאֵל נִרְאִים כָּל הַזְּכָרִים שֶׁשּׁוֹמְרִים אוֹת בְּרִית זוֹ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. מִיהוּ שֶׁיָּכוֹל לְהַזִּיק לְבֵן שֶׁהוּא בְּאֶמְצַע אָבִיו מִכָּאן, וְאִמּוֹ מִכָּאן, וְהוּא בֵּינֵיהֶם? וְזֶה כְּשֶׁהוּא אַחֲרֵי ה'.</p>"],[9522012342,"<p>בֹּא וּרְאֵה, אוֹתוֹ רָקִיעַ כְּשֶׁסּוֹבֵב בְּגִלְגּוּל, מְנַגֵּן בְּנִגּוּן, וּמִקּוֹל נַהֲמַת הַמַּיִם הַנּוֹבְעִים לֹא יָדוּעַ אוֹתוֹ נִגּוּן. כָּל אוֹתָם הָאַגָּנִים שֶׁבְּאַרְבָּעָה צְדָדִים מִתְמַלְּאִים מִנְּבִיעַת הַמַּיִם שֶׁנּוֹבְעִים. מִי שֶּׁהוּא בִּפְנִים, בִּשְׁנֵי צְדָדִים עוֹמֵד שָׁם. אֶחָד בְּשִׂמְחָה, שֶׁאֵין שִׂמְחָה כְּאוֹתָהּ שִׂמְחָה בָּעוֹלָם, לְקַיֵּם (שם ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה. וְאֶחָד בְּיִרְאָה, שֶׁאֵין יִרְאָה כְּאוֹתָהּ יִרְאָה בָּעוֹלָם, לְקַיֵּם (שם ב) עִבְדוּ אֶת ה' בְּיִרְאָה.</p>\n<p>מַעִִיַן מַיִם אֶחָד שֶׁנּוֹבֵעַ מִצַּד מִזְרָח, זֶהוּ שֶׁאָמַר יְחֶזְקֵאל הַנָּבִיא. מִמַּעְיָן זֶה לֹא יְכוֹלִים לְסַיֵּם שֶׁבַח כָּל בְּנֵי הָעוֹלָם. בְּמָקוֹם שֶׁנּוֹלַד שָׁם לְצַד מִזְרָח, אֵין עֹמֶק וְרוּם שֶׁלּוֹ אֶלָּא זֶרֶת, וְלֹא יוֹתֵר.</p>\n<p>כְּשֶׁנּוֹבְעִים הַמַּיִם וְעוֹלִים, עוֹלִים כָּל מִינֵי מַרְגָּלִיּוֹת שֶׁבָּעוֹלָם, וְלֹא נוֹפְלִים בַּחוּץ. כָּעֵת נִרְאִים בְּגָוֶן אֶחָד, לְפִי שָׁעָה נוֹפְלִים אֵלֶּה, וְהִנֵּה עוֹלִים אֲחֵרִים בְּגָוֶן אַחֵר בְּכָל מִינֵי גְוָנִים שֶׁבָּעוֹלָם. נוֹפְלוֹת אוֹתָן מַרְגָּלִיּוֹת, וְלֹא נוֹפְלוֹת בַּחוּץ.</p>\n<p>סְבִיב אוֹתָהּ נְבִיעָה סוֹבְבִים כַּפְתּוֹר וָפֶרַח, וְלֹא יְכוֹלִים כָּל בְּנֵי הָעוֹלָם לַעֲמֹד עַל אוֹתָם גְּוָנִים, כֻּלָּם שַׁלְהָבוֹת לוֹהֲטוֹת, וְלֹא יְכוֹלִים לְהִסְתַּכֵּל בָּהֶם. לֹא יָדוּעַ חֲשִׁיבוּת הַמַּעֲשֶׂה. הֶעָלִים שֶׁלָּהֶם נוֹצְצִים בְּכַמָּה גְוָנִים.</p>\n<p>מַעָשֵׂה צִיּוּר, אֻמָּנוּת רִבּוֹן הָעוֹלָם, מְכַסִּים עַל שְׁלֹשׁ מֵאוֹת וְשִׁבְעִים וַחֲמִשָּׁה כְּרוּבִים שֶׁתַּחְתֵּיהֶם, אַחַר שְׂבָכִים אֲחֵרִים לִפְנִים. וְאוֹתָם שְׂבָכִים סְבִיב הָעֲזָרָה לִפְנִים.</p>\n<p>וּלְמַעְלָה מֵהֶם אוֹתָן גְּפָנִים פְּרוּשׂוֹת, תַּחַת הַגְּפָנִים אוֹתָם כְּרוּבִים, כֻּלָּם בִּכְנָפַיִם פְּרוּשׂוֹת מְשֻׁלָּבוֹת אֵלּוּ בְאֵלּוּ. כָּאן אָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בְּאוֹתָן גְּפָנִים, מְאִירִים פָּנָיו כְּאוֹר הַשֶּׁמֶשׁ.</p>\n<p>אוֹתָם שְׂבָכִים שֶׁתּוֹחֲמִים סָבִיב סָבִיב לָעֲזָרָה, כֻּלָּם מְרֻקָּמִים בְּחוּטִים שֶׁמְּאִירִים בִּגְוָנִים גְּדוֹלִים, לוֹהֲטִים בְּאַרְבָּעָה מִינֵי זֹּהַר שֶׁל אֵשׁ. שַׁלְהָבוֹת עוֹלוֹת, וּגְוָנִים נוֹצְצִים, וְלִפְעָמִים הַשַּׁלְהָבוֹת שׁוֹכְכוֹת, וְאוֹרוֹת וּגְוָנִים עוֹלִים וּמַכִּים אֵלֶּה בְאֵלֶּה.</p>\n<p>שֵׁשֶׁת אֲלָפִים אַגָּנִים לְגַבֵּי אוֹתָם שְׂבָכִים, אַרְבָּעָה גְוָנִים לְאַרְבָּעָה צְדָדִים שֶׁל הָעֲזָרָה. אֵלֶּה הֵם גְּדוֹלִים, וּנְבִיעַת הַמַּיִם הַחַיִּים בְּכָל הַצְּדָדִים. וְהֵם נוֹפְלִים בְּאוֹתָם אַגָּנִים, וְנִבְלָעִים בִּמְקוֹמָם, וּמַיִם אֵלֶּה לֹא יוֹדְעִים לְאָן הוֹלְכִים.</p>\n<p>בְּאֶמְצַע הָעֲזָרָה יָקוּמוּ כָּל יִשְׂרָאֵל וְיֵרָאוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. בְּצַד דָּרוֹם בַּעֲזָרָה זוֹ נוֹלַד מַעְיָן מַיִם אֶחָד, וְנִדְמָה (והתרבה) שֶׁיִּשְׁטְפוּ הַמַּיִם אֶת כָּל הָעוֹלָם. מִי שֶׁיִּכָּנֵס בָּהֶם, יִהְיוּ עַד הַבִּרְכַּיִם. יִכָּנֵס בָּהֶם גִּבּוֹר גָּדוֹל, יִכָּנֵס בָּהֶם עַד הַבִּרְכַּיִם. אִם תִּינוֹק בֶּן יוֹם, עַד הַבִּרְכַּיִם. מִי שֶׁשּׁוֹתֶה מֵהֶם יִתִחַכֵּם, וְיִתְפַּקַּח בְּחָכְמָה.</p>\n<p>מַעְיָן זֶה יוֹצֵא מִתּוֹךְ מַרְגָּלִית קְטַנָּה אַחַת בְּכֹתֶל דָּרוֹם. אוֹתָם הַמַּיִם נִבְלָעִים תּוֹךְ הַמָּקוֹם (תוך המקום הזה), וּמִשָּׁם יֵצְאוּ הַחוּצָה מֵהַמִּקְדָּשׁ, שֶׁעַד שֶׁיַּעֲלוּ לְנַחַל שִׁטִּים, יִשְׁטְפוּ אוֹתָהּ זִמָּה שֶׁיָּלְדוּ הַמַּיִם שֶׁבַּשִּׁטִּים. וְעַל כָּךְ מַיִם אֵלֶּה בָּעֲזָרָה, בִּגְלַל אֵלּוּ שֶׁנִּרְאוּ שָׁם זְכָרִים, הָיוּ שׁוֹתִים מֵהַמַּיִם, לֹא נִתְעוֹרְרוּ לַנְּקֵבוֹת בְּבוֹאָם לְהִתְרָאוֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ. וְעוֹד, שֶׁהֲרֵי יִתְפַּקְּחוּ לָדַעַת דְּבָרִים סְתוּמִים שֶׁל הַמֶּלֶךְ הָעֶלְיוֹן, תּוֹךְ הַמִּקְדָּשׁ הַזֶּה כָּל הַהִרְהוּרִים נִשְׁכְּחוּ, פְּרָט לַהִרְהוּר שֶׁל חֶדְוַת הַמֶּלֶךְ הַקָּדוֹשׁ.</p>\n<p>עָנָף אֶחָד יוֹצֵא בְתוֹךְ אֶמְצַע אוֹתוֹ מַעְיָן. אָמַר רֹאשׁ הַיְשִׁיבָה, כְּשֶׁהִתְקָרַבְתִּי לְאוֹתוֹ עָנָף שֶׁבְּתוֹךְ הַמַּעְיָן, עָלָה עָנָף לְמַעְלָה לְמַעְלָה. כָּל מַה שֶּׁהִתְקָרַבְתִּי - כָּךְ עָלָה. יְסוֹד וְשֹׁרֶשׁ אוֹתוֹ עָנָף אֵינוֹ רַק בַּמַּיִם. אוֹתוֹ עָנָף מְכַסֶּה עוֹלָמוֹת. כָּל גּוֹנֵי הָעוֹלָם בְּאוֹתָם הָעֲנָפִים שֶׁלּוֹ. פִּרְיוֹ לֹא יָדוּעַ מַהוּ, וְלֹא יְכוֹלִים לָדַעַת. וְאָמַר שֶׁשָּׁאַל אֶת הַמָּשִׁיחַ עַל אוֹתוֹ פְּרִי, וְאָמַר, פְּרִי זֶה גָּנוּז (זכריה ח) לְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרֹב יָמִים. מִי שֶׁזּוֹכֶה לָדַעַת זֶה - שֶׁיֵּדַע.</p>\n<p>רָקִיעַ אֶחָד יֵשׁ עַל אוֹתוֹ עָנָף פָּרוּשׂ לְמַעְלָה. מֵאוֹתוֹ רָקִיעַ הוֹלֵךְ טַל עַל גַּבֵּי אוֹתוֹ מַעְיָן, וְלֹא יוֹתֵר. כְּשֶׁמִּסְתַּכֵּל אָדָם עַל אוֹתוֹ רָקִיעַ מֵרָחוֹק, דּוֹמֶה תְכֵלֶת יוֹתֵר קָרֵב, דּוֹמֶה אָדם. קָרֵב יוֹתֵר, דּוֹמֶה יָרֹק. קָרֵב יוֹתֵר, דּוֹמֶה לָבָן, שֶׁאֵין בָּעוֹלָם לָבָן כְּמוֹתוֹ. טַל שֶׁהוֹלֵךְ מִמֶּנּוּ נִשְׁאָב בְּאוֹתוֹ עָנָף, וְעוֹשֶׂה פְרִי זֶה וּמִתְגַּדֵּל. אוֹתוֹ רָקִיעַ הוּא הוּא הוֹלֵךְ בְּגִלְגּוּל יוֹתֵר מִמַּה שֶּׁעֵינַיִם יְכוֹלוֹת לְהִסְתַּכֵּל.</p>"],[9522012343,"<p>כָּל אוֹתָם שׁוֹמְרֵי בְּרִית הַקֹּדֶשׁ (רוצים) שֶׁרוֹצִים לְהֵרָאוֹת לִפְנֵי הַמֶּלֶךְ, שֶׁהֲרֵי לֹא נִרְאוּ אֶלָּא בִּשְׁבִיל לְהַרְאוֹת שֶׁהֵם בְּנֵי מִילָה קְדוֹשָׁה. וְעַל זֶה, (שמות כג) יֵרָאֶה כָּל זְכוּרְךְ, אוֹתָם בְּנֵי בְּרִית קֹדֶשׁ. דִּיֵּק רֹאשׁ הַיְשִׁיבָה, זְכוּרְךְ וְלֹא זְכָרְךְ, שֶׁהֲרֵי זָכָר כָּתוּב, וְלֹא זָכוּר. מַה זֶּה זְכוּרְךְ? אֶלָּא כָּל אוֹתָם שֶׁשָּׁמְרוּ בְּרִית קֹדֶשׁ וְלֹא חָטְאוּ בוֹ, הֵם הָיוּ בְּנֵי הַמֶּלֶךְ שֶׁבְּכָל יוֹם מִשְׁתַּבֵּחַ בָּהֶם וְזוֹכֵר אוֹתָם תָּמִיד. וְעַל כֵּן זְכוּרְךְ, הַהוּא שֶׁיֵּשׁ בּוֹ בְּרִית קְדוֹשָׁה, שֶׁזּוֹכֵר אוֹתָם הַמֶּלֶךְ בְּכָל יוֹם, שֶׁאֵין שֶׁבַח לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן (אלא) כְּמִי שֶׁשּׁוֹמֵר בְּרִית זוֹ.</p>\n<p>וְעַל כֵּן צָרִיךְ לְהֵרָאוֹת שָׁלֹשׁ פְּעָמִים בְּשָׁנָה לְפָנָיו. שָׁלֹשׁ פְּעָמִים לָמָּה? אֶלָּא בִּגְלַל אָבוֹת הָרִאשׁוֹנִים שֶׁקִּבְּלוּ בְרִית זוֹ רִאשׁוֹנָה לְכָל מִצְווֹת הַתּוֹרָה, וּמִשּׁוּם כָּךְ שָׁלֹשׁ פְּעָמִים הֵם בְּשָׁנָה. אַבְרָהָם קִבֵּל בְּרִית, יִצְחָק קִבֵּל בְּרִית, יַעֲקֹב הָיָה שָׁלֵם מִכֻּלָּם, וְעַל כֵּן כָּתוּב בּוֹ (בראשית כה) וְיַעֲקֹב אִישׁ תָּם, שָׁלֵם מֵהַכֹּל.</p>\n<p>אַבְרָהָם נִקְרָא תָמִים, וְלֹא הָיָה כָּל כָּךְ שָׁלֵם, אֲבָל תָּם - שָׁלֵם מֵהַכֹּל. מַה כָּתוּב בְּנֹחַ? (שם ו) אִישׁ צַדִּיק תָּמִים הָיָה בְּדרֹתָיו. הָיָה רָשׁוּם בְּרֹשֶׁם קָדוֹשׁ בֵּינֵיהֶם. וְאָמַר רֹאשׁ הַיְשִׁיבָה, בְּכָל מָקוֹם שֶׁכָּתוּב תָּמִים, שֶׁרָשׁוּם בְּרֹשֶׁם קָדוֹשׁ בְּאוֹת קִיּוּם הַבְּרִית, וּמִשּׁוּם שֶׁשָּׁמַר הַבְּרִית נִקְרָא תָמִים בְּדרֹתָיו, מַה שֶּׁלֹּא הָיוּ כֻלָּם כָּךְ, שֶׁהֵם מְחַבְּלִים דַּרְכֵיהֶם.</p>\n<p>וְעַל זֶה כָּתוּב אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ. וְכִי מִי יָכוֹל לָלֶכֶת עִמּוֹ? אֶלָּא כָּל מִי שֶׁשּׁוֹמֵר בְּרִית קֹדֶשׁ, מִזְדַּוֶּגֶת בּוֹ שְׁכִינָה וְשׁוֹרָה עָלָיו. וּמִשּׁוּם כָּךְ, (דברים יח) תָּמִים תִּהְיֶה עִם ה' אֱלֹהֶיךְ. תָּמִים תִּהְיֶה, וְאַחַר כָּךְ עִם ה' אֱלֹהֶיךְ. בְּזִוּוּג אֶחָד. שֶׁכֵּיוָן שֶׁשּׁוֹמֵר בְּרִית זוֹ, עִם ה' לִהְיוֹת, וְלֹא נִפְרָד מִמֶּנּוּ.</p>\n<p>בְּאַבְרָהָם כָּתוּב, (בראשית יז) הִתְהַלֵּךְ לְפָנַי וֶהְיֵה תָמִים, מִילַת אוֹתוֹ בְּרִית. הִתְהַלֵּךְ לְפָנַי - מִכָּאן שֶׁלֹּא יֵלֵךְ גֶּבֶר אַחַר אִשָּׁה, אֶלָּא לְפָנֶיהָ דֶּרֶךְ כָּשֵׁר הוּא. וַהֲרֵי כָּתוּב (שמות כג) הִנֵּה אָנֹכִי שּלֵחַ מַלְאָךְ לְפָנֶיךְ. (שם לג) וְשָׁלַחְתִּי לְפָנֶיךְ מַלְאָךְ. לְאַבְרָהָם שֶׁלֹּא הָיָה מָהוּל, דָּחָה אוֹתוֹ לְפָנֶיהָ. וְעַל כֵּן לֹא כָתוּב הֱיֵה תָמִים וְהִתְהַלֵּךְ לְפָנַי, אֶלָּא הִתְהַלֵּךְ לְפָנַי, שֶׁלֹּא רָאוּי אַתָּה עַד שֶׁתִּהְיֶה תָמִים. וְכֵן בְּכֻלָּם, כֵּיוָן שֶׁבֶּן אָדָם תָּמִים וְשׁוֹמֵר אוֹתוֹ, מִיָּד הִיא לְפָנָיו, וְהוּא אַחֲרֶיהָ, כָּשֵׁר הוּא לָזֶה. לְחִסָּרוֹן מַה כָּתוּב? (שמואל א טו) כִּי שָׁב מֵאַחֲרַי.</p>\n<p>נֹחַ מָהוּל הָיָה וְתָמִים, פְּרִיעָה לֹא הָיְתָה בּוֹ, וּמִשּׁוּם שֶׁלֹּא הָיְתָה בּוֹ פְּרִיעָה, מַה כָּתוּב? אֶת הָאֱלֹהִים, וְלֹא אַחַר הָאֱלֹהִים. לְפָנִים לֹא הָיָה, מִשּׁוּם שֶׁהָיָה מָהוּל. לְאָחוֹר לֹא הָיָה, מִשּׁוּם שֶׁלֹּא נִפְרַע. אָז אֵיךְ הָיָה? אֶת הָאֱלֹהִים, סָמוּךְ לוֹ, וְלֹא יָכוֹל לְהִסְתַּכֵּל בּוֹ, שֶׁלֹּא כָּל כָּךְ כָּשֵׁר.</p>\n<p>בְּיִשְׂרָאֵל כָּתוּב, (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן (וגו') וְלַיְלָה בְּעַמּוּד אֵשׁ וְגוֹ'. כֵּיוָן שֶׁאָמְרוּ יִשְׂרָאֵל (שם יד) הֲמִבְּלִי אֵין קְבָרִים בְּמִצְרַיִם וְגוֹ', כִּי טוֹב לָנוּ עֲבֹד אֶת מִצְרַיִם - כִּבְיָכוֹל נֶחֱלַשׁ דַּעְתּוֹ. כָּתוּב וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל וַיֵּלֶךְ מֵאַחֲרֵיהֶם. וַיִּסַּע, לַעֲשׂוֹת בָּהֶם נְקָמוֹת.</p>"],[9522012344,"<p>וְעַל זֶה שָׂמַח הַמָּשִׁיחַ וְשָׂמַח רֹאשׁ הַיְשִׁיבָה, שֶׁהִתְבַּשֵּׂר בָּזֶה. וְאָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁהֲרֵי דִּיֵּק לַמָּשִׁיחַ וְאָמַר, מִנַּיִן הָיָה לְדָנִיֵּאל שֶׁאָמַר, (דניאל ה) שָׁבַר מַלְכוּתְךְ לִשְׁנַיִם וְנִתְּנָה לְמָדַי וּפָרַס? מֵאוֹתָן אוֹתִיּוֹת שֶׁל וּפַרְסִין נִשְׁמַע לוֹ. וְכָאן מַהוּ? אָמַר לוֹ, כָּךְ זֶה וַדַּאי, פְּרֵס פְּרִיסַת מַלְכוּתָךְ (שבר מלכותך) הָרְשָׁעָה עַל יְדֵי מָשִׁיחַ אַחֵר, וְאַחַר כָּךְ יִשְׁלֹט מֶלֶךְ פָּרַס וְיִטֹּל מַמְלָכוֹת רַבּוֹת, וְיִשְׁלֹט עַל אֶרֶץ הַקֹּדֶשׁ שְׁנֵים עָשָׂר חֳדָשִׁים, וְיִשְׁלֹט וְיַהֲרֹג רַבִּים וְאוֹתוֹ מָשִׁיחַ, וְאַחַר כָּךְ יִפֹּל, וִיקַבְּלוּ אֶת הַמַּלְכוּת קְדוֹשִׁים עֶלְיוֹנִים. וְעַל זֶה וּפַרְסִין, מֶלֶךְ פָּרַס נִשְׁמָע כָּאן.</p>\n<p>אִי חָסִיד קָדוֹשׁ, כַּמָּה חֶדְוָה עַל חֶדְוָה בְּאוֹתוֹ מַעְיָן. בְּאוֹתוֹ מַעְיָן מְגַדְּלִים כָּל מִינֵי אִילָנוֹת שֶׁהִצִּיב הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, וְכֻלָּם קַיָּמִים לִרְפוּאָה, עָלִים וּפֵרוֹת וַעֲנָפִים, וּלְשִׂמְחַת הַלֵּב תָּמִיד. וְאֵין בֵּינֵיהֶם רָעָב וּדְאָגָה וַאֲנָחָה לְעוֹלָמִים. אַשְׁרֵי הָעָם שֶׁלְּכָל זֶה מְצַפִּים וְכָל זֶה גָּנוּז לָהֶם.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, בְּקַרְקַע הַמִּקְדָּשׁ הַזֶּה יֵשׁ מֵאוֹתָן הַפְּלָאוֹת. אָמַר לוֹ, אִי רַבִּי, אִי רַבִּי, אַשְׁרֵי חֶלְקְךְ שֶׁכָּל זֶה בְּאוֹתוֹ עַל גַּבֵּי אוֹתוֹ מַעְיָן רָקוּם, אֲבָל אֵין מִי שֶׁיָּכוֹל לְהִסְתַּכֵּל בּוֹ. לִפְעָמִים אוֹרוֹ אוֹר, לִפְעָמִים חֹשֶׁךְ, לִפְעָמִים גּוֹן אַרְגָּמָן, נוֹצְצִים שֶׁהָעֵינַיִם לֹא יְכוֹלוֹת לְהִסְתַּכֵּל לְמַעְלָה. (ההיא) הִיא שֶּׁשָּׁאַלְתָּ, חָסִיד קָדוֹשׁ, מֵאוֹתוֹ קַרְקַע הַמִּקְדָּשׁ, רֹאשׁ הַיְשִׁיבָה לֹא נִפְרָד מִמֶּנּוּ, שֶׁהֲרֵי גָּנוּז הוּא בְּתוֹךְ הַיַּרְדֵּן, וַהֲרֵי אָמַרְתִּי לְךְ מַה שֶּׁאָמַרְתִּי, אֲבָל נִשְׁאַל דָּבָר זֶה, וְתֵדַע מַה שֶּׁתֵּדַע.</p>\n<p>יַרְדֵּן זֶה נִכְנָס וְנִמְשָׁךְ זְמַן אֶחָד בַּשָּׁנָה לְתוֹךְ אוֹתוֹ נָהָר שֶׁיּוֹצֵא מֵעֵדֶן, וְלֹא מֵאוֹתָם אַרְבָּעָה נְהָרוֹת שֶׁנִּמְשָׁכִים מִמֶּנּוּ, אֶלָּא בּוֹ מַמָּשׁ. כֵּיוָן שֶׁהִגִּיעַ אֵלָיו, הוּא נִמְשָׁךְ וּמִתְפַּשֵּׁט וְנִכְנָס לְתוֹךְ הַיַּרְדֵּן. וְכֵיוָן שֶׁמַּגִּיעַ לְתוֹךְ קַרְקַע הַמִּקְדָּשׁ, נִמְצָא שָׁם שְׁלֹשָׁה יָמִים, וְלֹא מִתְפַּשֵּׁט וְלֹא נִמְשָׁךְ לְמָקוֹם אַחֵר. וְאָמַר רֹאשׁ הַיְשִׁיבָה, שֶׁכְּשֶׁחוֹזֵר אוֹתוֹ נָהָר לִמְקוֹמוֹ, מַשְׁאִיר שָׁם כָּל מִינֵי צִיּוּרִים שֶׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּגַן עֵדֶן, שֶׁאוֹתָם צִיּוּרִים גְּנוּזִים תַּחַת מְקוֹמָם.</p>"],[9522012345,"<p>אֵלֶּה כָּאן וְאֵלֶּה כָּאן, וְעוֹלִים וְיוֹרְדִים כְּמִקֹּדֶם. בְּאוֹתוֹ צַד דָּרוֹם יֵשׁ שְׁלֹשׁ מֵאוֹת וַחֲמִשִּׁים עַמּוּדִים מִכָּל מִינֵי מַרְגָּלִיּוֹת. וְאֵלֶּה אוֹתָם שֶׁמְּאִירִים תָּמִיד, וְנוֹטְפִים בְּשָׂמִים נִסְתָּרִים שֶׁלֹּא הִתְגַּלּוּ מֵעוֹלָם. אַרְבָּעָה אַגָּנִים בְּכָל עַמּוּד וְעַמּוּד נְעוּצִים. וּכְשֶׁאוֹתָם בְּשָׂמִים נוֹטְפִים מֵאוֹתָם עַמּוּדִים, נוֹפְלִים בָּהֶם, וּמִתְמַלְּאִים כָּל הָאַגָּנוֹת, וְלֹא יוֹצְאִים הַבְּשָׂמִים הַחוּצָה. מֵאוֹתָם בְּשָׂמִים עֲתִידִים לֶעָתִיד</p>\n<p>לָבא לְהַקְטִיר בְּכָל יוֹם קְטֹרֶת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, שֶׁלֹּא יִהְיוּ מִכְּתִישַׁת בְּנֵי הָאָדָם. אוֹתָם בְּשָׂמִים לֹא יָדוּעַ עִקָּרָם, וּמִמֶּה הָיוּ, אֶלָּא מֵאוֹתָם עַמּוּדִים שֶׁנּוֹפְלִים שָׁם.</p>\n<p>שְׁנֵי נְשָׁרִים בְּכָל עַמּוּד וְעַמּוּד נוֹצְצִים וְלוֹהֲטִים בְּכָל הַגְּוָנִים. שְׁבַע מֵאוֹת נְשָׁרִים הֵם, פּוֹרְחִים אֵלֶּה כָּאן וְאֵלֶּה כָּאן בְּגִלְגּוּל הָעַמּוּדִים. כְּשֶׁמִּסְתּוֹבְבִים, לֹא יְכוֹלוֹת הָעֵינַיִם לְהִסְתַּכֵּל הַמָּקוֹם שֶׁבָּהֶם.</p>\n<p>שָׁלֹש אוֹתִיּוֹת בּוֹלְטוֹת וּפוֹרְחוֹת מִפֶּה זֶה לְפֶה זֶה. בְּגִלְגּוּל הָעַמּוּדִים וּנְשָׁרִים. כָּל אוֹתָן אוֹתִיּוֹת מְרֻקָּמוֹת בְּאֵשׁ לְבָנָה וְזָהָב יָרֹק. אַלְפַּיִם וּמֵאָה מְנוֹרוֹת תְּלוּיוֹת בֵּין אוֹתָם עַמּוּדִים, וְאַלְפַּיִם וּמֵאָה נֵרוֹת בְּכָל מְנוֹרָה וּמְנוֹרָה. דּוֹלְקִים בַּיּוֹם, וּבַלַּיְלָה דּוֹעֲכִים עַל צַעַר יִשְׂרָאֵל. כְּשֶׁמַּגִּיעַ הַבֹּקֶר דּוֹלְקִים כֻּלָּם מֵעַצְמָם.</p>"],[9522012346,"<p>עַד שֶׁהָיוּ יוֹשְׁבִים, אָמְרוּ, הֲרֵי יָרַד הַלַּיְלָה. אָמַר לוֹ לְרַבִּי שִׁמְעוֹן, אִי חָסִיד קָדוֹשׁ, אוֹר הָעוֹלָם, קַח פִּנְקָס שֶׁל תִּיק זֶה, וְקַח נֵר וּכְתֹב דְּבָרִים אֵלּוּ, שֶׁהֲרֵי הִגִּיעַ זְמַנֵּנוּ לִפְקֹד כָּל אֶחָד וְאֶחָד לְתוֹךְ קִבְרוֹ עַד חֲצוֹת הַלַּיְלָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנַס לְתוֹךְ הַגָּן לְהִשְׁתַּעֲשֵׁעַ יַחַד עִם הַצַּדִּיקִים, וְאָז כָּל אֶחָד וְאֶחָד פּוֹרֵחַ לְשָׁם. וּלְמָחָר נִהְיֶה אֶצְלְךְ, הוֹאִיל וְנָתְנוּ לָנוּ רְשׁוּת לְהַשְׁלִים דּוֹרוֹן שֶׁמְּשַׁלְּחִים לְךְ. פָּרְחוּ, וּבָכָה רַבִּי שִׁמְעוֹן וְגָעָה.</p>\n<p>פָּתַח וְאָמַר, (משלי ה) אַיֶּלֶת אֲהָבִים וְיַעֲלַת חֵן דַּדֶּיהָ יְרַוֻּךְ בְכָל עֵת בְּאַהֲבָתָהּ תִּשְׁגֶּה תָמִיד. תּוֹרָה תּוֹרָה, אוֹר כָּל הָעוֹלָמוֹת, כַּמָּה יַמִּים וּנְחָלִים וּמְקוֹרוֹת וּמַבּוּעִים מִתְפַּשְּׁטִים מִמֵּךְ לְכָל הַצְּדָדִים. מִמֵּךְ הַכֹּל, עָלַיִךְ עוֹמְדִים עֶלְיוֹנִים וְתַחְתּוֹנִים, אוֹר הָעֶלְיוֹן (בזה) מִמֵּךְ יוֹצֵא. תּוֹרָה תּוֹרָה, מָה אֹמַר לְפָנַיִךְ? אַיֶּלֶת אֲהָבִים אַתְּ, וְיַעֲלַת חֵן, (אצל) מַעְלָה וּמַטָּה אֲהוּבִים שֶׁלָּךְ. מִי יִזְכֶּה לִינֹק מִמֵּךְ כָּרָאוּי? תּוֹרָה תּוֹרָה, שַׁעֲשׁוּעִים שֶׁל רִבּוֹנֵךְ, מִי יָכוֹל לְגַלּוֹת וְלוֹמַר סְתָרִים וּגְנִיזוֹת שֶׁלָּךְ? בָּכָה, וְהִכְנִיס רֹאשׁוֹ בֵּין בִּרְכָּיו וְנָשַׁק אֶת הֶעָפָר.</p>\n<p>בֵּין כָּךְ רָאָה כַּמָּה דְמֻיּוֹת שֶׁל חֲבֵרִים סְבִיבוֹ. אָמַר לוֹ, אַל תִּירָא בַּר יוֹחַאי, אַל תִּפְחַד מְנוֹרָה קְדוֹשָׁה, כְּתֹב וּשְׂמַח תּוֹךְ שִׂמְחַת רִבּוֹנְךְ. כָּתַב כָּל הַדְּבָרִים הַלָּלוּ שֶׁשָּׁמַע בְּאוֹתוֹ לַיְלָה, וְלָמַד בָּהֶם וְעָסַק בָּהֶם, וְלֹא שָׁכַח דָּבָר. וְאוֹתוֹ נֵר הֵאִיר לְפָנָיו כָּל אוֹתוֹ הַלַּיְלָה עַד שֶׁהִגִּיעַ הַבֹּקֶר. כְּשֶׁהִגִּיעַ הַבֹּקֶר, הֵרִים עֵינָיו, וְרָאָה אוֹר אֶחָד שֶׁהָיָה מֵאִיר בָּרָקִיעַ. הוֹרִיד עֵינָיו לְמַטָּה. חָזַר כְּמִקֹּדֶם וְרָאָה אוֹר בְּכָל הָרָקִיעַ שֶׁמֵּאִיר וְעוֹלֶה בְּאוֹתוֹ אוֹר דְּמוּת הַבַּיִת בְּכַמָּה צִיּוּרִים. שָׂמַח רַבִּי שִׁמְעוֹן, וּלְפִי רֶגַע נִגְנַז כָּל אוֹתוֹ הָאוֹר.</p>\n<p>בֵּין כָּךְ הֲרֵי אוֹתָם שְׁנֵי שְׁלִיחִים בָּאִים. מְצָאוּהוּ רֹאשׁוֹ בֵּין בִּרְכָּיו. אָמְרוּ לוֹ, שָׁלוֹם עָלֶיךְ מֹר! שָׁלוֹם לְמִי שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים רוֹצִים לְהַקְדִּים לוֹ שָׁלוֹם. קוּם! קָם רַבִּי שִׁמְעוֹן וְשָׂמַח בָּהֶם. אָמְרוּ לוֹ, וְלֹא רָאִיתָ נַחַת רוּחַ שֶׁעָשָׂה לְךְ רִבּוֹנְךְ? רָאִיתָ אוֹר הַבַּיִת בָּרָקִיעַ? אָמַר לָהֶם, רָאִיתִי. אָמְרוּ לוֹ, בְּאוֹתָהּ שָׁעָה הוֹצִיא הַתְּהוֹם בֵּית הַמִּקְדָּשׁ, וְהֶעֱבִירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיָּם הַגָּדוֹל, וּמֵאוֹרוֹ הָיָה מוּאָר בָּרָקִיעַ.</p>\n<p>אָמְרוּ לוֹ, רֹאשׁ הַיְשִׁיבָה דּוֹרֵשׁ בִּשְׁלוֹמְךְ, וַהֲרֵי יוֹדֵעַ שֶׁאָנוּ שְׁלִיחִים אֵלֶיךְ, וְכַמָּה דְבָרִים חֲדָשִׁים עַתִּיקִים הִתְחַדְּשׁוּ בַתּוֹרָה בַּלַּיְלָה הַזֶּה. אָמַר לָהֶם, בְּבַקָּשָׁה מִכֶּם, אִמְרוּ דָבָר אֶחָד מֵהֶם. אָמְרוּ, לֹא נִתְּנָה לָנוּ רְשׁוּת לְמַה שֶּׁבָּאנוּ אֵלֶיךְ, אֲבָל דָּבָר חָדָשׁ הָיָה אֵלֶיךְ כָּעֵת.</p>"],[9522012347,"<p>פָּתַח רֹאשׁ הַיְשִׁיבָה וְאָמַר, (בראשית יב) וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךְ מֵאַרְצְךְ וְגוֹ'. זֶה בִּשְׁבִיל שֶׁנִּרְאֶה בּוֹ אוֹר כְּמוֹ זֶה. מִי שֶׁלֹּא זוֹכֶה בְּמָקוֹם זֶה, יֵלֵךְ וְיִקַּח עַצְמוֹ לְמָקוֹם אַחֵר וְיִזְכֶּה בּוֹ. עֵץ שֶׁדּוֹלֵק, וְהָאוֹר לֹא עוֹלֶה וּמֵאִיר בּוֹ, יְנַעְנְעוּ אוֹתוֹ וְיַעֲלֶה בּוֹ הָאוֹר וְיָאִיר. וְהָיִינוּ עֲתִידִים לִשְׁמֹעַ, אֲבָל בִּשְׁבִיל לָבא אֵלֶיךְ לֹא רָצִינוּ לְהִתְעַכֵּב. שָׂמַח רַבִּי שִׁמְעוֹן.</p>\n<p>אָמְרוּ לוֹ, אִי חָסִיד קָדוֹשׁ, כָּל הַדְּבָרִים שֶׁבְּתוֹכֵנוּ בַּתּוֹרָה, דְּבָרִים קְטַנִּים הֵם בְּכָל דָּבָר וְדָבָר. וְאוֹתָם דְּבָרִים קְטַנִּים, כַּמָּה הֵם דְּבָרִים גְּדוֹלִים וְעֶלְיוֹנִים עַד שֶׁאֵין לָהֶם שִׁעוּר? שֶׁהֲרֵי אֵין בָּנוּ סָפֵק, אֶלָּא בֵּרוּר הַתּוֹרָה עַל בֻּרְיָהּ. וְכָעֵת רֹאשׁ הַיְשִׁיבָה פֵּרַשׁ דְּבָרִים סְתוּמִים עַל זֶה בִּגְלַל מַה שֶּׁעִקַּר הַנְּשָׁמָה לָמָּה לֹא מֵאִיר בְּמָקוֹם זֶה וְזוֹכֶה לִהְיוֹת מוּאָר בְּמָקוֹם אַחֵר? וְעַד עַתָּה לֹא זָכִינוּ בָזֶה בִּשְׁבִיל לָבֹא אֵלֶיךְ.</p>\n<p>וְדָבָר אַחֵר זָכִינוּ לִשְׁמֹעַ מִמֶּנּוּ: רוּחַ שֶׁהוֹלֶכֶת עֲרֻמָּה בְּאוֹתוֹ עוֹלָם בְּלִי בָנִים, אִשְׁתּוֹ תֵּעָשֶׂה כְלִי לִבְנוֹתוֹ. מָה הַטַּעַם? אִשְׁתּוֹ הִיא נֵר שֶׁנִּדְלֶקֶת מִמֶּנּוּ, וּשְׁנֵיהֶם נֵר אֶחָד הָיוּ, אוֹר זֶה יוֹצֵא מֵאוֹר זֶה. דָּעַךְ זֶה, נִדְלָק מִתּוֹךְ אוֹרוֹ מַמָּשׁ, מִשּׁוּם שֶׁהָיוּ אוֹר אֶחָד.</p>"]]});
